INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Atemndobs/v0-fireside-blog/Design System', 'community', 'Atemndobs', 'v0-fireside-blog', 'Atemndobs/v0-fireside-blog', 'Design System', 0, 0, 33, '2026-03-08T01:57:15.605Z', '2026-03-08T02:13:09.255Z', '392d520f1c78a41379d309321425a63975da22b682fd61526cba695c2d735be6', '{"id":"Atemndobs/v0-fireside-blog/Design System","name":"Design System","description":{"en":"The Design System skill provides guidance for implementing UI patterns in the Fireside Tribe project, benefiting developers who need to model their video pages after Billboard''s design.","zh":"设计系统技能提供了Billboard风格UI模式的实现指南，包括视频网格布局和英雄视频展示","ja":"デザインシステムスキルは、ビデオグリッドレイアウトやヒーロービデオ表示など、BillboardスタイルUIパターンの実装ガイドを提供します","ko":"디자인 시스템 스킬은 비디오 그리드 레이아웃 및 히어로 비디오 표시 등 Billboard 스타일 UI 패턴의 구현 가이드를 제공합니다","es":"El sistema de diseño inspirado en Billboard permite crear patrones UI atractivos para la cuadrícula de videos y episodios","fr":"Le système de conception inspiré de Billboard permet de créer des modèles d''UI attrayants pour la grille de vidéos et d''épisodes","de":"Das Design-System im Stil von Billboard ermöglicht die Erstellung ansprechender Benutzeroberflächen-Muster für die Video- und Episoden-Grid","pt":"O Design System é uma abordagem para implementar padrões de UI inspirados no Billboard. Ele fornece orientação para criar layouts de grade de vídeo e hero de vídeo em destaque.","ru":"Design System - это подход к реализации шаблонов UI, вдохновленных Billboard. Он предоставляет руководство для создания макетов видеогрида и видеогероя.","ar":"Design System هو نهج لتنفيذ أنماط واجهة المستخدم الملهمة من Billboard. يوفر إرشادات لإنشاء تخطيطات شبكة الفيديو والفيديو الهيرو"},"seo":{"title":{"en":"Design System: Implementation Guide for AI Agents","zh":"设计系统Setup Guide：Billboard风格UI模式","ja":"デザインシステム Setup Guide：BillboardスタイルUIパターン","ko":"디자인 시스템 Setup Guide: Billboard 风格 UI 패턴","es":"Guía de Implementación de Diseño de Sistema para Patrones UI","fr":"Guide de Mise en Place de Système de Conception pour Modè...","de":"Implementierungsleitfaden für Design-System für Benutzero...","pt":"Guia de Configuração de Design System para Desenvolvedores","ru":"ИИ Агенты: Руководство по настройке Design System","ar":"دليل تصميم النظام للتحكم في واجهة المستخدم"},"description":{"en":"Unlock the power of Billboard-inspired UI patterns with our Design System skill - learn how to implement episodes/video grid layouts and more","zh":"了解如何在Fireside Tribe项目中实现Billboard风格UI模式，包括视频网格布局和英雄视频展示","ja":"Fireside TribeプロジェクトでBillboardスタイルUIパターンを実装する方法について学びます。ビデオグリッドレイアウトやヒーロービデオ表示など","ko":"Fireside Tribe 프로젝트에서 Billboard 스타일 UI 패턴을 구현하는 방법에 대해 알아보세요. 비디오 그리드 레이아웃 및 히어로 비디오 표시 등","es":"Aprenda a implementar un sistema de diseño inspirado en Billboard para su proyecto Fireside Tribe con nuestra guía paso a paso","fr":"Découvrez comment mettre en place un système de conception inspiré de Billboard pour votre projet Fireside Tribe avec notre guide étape par étape","de":"Erfahren Sie, wie Sie ein Design-System im Stil von Billboard für Ihr Fireside Tribe-Projekt mit unserer Schritt-für-Schritt-Anleitung implementieren","pt":"Aprenda a implementar padrões de UI inspirados no Billboard com o Design System. Veja como criar layouts de grade de vídeo e hero de vídeo em destaque.","ru":"Изучите, как реализовать шаблоны UI, вдохновленные Billboard, с помощью Design System. Узнайте, как создать макеты видеогрида и видеогероя.","ar":"تعرف على كيفية تنفيذ أنماط واجهة المستخدم الملهمة من Billboard مع Design System. انظر كيفية إنشاء تخطيطات شبكة الفيديو والفيديو الهيرو"},"definition":{"en":"Design System is a set of guidelines for implementing consistent UI patterns, including episodes/video grid layouts and hero sections.","zh":"设计系统是一种实现Billboard风格UI模式的技能，用于创建一致的用户界面","ja":"デザインシステムは、BillboardスタイルUIパターンを実装するスキルで、一貫したユーザーインターフェイスを作成するために使用されます","ko":"디자인 시스템은 Billboard 스타일 UI 패턴을 구현하는 스킬로 일관된 사용자 인터페이스를 생성하는 데 사용됩니다","es":"Un sistema de diseño es un conjunto de patrones y principios para crear interfaces de usuario coherentes","fr":"Un système de conception est un ensemble de modèles et de principes pour créer des interfaces utilisateur cohérentes","de":"Ein Design-System ist eine Sammlung von Mustern und Prinzipien zur Erstellung konsistenter Benutzeroberflächen","pt":"Design System é um conjunto de diretrizes para criar interfaces de usuário consistentes e inspiradas no Billboard.","ru":"Design System - это набор руководств для создания согласованных и вдохновленных Billboard интерфейсов пользователя.","ar":"Design System هو مجموعة من الإرشادات لإنشاء واجهات مستخدم متسقة وملهمة من Billboard"},"features":{"en":["Models episodes/video grid layouts after Billboard Video Page","Uses TypeScript (TSX) for component development","Utilizes Image component with fill and object-cover classes","Applies absolute positioning and gradient backgrounds for hero sections","Supports max-h and aspect-video classes for responsive design"],"zh":["视频网格布局","英雄视频展示","使用React实现UI组件","支持TSX语法","自定义背景渐变效果"],"ja":["ビデオグリッドレイアウト","ヒーロービデオ表示","Reactを使用したUIコンポーネントの実装","TSX構文のサポート","背景グラデーション効果のカスタマイズ"],"ko":["비디오 그리드 레이아웃","히어로 비디오 표시","React를 사용한 UI 컴포넌트 구현","TSX 문법 지원","배경 그라데이션 효과의 사용자 정의"],"es":["Diseño de cuadrícula de videos inspirado en Billboard","Implementación de patrones UI con React y TypeScript","Uso de componentes de imagen con fill y object-cover","Creación de gradientes de fondo con from-black/90 y via-black/50"],"fr":["Conception de grille de vidéos inspirée de Billboard","Mise en place de modèles d''UI avec React et TypeScript","Utilisation de composants d''image avec fill et object-cover","Création de dégradés de fond avec from-black/90 et via-black/50"],"de":["Design der Video-Grid im Stil von Billboard","Implementierung von Benutzeroberflächen-Mustern mit React und TypeScript","Verwendung von Bildkomponenten mit fill und object-cover","Erstellung von Hintergrund-Gradienten mit from-black/90 und via-black/50"],"pt":["Implementação de padrões de UI inspirados no Billboard","Criação de layouts de grade de vídeo","Desenvolvimento de hero de vídeo em destaque com React","Utilização de bibliotecas de imagem para otimização de desempenho","Integração com tecnologias de front-end para melhor experiência do usuário"],"ru":["Реализация шаблонов UI, вдохновленных Billboard","Создание макетов видеогрида","Разработка видеогероя с помощью React","Использование библиотек изображений для оптимизации производительности","Интеграция с технологиями фронтэнда для лучшего опыта пользователя"],"ar":["تنفيذ أنماط واجهة المستخدم الملهمة من Billboard","إنشاء تخطيطات شبكة الفيديو","تطوير الفيديو الهيرو باستخدام React","استخدام مكتبات الصور لتحسين الأداء","التكامل مع تقنيات الواجهة الأمامية لتحسين تجربة المستخدم"]},"keywords":{"en":["how to use Design System","Design System implementation guide","Design System vs Material UI","Design System install for React","what is Design System in UI design","Design System setup for TypeScript projects"],"zh":["设计系统","Billboard风格UI","视频网格布局","英雄视频展示","React","TSX","背景渐变效果"],"ja":["デザインシステム","BillboardスタイルUI","ビデオグリッドレイアウト","ヒーロービデオ表示","React","TSX","背景グラデーション効果"],"ko":["디자인 시스템","Billboard 스타일 UI","비디오 그리드 레이아웃","히어로 비디오 표시","React","TSX","배경 그라데이션 효과"],"es":["sistema de diseño","patrones UI","React","TypeScript","diseño de cuadrícula de videos","Billboard","Fireside Tribe","implementación de diseño de sistema"],"fr":["système de conception","modèles d''UI","React","TypeScript","conception de grille de vidéos","Billboard","Fireside Tribe","mise en place de système de conception"],"de":["Design-System","Benutzeroberflächen-Muster","React","TypeScript","Design der Video-Grid","Billboard","Fireside Tribe","Implementierung von Design-System"],"pt":["Design System","padrões de UI","Billboard","React","desenvolvimento de interfaces de usuário","otimização de desempenho","bibliotecas de imagem","tecnologias de front-end"],"ru":["Design System","шаблоны UI","Billboard","React","разработка интерфейсов пользователя","оптимизация производительности","библиотеки изображений","технологии фронтэнда"],"ar":["Design System","أنماط واجهة المستخدم","Billboard","React","تطوير واجهات المستخدم","تحسين الأداء","مكتبات الصور","تقنيات الواجهة الأمامية"]}},"owner":"Atemndobs","repo":"v0-fireside-blog","repoPath":"Atemndobs/v0-fireside-blog","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.605Z","topics":[],"category":"community","skillMd":{"name":"Design System","description":"Billboard-inspired design patterns for implementing UI components with video grids, chart layouts, and editorial typography","bodyPreview":"# Design System Skill\n\nGuidance for implementing Billboard-inspired UI patterns in the Fireside Tribe project.\n\n## Episodes/Video Grid Layout\n\nModel after [Billboard Video Page](https://www.billboard.com/video/):\n\n### Featured Video Hero\n```tsx\n<section className=\"relative w-full aspect-video max-h-[70vh]\">\n  <Image src={episode.thumbnail} fill className=\"object-cover\" />\n  <div className=\"absolute inset-0 bg-gradient-to-t from-black/90 via-black/50 to-transparent\" />\n  <div className=\"absolute","body":"# Design System Skill\n\nGuidance for implementing Billboard-inspired UI patterns in the Fireside Tribe project.\n\n## Episodes/Video Grid Layout\n\nModel after [Billboard Video Page](https://www.billboard.com/video/):\n\n### Featured Video Hero\n```tsx\n<section className=\"relative w-full aspect-video max-h-[70vh]\">\n  <Image src={episode.thumbnail} fill className=\"object-cover\" />\n  <div className=\"absolute inset-0 bg-gradient-to-t from-black/90 via-black/50 to-transparent\" />\n  <div className=\"absolute bottom-0 p-8 space-y-4\">\n    <Badge>Featured</Badge>\n    <h1 className=\"text-4xl font-bold\">{episode.title}</h1>\n    <p className=\"text-gray-300 max-w-2xl\">{episode.description}</p>\n  </div>\n</section>\n```\n\n### Video Card Grid\n```tsx\n<div className=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6\">\n  {episodes.map((ep) => (\n    <VideoCard key={ep._id} episode={ep} />\n  ))}\n</div>\n```\n\n### Video Card Component\n```tsx\n<article className=\"group cursor-pointer\">\n  <div className=\"relative aspect-video rounded-lg overflow-hidden\">\n    <Image src={ep.thumbnail} fill className=\"object-cover transition-transform group-hover:scale-105\" />\n    <div className=\"absolute bottom-2 right-2 bg-black/80 px-2 py-1 text-sm rounded\">\n      {ep.duration}\n    </div>\n  </div>\n  <div className=\"mt-3 space-y-1\">\n    <h3 className=\"font-semibold line-clamp-2 group-hover:text-red-500 transition-colors\">\n      {ep.title}\n    </h3>\n    <p className=\"text-sm text-gray-400\">{ep.publishedAt}</p>\n  </div>\n</article>\n```\n\n## Chart-Style Rankings\n\nFor featuring top episodes or artists:\n\n```tsx\n<ol className=\"space-y-4\">\n  {items.map((item, index) => (\n    <li key={item._id} className=\"flex items-center gap-4 p-4 bg-zinc-900 rounded-lg\">\n      <span className=\"text-3xl font-bold text-gray-500 w-12 text-center\">\n        {index + 1}\n      </span>\n      <Image src={item.image} width={64} height={64} className=\"rounded\" />\n      <div className=\"flex-1\">\n        <h4 className=\"font-semibold\">{item.title}</h4>\n        <p className=\"text-sm text-gray-400\">{item.subtitle}</p>\n      </div>\n      <div className=\"flex gap-2\">\n        <Badge variant=\"outline\">Peak: #{item.peak}</Badge>\n        <Badge variant=\"outline\">Weeks: {item.weeks}</Badge>\n      </div>\n    </li>\n  ))}\n</ol>\n```\n\n## Section Headers\n\nBillboard-style section headers with \"See All\" links:\n\n```tsx\n<div className=\"flex items-center justify-between mb-6\">\n  <h2 className=\"text-2xl font-bold uppercase tracking-wide\">{title}</h2>\n  <Link href={seeAllHref} className=\"text-red-500 hover:underline text-sm font-medium\">\n    See All →\n  </Link>\n</div>\n```\n\n## Color Tokens\n\n```css\n:root {\n  --background: #0a0a0a;\n  --surface: #171717;\n  --surface-elevated: #262626;\n  --accent: #ef4444;\n  --text-primary: #ffffff;\n  --text-secondary: #a3a3a3;\n  --text-muted: #525252;\n}\n```\n\n## Responsive Breakpoints\n\nFollow TailwindCSS defaults:\n- `sm`: 640px (mobile landscape)\n- `md`: 768px (tablet)\n- `lg`: 1024px (desktop)\n- `xl`: 1280px (wide desktop)\n\n## Motion Guidelines\n\nUse Framer Motion with subtle, performant animations:\n\n```tsx\nconst cardVariants = {\n  hidden: { opacity: 0, y: 20 },\n  visible: { opacity: 1, y: 0, transition: { duration: 0.3 } },\n};\n\n<motion.div variants={cardVariants} initial=\"hidden\" animate=\"visible\">\n  {/* content */}\n</motion.div>\n```\n"},"lastSynced":"2026-03-08T02:13:09.255Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing to implement Billboard-inspired UI patterns in the Fireside Tribe project.","zh":"非常适合需要在 Fireside Tribe 项目中实现 Billboard 风格 UI 模式的前端代理","ja":"Fireside Tribe プロジェクトで Billboard にインスパイアされた UI パターンを実装する必要があるフロントエンド エージェントに最適","ko":"Fireside Tribe 프로젝트에서 Billboard风格의 UI 패턴을 구현해야 하는 프론트엔드 에이전트에게 완벽함","es":"Perfecto para Agentes Frontend que necesitan implementar patrones de UI inspirados en Billboard en el proyecto Fireside Tribe.","fr":"Parfait pour les agents Frontend qui ont besoin de mettre en œuvre des modèles d''UI inspirés de Billboard dans le projet Fireside Tribe.","de":"Perfekt für Frontend-Agents, die Billboard-inspirierte UI-Muster im Fireside Tribe-Projekt implementieren müssen.","pt":"Perfeito para Agentes Frontend que precisam implementar padrões de UI inspirados no Billboard no projeto Fireside Tribe.","ru":"Идеально подходит для агентов Frontend, которым необходимо реализовать шаблоны UI, вдохновленные Billboard, в проекте Fireside Tribe.","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى تنفيذ أنماط واجهة المستخدم الملهمة من Billboard في مشروع Fireside Tribe."},"recommendation":{"en":"Empowers agents to generate responsive video grid layouts using TypeScript and React, featuring hero sections with absolute positioning and gradient overlays, while leveraging CSS classes for styling and layout management.","zh":"赋予代理生成响应式视频网格布局的能力，使用 TypeScript 和 React，具有绝对定位和渐变叠加的英雄部分，并利用 CSS 类进行样式和布局管理","ja":"TypeScript と React を使用して、絶対位置指定とグラデーション重ねを備えたヒーローセクションを持つ、レスポンシブなビデオグリッドレイアウトを生成するエージェントの能力を付与し、CSS クラスを使用してスタイルとレイアウト管理を行う","ko":"에이전트가 타입스크립트와 리액트를 사용하여 반응형 비디오 그리드 레이아웃을 생성할 수 있도록 하는데, 절대 위치 지정과 그라데이션 오버레이를 갖춘 히어로 섹션이 포함되어 있으며, CSS 클래스를 사용하여 스타일과 레이아웃 관리를 수행","es":"Habilita a los agentes para generar diseños de cuadrícula de video responsivos utilizando TypeScript y React, con secciones de héroe con posicionamiento absoluto y superposiciones de gradiente, al mismo tiempo que aprovecha las clases CSS para el estilo y la gestión del diseño.","fr":"Permet aux agents de générer des dispositions de grille de vidéo responsives en utilisant TypeScript et React, avec des sections de héros à positionnement absolu et des superpositions de dégradé, tout en exploitant les classes CSS pour le style et la gestion de la disposition.","de":"Ermöglicht es Agents, responsive Video-Raster-Layouts mit TypeScript und React zu generieren, mit Hero-Abschnitten mit absoluter Positionierung und Farbverlaufs-Overlays, während es CSS-Klassen für Stil und Layout-Verwaltung nutzt.","pt":"Habilita os agentes a gerar layouts de grade de vídeo responsivos usando TypeScript e React, com seções de destaque com posicionamento absoluto e sobreposições de gradiente, aproveitando classes CSS para estilização e gerenciamento de layout.","ru":"Позволяет агентам генерировать адаптивные сеточные макеты видео, используя TypeScript и React, с героическими разделами с абсолютным позиционированием и наложением градиентов, при этом использует классы CSS для стилизации и управления макетом.","ar":"تمكين الوكلاء من توليد تخطيطات شبكية للفيديو المستجيبة باستخدام TypeScript و React، مع أقسام البطل مع التموضع المطلق وتأثيرات التدرج، مع الاستفادة من فئات CSS لتصميم وتنظيم التخطيط."},"useCases":{"en":["Implementing featured video hero sections with thumbnail images","Generating episodes/video grid layouts with absolute positioning","Customizing UI patterns with CSS classes and gradient overlays"],"zh":["实现具有缩略图图像的特色视频英雄部分","使用绝对定位生成剧集/视频网格布局","使用 CSS 类和渐变叠加自定义 UI 模式"],"ja":["サムネイル画像を持つ特集ビデオヒーローセクションを実装する","絶対位置指定を使用してエピソード/ビデオグリッドレイアウトを生成する","CSS クラスとグラデーション重ねを使用して UI パターンをカスタマイズする"],"ko":["썸네일 이미지와 함께 특집 비디오 히어로 섹션 구현","절대 위치 지정 사용하여 에피소드/비디오 그리드 레이아웃 생성","CSS 클래스와 그라데이션 오버레이를 사용하여 UI 패턴 사용자 정의"],"es":["Implementar secciones de vídeo héroe con imágenes en miniatura","Generar diseños de cuadrícula de episodios/vídeos con posicionamiento absoluto","Personalizar patrones de UI con clases CSS y superposiciones de gradiente"],"fr":["Mettre en œuvre des sections de vidéo héros avec des images en miniature","Générer des dispositions de grille d''épisodes/vídeos avec un positionnement absolu","Personnaliser les modèles d''UI avec des classes CSS et des superpositions de dégradé"],"de":["Implementierung von Video-Hero-Abschnitten mit Vorschaubildern","Generierung von Episoden/Video-Raster-Layouts mit absoluter Positionierung","Anpassen von UI-Mustern mit CSS-Klassen und Farbverlaufs-Overlays"],"pt":["Implementação de seções de destaque de vídeo com imagens em miniatura","Geração de layouts de grade de episódios/vídeo com posicionamento absoluto","Personalização de padrões de UI com classes CSS e sobreposições de gradiente"],"ru":["Реализация разделов видео-героев с изображениями в миниатюре","Генерация макетов сетки эпизодов/видео с абсолютным позиционированием","Настройка шаблонов UI с помощью классов CSS и наложением градиентов"],"ar":["تنفيذ أقسام الفيديو الرئيسية مع صور مصغرة","توليد تخطيطات شبكية للحلقات/الفيديو مع التموضع المطلق","تخصيص أنماط واجهة المستخدم باستخدام فئات CSS وتأثيرات التدرج"]},"limitations":{"en":["Requires knowledge of TypeScript and React","Limited to Fireside Tribe project scope","Dependent on Billboard video page design for inspiration"],"zh":["需要 TypeScript 和 React 的知识","仅限 Fireside Tribe 项目范围","依赖于 Billboard 视频页面设计以获取灵感"],"ja":["TypeScript と React の知識が必要","Fireside Tribe プロジェクトの範囲に限定される","ビルボードのビデオページデザインに依存してインスピレーションを得る"],"ko":["타입스크립트와 리액트에 대한 지식이 필요","파이어사이드 트라이브 프로젝트 범위에만 제한","빌보드 비디오 페이지 디자인에 의존하여 영감을 얻음"],"es":["Requiere conocimiento de TypeScript y React","Limitado al alcance del proyecto Fireside Tribe","Dependiente del diseño de la página de vídeo de Billboard para la inspiración"],"fr":["Nécessite une connaissance de TypeScript et React","Limité à la portée du projet Fireside Tribe","Dépend du design de la page de vidéo Billboard pour l''inspiration"],"de":["Benötigt Kenntnisse von TypeScript und React","Begrenzt auf den Umfang des Fireside Tribe-Projekts","Abhängig vom Design der Billboard-Videoseite für die Inspiration"],"pt":["Exige conhecimento de TypeScript e React","Limitado ao escopo do projeto Fireside Tribe","Dependente do design da página de vídeo do Billboard para inspiração"],"ru":["Требует знания TypeScript и React","Ограничен рамками проекта Fireside Tribe","Зависит от дизайна страницы видео Billboard для вдохновения"],"ar":["يتطلب معرفة TypeScript و React","محدود بنطاق مشروع Fireside Tribe","يعتمد على تصميم صفحة الفيديو الت属 لشركة Billboard للإلهام"]},"version":4},"contentHash":"392d520f1c78a41379d309321425a63975da22b682fd61526cba695c2d735be6","qualityScore":33}');
