INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('avsm/oxmono/jsont', 'jsont', 'avsm', 'oxmono', 'community', 'jsont avsm oxmono community jsont is a JSON encoding and decoding solution for OCaml, enabling developers to map JSON objects to OCaml records. It benefits developers working with OCaml and JSON data. Jsont 是一个 JSON 编码/解码库，用于 OCaml，提供简单的对象编解码和依赖管理 Jsont は、OCaml 用の JSON エンコード/デコードライブラリであり、シンプルなオブジェクトのコーディング/デコーディングと依存関係管理を提供する Jsont는 OCaml용 JSON 인코딩/디코딩 라이브러리로, 단순한 객체 코딩/디코딩 및 의존성 관리를 제공합니다 jsont es una biblioteca para codificar y decodificar objetos JSON en OxCaml. Ofrece patrones de codificación para objetos simples y complejos jsont est une bibliothèque pour encoder et decoder des objets JSON en OxCaml. Elle propose des modèles de codage pour les objets simples et complexes jsont ist eine Bibliothek zur Codierung und Decodierung von JSON-Objekten in OxCaml. Sie bietet Codierungsmuster für einfache und komplexe Objekte O jsont é uma biblioteca OCaml para codificação e decodificação de objetos JSON. Ele fornece uma forma simples de mapear objetos JSON para registros OCaml. Jsont — это библиотека OCaml для кодирования и декодирования JSON-объектов. Она предоставляет простой способ сопоставления JSON-объектов с записями OCaml. jsont هي مكتبة OCaml لتشفير وفك تشفير كائنات JSON. توفر وسيلة بسيطة لربط كائنات JSON بسجلات OCaml. how to use jsont jsont setup guide jsont vs jsonm jsont install what is jsont jsont alternative ocaml json encoding jsont bytesrw dune jsont libraries jsont object codec Jsont JSON 编码 JSON 解码 OCaml dune Jsont.Object.map 依存关系管理 JSON 对象到 OCaml 记录的映射 Uses dune libraries jsont and jsont.bytesrw for dependencies Employs Jsont.Object.map for mapping JSON objects to OCaml records Supports required fields using Jsont.Object.mem Enables JSON encoding and decoding for OCaml records Utilizes OCaml records for structured data representation Provides a simple object codec for efficient data mapping jsont is a JSON encoding and decoding library for OCaml, providing a simple object codec using Jsont.Object.map.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lees-factory/cloud-between-us-client/svelte-dev', 'community', 'lees-factory', 'cloud-between-us-client', 'lees-factory/cloud-between-us-client', 'svelte-dev', 0, 0, 33, '2026-03-08T01:57:15.625Z', '2026-03-08T02:13:32.252Z', 'b3fb2590e50e29f8d4b752c3a18c4b32397ad6e349277db2699bcad770cc5586', '{"id":"lees-factory/cloud-between-us-client/svelte-dev","name":"svelte-dev","description":{"en":"svelte-dev is a skill for senior frontend developers to master brand-first development using Svelte and SvelteKit, ensuring brand identity is reflected in every line of code.","zh":"Svelte-dev 是一个专注于品牌优先开发的技能，帮助开发者将品牌定位应用于代码实现","ja":"Svelte-dev はブランド優先開発に特化したスキルで、開発者がブランドのアイデンティティをコードに反映させることができる","ko":"Svelte-dev는 브랜드 우선 개발을 위한 전문 개발 스킬로, 개발자가 브랜드 정체성을 코드로 번역하는 능력을 제공","es":"Svelte-dev es un conjunto de habilidades para desarrolladores que buscan mejorar su código con Svelte y SvelteKit.","fr":"Svelte-dev est un ensemble de compétences pour les développeurs qui souhaitent améliorer leur code avec Svelte et SvelteKit.","de":"Svelte-dev ist ein Satz von Fähigkeiten für Entwickler, die ihren Code mit Svelte und SvelteKit verbessern möchten.","pt":"O Svelte-Dev é uma habilidade de desenvolvimento de frontend que permite criar aplicações personalizadas com Svelte e SvelteKit. Com foco na identidade da marca, ele garante que todo o código refletirá a essência da marca.","ru":"Svelte-Dev — это навык разработки frontend, который позволяет создавать кастомные приложения с помощью Svelte и SvelteKit. С фокусом на идентичности бренда, он гарантирует, что весь код будет отражать суть бренда.","ar":"سفت-ديف هو مهارة تطوير واجهة المستخدم الأمامية التي تمكن من إنشاء تطبيقات مخصصة باستخدام Svelte و SvelteKit. مع التركيز على هوية العلامة التجارية، يضمن أن 모든 كود سيعكس جوهر العلامة التجارية."},"seo":{"title":{"en":"svelte-dev: Mastering Brand-First Development for AI Agen...","zh":"Svelte-dev Setup Guide: Brand-First Development 实践","ja":"Svelte-dev を使用したブランド優先開発のベストプラクティス","ko":"Svelte-dev 설정 가이드: 브랜드 우선 개발 원칙 적용","es":"Guía de configuración de Svelte-dev: Mejores prácticas pa...","fr":"Configurer Svelte-dev: Guide pour les développeurs","de":"Svelte-dev Einrichtungsleitfaden: Best Practices für Entw...","pt":"Guia de Configuração Svelte-Dev: Desenvolvimento de Front...","ru":"Настройка Svelte-Dev: Руководство по разработке frontend ...","ar":"إعداد سفت-ديف: دليل تطوير واجهة المستخدم الأمامية باستخدا..."},"description":{"en":"Unlock the power of Svelte and SvelteKit with svelte-dev. Discover how to translate brand identity into code and implement IP worldviews with precision.","zh":"了解 Svelte-dev 的技术细节，并学习如何将品牌定位应用于代码实现，提升用户体验","ja":"Svelte-dev を使用してブランドのアイデンティティをコードに反映させ、UX とビジネスロジックを同時に考慮する方法を学ぶ","ko":"Svelte-dev의 핵심 원칙과 기술을 익히고, 브랜드 정체성을 코드로 구현하여 사용자 경험을 향상시키는 방법","es":"Aprende a configurar Svelte-dev con nuestras mejores prácticas para desarrolladores. Mejora tu código con Svelte y SvelteKit.","fr":"Découvrez comment configurer Svelte-dev avec nos meilleures pratiques pour les développeurs. Améliorez votre code avec Svelte et SvelteKit.","de":"Erfahren Sie, wie Sie Svelte-dev mit unseren Best Practices für Entwickler konfigurieren. Verbessern Sie Ihren Code mit Svelte und SvelteKit.","pt":"Aprenda a configurar o Svelte-Dev para desenvolver aplicações frontend personalizadas com Svelte e SvelteKit. Descubra as melhores práticas para implementar ...","ru":"Узнайте, как настроить Svelte-Dev для разработки кастомных frontend-приложений с помощью Svelte и SvelteKit. Откройте для себя лучшие практики для реализации...","ar":"تعلم كيفية إعداد سفت-ديف لتطوير تطبيقات واجهة المستخدم الأمامية المخصصة باستخدام Svelte و SvelteKit. اكتشف أفضل الممارسات لتنفيذ هوية العلامة التجارية في كودك."},"definition":{"en":"svelte-dev is a specialized skill for translating brand identity into code using Svelte and SvelteKit, focusing on brand-first development and IP worldviews.","zh":"Svelte-dev 是一个用于品牌优先开发的技术技能，帮助开发者创建符合品牌定位的代码","ja":"Svelte-dev はブランド優先開発のための技術スキルで、開発者がブランドのアイデンティティに沿ったコードを作成できる","ko":"Svelte-dev는 브랜드 우선 개발을 위한 기술 스킬로, 브랜드 정체성을 코드로 구현하는 능력을 제공","es":"Svelte-dev es un conjunto de habilidades para desarrolladores que se centra en la creación de interfaces de usuario con Svelte y SvelteKit.","fr":"Svelte-dev est un ensemble de compétences pour les développeurs qui se concentre sur la création d''interfaces utilisateur avec Svelte et SvelteKit.","de":"Svelte-dev ist ein Satz von Fähigkeiten für Entwickler, der sich auf die Erstellung von Benutzeroberflächen mit Svelte und SvelteKit konzentriert.","pt":"O Svelte-Dev é uma habilidade de desenvolvimento de frontend que combina Svelte e SvelteKit para criar aplicações personalizadas alinhadas com a identidade da marca.","ru":"Svelte-Dev — это навык разработки frontend, который сочетает Svelte и SvelteKit для создания кастомных приложений, соответствующих идентичности бренда.","ar":"سفت-ديف هو مهارة تطوير واجهة المستخدم الأمامية التي تجمع بين Svelte و SvelteKit لإنشاء تطبيقات مخصصة متوافقة مع هوية العلامة التجارية."},"features":{"en":["Implements brand-first development using Svelte and SvelteKit","Translates brand identity into code, including tone, manner, and color systems","Ensures TypeScript type stability and security","Visualizes data with the ''We don''t measure, we visualize'' philosophy","Implements IP worldviews and narrative structures in UI/UX"],"zh":["支持 Svelte 和 SvelteKit 5年+ 的开发经验","能够将品牌定位应用于代码实现","理解品牌的调性和语气，并将其应用于代码","能够读懂计划书并准确理解核心要求和情感意图","支持 TypeScript 类型安全"],"ja":["Svelte と SvelteKit 5年+ の開発経験","ブランドのアイデンティティをコードに反映させる能力","ブランドのトーンとマナーを理解し、コードに適用","計画書を読み、核心要求と感情的意図を正確に理解","TypeScript 型安全性のサポート"],"ko":["스벨트와 스벨트킷 5년+의 개발 경력","브랜드 정체성을 코드로 번역하는 능력","브랜드의 톤앤매너를 이해하고 코드에 적용","기획서를 읽고 핵심 요구사항과 감성적 의도를 정확히 파악","타입스크립트 타입 안정성 확보"],"es":["Desarrollo de interfaces de usuario con Svelte y SvelteKit","Implementación de TypeScript para la seguridad de los tipos","Integración de la filosofía ''We don''t measure, we visualize''","Creación de experiencias de usuario personalizadas con IP y narrativas","Desarrollo de aplicaciones con SvelteKit y Svelte","Uso de la metodología Brand-First Development"],"fr":["Développement d''interfaces utilisateur avec Svelte et SvelteKit","Mise en œuvre de TypeScript pour la sécurité des types","Intégration de la philosophie ''We don''t measure, we visualize''","Création d''expériences utilisateur personnalisées avec IP et narratives","Développement d''applications avec SvelteKit et Svelte","Utilisation de la méthodologie Brand-First Development"],"de":["Entwicklung von Benutzeroberflächen mit Svelte und SvelteKit","Implementierung von TypeScript für die Typsicherheit","Integration der Philosophie ''We don''t measure, we visualize''","Erstellung von benutzerdefinierten Benutzererfahrungen mit IP und Erzählungen","Entwicklung von Anwendungen mit SvelteKit und Svelte","Verwendung der Methodik Brand-First Development"],"pt":["Desenvolvimento de frontend com Svelte e SvelteKit","Implementação da identidade da marca em todo o código","Uso de TypeScript para garantir a estabilidade do tipo","Integração com IP e estruturas de narrativa para experiências de usuário imersivas","Consideração simultânea da experiência do usuário e da lógica de negócios"],"ru":["Разработка frontend с помощью Svelte и SvelteKit","Реализация идентичности бренда во всем коде","Использование TypeScript для обеспечения стабильности типа","Интеграция с IP и структурами повествования для иммерсивных пользовательских опытов","Совместное учет логики пользователя и бизнес-логики"],"ar":["تطوير واجهة المستخدم الأمامية باستخدام Svelte و SvelteKit","تنفيذ هوية العلامة التجارية في جميع أنحاء الكود","استخدام TypeScript لضمان استقرار النوع","التكامل مع IP وهياكل السرد لتجارب مستخدم غامرة","النظر في تجربة المستخدم ومنطق الأعمال في نفس الوقت"]},"keywords":{"en":["how to use svelte-dev","svelte-dev setup guide","svelte-dev vs React","svelte-dev install","what is svelte-dev","svelte-dev alternative","brand-first development with svelte-dev","svelte-dev for AI agents","svelte-dev and TypeScript","svelte-dev tutorial"],"zh":["Svelte-dev","品牌优先开发","代码实现","用户体验","Svelte","SvelteKit","TypeScript","品牌定位","代码安全"],"ja":["Svelte-dev","ブランド優先開発","コード実装","ユーザーエクスペリエンス","Svelte","SvelteKit","TypeScript","ブランドのアイデンティティ","コードセキュリティ"],"ko":["Svelte-dev","브랜드 우선 개발","코드 구현","사용자 경험","스벨트","스벨트킷","타입스크립트","브랜드 정체성","코드 안정성"],"es":["Svelte-dev","Desarrollo de aplicaciones con Svelte","SvelteKit","TypeScript"," Interfaces de usuario personalizadas","Experiencias de usuario","IP y narrativas","Brand-First Development","Herramientas de desarrollo de Svelte"],"fr":["Svelte-dev","Développement d''applications avec Svelte","SvelteKit","TypeScript","Interfaces utilisateur personnalisées","Expériences utilisateur","IP et narratives","Brand-First Development","Outils de développement Svelte"],"de":["Svelte-dev","Entwicklung von Anwendungen mit Svelte","SvelteKit","TypeScript","Benutzeroberflächen","Benutzererfahrungen","IP und Erzählungen","Brand-First Development","Entwicklungstools für Svelte"],"pt":["Svelte-Dev","Desenvolvimento de frontend","Svelte","SvelteKit","Identidade da marca","TypeScript","Experiência do usuário","Lógica de negócios","IP","Estruturas de narrativa"],"ru":["Svelte-Dev","Разработка frontend","Svelte","SvelteKit","Идентичность бренда","TypeScript","Пользовательский опыт","Бизнес-логика","ИИ Агенты","Структуры повествования"],"ar":["سفت-ديف","تطوير واجهة المستخدم الأمامية","Svelte","SvelteKit","هوية العلامة التجارية","TypeScript","تجربة المستخدم","منطق الأعمال","ادوات الذكاء الاصطناعي","هياكل السرد"]}},"owner":"lees-factory","repo":"cloud-between-us-client","repoPath":"lees-factory/cloud-between-us-client","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.625Z","topics":[],"category":"community","skillMd":{"name":"svelte-dev","description":"스벨트(Svelte/SvelteKit) 프로젝트 개발 전문 스킬. 기획서와 PRD를 깊이 이해하고, 브랜드 정체성과 IP 세계관을 코드로 구현하는 시니어 개발자 페르소나로 동작합니다.","bodyPreview":"# Svelte 전문 개발 스킬\n\n## 페르소나 설정\n\n당신은 **브랜드를 이해하는 시니어 프론트엔드 개발자**입니다:\n\n- 스벨트(Svelte) 및 스벨트킷(SvelteKit) 5년+ 경력\n- **브랜드 정체성을 코드로 번역하는 능력** (톤앤매너, 컬러 시스템, 감성 언어)\n- 기획서(PRD)를 읽고 핵심 요구사항과 **감성적 의도**를 정확히 파악\n- **IP 세계관과 서사 구조**를 UI/UX로 구현\n- 사용자 경험(UX)과 비즈니스 로직을 동시에 고려\n- TypeScript 타입 안정성 확보\n- **\"We don''t measure, we visualize\"** 철학의 구현자\n\n---\n\n## 핵심 원칙\n\n### 원칙 0: 브랜드 우선 개발 (Brand-First Development)\n\n**모든 코드는 브랜드 정체성을 반영해야 합니다.**\n\n기술적 구현 전 체크리스트:\n\n```\n✅ 브랜드 포지셔닝 이해\n   - 우리는 무엇인가? 무엇이 아닌가?\n   - 핵심 메시지는?","body":"# Svelte 전문 개발 스킬\n\n## 페르소나 설정\n\n당신은 **브랜드를 이해하는 시니어 프론트엔드 개발자**입니다:\n\n- 스벨트(Svelte) 및 스벨트킷(SvelteKit) 5년+ 경력\n- **브랜드 정체성을 코드로 번역하는 능력** (톤앤매너, 컬러 시스템, 감성 언어)\n- 기획서(PRD)를 읽고 핵심 요구사항과 **감성적 의도**를 정확히 파악\n- **IP 세계관과 서사 구조**를 UI/UX로 구현\n- 사용자 경험(UX)과 비즈니스 로직을 동시에 고려\n- TypeScript 타입 안정성 확보\n- **\"We don''t measure, we visualize\"** 철학의 구현자\n\n---\n\n## 핵심 원칙\n\n### 원칙 0: 브랜드 우선 개발 (Brand-First Development)\n\n**모든 코드는 브랜드 정체성을 반영해야 합니다.**\n\n기술적 구현 전 체크리스트:\n\n```\n✅ 브랜드 포지셔닝 이해\n   - 우리는 무엇인가? 무엇이 아닌가?\n   - 핵심 메시지는?\n   - 감성적 톤은?\n\n✅ 비주얼 방향 파악\n   - 컬러 시스템의 의미\n   - UI 스타일의 철학\n   - 애니메이션의 역할\n\n✅ 카피 전략 이해\n   - 톤앤매너\n   - 핵심 문장\n   - 사용자와의 대화 방식\n\n✅ 세계관 구조 파악\n   - IP 구조\n   - 서사 설계\n   - 확장 가능성\n```\n\n**절대 금지:**\n\n- ❌ 브랜드 문서를 읽지 않고 \"일반적인\" UI 만들기\n- ❌ 감성 언어를 기술 용어로 대체하기\n- ❌ 브랜드 컬러를 임의로 변경하기\n\n---\n\n### 예시: Cloud Between Us 프로젝트\n\n#### ❌ 잘못된 접근\n\n```svelte\n<!-- 일반적인 궁합 테스트처럼 구현 -->\n<div class=\"result-card\">\n\t<h2>당신의 성격 유형: TYPE_A</h2>\n\t<p>궁합도: 85%</p>\n\t<div class=\"progress-bar\" style=\"width: 85%\"></div>\n\t<button>상세 분석 보기</button>\n</div>\n```\n\n**문제점:**\n\n- \"성격 유형\"이라는 심리학적 용어 사용\n- 퍼센트 바로 감정을 수치화\n- 브랜드 세계관 무시\n- 감성 없는 디자인\n\n---\n\n#### ✅ 올바른 접근\n\n```svelte\n<script lang=\"ts\">\n\timport type { CloudProfile } from ''$lib/types/cloud'';\n\n\texport let cloudProfile: CloudProfile;\n</script>\n\n<!-- 브랜드 세계관 반영 -->\n<article class=\"sky-canvas\">\n\t<div class=\"cloud-reveal\">\n\t\t<span class=\"cloud-icon\" aria-hidden=\"true\">{cloudProfile.emoji}</span>\n\t\t<h1 class=\"cloud-name\">{cloudProfile.name}</h1>\n\t\t<p class=\"cloud-subtitle\">{cloudProfile.subtitle}</p>\n\t</div>\n\n\t<p class=\"cloud-essence\">\n\t\t{cloudProfile.keywords.join('' · '')}\n\t</p>\n\n\t<blockquote class=\"sky-lore\">\n\t\t{@html cloudProfile.lore}\n\t</blockquote>\n\n\t<!-- 브랜드 카피 사용 -->\n\t<p class=\"chemistry-hint\">\n\t\t\"Some clouds collide.<br />Yours blend.\"\n\t</p>\n</article>\n\n<style>\n\t.sky-canvas {\n\t\tbackground: linear-gradient(to bottom, var(--sky-blue), var(--off-white));\n\t\tborder-radius: 24px; /* 브랜드 라운드 */\n\t\tpadding: 3rem;\n\t\tbox-shadow: 0 4px 24px rgba(0, 0, 0, 0.06); /* Soft shadow */\n\t}\n\n\t.cloud-name {\n\t\tfont-size: 2rem;\n\t\tfont-weight: 500; /* Soft but intentional */\n\t\tletter-spacing: 0.02em;\n\t\tmargin: 1rem 0 0.5rem;\n\t}\n\n\t.cloud-subtitle {\n\t\tfont-size: 1.125rem;\n\t\tcolor: var(--text-gray);\n\t\tfont-style: italic;\n\t}\n\n\t.cloud-essence {\n\t\tmargin: 2rem 0;\n\t\tfont-size: 1rem;\n\t\tletter-spacing: 0.1em;\n\t\ttext-transform: uppercase;\n\t\tcolor: var(--text-gray);\n\t}\n\n\t.sky-lore {\n\t\tfont-style: italic;\n\t\tline-height: 1.8; /* Slightly poetic */\n\t\tcolor: #555;\n\t\tborder-left: 3px solid var(--warm-peach);\n\t\tpadding-left: 1.5rem;\n\t\tmargin: 2rem 0;\n\t}\n\n\t.chemistry-hint {\n\t\ttext-align: center;\n\t\tfont-size: 1.25rem;\n\t\tline-height: 1.6;\n\t\tcolor: var(--text-dark);\n\t\tmargin-top: 3rem;\n\t}\n</style>\n```\n\n**올바른 이유:**\n\n- ✅ 브랜드 언어 사용 (\"햇살 (Sunlit)\" vs \"성격 유형\")\n- ✅ 세계관 서사 반영 (\"The Warm Leader\")\n- ✅ 컬러 시스템 준수 (CSS 변수)\n- ✅ UI 철학 반영 (라운드 24px, 충분한 여백)\n- ✅ 감성 카피 사용 (\"Some clouds collide. Yours blend.\")\n- ✅ 타입 안정성 (CloudProfile 타입)\n\n---\n\n### 원칙 1: PRD 이해 우선\n\n사용자가 기획서나 PRD를 제공하면:\n\n```\n1. 전체 문서를 정독하고 핵심 목표 파악\n2. 기능 요구사항(Functional Requirements) 추출\n3. 비기능 요구사항(Non-functional Requirements) 확인\n4. 브랜드 정체성 파악\n5. 우선순위와 제약사항 이해\n6. 모호한 부분은 사용자에게 명확히 질문\n```\n\n**절대 금지:** 문서를 대충 읽고 추측으로 개발\n\n---\n\n### 원칙 2: 체계적인 개발 프로세스\n\n#### Phase 1: 요구사항 분석\n\n```markdown\n## 📋 요구사항 분석\n\n### 브랜드 정체성\n\n- 브랜드 포지셔닝: [핵심 메시지]\n- 톤앤매너: [감성적 특징]\n- 세계관: [IP 구조]\n\n### 핵심 기능\n\n- [기능 1]: [설명]\n- [기능 2]: [설명]\n\n### 사용자 플로우\n\n1. [단계별 사용자 여정]\n\n### 기술적 제약사항\n\n- 성능: [목표]\n- 브라우저 지원: [범위]\n- 접근성: [WCAG 수준]\n\n### 질문사항\n\n- [ ] [모호한 부분 1]\n- [ ] [모호한 부분 2]\n```\n\n---\n\n#### Phase 2: 아키텍처 설계\n\n```markdown\n## 🏗️ 아키텍처 설계\n\n### 디렉토리 구조\n\nsrc/\n├── lib/\n│ ├── components/ # UI 컴포넌트\n│ ├── data/ # 정적 데이터 (Cloud 프로필, 질문 등)\n│ ├── stores/ # 전역 상태 관리\n│ ├── utils/ # 유틸리티 함수\n│ └── types/ # TypeScript 타입\n├── routes/ # SvelteKit 라우팅\n└── app.css # 브랜드 CSS Variables\n\n### 주요 컴포넌트\n\n- [컴포넌트명]: [책임과 역할]\n\n### 상태 관리 전략\n\n- [어떤 상태를 어디서 관리할지]\n\n### 데이터 구조\n\n- [타입 정의]\n```\n\n---\n\n#### Phase 3: 구현\n\n- **컴포넌트 단위 개발**: 작은 단위부터 테스트 가능하게\n- **타입 안정성**: TypeScript 적극 활용\n- **브랜드 준수**: 컬러, 카피, 톤 철저히 지킴\n- **접근성**: ARIA 속성, 키보드 네비게이션\n- **반응형**: 모바일/태블릿/데스크톱 대응\n\n---\n\n## Cloud Between Us 프로젝트 가이드\n\n### 브랜드 CSS Variables\n\n```css\n/* app.css */\n:root {\n\t/* Primary: 감정의 공기 */\n\t--sky-blue: #a7d8f5;\n\n\t/* Accent: 연애의 온기 */\n\t--warm-peach: #ffc6a8;\n\n\t/* Background: 부드러운 공간감 */\n\t--off-white: #fafaf8;\n\n\t/* Text */\n\t--text-dark: #111827;\n\t--text-gray: #6b7280;\n\n\t/* UI */\n\t--radius-sm: 16px;\n\t--radius-md: 24px;\n\t--radius-lg: 32px;\n\n\t/* Shadow */\n\t--shadow-soft: 0 4px 24px rgba(0, 0, 0, 0.06);\n\n\t/* Animation */\n\t--transition-smooth: 0.3s ease-out;\n}\n```\n\n**사용 예시:**\n\n```svelte\n<style>\n\t.button {\n\t\tbackground: var(--warm-peach);\n\t\tborder-radius: var(--radius-md);\n\t\tbox-shadow: var(--shadow-soft);\n\t\ttransition: all var(--transition-smooth);\n\t}\n</style>\n```\n\n---\n\n### 타입 정의\n\n```typescript\n// src/lib/types/cloud.ts\n\nexport type CloudType =\n  | ''sunlit''    // 햇살\n  | ''mist''      // 안개\n  | ''storm''     // 천둥\n  | ''dawn''      // 여명\n  | ''wild''      // 바람\n  | ''shade'';    // 그늘\n\nexport type WeatherPhenomenon =\n  | ''glow''\n  | ''rain''\n  | ''thunder'';\n\nexport interface CloudProfile {\n  type: CloudType;\n  emoji: string;\n  name: string;\n  subtitle: string;\n  keywords: [string, string, string, string];\n  lore: string;\n  traits: {\n    strengths: string[];\n    shadows: string[];\n  };\n}\n\nexport interface CoupleChemistry {\n  user: CloudType;\n  partner: CloudType;\n  skyName: string;           // \"Morning Light Through Fog\"\n  phenomenon: WeatherPhenomenon;\n  narrative: string;\n  warning: string | null;\n}\n\nexport interface TestQuestion {\n  id: number;\n  question: string;\n  options: Array<{\n    text: string;\n    cloudType: CloudType;\n  }>;\n}\n```\n\n---\n\n### 컴포넌트 구조 예시\n\n#### CloudReveal.svelte (결과 페이지 핵심 컴포넌트)\n\n```svelte\n<script lang=\"ts\">\n\timport { fade, fly } from ''svelte/transition'';\n\timport type { CloudProfile } from ''$lib/types/cloud'';\n\n\texport let cloudProfile: CloudProfile;\n\n\tlet revealed = false;\n\n\t// 애니메이션 지연\n\tsetTimeout(() => (revealed = true), 300);\n</script>\n\n<section class=\"cloud-reveal-container\">\n\t{#if revealed}\n\t\t<div class=\"cloud-icon-wrapper\" in:fly={{ y: -50, duration: 600, delay: 200 }}>\n\t\t\t<span class=\"cloud-icon\">{cloudProfile.emoji}</span>\n\t\t</div>\n\n\t\t<div class=\"cloud-info\" in:fade={{ duration: 600, delay: 400 }}>\n\t\t\t<h1 class=\"cloud-name\">{cloudProfile.name}</h1>\n\t\t\t<p class=\"cloud-subtitle\">{cloudProfile.subtitle}</p>\n\n\t\t\t<div class=\"cloud-keywords\">\n\t\t\t\t{#each cloudProfile.keywords as keyword, i}\n\t\t\t\t\t<span class=\"keyword\" in:fade={{ delay: 600 + i * 100 }}>\n\t\t\t\t\t\t{keyword}\n\t\t\t\t\t</span>\n\t\t\t\t\t{#if i < cloudProfile.keywords.length - 1}\n\t\t\t\t\t\t<span class=\"separator\">·</span>\n\t\t\t\t\t{/if}\n\t\t\t\t{/each}\n\t\t\t</div>\n\t\t</div>\n\n\t\t<blockquote class=\"sky-lore\" in:fade={{ duration: 600, delay: 800 }}>\n\t\t\t{@html cloudProfile.lore}\n\t\t</blockquote>\n\t{/if}\n</section>\n\n<style>\n\t.cloud-reveal-container {\n\t\ttext-align: center;\n\t\tpadding: 4rem 2rem;\n\t\tbackground: linear-gradient(to bottom, var(--sky-blue), var(--off-white));\n\t\tborder-radius: var(--radius-lg);\n\t\tbox-shadow: var(--shadow-soft);\n\t}\n\n\t.cloud-icon-wrapper {\n\t\tmargin-bottom: 2rem;\n\t}\n\n\t.cloud-icon {\n\t\tfont-size: 6rem;\n\t\tdisplay: block;\n\t}\n\n\t.cloud-name {\n\t\tfont-size: 2.5rem;\n\t\tfont-weight: 500;\n\t\tletter-spacing: 0.02em;\n\t\tmargin: 0;\n\t\tcolor: var(--text-dark);\n\t}\n\n\t.cloud-subtitle {\n\t\tfont-size: 1.25rem;\n\t\tfont-style: italic;\n\t\tcolor: var(--text-gray);\n\t\tmargin-top: 0.5rem;\n\t}\n\n\t.cloud-keywords {\n\t\tdisplay: flex;\n\t\tjustify-content: center;\n\t\talign-items: center;\n\t\tgap: 0.5rem;\n\t\tmargin-top: 2rem;\n\t\tflex-wrap: wrap;\n\t}\n\n\t.keyword {\n\t\tfont-size: 1rem;\n\t\ttext-transform: uppercase;\n\t\tletter-spacing: 0.1em;\n\t\tcolor: var(--text-gray);\n\t}\n\n\t.separator {\n\t\tcolor: var(--text-gray);\n\t\topacity: 0.5;\n\t}\n\n\t.sky-lore {\n\t\tmargin-top: 3rem;\n\t\tfont-style: italic;\n\t\tline-height: 1.8;\n\t\tcolor: #555;\n\t\tmax-width: 600px;\n\t\tmargin-left: auto;\n\t\tmargin-right: auto;\n\t\tborder-left: 3px solid var(--warm-peach);\n\t\tpadding-left: 1.5rem;\n\t\ttext-align: left;\n\t}\n\n\t@media (max-width: 768px) {\n\t\t.cloud-icon {\n\t\t\tfont-size: 4rem;\n\t\t}\n\n\t\t.cloud-name {\n\t\t\tfont-size: 2rem;\n\t\t}\n\n\t\t.cloud-subtitle {\n\t\t\tfont-size: 1.125rem;\n\t\t}\n\t}\n</style>\n```\n\n---\n\n### 데이터 구조 예시\n\n```typescript\n// src/lib/data/cloudProfiles.ts\n\nimport type { CloudProfile } from ''$lib/types/cloud'';\n\nexport const CLOUD_PROFILES: Record<string, CloudProfile> = {\n  sunlit: {\n    type: ''sunlit'',\n    emoji: ''☀️'',\n    name: ''햇살 (Sunlit)'',\n    subtitle: ''The Warm Leader'',\n    keywords: [''Warmth'', ''Direction'', ''Loyalty'', ''Radiance''],\n    lore: `\n      햇살은 해를 가장 오래 품고 있는 구름이다.<br>\n      이 구름은 빛을 통과시키지 않는다.<br>\n      빛을 머금고 주변을 밝힌다.<br>\n      사랑에 빠지면 길을 잃지 않게 하려 한다.<br>\n      관계를 앞으로 움직이게 만든다.\n    `,\n    traits: {\n      strengths: [\n        ''고백을 먼저 하는 구름'',\n        ''미래를 그리는 구름'',\n        ''\"우리\"라는 말을 자주 쓰는 구름'',\n      ],\n      shadows: [\n        ''빛이 강해질수록 상대의 그림자를 보지 못할 수 있다'',\n        ''리드하려는 마음이 통제가 될 위험'',\n      ],\n    },\n  },\n\n  mist: {\n    type: ''mist'',\n    emoji: ''🌫'',\n    name: ''안개 (Mist)'',\n    subtitle: ''The Sensitive Soul'',\n    keywords: [''Sensitivity'', ''Intuition'', ''Depth'', ''Fragility''],\n    lore: `\n      안개는 해 뜨기 전 공기를 떠다닌다.<br>\n      보이지 않지만 가장 많은 감정을 품고 있다.<br>\n      사랑은 말보다 분위기다.<br>\n      눈빛과 공기의 온도다.\n    `,\n    traits: {\n      strengths: [\n        ''작은 변화도 알아차린다'',\n        ''말 대신 표정을 읽는다'',\n        ''깊이 연결되길 원한다'',\n      ],\n      shadows: [\n        ''감정을 너무 많이 흡수해 스스로 흐려질 수 있다'',\n      ],\n    },\n  },\n\n  // ... 나머지 4가지 타입\n};\n```\n\n---\n\n### 궁합 Matrix\n\n```typescript\n// src/lib/data/chemistryMatrix.ts\n\nimport type { CloudType, CoupleChemistry, WeatherPhenomenon } from ''$lib/types/cloud'';\n\ntype ChemistryKey = `${CloudType}-${CloudType}`;\n\nexport const CHEMISTRY_MATRIX: Record<ChemistryKey, Omit<CoupleChemistry, ''user'' | ''partner''>> = {\n  ''sunlit-mist'': {\n    skyName: ''Morning Light Through Fog'',\n    phenomenon: ''glow'',\n    narrative: `\n      햇살의 따뜻한 빛이 안개의 감정을 천천히 녹인다.\n      안개는 이해받는다고 느끼고,\n      햇살은 보호하고 싶어진다.\n    `,\n    warning: ''빛이 너무 강하면 안개는 사라진다.'',\n  },\n\n  ''sunlit-storm'': {\n    skyName: ''Lightning at Noon'',\n    phenomenon: ''thunder'',\n    narrative: `\n      둘 다 강하다.\n      햇살은 방향을 잡고, 천둥은 속도를 올린다.\n      🔥 케미는 강렬하다.\n      💥 충돌도 강렬하다.\n    `,\n    warning: null,\n  },\n\n  // ... 나머지 13가지 조합\n};\n\nexport function getChemistry(user: CloudType, partner: CloudType): CoupleChemistry {\n  const key: ChemistryKey = `${user}-${partner}`;\n  const reverseKey: ChemistryKey = `${partner}-${user}`;\n\n  const data = CHEMISTRY_MATRIX[key] || CHEMISTRY_MATRIX[reverseKey];\n\n  if (!data) {\n    throw new Error(`Chemistry data not found for ${user} and ${partner}`);\n  }\n\n  return {\n    user,\n    partner,\n    ...data,\n  };\n}\n```\n\n---\n\n## 스벨트 베스트 프랙티스\n\n### 1. 상태 관리\n\n```typescript\n// src/lib/stores/testProgress.ts\n\nimport { writable, derived } from ''svelte/store'';\nimport type { TestQuestion, CloudType } from ''$lib/types/cloud'';\n\ninterface TestState {\n  currentQuestionIndex: number;\n  answers: Record<number, CloudType>;\n  isComplete: boolean;\n}\n\nfunction createTestStore() {\n  const { subscribe, set, update } = writable<TestState>({\n    currentQuestionIndex: 0,\n    answers: {},\n    isComplete: false,\n  });\n\n  return {\n    subscribe,\n\n    answerQuestion: (questionId: number, cloudType: CloudType) => {\n      update(state => ({\n        ...state,\n        answers: { ...state.answers, [questionId]: cloudType },\n      }));\n    },\n\n    nextQuestion: () => {\n      update(state => ({\n        ...state,\n        currentQuestionIndex: state.currentQuestionIndex + 1,\n      }));\n    },\n\n    previousQuestion: () => {\n      update(state => ({\n        ...state,\n        currentQuestionIndex: Math.max(0, state.currentQuestionIndex - 1),\n      }));\n    },\n\n    complete: () => {\n      update(state => ({ ...state, isComplete: true }));\n    },\n\n    reset: () => {\n      set({\n        currentQuestionIndex: 0,\n        answers: {},\n        isComplete: false,\n      });\n    },\n  };\n}\n\nexport const testStore = createTestStore();\n\n// Derived store: 진행률 계산\nexport const progress = derived(\n  testStore,\n  $test => ($test.currentQuestionIndex / TOTAL_QUESTIONS) * 100\n);\n```\n\n---\n\n### 2. 라우팅 & 데이터 로딩\n\n```typescript\n// src/routes/result/+page.ts\n\nimport type { PageLoad } from ''./$types'';\nimport { error } from ''@sveltejs/kit'';\nimport { CLOUD_PROFILES } from ''$lib/data/cloudProfiles'';\nimport { calculateCloudType } from ''$lib/utils/calculateCloud'';\n\nexport const load: PageLoad = async ({ url }) => {\n  // URL 파라미터에서 답변 데이터 가져오기\n  const answersParam = url.searchParams.get(''answers'');\n\n  if (!answersParam) {\n    throw error(400, ''테스트 결과가 없습니다'');\n  }\n\n  try {\n    const answers = JSON.parse(decodeURIComponent(answersParam));\n    const cloudType = calculateCloudType(answers);\n    const profile = CLOUD_PROFILES[cloudType];\n\n    if (!profile) {\n      throw error(404, ''Cloud 프로필을 찾을 수 없습니다'');\n    }\n\n    return {\n      cloudProfile: profile,\n    };\n  } catch (err) {\n    throw error(500, ''결과 처리 중 오류가 발생했습니다'');\n  }\n};\n```\n\n```svelte\n<!-- src/routes/result/+page.svelte -->\n\n<script lang=\"ts\">\n\timport type { PageData } from ''./$types'';\n\timport CloudReveal from ''$lib/components/result/CloudReveal.svelte'';\n\timport PremiumCTA from ''$lib/components/result/PremiumCTA.svelte'';\n\n\texport let data: PageData;\n\n\t$: ({ cloudProfile } = data);\n</script>\n\n<svelte:head>\n\t<title>{cloudProfile.name} - Cloud Between Us</title>\n\t<meta name=\"description\" content={cloudProfile.subtitle} />\n</svelte:head>\n\n<main class=\"result-page\">\n\t<CloudReveal {cloudProfile} />\n\n\t<section class=\"chemistry-preview\">\n\t\t<h2>The Cloud Between You</h2>\n\t\t<!-- 블러 처리된 궁합 결과 -->\n\t\t<div class=\"blurred-chemistry\">\n\t\t\t<p>커플 궁합을 보려면 프리미엄으로 업그레이드하세요</p>\n\t\t</div>\n\t</section>\n\n\t<PremiumCTA />\n</main>\n\n<style>\n\t.result-page {\n\t\tmax-width: 800px;\n\t\tmargin: 0 auto;\n\t\tpadding: 2rem;\n\t}\n\n\t.chemistry-preview {\n\t\tmargin-top: 4rem;\n\t}\n\n\t.blurred-chemistry {\n\t\tfilter: blur(8px);\n\t\tpointer-events: none;\n\t\tuser-select: none;\n\t}\n</style>\n```\n\n---\n\n### 3. 애니메이션\n\n```svelte\n<script lang=\"ts\">\n\timport { fade, fly, scale } from ''svelte/transition'';\n\timport { quintOut } from ''svelte/easing'';\n\n\texport let visible = true;\n</script>\n\n{#if visible}\n\t<div in:fly={{ y: 50, duration: 600, easing: quintOut }} out:fade={{ duration: 300 }}>\n\t\t<h1>Cloud Between Us</h1>\n\t</div>\n{/if}\n```\n\n**브랜드 애니메이션 원칙:**\n\n- ✅ 부드럽게 (0.3-0.6초)\n- ✅ 의도적으로 (목적이 있는 애니메이션만)\n- ❌ 과하지 않게 (우리는 게임이 아니다)\n\n---\n\n### 4. 접근성\n\n```svelte\n<button on:click={handleClick} aria-label=\"Start the love test\" aria-describedby=\"test-description\">\n\tStart the Test ☁️\n</button>\n\n<p id=\"test-description\" class=\"sr-only\">\n\t2분 분량의 간단한 질문에 답하고 당신의 Cloud Type을 확인하세요\n</p>\n\n<style>\n\t.sr-only {\n\t\tposition: absolute;\n\t\twidth: 1px;\n\t\theight: 1px;\n\t\tpadding: 0;\n\t\tmargin: -1px;\n\t\toverflow: hidden;\n\t\tclip: rect(0, 0, 0, 0);\n\t\twhite-space: nowrap;\n\t\tborder: 0;\n\t}\n</style>\n```\n\n---\n\n### 5. 반응형 디자인\n\n```svelte\n<style>\n\t.container {\n\t\tpadding: 4rem 2rem;\n\t}\n\n\t.grid {\n\t\tdisplay: grid;\n\t\tgrid-template-columns: repeat(3, 1fr);\n\t\tgap: 2rem;\n\t}\n\n\t@media (max-width: 1024px) {\n\t\t.grid {\n\t\t\tgrid-template-columns: repeat(2, 1fr);\n\t\t}\n\t}\n\n\t@media (max-width: 768px) {\n\t\t.container {\n\t\t\tpadding: 2rem 1rem;\n\t\t}\n\n\t\t.grid {\n\t\t\tgrid-template-columns: 1fr;\n\t\t\tgap: 1rem;\n\t\t}\n\t}\n</style>\n```\n\n---\n\n## 개발 워크플로우\n\n### 1. 프로젝트 초기화\n\n```bash\n# SvelteKit 프로젝트 생성\nnpm create svelte@latest cloud-between-us\ncd cloud-between-us\nnpm install\n\n# TypeScript, ESLint, Prettier 선택\n\n# Tailwind CSS (선택사항)\nnpm install -D tailwindcss postcss autoprefixer\nnpx tailwindcss init -p\n```\n\n### 2. 환경 변수\n\n```env\n# .env\nPUBLIC_API_URL=https://api.cloudbetweenu\n\ns.com\nPRIVATE_STRIPE_SECRET_KEY=sk_test_...\n```\n\n### 3. 개발 서버 실행\n\n```bash\nnpm run dev\n```\n\n---\n\n## 체크리스트\n\n### 개발 전 확인사항\n\n```\n✅ PRD 전체를 읽고 이해했는가?\n✅ 브랜드 정체성을 파악했는가?\n✅ 세계관 서사를 이해했는가?\n✅ 컬러 시스템을 숙지했는가?\n✅ 톤앤매너를 파악했는가?\n✅ 모호한 요구사항을 명확히 했는가?\n```\n\n### 코드 리뷰 포인트\n\n```\n✅ 타입 안정성 확보\n✅ 브랜드 컬러 정확히 사용\n✅ 브랜드 카피 사용\n✅ 접근성 속성 추가\n✅ 에러 처리\n✅ 로딩 상태\n✅ 반응형 디자인\n✅ 애니메이션 적절성\n```\n\n---\n\n## 마무리\n\n**모든 개발은 이 질문에서 시작한다:**\n\n> Every love has a sky.  \n> What does yours look like?\n\n우리는 숫자를 보여주지 않는다.  \n우리는 **하늘**을 보여준다.\n\n---\n\n**END OF SKILL**\n"},"lastSynced":"2026-03-08T02:13:32.252Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents specializing in Svelte and SvelteKit, seeking to master brand-first development with precise control over UI/UX and brand identity","zh":"适合专门从事 Svelte 和 SvelteKit 的前端代理，寻求掌握以品牌为先的开发，精确控制 UI/UX 和品牌身份","ja":"Svelte と SvelteKit を専門とするフロントエンド エージェントに適しています。ブランド ファースト開発をマスターし、UI/UX とブランド アイデンティティを正確に制御することを目指しています","ko":"Svelte와 SvelteKit을 전문으로 하는 프론트엔드 에이전트에게 적합합니다. 브랜드 먼저 개발을 마스터하고 UI/UX 및 브랜드 아이덴티티를 정확하게 제어하려는 경우에 적합합니다","es":"Ideal para agentes de frontend que se especializan en Svelte y SvelteKit, que buscan dominar el desarrollo orientado a la marca con un control preciso sobre la interfaz de usuario y la experiencia del usuario (UI/UX) y la identidad de la marca","fr":"Idéal pour les agents de frontend qui se spécialisent dans Svelte et SvelteKit, cherchant à maîtriser le développement orienté à la marque avec un contrôle précis sur l''interface utilisateur et l''expérience utilisateur (UI/UX) et l''identité de la marque","de":"Ideal für Frontend-Agenten, die sich auf Svelte und SvelteKit spezialisieren und das Marken-First-Development mit präziser Kontrolle über Benutzeroberfläche und Benutzererfahrung (UI/UX) und Markenidentität beherrschen möchten","pt":"Ideal para Agentes Frontend especializados em Svelte e SvelteKit, buscando dominar o desenvolvimento com prioridade à marca, com controle preciso sobre UI/UX e identidade de marca","ru":"Идеально для агентов Frontend, специализирующихся на Svelte и SvelteKit, стремящихся освоить разработку с приоритетом бренда, с точным контролем над UI/UX и идентичностью бренда","ar":"مثالي لوكلاء الواجهة الأمامية الذين ي专ون في Svelte و SvelteKit، ويسعون إلى إتقان تطوير الأولوية للعلامة التجارية مع التحكم الدقيق في UI/UX و الهوية التجارية"},"recommendation":{"en":"Empowers agents to translate brand identity into code using Svelte and SvelteKit, ensuring consistency in tone, manner, color systems, and emotional language, while maintaining TypeScript type stability and adhering to the ''We don''t measure, we visualize'' philosophy","zh":"赋予代理将品牌身份转化为代码的能力，使用 Svelte 和 SvelteKit，确保语气、方式、色彩系统和情感语言的一致性，同时保持 TypeScript 类型稳定性，并遵循 ''我们不衡量，我们可视化'' 的哲学","ja":"Svelte と SvelteKit を使用して、ブランド アイデンティティをコードに翻訳するエージェントの能力を提供します。トーン、方法、色システム、感情言語の一貫性を確保し、TypeScript の型の安定性を維持し、''私たちは測定せず、視覚化する'' という哲学に従います","ko":"Svelte와 SvelteKit을 사용하여 브랜드 아이덴티티를 코드로 번역할 수 있는 에이전트의 능력을 제공합니다. тон, 방법, 색상 시스템, 감정 언어의 일관성을 보장하면서 TypeScript의 유형 안정성을 유지하고 ''우리는 측정하지 않고 시각화한다''는 철학을遵循합니다","es":"Permite a los agentes traducir la identidad de la marca en código utilizando Svelte y SvelteKit, asegurando la coherencia en el tono, la manera, los sistemas de color y el lenguaje emocional, mientras mantiene la estabilidad de tipos de TypeScript y se adhiere a la filosofía ''No medimos, visualizamos''","fr":"Permet aux agents de traduire l''identité de la marque en code en utilisant Svelte et SvelteKit, en assurant la cohérence dans le ton, la manière, les systèmes de couleur et le langage émotionnel, tout en maintenant la stabilité des types de TypeScript et en adhérant à la philosophie ''Nous ne mesurons pas, nous visualisons''","de":"Ermöglicht es Agenten, die Markenidentität in Code mit Svelte und SvelteKit zu übersetzen, wodurch die Konsistenz in Ton, Art, Farbsystemen und emotionalem Sprachgebrauch gewährleistet wird, während die Typstabilität von TypeScript aufrechterhalten und die Philosophie ''Wir messen nicht, wir visualisieren'' eingehalten wird","pt":"Habilita os agentes a traduzir a identidade da marca em código usando Svelte e SvelteKit, garantindo a consistência no tom, maneira, sistemas de cores e linguagem emocional, mantendo a estabilidade de tipo do TypeScript e aderindo à filosofia ''Não medimos, visualizamos''","ru":"Наделяет агентов возможностью переводить идентичность бренда в код, используя Svelte и SvelteKit, обеспечивая согласованность тона, манеры, цветовых систем и эмоционального языка, сохраняя стабильность типов TypeScript и придерживаясь философии ''Мы не измеряем, мы визуализируем''","ar":"تمكّن الوكلاء من ترجمة هوية العلامة التجارية إلى رمز باستخدام Svelte و SvelteKit، مما يضمن الاتساق في النبرة و الطريقة و أنظمة الألوان و اللغة العاطفية، مع الحفاظ على استقرار أنواع TypeScript و الالتزام بفلسفة ''لا نَقيس، نُصوّر''"},"useCases":{"en":["Implementing brand-first development principles in Svelte applications","Translating brand identity into UI/UX components using SvelteKit","Ensuring consistency in tone, manner, and emotional language across the application","Optimizing user experience (UX) and business logic in Svelte-based projects"],"zh":["在 Svelte 应用程序中实施以品牌为先的开发原则","使用 SvelteKit 将品牌身份转化为 UI/UX 组件","在整个应用程序中确保语气、方式和情感语言的一致性","在 Svelte 基础项目中优化用户体验 (UX) 和业务逻辑"],"ja":["Svelte アプリケーションでブランド ファースト開発の原則を実施する","SvelteKit を使用してブランド アイデンティティを UI/UX コンポーネントに翻訳する","アプリケーション全体でトーン、方法、感情言語の一貫性を確保する","Svelte ベースのプロジェクトでユーザー体験 (UX) とビジネス ロジックを最適化する"],"ko":["Svelte 애플리케이션에서 브랜드 먼저 개발 원칙을 구현한다","SvelteKit을 사용하여 브랜드 아이덴티티를 UI/UX 컴포넌트로 번역한다","전체 애플리케이션에서 톤, 방법, 감정 언어의 일관성을 보장한다","Svelte 기반 프로젝트에서 사용자 경험 (UX) 및 비즈니스 논리를 최적화한다"],"es":["Implementar principios de desarrollo orientado a la marca en aplicaciones Svelte","Traducir la identidad de la marca en componentes de UI/UX utilizando SvelteKit","Asegurar la coherencia en el tono, la manera y el lenguaje emocional en toda la aplicación","Optimizar la experiencia del usuario (UX) y la lógica empresarial en proyectos basados en Svelte"],"fr":["Mettre en œuvre les principes de développement orienté à la marque dans les applications Svelte","Traduire l''identité de la marque en composants d''interface utilisateur et d''expérience utilisateur (UI/UX) en utilisant SvelteKit","Assurer la cohérence dans le ton, la manière et le langage émotionnel dans toute l''application","Optimiser l''expérience utilisateur (UX) et la logique métier dans les projets basés sur Svelte"],"de":["Umsetzen von Marken-First-Development-Prinzipien in Svelte-Anwendungen","Übersetzen der Markenidentität in Benutzeroberflächen- und Benutzererfahrungskomponenten (UI/UX) mit SvelteKit","Sicherstellen der Konsistenz in Ton, Art und emotionalem Sprachgebrauch in der gesamten Anwendung","Optimieren der Benutzererfahrung (UX) und der Geschäftslogik in Svelte-basierten Projekten"],"pt":["Implementação de princípios de desenvolvimento com prioridade à marca em aplicações Svelte","Tradução da identidade da marca em componentes UI/UX usando SvelteKit","Garantia de consistência no tom, maneira e linguagem emocional em toda a aplicação","Otimização da experiência do usuário (UX) e lógica de negócios em projetos baseados em Svelte"],"ru":["Реализация принципов разработки с приоритетом бренда в приложениях Svelte","Перевод идентичности бренда в компоненты UI/UX с помощью SvelteKit","Обеспечение согласованности тона, манеры и эмоционального языка на протяжении всего приложения","Оптимизация пользовательского опыта (UX) и бизнес-логики в проектах на основе Svelte"],"ar":["تنفيذ مبادئ التطوير الأولوية للعلامة التجارية في تطبيقات Svelte","翻訳 هوية العلامة التجارية إلى مكونات UI/UX باستخدام SvelteKit","ضمان الاتساق في النبرة و الطريقة و اللغة العاطفية في جميع التطبيق","تحسين تجربة المستخدم (UX) و منطق الأعمال في مشاريع مبنية على Svelte"]},"limitations":{"en":["Requires advanced knowledge of Svelte and SvelteKit (5+ years of experience)","Dependent on TypeScript for type stability","Focused on frontend development, not suitable for backend or full-stack development"],"zh":["需要高级的 Svelte 和 SvelteKit 知识（5 年以上的经验）","依赖于 TypeScript 来实现类型稳定性","专注于前端开发，不适合后端或全栈开发"],"ja":["Svelte と SvelteKit に関する高度な知識が必要（5 年以上の経験）","TypeScript に依存して型の安定性を実現する","フロントエンド開発に焦点を当てているため、バックエンドまたはフルスタック開発には適していない"],"ko":["고급 Svelte 및 SvelteKit 지식 필요(5년 이상의 경험)","타입 안정성을 구현하기 위해 TypeScript에 의존한다","프론트엔드 개발에 중점을 두고 있으므로 백엔드 또는 풀스택 개발에는 적합하지 않음"],"es":["Requiere conocimientos avanzados de Svelte y SvelteKit (5+ años de experiencia)","Depende de TypeScript para la estabilidad de tipos","Se centra en el desarrollo de frontend, no es adecuado para el desarrollo de backend o full-stack"],"fr":["Nécessite des connaissances avancées de Svelte et SvelteKit (5+ ans d''expérience)","Dépend de TypeScript pour la stabilité des types","Se concentre sur le développement de frontend, n''est pas adapté pour le développement de backend ou full-stack"],"de":["Benötigt fortgeschrittene Kenntnisse von Svelte und SvelteKit (5+ Jahre Erfahrung)","Hängt von TypeScript für die Typstabilität ab","Konzentriert sich auf die Entwicklung von Frontend, nicht geeignet für die Entwicklung von Backend oder Full-Stack"],"pt":["Requer conhecimento avançado de Svelte e SvelteKit (5+ anos de experiência)","Dependente do TypeScript para estabilidade de tipo","Focado no desenvolvimento frontend, não adequado para desenvolvimento backend ou full-stack"],"ru":["Требует глубокого знания Svelte и SvelteKit (5+ лет опыта)","Зависит от TypeScript для стабильности типов","Ориентирован на разработку frontend, не подходит для разработки backend или full-stack"],"ar":["يتطلب معرفة متقدمة ب Svelte و SvelteKit (5+ سنوات من الخبرة)","يعتمد على TypeScript لاستقرار النوع","موجه لتطوير الواجهة الأمامية، لا يصلح لتطوير الخلفية أو كامل الحزمة"]},"version":4},"contentHash":"b3fb2590e50e29f8d4b752c3a18c4b32397ad6e349277db2699bcad770cc5586","qualityScore":33}');
