INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('lees-factory/cloud-between-us-client/svelte-dev', 'svelte-dev', 'lees-factory', 'cloud-between-us-client', 'community', 'svelte-dev lees-factory cloud-between-us-client community svelte-dev is a skill for senior frontend developers to master brand-first development using Svelte and SvelteKit, ensuring brand identity is reflected in every line of code. Svelte-dev 是一个专注于品牌优先开发的技能，帮助开发者将品牌定位应用于代码实现 Svelte-dev はブランド優先開発に特化したスキルで、開発者がブランドのアイデンティティをコードに反映させることができる Svelte-dev는 브랜드 우선 개발을 위한 전문 개발 스킬로, 개발자가 브랜드 정체성을 코드로 번역하는 능력을 제공 Svelte-dev es un conjunto de habilidades para desarrolladores que buscan mejorar su código con Svelte y SvelteKit. Svelte-dev est un ensemble de compétences pour les développeurs qui souhaitent améliorer leur code avec Svelte et SvelteKit. Svelte-dev ist ein Satz von Fähigkeiten für Entwickler, die ihren Code mit Svelte und SvelteKit verbessern möchten. O Svelte-Dev é uma habilidade de desenvolvimento de frontend que permite criar aplicações personalizadas com Svelte e SvelteKit. Com foco na identidade da marca, ele garante que todo o código refletirá a essência da marca. Svelte-Dev — это навык разработки frontend, который позволяет создавать кастомные приложения с помощью Svelte и SvelteKit. С фокусом на идентичности бренда, он гарантирует, что весь код будет отражать суть бренда. سفت-ديف هو مهارة تطوير واجهة المستخدم الأمامية التي تمكن من إنشاء تطبيقات مخصصة باستخدام Svelte و SvelteKit. مع التركيز على هوية العلامة التجارية، يضمن أن 모든 كود سيعكس جوهر العلامة التجارية. how to use svelte-dev svelte-dev setup guide svelte-dev vs React svelte-dev install what is svelte-dev svelte-dev alternative brand-first development with svelte-dev svelte-dev for AI agents svelte-dev and TypeScript svelte-dev tutorial Svelte-dev 品牌优先开发 代码实现 用户体验 Svelte SvelteKit TypeScript 品牌定位 代码安全 Implements brand-first development using Svelte and SvelteKit Translates brand identity into code, including tone, manner, and color systems Ensures TypeScript type stability and security Visualizes data with the ''We don''t measure, we visualize'' philosophy Implements IP worldviews and narrative structures in UI/UX svelte-dev is a specialized skill for translating brand identity into code using Svelte and SvelteKit, focusing on brand-first development and IP worldviews.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tae2089/finance-agent-skills/stock-investment-analysis', 'community', 'tae2089', 'finance-agent-skills', 'tae2089/finance-agent-skills', 'stock-investment-analysis', 0, 0, 33, '2026-03-08T01:57:15.631Z', '2026-03-08T02:13:34.862Z', 'f994ae87eef0dce858b4dab353d1bae47482b4eb62da83356adf87c79fe819fa', '{"id":"tae2089/finance-agent-skills/stock-investment-analysis","name":"stock-investment-analysis","description":{"en":"The stock-investment-analysis skill performs enterprise analysis for informed stock buying and selling decisions, benefiting investors and financial analysts.","zh":"股票投资分析工具提供企业分析和股票买卖建议，帮助您做出明智的投资决策","ja":"株式投資分析AIエージェントは企業分析と株式の売買アドバイスを提供し、賢明な投資決定をサポートします","ko":"주식 투자 분석 스킬은 기업 분석과 주식 매수/매도 의사결정을 지원하여 현명한 투자 결정에 도움을 줍니다","es":"El análisis de inversiones en acciones es un proceso que implica evaluar el desempeño de una empresa para tomar decisiones informadas sobre compras y ventas de acciones","fr":"L''analyse d''investissement en actions est un processus qui consiste à évaluer la performance d''une entreprise pour prendre des décisions éclairées sur les achats et les ventes d''actions","de":"Die Analyse von Aktienanlagen ist ein Prozess, der die Bewertung der Leistung eines Unternehmens beinhaltet, um fundierte Entscheidungen über den Kauf und Verkauf von Aktien zu treffen","pt":"O skill de análise de investimentos em ações ajuda a tomar decisões informadas sobre compra e venda de ações utilizando análise de empresas e inteligência artificial","ru":"Навык анализа акций помогает принимать обоснованные решения о покупке и продаже акций с помощью анализа компаний и ИИ","ar":"مهارة تحليل الاستثمار في الأسهم تساعد على اتخاذ قرارات مدروسة بشأن الشراء والبيع باستخدام تحليل الشركات والذكاء الاصطناعي"},"seo":{"title":{"en":"stock-investment-analysis: AI-Powered Stock Analysis Setu...","zh":"股票投资分析工具：使用指南","ja":"株式投資分析AIエージェントの設定方法","ko":"주식 투자 분석 스킬 사용법 및 설정 가이드","es":"Guía de configuración para análisis de inversiones en acc...","fr":"Configurer l''analyse d''investissement en actions","de":"Einrichtungsleitfaden für Aktien-Anlageanalyse","pt":"Guia de Análise de Investimentos em Ações com Ferramentas...","ru":"Настройка анализа акций для инвестиций с помощью ИИ Агентов","ar":"دليل تحليل الاستثمار في الأسهم باستخدام أدوات الذكاء الاص..."},"description":{"en":"Unlock data-driven stock investment decisions with our AI agent skill, featuring real-time analysis and comparison tools. Get started now!","zh":"了解股票投资分析工具的功能和特点，掌握股票买卖的时机和策略","ja":"株式投資分析AIエージェントの機能と特徴を紹介します。株式の売買時機と戦略を把握しましょう","ko":"주식 투자 분석 스킬의 기능과 특징을 알아보세요. 주식 매수/매도 타이밍과 전략을 정립하세요","es":"Aprende a utilizar herramientas de análisis de inversiones en acciones para tomar decisiones informadas sobre compras y ventas de acciones","fr":"Découvrez comment utiliser les outils d''analyse d''investissement en actions pour prendre des décisions éclairées sur les achats et les ventes d''actions","de":"Erfahren Sie, wie Sie Tools für die Analyse von Aktienanlagen verwenden können, um fundierte Entscheidungen über den Kauf und Verkauf von Aktien zu treffen","pt":"Aprenda a utilizar ferramentas de análise de investimentos em ações para tomar decisões informadas com a ajuda da inteligência artificial","ru":"Используйте ИИ Агенты для анализа акций и принятия обоснованных решений при инвестировании","ar":"تعلم كيفية استخدام أدوات تحليل الاستثمار في الأسهم لاتخاذ قرارات مدروسة مع مساعدة الذكاء الاصطناعي"},"definition":{"en":"stock-investment-analysis is a skill that analyzes stocks for investment decisions, providing insights on buy/sell timing, stock comparisons, and earnings analysis.","zh":"股票投资分析工具是一种使用数据分析和机器学习算法来分析股票市场和提供投资建议的软件","ja":"株式投資分析AIエージェントは、データ分析と機械学習アルゴリズムを使用して株式市場を分析し、投資アドバイスを提供するソフトウェアです","ko":"주식 투자 분석 스킬은 데이터 분석과 기계 학습 알고리즘을 사용하여 주식 시장과 기업을 분석하고 투자 의사결정을 지원하는 소프트웨어입니다","es":"Análisis de inversiones en acciones es una técnica que utiliza datos financieros y de mercado para evaluar el potencial de una acción","fr":"L''analyse d''investissement en actions est une technique qui utilise des données financières et de marché pour évaluer le potentiel d''une action","de":"Die Analyse von Aktienanlagen ist eine Technik, die Finanz- und Marktdaten verwendet, um das Potenzial einer Aktie zu bewerten","pt":"Análise de investimentos em ações é o processo de avaliar empresas para tomar decisões informadas sobre compra e venda de ações","ru":"Анализ акций - это процесс оценки компаний для принятия обоснованных решений о покупке и продаже акций","ar":"تحليل الاستثمار في الأسهم هو عملية تقييم الشركات لاتخاذ قرارات مدروسة بشأن الشراء والبيع"},"features":{"en":["Performs enterprise analysis for stock buying and selling decisions","Provides real-time stock comparisons, such as Kakao vs Naver","Analyzes earnings reports, including surprise earnings announcements","Evaluates chart patterns, including cloud chart analysis","Supports various stock analysis scenarios, including buy/sell timing and stock portfolio review"],"zh":["企业财务分析","股票买卖建议","市场趋势分析","数据可视化","机器学习算法"],"ja":["企業の財務分析","株式の売買アドバイス","市場の趨勢分析","データの可視化","機械学習アルゴリズム"],"ko":["기업 실적 분석","주식 매수/매도 의사결정","시장趨勢 분석","데이터 시각화","기계 학습 알고리즘"],"es":["Análisis de tendencias de mercado","Evaluación de la salud financiera de una empresa","Identificación de oportunidades de compra y venta","Análisis de indicadores técnicos","Comparación de rendimiento de diferentes acciones"],"fr":["Analyse des tendances du marché","Évaluation de la santé financière d''une entreprise","Identification des opportunités d''achat et de vente","Analyse des indicateurs techniques","Comparaison des performances de différentes actions"],"de":["Markttrend-Analyse","Bewertung der Finanzgesundheit eines Unternehmens","Identifizierung von Kauf- und Verkaufschancen","Analyse von technischen Indikatoren","Vergleich der Leistung verschiedener Aktien"],"pt":["Análise de empresas para tomada de decisões informadas","Utilização de inteligência artificial para análise de tendências","Comparação de ações para identificar oportunidades de investimento","Análise de relatórios financeiros para avaliar desempenho de empresas","Verificação de gráficos para identificar padrões de mercado"],"ru":["Анализ компаний для принятия обоснованных решений","Использование ИИ для анализа тенденций","Сравнение акций для выявления возможностей инвестирования","Анализ финансовых отчетов для оценки эффективности компаний","Проверка графиков для выявления закономерностей рынка"],"ar":["تحليل الشركات لاتخاذ قرارات مدروسة","استخدام الذكاء الاصطناعي لتحليل الاتجاهات","مقارنة الأسهم لتحديد فرص الاستثمار","تحليل التقارير المالية لتقييم أداء الشركات","التحقق من الرسومات لتحديد أنماط السوق"]},"keywords":{"en":["how to use stock-investment-analysis","stock-investment-analysis setup guide","stock investment analysis tools","stock-investment-analysis vs technical analysis","stock-investment-analysis install","what is stock-investment-analysis","stock-investment-analysis alternative","stock investment analysis for beginners","stock-investment-analysis tutorial","stock investment analysis software"],"zh":["股票投资分析","企业分析","股票买卖建议","数据分析","机器学习","投资决策","股票市场分析"],"ja":["株式投資分析","企業分析","株式の売買アドバイス","データ分析","機械学習","投資決定","株式市場分析"],"ko":["주식 투자 분석","기업 실적 분석","주식 매수/매도 의사결정","데이터 분석","기계 학습","투자 결정","주식 시장 분석"],"es":["análisis de inversiones en acciones","herramientas de análisis de acciones","inversión en acciones","análisis técnico de acciones","análisis fundamental de acciones","mejores prácticas para la inversión en acciones"],"fr":["analyse d''investissement en actions","outils d''analyse d''actions","investissement en actions","analyse technique d''actions","analyse fondamentale d''actions","meilleures pratiques pour l''investissement en actions"],"de":["Analyse von Aktienanlagen","Tools für die Analyse von Aktien","Investition in Aktien","technische Analyse von Aktien","fundamentale Analyse von Aktien","Best Practices für die Investition in Aktien"],"pt":["análise de investimentos em ações","ferramentas de inteligência artificial","análise de empresas","compra e venda de ações","relatórios financeiros","gráficos de ações","oportunidades de investimento"],"ru":["анализ акций","ИИ Агенты","анализ компаний","покупка и продажа акций","финансовые отчеты","графики акций","возможности инвестирования"],"ar":["تحليل الاستثمار في الأسهم","أدوات الذكاء الاصطناعي","تحليل الشركات","الشراء والبيع","التقارير المالية","الرسومات الأسهم","فرص الاستثمار"]}},"owner":"tae2089","repo":"finance-agent-skills","repoPath":"tae2089/finance-agent-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.631Z","topics":[],"category":"community","skillMd":{"name":"stock-investment-analysis","description":"주식 및 ETF 투자를 위한 종합 분석 스킬. 매수/매도 판단을 위한 분석을 수행합니다. 다음 상황에서 사용 - (1) 특정 종목/ETF 매수 검토 요청, (2) 보유 종목 매도 타이밍 분석, (3) 종목 비교 분석, (4) 투자 아이디어 검증, (5) 실적 발표 후 분석, (6) ETF 추세 매매 분석, (7) ETF 괴리율 확인","bodyPreview":"# 주식 투자 분석 스킬\n\n주식 매수/매도 의사결정을 위한 기업 분석을 수행합니다.\n\n## 언제 사용하나요?\n\n### 이 스킬을 사용해야 하는 경우\n\n| 상황          | 예시 질문                                                    |\n| ------------- | ------------------------------------------------------------ |\n| 매수 검토     | \"삼성전자 지금 사도 될까?\", \"NVDA 분석해줘\"                  |\n| 매도 타이밍   | \"네이버 언제 팔아야 할까?\", \"보유 종목 점검해줘\"             |\n| 종목 비교     | \"카카오 vs 네이버 뭐가 나아?\", \"2차전지 종목 비교\"           |\n| 실적 분석     | \"삼성전자 실적 발표됐는데 어때?\", \"어닝 서프라이즈 분석\"     |\n| 차트 검증     | \"이 종목 구름대","body":"# 주식 투자 분석 스킬\n\n주식 매수/매도 의사결정을 위한 기업 분석을 수행합니다.\n\n## 언제 사용하나요?\n\n### 이 스킬을 사용해야 하는 경우\n\n| 상황          | 예시 질문                                                    |\n| ------------- | ------------------------------------------------------------ |\n| 매수 검토     | \"삼성전자 지금 사도 될까?\", \"NVDA 분석해줘\"                  |\n| 매도 타이밍   | \"네이버 언제 팔아야 할까?\", \"보유 종목 점검해줘\"             |\n| 종목 비교     | \"카카오 vs 네이버 뭐가 나아?\", \"2차전지 종목 비교\"           |\n| 실적 분석     | \"삼성전자 실적 발표됐는데 어때?\", \"어닝 서프라이즈 분석\"     |\n| 차트 검증     | \"이 종목 구름대 돌파했는데 진짜야?\", \"RSI 보고 매수해도 돼?\" |\n| 저점 매수     | \"많이 빠졌는데 반등할까?\", \"바닥인지 확인해줘\"               |\n| 고점 확인     | \"지금 고점 아니야?\", \"더 오를 수 있어?\"                      |\n| ETF 분석      | \"TIGER 미국S&P500 분석해줘\", \"QQQ 지금 추세 어때?\"           |\n| ETF 추세 매매 | \"KODEX 200 이동평균선 분석해줘\", \"SPY 매수 타이밍이야?\"      |\n| ETF 괴리율    | \"이 ETF 괴리율 괜찮아?\", \"NAV 대비 비싼 거 아니야?\"          |\n\n### 이 스킬을 사용하지 않아도 되는 경우\n\n| 상황           | 대안                    |\n| -------------- | ----------------------- |\n| 단순 주가 확인 | 웹 검색으로 빠르게 확인 |\n| 기업 일반 정보 | 일반 대화로 답변        |\n| 경제 뉴스 요약 | 웹 검색 후 요약         |\n| 투자 기초 개념 | 일반 설명으로 충분      |\n\n### 분석 깊이 선택\n\n| 요청 유형                      | 분석 수준   | 출력 형식                          |\n| ------------------------------ | ----------- | ---------------------------------- |\n| \"간단히 봐줘\", \"빠르게 체크\"   | 핵심 지표만 | 대화형 응답                        |\n| \"분석해줘\", \"검토해줘\"         | 표준 분석   | 대화형 + 요약                      |\n| \"상세 분석\", \"보고서 만들어줘\" | 전체 분석   | `./record/{종목명}/{날짜}.md` 저장 |\n| \"종목.md 기준으로 전체 분석\"   | 배치 분석   | 종목별 보고서 생성                 |\n\n---\n\n## 분석 시작\n\n### 1. 종목.md 파일 읽기\n\n분석 시작 전 `종목.md` 파일을 먼저 읽어 분석 대상 목록 확인\n\n**종목.md 형식:**\n\n```markdown\n# 분석 대상 종목\n\n| 회사명           | 종목코드 |\n| ---------------- | -------- |\n| 삼성전자         | 005930   |\n| 네이버           | 035420   |\n| KODEX 200        | 069500   |\n| TIGER 미국S&P500 | 360750   |\n| AAPL             | AAPL     |\n| SPY              | SPY      |\n| QQQ              | QQQ      |\n```\n\n→ ETF는 자동으로 **Step 1-ETF** 워크플로우 적용\n\n### 2. 순차 분석 진행\n\n```\n1. 종목.md 읽기\n2. 첫 번째 종목부터 순서대로 분석\n3. 각 종목 분석 완료 후 ./record/{종목명}/{날짜}.md 저장\n4. 다음 종목으로 이동\n5. 모든 종목 완료 시 요약 출력\n```\n\n### 3. 분석 완료 후 요약\n\n```markdown\n## 분석 완료 요약\n\n### 개별 주식\n\n| 종목     | 현재가    | PER  | 기술적 판단 | 의견 | 보고서                        |\n| -------- | --------- | ---- | ----------- | ---- | ----------------------------- |\n| 삼성전자 | 00,000원  | 00.0 | 구름대 상단 | 긍정 | ./record/삼성전자/20260118.md |\n| 네이버   | 000,000원 | 00.0 | RSI 과매수  | 주의 | ./record/네이버/20260118.md   |\n\n### ETF\n\n| ETF명     | 현재가   | 괴리율 | 일봉 추세 | 주봉 추세 | 의견     | 보고서                         |\n| --------- | -------- | ------ | --------- | --------- | -------- | ------------------------------ |\n| KODEX 200 | 00,000원 | +0.1%  | 정배열    | 정배열    | 매수적합 | ./record/KODEX 200/20260118.md |\n| SPY       | $000.00  | -0.2%  | 정배열    | 횡보      | 단기매수 | ./record/SPY/20260118.md       |\n```\n\n## 사용 도구\n\n### 1. 웹 검색 (google_web_search)\n\n실시간 주가, 뉴스, 실적 정보 수집에 사용\n\n### 2. 웹 페이지 수집 (web_fetch)\n\n상세 재무 데이터, 공시 내용 확인에 사용\n\n### 3. 보고서 생성 (Markdown)\n\n분석 결과를 `.md` 파일로 저장하여 제공\n\n- 간단 분석: 대화형 응답\n- 상세 분석: `./record/{종목명}/{YYYYMMDD}.md` 생성\n  - 예: `./record/삼성전자/20260118.md`\n  - 종목별 폴더에 날짜별로 기록 누적\n\n## 데이터 소스 (우선순위순)\n\n### 한국 주식\n\n| 용도      | 소스        | URL                                                   | 수집 정보                         |\n| --------- | ----------- | ----------------------------------------------------- | --------------------------------- |\n| 주가/시세 | 네이버 금융 | `finance.naver.com/item/main.naver?code={종목코드}`   | 현재가, 시총, 52주 고저, 거래량   |\n| 재무제표  | 네이버 금융 | `finance.naver.com/item/coinfo.naver?code={종목코드}` | 매출, 영업이익, 순이익, 부채비율  |\n| 투자지표  | 네이버 금융 | 위와 동일                                             | PER, PBR, ROE, 배당수익률         |\n| 공시      | DART        | `dart.fss.or.kr`                                      | 사업보고서, 분기보고서, 주요 공시 |\n| 컨센서스  | 네이버 금융 | `finance.naver.com/item/coinfo.naver?code={종목코드}` | 애널리스트 목표가, 투자의견       |\n| 뉴스      | 웹 검색     | -                                                     | 최신 이슈, 공시 해석              |\n\n### 미국 주식\n\n| 용도      | 소스          | URL                                                         | 수집 정보                                  |\n| --------- | ------------- | ----------------------------------------------------------- | ------------------------------------------ |\n| 주가/시세 | Yahoo Finance | `finance.yahoo.com/quote/{티커}`                            | 현재가, 시총, 52주 범위                    |\n| 재무제표  | Yahoo Finance | `finance.yahoo.com/quote/{티커}/financials`                 | Income Statement, Balance Sheet, Cash Flow |\n| 투자지표  | Yahoo Finance | `finance.yahoo.com/quote/{티커}/key-statistics`             | PER, PBR, EV/EBITDA, 마진                  |\n| 공시      | SEC EDGAR     | `sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK={티커}` | 10-K, 10-Q, 8-K                            |\n| 뉴스      | 웹 검색       | -                                                           | 실적 발표, 애널리스트 코멘트               |\n\n### 한국 ETF\n\n| 용도        | 소스        | URL                                                   | 수집 정보                   |\n| ----------- | ----------- | ----------------------------------------------------- | --------------------------- |\n| 시세/괴리율 | 네이버 금융 | `finance.naver.com/item/main.naver?code={종목코드}`   | 현재가, NAV, 괴리율, 거래량 |\n| 구성종목    | 네이버 금융 | `finance.naver.com/item/coinfo.naver?code={종목코드}` | 상위 보유종목, 비중         |\n| 기초지수    | 웹 검색     | -                                                     | 추종 지수, 운용 방식        |\n| 차트        | 네이버 금융 | -                                                     | 일봉/주봉 이동평균선        |\n\n### 미국 ETF\n\n| 용도     | 소스          | URL                                       | 수집 정보                |\n| -------- | ------------- | ----------------------------------------- | ------------------------ |\n| 시세     | Yahoo Finance | `finance.yahoo.com/quote/{티커}`          | 현재가, NAV, 52주 범위   |\n| 구성종목 | Yahoo Finance | `finance.yahoo.com/quote/{티커}/holdings` | 상위 보유종목, 섹터 비중 |\n| 괴리율   | ETF.com       | `etf.com/{티커}`                          | Premium/Discount         |\n| 차트     | Yahoo Finance | -                                         | 이동평균선, 기술적 지표  |\n\n## 분석 워크플로우\n\n### 워크플로우 요약\n\n```\n종목.md 읽기\n     ↓\nStep 0: 종목 유형 판별\n     ↓\n  ┌──────────┴──────────┐\n  ↓                     ↓\n[ETF]               [개별 주식]\n  ↓                     ↓\nStep 1-ETF          Step 1: 기본 정보\n  │                     ↓\n  │                 Step 2: 재무 데이터\n  │                     ↓\n  │                 Step 3: 기술적 분석\n  │                     ↓\n  │                 Step 4: 심층 분석\n  ↓                     ↓\nStep 5-ETF          Step 5: 보고서 생성\n  │                     │\n  └──────────┬──────────┘\n             ↓\n    ./record/{종목명}/{날짜}.md 저장\n             ↓\n        다음 종목으로\n```\n\n### Step 0: 종목 유형 판별\n\n```\nETF 판별 기준:\n- 종목명에 \"ETF\" 포함\n- 티커가 SPY, QQQ, VOO 등 ETF 티커\n- 운용사 키워드: KODEX, TIGER, KBSTAR, ACE, Vanguard, iShares 등\n\n→ ETF인 경우: Step 1-ETF로 이동\n→ 개별 주식인 경우: Step 1로 이동\n```\n\n### Step 1-ETF: ETF 전용 분석\n\n**⚠️ 필수 참조:** `references/etf-analysis.md`\n\n```\n1. 기초지수/구성종목 확인\n   - google_web_search: \"{ETF명} 기초지수 구성종목\"\n   - google_web_search: \"{ETF명} 상위 보유종목\"\n\n2. 이동평균선 추세 분석 (일봉)\n   - google_web_search: \"{ETF명} 일봉 차트\"\n   - 체크: 정배열/역배열, 20일선 위치, 기울기\n\n3. 이동평균선 추세 분석 (주봉)\n   - google_web_search: \"{ETF명} 주봉 차트\"\n   - 체크: 20주선 위치, 중기 추세 방향\n\n4. 괴리율 확인\n   - google_web_search: \"{ETF명} 괴리율 NAV\"\n   - 체크: ±1% 이내 적정, ±2% 이상 주의\n\n추세 매매 판단:\n□ 일봉 정배열 + 주봉 정배열 → ✅ 매수 적합\n□ 일봉 정배열 + 주봉 횡보 → 단기만 매수\n□ 일봉 역배열 + 주봉 정배열 → 눌림목 대기\n□ 일봉 역배열 + 주봉 역배열 → ❌ 매수 금지\n```\n\n→ ETF 분석 완료 후 **Step 5-ETF**로 이동\n\n[한국 주식]\n\n1. google_web_search: \"{종목명} 주가\"\n2. google_web_search: 네이버 금융 종목 페이지\n3. google_web_search: \"{종목명} 최근 뉴스\"\n\n[미국 주식]\n\n1. google_web_search: \"{티커} stock price\"\n2. google_web_search: Yahoo Finance 종목 페이지\n3. google_web_search: \"{티커} news\"\n\n```\n\n### Step 2: 재무 데이터 수집 (개별 주식)\n\n**참조:** `references/financial-analysis.md` (재무제표 해석 가이드)\n\n```\n\n[한국 주식]\n\n1. web_fetch: 네이버 금융 기업실적분석 탭\n2. google_web_search: \"{종목명} {최근분기} 실적\"\n3. google_web_search: \"{종목명} DART 사업보고서\" (필요시)\n\n[미국 주식]\n\n1. web_fetch: Yahoo Finance Financials 탭\n2. web_fetch: Yahoo Finance Key Statistics 탭\n3. google_web_search: \"{티커} earnings {최근분기}\"\n\n```\n\n### Step 3: 기술적 분석 (개별 주식 - 구름대 돌파 검증)\n\n**⚠️ 분석 전 필수:** `references/technical-analysis.md` 읽기\n\n```\n\n1. google_web_search: \"{종목명} 일목균형표\"\n2. google_web_search: \"{종목명} RSI\"\n3. google_web_search: \"{종목명} 거래량 차트\"\n\n체크 항목 (technical-analysis.md 기준):\n□ 구름대 위치 (상단/내부/하단)\n□ RSI 수준 (과매수 70+ 주의)\n□ RSI 다이버전스 여부 (고점 매수 방지 핵심!)\n□ 거래량 동반 여부 (20일 평균 대비 1.5배+)\n□ 돌파 신뢰도 점수 산출 (9점 만점)\n\n```\n\n**고점 매수 방지 필수 체크:**\n\n- RSI 70 이상 → 매수 금지\n- RSI 하락 다이버전스 (주가↑ + RSI↓) → 매수 금지\n- 거래량 미동반 돌파 → 가짜 돌파 의심\n\n### Step 4: 심층 분석 (개별 주식)\n\n**참조:** `references/investment-checklist.md`, `references/investment-metrics.md`\n\n```\n\n1. google_web_search: \"{종목명} 경쟁사 비교\"\n2. google_web_search: \"{종목명} 애널리스트 리포트\"\n3. google_web_search: \"{종목명} 목표주가\"\n4. google_web_search: \"{산업명} 전망 {연도}\"\n\n```\n\n### Step 5: 보고서 생성 (개별 주식)\n\n**필수:** `references/report-template.md` 읽고 **개별 주식 템플릿** 사용\n\n```\n\n1. report-template.md 읽기\n2. 수집 데이터로 각 섹션 채우기\n3. 기술적 분석 섹션은 technical-analysis.md 기준으로 작성\n4. ./record/{종목명}/{YYYYMMDD}.md 저장\n\n```\n\n### Step 5-ETF: ETF 보고서 생성\n\n**필수:** `references/report-template.md` 읽고 **ETF 전용 템플릿** 사용\n\n```\n\n1. report-template.md 읽기 (하단의 \"ETF 전용 템플릿\" 섹션 사용)\n2. 기초지수, 구성종목 정보 채우기\n3. 일봉/주봉 이동평균선 분석 결과 작성\n4. 괴리율 분석 결과 작성\n5. ./record/{ETF명}/{YYYYMMDD}.md 저장\n\n```\n\n**ETF 보고서 필수 항목:**\n\n- [ ] 기초지수 및 상위 10개 구성종목\n- [ ] 일봉 이동평균선 (5/20/60/120일) 정배열/역배열\n- [ ] 주봉 이동평균선 (5/20주) 추세 방향\n- [ ] 괴리율 (NAV 대비 %)\n- [ ] 추세 매매 적합도 판단\n\n## 수집 데이터 체크리스트\n\n### 개별 주식 필수 항목\n\n- [ ] 현재 주가, 시가총액\n- [ ] PER, PBR\n- [ ] 최근 4분기 매출/영업이익\n- [ ] 부채비율\n- [ ] 52주 최고/최저\n- [ ] 최근 주요 뉴스 3건\n\n### 개별 주식 권장 항목\n\n- [ ] ROE, ROA\n- [ ] 영업현금흐름\n- [ ] 배당수익률, 배당성향\n- [ ] 애널리스트 컨센서스\n- [ ] 대주주 지분율\n\n### ETF 필수 항목\n\n- [ ] 현재가, 거래량\n- [ ] 기초지수명\n- [ ] 상위 10개 구성종목 및 비중\n- [ ] 괴리율 (NAV 대비)\n- [ ] 일봉 이동평균선 배열 (5/20/60/120일)\n- [ ] 주봉 이동평균선 배열 (5/20주)\n\n### ETF 권장 항목\n\n- [ ] 총보수(운용보수)\n- [ ] 순자산(AUM)\n- [ ] 섹터 비중\n- [ ] 추적오차\n\n## 결과 출력 형식\n\n### 간단 분석 (대화형)\n\n핵심 정보만 요약하여 채팅으로 전달\n\n### 상세 분석 (마크다운 보고서)\n\n**⚠️ 보고서 생성 전 필수 참조:**\n\n| 종목 유형 | 참조 파일                                      | 사용 템플릿      |\n| --------- | ---------------------------------------------- | ---------------- |\n| 개별 주식 | `report-template.md` + `technical-analysis.md` | 개별 주식 템플릿 |\n| ETF       | `report-template.md` + `etf-analysis.md`       | ETF 전용 템플릿  |\n\n**저장 경로:**\n\n```\n\n./record/{종목명 또는 ETF명}/{YYYYMMDD}.md\n\n예시:\n./record/\n├── 삼성전자/\n│ ├── 20260115.md\n│ └── 20260118.md\n├── TIGER 미국S&P500/\n│ └── 20260118.md\n├── SPY/\n│ └── 20260118.md\n└── ...\n\n```\n\n**개별 주식 보고서 생성 순서:**\n\n```\n\n1. references/report-template.md 읽기 (개별 주식 템플릿)\n2. 수집한 데이터로 템플릿 채우기\n3. references/technical-analysis.md 참고하여 기술적 분석 작성\n4. ./record/{종목명}/{YYYYMMDD}.md 저장\n\n```\n\n**ETF 보고서 생성 순서:**\n\n```\n\n1. references/report-template.md 읽기 (ETF 전용 템플릿)\n2. references/etf-analysis.md 참고\n3. 기초지수, 구성종목, 이동평균선, 괴리율 채우기\n4. ./record/{ETF명}/{YYYYMMDD}.md 저장\n\n```\n\n## 참고 문서\n\n### 필수 참조 (보고서 생성 시)\n\n| 순서 | 파일                                 | 용도                       |\n| ---- | ------------------------------------ | -------------------------- |\n| 1    | `references/report-template.md`      | 보고서 구조 및 템플릿      |\n| 2    | `references/technical-analysis.md`   | 일목균형표/RSI/거래량 분석 |\n| 3    | `references/investment-checklist.md` | 매수/매도 판단 체크리스트  |\n\n### ETF 분석 시 필수 참조\n\n| 파일                         | 용도                                   |\n| ---------------------------- | -------------------------------------- |\n| `references/etf-analysis.md` | 추종지수, 이동평균선 추세, 괴리율 분석 |\n\n### 선택 참조 (심층 분석 시)\n\n| 파일                               | 용도                      |\n| ---------------------------------- | ------------------------- |\n| `references/investment-metrics.md` | PER/PBR 밸류에이션 가이드 |\n| `references/financial-analysis.md` | 재무제표 해석 방법        |\n\n### 설정 파일\n\n| 파일                | 용도                 |\n| ------------------- | -------------------- |\n| `assets/종목.md`    | 분석 대상 종목 목록  |\n| `assets/index.html` | 보고서 뷰어 (로컬용) |\n```\n"},"lastSynced":"2026-03-08T02:13:34.862Z","agentAnalysis":{"suitability":{"en":"Perfect for Financial Analysis Agents needing advanced stock market data processing and visualization capabilities.","zh":"非常适合需要高级股票市场数据处理和可视化能力的金融分析代理","ja":"財務分析エージェントが高度な株式市場データ処理および視覚化機能を必要とする場合に最適","ko":"고급 주식 시장 데이터 처리 및 시각화 기능이 필요한 금융 분석 에이전트에게 적합","es":"Perfecto para Agentes de Análisis Financiero que necesitan capacidades avanzadas de procesamiento y visualización de datos del mercado de valores.","fr":"Parfait pour les Agents d''Analyse Financière ayant besoin de capacités avancées de traitement et de visualisation des données du marché boursier.","de":"Perfekt für Finanzanalyse-Agents, die erweiterte Aktienmarktdatenverarbeitungs- und Visualisierungsfähigkeiten benötigen.","pt":"Perfeito para Agentes de Análise Financeira que necessitam de capacidades avançadas de processamento e visualização de dados do mercado de ações.","ru":"Идеально подходит для финансовых аналитических агентов, которым требуются продвинутые возможности обработки и визуализации данных фондового рынка.","ar":"مثالي لعميل التحليل المالي الذين يحتاجون إلى قدرات متقدمة لمعالجة بيانات سوق الأسهم وتحليلها."},"recommendation":{"en":"Empowers agents to perform comprehensive enterprise analysis for informed stock buying and selling decisions, leveraging technical keywords like 차트 검증, 실적 분석, and 종목 비교, while utilizing data formats such as financial statements and market trends.","zh":"赋予代理商进行全面企业分析的能力，以便在技术关键词如 차트 검증、실적 분석、종목 비교的基础上，利用财务报表和市场趋势等数据格式做出明智的股票买卖决策","ja":"エージェントが技術キーワード seperti 차트 검증、실적 분석、종목 비교 を活用し、財務諸表や市場動向などのデータ形式を利用して、情報に基づいた株式の買い売り決定を行うための包括的な企業分析を実施する能力を提供する","ko":"에이전트가 차트 검증, 실적 분석, 종목 비교와 같은 기술 키워드를 활용하여 재무제표 및 시장 동향 등의 데이터 형식을 사용하여 정보에 기반한 주식 매수/매도 결정에 대한 종합적인 기업 분석을 수행할 수 있는 능력을 제공","es":"Habilita a los agentes a realizar un análisis empresarial integral para tomar decisiones informadas de compra y venta de acciones, aprovechando palabras clave técnicas como 차트 검증, 실적 분석 y 종목 비교, al mismo tiempo que utiliza formatos de datos como estados financieros y tendencias del mercado.","fr":"Permet aux agents de réaliser une analyse d''entreprise complète pour prendre des décisions éclairées d''achat et de vente d''actions, en exploitant des mots-clés techniques tels que 차트 검증, 실적 분석 et 종목 비교, tout en utilisant des formats de données tels que les états financiers et les tendances du marché.","de":"Ermöglicht es Agents, eine umfassende Unternehmensanalyse für fundierte Kauf- und Verkaufsentscheidungen von Aktien durchzuführen, indem technische Schlüsselwörter wie 차트 검증, 실적 분석 und 종목 비교 genutzt werden, während Datenformate wie Finanzberichte und Markttrends verwendet werden.","pt":"Habilita agentes a realizar uma análise empresarial abrangente para tomar decisões informadas de compra e venda de ações, utilizando palavras-chave técnicas como 차트 검증, 실적 분석 e 종목 비교, e utilizando formatos de dados como demonstrações financeiras e tendências do mercado.","ru":"Позволяет агентам проводить всесторонний корпоративный анализ для принятия обоснованных решений о покупке и продаже акций, используя технические ключевые слова, такие как 차트 검증, 실적 분석 и 종목 비교, а также использует форматы данных, такие как финансовые отчеты и рыночные тенденции.","ar":"تمكن الوكيل من إجراء تحليل شامل للشركات من أجل اتخاذ قرارات مستنيرة لشراء وبيع الأسهم، مستخدما مفاتيح تقنية مثل 차트 검증 و 실적 분석 و 종목 비교، وتحليل بيانات مثل البيانات المالية واتجاهات السوق."},"useCases":{"en":["Analyzing stock performance using 실적 분석 and 어닝 서프라이즈","Comparing stock prices and predicting future trends using 차트 검증","Evaluating investment opportunities through 종목 비교 and 매수/매도 타이밍 analysis"],"zh":["使用 실적 분석 和 어닝 서프라이즈 分析股票表现","使用 차트 검증 预测未来趋势和比较股票价格","通过 종목 비교 和 매수/매도 타이밍 分析评估投资机会"],"ja":["実際分析 と 어닝 서프라이즈 を使用して株式のパフォーマンスを分析","차트 검증 を使用して将来の傾向を予測し、株価を比較","종목 비교 と 매수/매도 타이밍 分析を使用して投資機会を評価"],"ko":["실적 분석과 어닝 서프라이즈를 사용하여 주식 성과를 분석","차트 검증을 사용하여 미래의 추세를 예측하고 주가 비교","종목 비교와 매수/매도 타이밍 분석을 통해 투자 기회를 평가"],"es":["Análisis del rendimiento de las acciones utilizando 실적 분석 y 어닝 서프라이즈","Comparación de los precios de las acciones y predicción de las tendencias futuras utilizando 차트 검증","Evaluación de oportunidades de inversión a través de 종목 비교 y análisis de 매수/매도 타이밍"],"fr":["Analyse de la performance des actions à l''aide de 실적 분석 et d''어닝 서프라이즈","Comparaison des prix des actions et prédiction des tendances futures à l''aide de 차트 검증","Évaluation des opportunités d''investissement via 종목 비교 et analyse de 매수/매도 타이밍"],"de":["Analyse der Aktienleistung unter Verwendung von 실적 분석 und 어닝 서프라이즈","Vergleich der Aktienkurse und Vorhersage zukünftiger Trends unter Verwendung von 차트 검증","Bewertung von Investitionsmöglichkeiten durch 종목 비교 und Analyse von 매수/매도 타이밍"],"pt":["Analisar o desempenho das ações usando 실적 분석 e 어닝 서프라이즈","Comparar preços de ações e prever tendências futuras usando 차트 검증","Avaliar oportunidades de investimento por meio de 종목 비교 e análise de 매수/매도 타이밍"],"ru":["Анализировать производительность акций с помощью 실적 분석 и 어닝 서프라이즈","Сравнивать цены акций и прогнозировать будущие тенденции с помощью 차트 검증","Оценивать возможности инвестиций с помощью 종목 비교 и анализа 매수/매도 타이밍"],"ar":["تحليل أداء الأسهم باستخدام 실적 분석 و 어닝 서프라이즈","مقارنة أسعار الأسهم والتنبؤ بالاتجاهات المستقبلية باستخدام 차트 검증","تقييم فرص الاستثمار من خلال 종목 비교 وتحليل 매수/매도 타이밍"]},"limitations":{"en":["Requires access to real-time market data and financial statements","Limited to analysis of publicly traded companies","May require additional configuration for non-Korean stock markets"],"zh":["需要访问实时市场数据和财务报表","仅限于公开交易公司的分析","可能需要为非韩国股票市场进行额外配置"],"ja":["リアルタイム市場データおよび財務諸表へのアクセスが必要","公開取引会社の分析のみ","非韓国株式市場の場合、追加の設定が必要になる可能性"],"ko":["실시간 시장 데이터 및 재무제표에 대한 액세스가 필요","공개 거래 회사에 대한 분석만 가능","비한국 주식 시장의 경우 추가 구성이 필요할 수 있음"],"es":["Requiere acceso a datos del mercado en tiempo real y estados financieros","Limitado al análisis de empresas cotizadas en bolsa","Puede requerir configuración adicional para mercados de valores no coreanos"],"fr":["Nécessite l''accès à des données de marché en temps réel et à des états financiers","Limité à l''analyse des entreprises cotées en bourse","Peut nécessiter une configuration supplémentaire pour les marchés boursiers non coréens"],"de":["Benötigt Zugriff auf Echtzeit-Marktdaten und Finanzberichte","Begrenzt auf die Analyse von börsennotierten Unternehmen","Kann eine zusätzliche Konfiguration für nicht-koreanische Aktienmärkte erfordern"],"pt":["Requer acesso a dados do mercado em tempo real e demonstrações financeiras","Limitado à análise de empresas negociadas publicamente","Pode requerer configuração adicional para mercados de ações não coreanos"],"ru":["Требует доступа к данным рынка в реальном времени и финансовым отчетам","Ограничен анализом публично торгуемых компаний","Может потребовать дополнительной настройки для не корейских фондовых рынков"],"ar":["يتطلب الوصول إلى بيانات السوق في الوقت الفعلي والبيانات المالية","محدود بالتحليل الشركات المتداولة علنا","يمكن أن يتطلب إعدادات إضافية لأنواع الأسهم غير الكورية"]},"version":4},"contentHash":"f994ae87eef0dce858b4dab353d1bae47482b4eb62da83356adf87c79fe819fa","qualityScore":33}');
