INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tae2089/finance-agent-skills/stock-investment-analysis', 'stock-investment-analysis', 'tae2089', 'finance-agent-skills', 'community', 'stock-investment-analysis tae2089 finance-agent-skills community The stock-investment-analysis skill performs enterprise analysis for informed stock buying and selling decisions, benefiting investors and financial analysts. 股票投资分析工具提供企业分析和股票买卖建议，帮助您做出明智的投资决策 株式投資分析AIエージェントは企業分析と株式の売買アドバイスを提供し、賢明な投資決定をサポートします 주식 투자 분석 스킬은 기업 분석과 주식 매수/매도 의사결정을 지원하여 현명한 투자 결정에 도움을 줍니다 El análisis de inversiones en acciones es un proceso que implica evaluar el desempeño de una empresa para tomar decisiones informadas sobre compras y ventas de acciones L''analyse d''investissement en actions est un processus qui consiste à évaluer la performance d''une entreprise pour prendre des décisions éclairées sur les achats et les ventes d''actions Die Analyse von Aktienanlagen ist ein Prozess, der die Bewertung der Leistung eines Unternehmens beinhaltet, um fundierte Entscheidungen über den Kauf und Verkauf von Aktien zu treffen O skill de análise de investimentos em ações ajuda a tomar decisões informadas sobre compra e venda de ações utilizando análise de empresas e inteligência artificial Навык анализа акций помогает принимать обоснованные решения о покупке и продаже акций с помощью анализа компаний и ИИ مهارة تحليل الاستثمار في الأسهم تساعد على اتخاذ قرارات مدروسة بشأن الشراء والبيع باستخدام تحليل الشركات والذكاء الاصطناعي how to use stock-investment-analysis stock-investment-analysis setup guide stock investment analysis tools stock-investment-analysis vs technical analysis stock-investment-analysis install what is stock-investment-analysis stock-investment-analysis alternative stock investment analysis for beginners stock-investment-analysis tutorial stock investment analysis software 股票投资分析 企业分析 股票买卖建议 数据分析 机器学习 投资决策 股票市场分析 Performs enterprise analysis for stock buying and selling decisions Provides real-time stock comparisons, such as Kakao vs Naver Analyzes earnings reports, including surprise earnings announcements Evaluates chart patterns, including cloud chart analysis Supports various stock analysis scenarios, including buy/sell timing and stock portfolio review stock-investment-analysis is a skill that analyzes stocks for investment decisions, providing insights on buy/sell timing, stock comparisons, and earnings analysis.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dboone323/tools-automation/swift-testing', 'community', 'dboone323', 'tools-automation', 'dboone323/tools-automation', 'swift-testing', 0, 0, 33, '2026-03-08T01:57:15.632Z', '2026-03-08T02:13:34.959Z', '9ab4831246021672627c780fb41f99591e01c6b867d0f2e5a4d9c79a554aba6b', '{"id":"dboone323/tools-automation/swift-testing","name":"swift-testing","description":{"en":"Swift-testing is a specialized skill for developing and testing iOS and macOS apps, providing tailored testing expertise for monorepo projects. It benefits developers by streamlining the testing process.","zh":"Swift 测试专家提供项目特定的测试专业知识，涵盖单元测试和 UI 测试","ja":"Swift テストのプロジェクト特定のテスト専門知識を提供する、ユニットテストと UI テストを含む","ko":"Swift 테스트의 프로젝트 특정 테스트 전문 지식을 제공합니다, 유닛 테스트와 UI 테스트 포함","es":"Swift Testing es una herramienta de prueba para aplicaciones iOS y macOS que permite a los desarrolladores escribir pruebas unitarias y de interfaz de usuario de manera eficiente","fr":"Swift Testing est un outil de test pour les applications iOS et macOS qui permet aux développeurs d''écrire des tests unitaires et d''interface utilisateur de manière efficace","de":"Swift Testing ist ein Testtool für iOS- und macOS-Apps, das es Entwicklern ermöglicht, Einheitstests und Benutzeroberflächentests effizient zu schreiben","pt":"O swift-testing é uma habilidade de teste personalizada para projetos iOS e macOS, com estrutura de teste e convenções de nomenclatura para testes unitários e de interface do usuário","ru":"Swift-testing - это навык тестирования, адаптированный для проектов iOS и macOS, с тестовой структурой и соглашениями об именах для юнит-тестов и тестов пользовательского интерфейса","ar":"swift-testing هو مهارة اختبار مخصصة لمشاريع iOS و macOS، مع هيكل اختبار وتوافق أسماء الملفات لاختبارات الوحدة وواجهة المستخدم"},"seo":{"title":{"en":"Swift-Testing: Expert Guide for iOS/mac