INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dboone323/tools-automation/swift-testing', 'swift-testing', 'dboone323', 'tools-automation', 'community', 'swift-testing dboone323 tools-automation community Swift-testing is a specialized skill for developing and testing iOS and macOS apps, providing tailored testing expertise for monorepo projects. It benefits developers by streamlining the testing process. Swift 测试专家提供项目特定的测试专业知识，涵盖单元测试和 UI 测试 Swift テストのプロジェクト特定のテスト専門知識を提供する、ユニットテストと UI テストを含む Swift 테스트의 프로젝트 특정 테스트 전문 지식을 제공합니다, 유닛 테스트와 UI 테스트 포함 Swift Testing es una herramienta de prueba para aplicaciones iOS y macOS que permite a los desarrolladores escribir pruebas unitarias y de interfaz de usuario de manera eficiente Swift Testing est un outil de test pour les applications iOS et macOS qui permet aux développeurs d''écrire des tests unitaires et d''interface utilisateur de manière efficace Swift Testing ist ein Testtool für iOS- und macOS-Apps, das es Entwicklern ermöglicht, Einheitstests und Benutzeroberflächentests effizient zu schreiben O swift-testing é uma habilidade de teste personalizada para projetos iOS e macOS, com estrutura de teste e convenções de nomenclatura para testes unitários e de interface do usuário Swift-testing - это навык тестирования, адаптированный для проектов iOS и macOS, с тестовой структурой и соглашениями об именах для юнит-тестов и тестов пользовательского интерфейса swift-testing هو مهارة اختبار مخصصة لمشاريع iOS و macOS، مع هيكل اختبار وتوافق أسماء الملفات لاختبارات الوحدة وواجهة المستخدم how to use swift-testing swift-testing for iOS development what is swift-testing swift-testing vs XCTest swift-testing setup guide swift-testing install for macOS swift-testing best practices swift-testing tutorial swift-testing alternative for app testing Swift 测试 iOS 测试 macOS 测试 单元测试 UI 测试 Swift 语言 AIエージェント 测试框架 Follows a project test structure with separate folders for source files, unit tests, and UI tests Utilizes a naming convention for test files, such as [SourceFile]Tests.swift Supports test function naming with a specific format, e.g., test_[unit]_[scenario]_[expected] Enables organization of unit tests in the ProjectNameTests folder Allows for UI tests to be stored in the ProjectNameUITests folder, if applicable Adheres to a standardized test convention for consistency across the project swift-testing is a project-specific testing expertise for iOS and macOS apps, following a structured approach to unit and UI tests within a monorepo');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dyh1807/axi-interconnect-kit/axi-kit-verify', 'community', 'dyh1807', 'axi-interconnect-kit', 'dyh1807/axi-interconnect-kit', 'axi-kit-verify', 0, 0, 33, '2026-03-08T01:57:15.639Z', '2026-03-08T02:13:40.471Z', '44a5e65cf330998137fbcdb7cbb7c14323846d0e8ed07aa26e57aacd8733ea10', '{"id":"dyh1807/axi-interconnect-kit/axi-kit-verify","name":"axi-kit-verify","description":{"en":"The axi-kit-verify skill provides a comprehensive AXI-Interconnect Interface for 4-read masters and 2-write master, benefiting developers working with complex digital systems. It enables standalone tests and demos for AXI4 and AXI3 protocols.","zh":"AXI-Kit-Verify 是一个用于验证 AXI-Interconnect 接口的工具，支持 4 个读取主控器和 2 个写入主控器。它提供了独立的测试和演示功能","ja":"AXI-Kit-Verify は、AXI-Interconnect インターフェイスを検証するためのツールです。4 つのリード マスターと 2 つのライト マスターをサポートします。スタンドアロン テストとデモ機能を提供します","ko":"AXI-Kit-Verify는 AXI-Interconnect 인터페이스를 검증하는 도구입니다. 4개의 읽기 마스터와 2개의 쓰기 마스터를 지원합니다. 독립 테스트와 데모 기능을 제공합니다","es":"axi-kit-verify es una herramienta para la verificación de interfaces de interconexión AXI con 4 maestros de lectura y 2 maestros de escritura. Proporciona pruebas y demos independientes para garantizar la compatibilidad y el rendimiento.","fr":"axi-kit-verify est un outil de vérification pour les interfaces de interconnexion AXI avec 4 maîtres de lecture et 2 maîtres d''écriture. Il offre des tests et des démos autonomes pour assurer la compatibilité et les performances.","de":"axi-kit-verify ist ein Werkzeug zur Überprüfung von AXI-Interconnect-Schnittstellen mit 4 Lese- und 2 Schreibmastern. Es bietet eigenständige Tests und Demos, um die Kompatibilität und Leistung zu gewährleisten.","pt":"O axi-kit-verify é uma ferramenta para verificar a interface AXI-Interconnect com 4 mestres de leitura e 2 mestres de escrita","ru":"axi-kit-verify - это инструмент для проверки интерфейса AXI-Interconnect с 4 мастерами чтения и 2 мастерами записи","ar":"axi-kit-verify هو أداة لتحقق واجهة AXI-Interconnect مع 4 أسياد قراءة و 2 أسياد كتابة"},"seo":{"title":{"en":"axi-kit-verify: AXI Interconnect Verification Setup Guide...","zh":"AXI-Kit-Verify Setup Guide: 4-Read Masters and 2-Write Ma...","ja":"AXI-Kit-Verify の設定方法: 4 つのリード マスターと 2 つのライト マスター インターフェイス","ko":"AXI-Kit-Verify 설정 가이드: 4개의 읽기 마스터와 2개의 쓰기 마스터 인터페이스","es":"Guía de configuración de axi-kit-verify para masters de l...","fr":"Guide de configuration d''axi-kit-verify pour les maîtres ...","de":"Einrichtungsanleitung für axi-kit-verify für Lese- und Sc...","pt":"Guia de Configuração do axi-kit-verify para Interface AXI","ru":"Руководство по настройке axi-kit-verify для интерфейса AX...","ar":"دليل إعداد axi-kit-verify لويفاء AXI أدوات الذكاء الاصطناعي"},"description":{"en":"Unlock efficient AXI interconnect verification with axi-kit-verify. Learn how to setup and utilize this powerful kit for 4-read masters and 2-write master in...","zh":"使用 AXI-Kit-Verify 进行 AXI-Interconnect 接口的验证，支持 4 个读取主控器和 2 个写入主控器","ja":"AXI-Kit-Verify を使用して AXI-Interconnect インターフェイスを検証します。4 つのリード マスターと 2 つのライト マスターをサポートします","ko":"AXI-Kit-Verify를 사용하여 AXI-Interconnect 인터페이스를 검증합니다. 4개의 읽기 마스터와 2개의 쓰기 마스터를 지원합니다","es":"Aprende a configurar y utilizar axi-kit-verify para interfaces de interconexión AXI con 4 maestros de lectura y 2 maestros de escritura","fr":"Découvrez comment configurer et utiliser axi-kit-verify pour les interfaces de interconnexion AXI avec 4 maîtres de lecture et 2 maîtres d''écriture","de":"Erfahren Sie, wie Sie axi-kit-verify für AXI-Interconnect-Schnittstellen mit 4 Lese- und 2 Schreibmastern konfigurieren und verwenden","pt":"Aprenda a configurar o axi-kit-verify para interface AXI-Interconnect com 4 mestres de leitura e 2 mestres de escrita","ru":"Узнайте, как настроить axi-kit-verify для интерфейса AXI-Interconnect с 4 мастерами чтения и 2 мастерами записи с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد axi-kit-verify لويفاء AXI-Interconnect مع 4 أسياد قراءة و 2 أسياد كتابة باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"axi-kit-verify is an AXI-Interconnect Interface verification kit designed for 4-read masters and 2-write master configurations, facilitating testing and validation of digital systems.","zh":"AXI-Kit-Verify 是一个用于验证 AXI-Interconnect 接口的工具","ja":"AXI-Kit-Verify は AXI-Interconnect インターフェイスを検証するためのツールです","ko":"AXI-Kit-Verify는 AXI-Interconnect 인터페이스를 검증하는 도구입니다","es":"axi-kit-verify es una herramienta de verificación para interfaces de interconexión AXI","fr":"axi-kit-verify est un outil de vérification pour les interfaces de interconnexion AXI","de":"axi-kit-verify ist ein Überprüfungstool für AXI-Interconnect-Schnittstellen","pt":"O que é axi-kit-verify? É uma ferramenta de verificação para interface AXI-Interconnect","ru":"Что такое axi-kit-verify? Это инструмент проверки для интерфейса AXI-Interconnect","ar":"ما هو axi-kit-verify؟ هو أداة لتحقق واجهة AXI-Interconnect"},"features":{"en":["Supports standalone tests via CMake and ctest commands","Enables AXI4 and AXI3 protocol demos with smoke test executables","Utilizes cmake -S and -B options for build configuration","Leverages ctest --output-on-failure for detailed test results","Compatible with USE_SIM_DDR and USE_SIM_DDR_AXI4 flags for simulator checks"],"zh":["支持 4 个读取主控器和 2 个写入主控器","提供独立的测试功能","提供独立的演示功能","支持 AXI4 和 AXI3 协议","使用 CMake 和 ctest 进行构建和测试"],"ja":["4 つのリード マスターと 2 つのライト マスターをサポートします","スタンドアロン テスト機能を提供します","スタンドアロン デモ機能を提供します","AXI4 と AXI3 プロトコルをサポートします","CMake と ctest を使用してビルドとテストを行います"],"ko":["4개의 읽기 마스터와 2개의 쓰기 마스터를 지원합니다","독립 테스트 기능을 제공합니다","독립 데모 기능을 제공합니다","AXI4와 AXI3 프로토콜을 지원합니다","CMake와 ctest를 사용하여 빌드와 테스트를 수행합니다"],"es":["Pruebas independientes para la verificación de la compatibilidad","Demos de funcionamiento para la verificación del rendimiento","Compatibilidad con 4 maestros de lectura y 2 maestros de escritura","Soporte para AXI4 y AXI3","Integración con herramientas de construcción como CMake"],"fr":["Tests autonomes pour la vérification de la compatibilité","Démonstrations de fonctionnement pour la vérification des performances","Compatibilité avec 4 maîtres de lecture et 2 maîtres d''écriture","Prise en charge de AXI4 et AXI3","Intégration avec des outils de construction tels que CMake"],"de":["Eigenständige Tests zur Überprüfung der Kompatibilität","Funktionsdemos zur Überprüfung der Leistung","Kompatibilität mit 4 Lese- und 2 Schreibmastern","Unterstützung für AXI4 und AXI3","Integration mit Build-Tools wie CMake"],"pt":["Suporte a 4 mestres de leitura","Suporte a 2 mestres de escrita","Interface AXI-Interconnect","Testes standalone com CMake","Demonstrações standalone com AXI4 e AXI3","Verificação de simulação de pais com AXI4"],"ru":["Поддержка 4 мастеров чтения","Поддержка 2 мастеров записи","Интерфейс AXI-Interconnect","Автономные тесты с CMake","Автономные демонстрации с AXI4 и AXI3","Проверка симуляции родителей с AXI4"],"ar":["دعم 4 أسياد قراءة","دعم 2 أسياد كتابة","واجهة AXI-Interconnect","اختبارات منفصلة مع CMake","تجارب منفصلة مع AXI4 و AXI3","تحقق محاكاة الوالدين مع AXI4"]},"keywords":{"en":["how to use axi-kit-verify","axi-kit-verify setup guide","axi interconnect verification","axi-kit-verify alternative","axi-kit-verify vs other verification tools","install axi-kit-verify","axi-kit-verify for 4-read masters and 2-write master"],"zh":["AXI-Kit-Verify","AXI-Interconnect","4 个读取主控器","2 个写入主控器","AXI4","AXI3","CMake","ctest","AI工具","AXI 接口验证"],"ja":["AXI-Kit-Verify","AXI-Interconnect","4 つのリード マスター","2 つのライト マスター","AXI4","AXI3","CMake","ctest","AIエージェント","AXI インターフェイス検証"],"ko":["AXI-Kit-Verify","AXI-Interconnect","4개의 읽기 마스터","2개의 쓰기 마스터","AXI4","AXI3","CMake","ctest","AI 에이전트","AXI 인터페이스 검증"],"es":["axi-kit-verify","interfaz de interconexión AXI","maestros de lectura y escritura","pruebas de compatibilidad","demos de funcionamiento","AXI4","AXI3","CMake","herramientas de verificación","desarrollo de hardware"],"fr":["axi-kit-verify","interface de interconnexion AXI","maîtres de lecture et d''écriture","tests de compatibilité","démonstrations de fonctionnement","AXI4","AXI3","CMake","outils de vérification","développement de matériel"],"de":["axi-kit-verify","AXI-Interconnect-Schnittstelle","Lese- und Schreibmaster","Kompatibilitätstests","Funktionsdemos","AXI4","AXI3","CMake","Überprüfungstools","Hardware-Entwicklung"],"pt":["axi-kit-verify","interface AXI-Interconnect","mestres de leitura","mestres de escrita","CMake","AXI4","AXI3","simulação de pais","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["axi-kit-verify","интерфейс AXI-Interconnect","мастера чтения","мастера записи","CMake","AXI4","AXI3","симуляция родителей","разработка программного обеспечения","инструменты разработки","ИИ Агенты"],"ar":["axi-kit-verify","واجهة AXI-Interconnect","أسياد قراءة","أسياد كتابة","CMake","AXI4","AXI3","محاكاة الوالدين","تطوير البرمجيات","أدوات التطوير","أدوات الذكاء الاصطناعي"]}},"owner":"dyh1807","repo":"axi-interconnect-kit","repoPath":"dyh1807/axi-interconnect-kit","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.639Z","topics":[],"category":"community","skillMd":{"name":"axi-kit-verify","description":"Run focused AXI-kit verification: unit tests, smoke demos, and integration checks from the parent simulator.","bodyPreview":"# AXI Kit Verification\n\n## Standalone tests\n```bash\ncmake -S projects/axi-interconnect-kit -B projects/axi-interconnect-kit/build\ncmake --build projects/axi-interconnect-kit/build -j\ncd projects/axi-interconnect-kit/build && ctest --output-on-failure\n```\n\n## Standalone demos\n```bash\nprojects/axi-interconnect-kit/build/axi4_smoke_demo\nprojects/axi-interconnect-kit/build/axi3_smoke_demo\n```\n\n## Parent simulator checks\nAXI4:\n```bash\ncmake -S . -B build -DUSE_SIM_DDR=ON -DUSE_SIM_DDR_AXI4=ON\ncmake -","body":"# AXI Kit Verification\n\n## Standalone tests\n```bash\ncmake -S projects/axi-interconnect-kit -B projects/axi-interconnect-kit/build\ncmake --build projects/axi-interconnect-kit/build -j\ncd projects/axi-interconnect-kit/build && ctest --output-on-failure\n```\n\n## Standalone demos\n```bash\nprojects/axi-interconnect-kit/build/axi4_smoke_demo\nprojects/axi-interconnect-kit/build/axi3_smoke_demo\n```\n\n## Parent simulator checks\nAXI4:\n```bash\ncmake -S . -B build -DUSE_SIM_DDR=ON -DUSE_SIM_DDR_AXI4=ON\ncmake --build build -j\ntimeout 20s ./build/a.out baremetal/new_dhrystone/dhrystone.bin\ntimeout 20s ./build/a.out baremetal/new_coremark/coremark.bin\ntimeout 60s ./build/a.out baremetal/linux.bin\n```\n\nAXI3:\n```bash\ncmake -S . -B build_axi3 -DUSE_SIM_DDR=ON -DUSE_SIM_DDR_AXI3=ON\ncmake --build build_axi3 -j\ntimeout 20s ./build_axi3/a.out baremetal/new_dhrystone/dhrystone.bin\ntimeout 20s ./build_axi3/a.out baremetal/new_coremark/coremark.bin\ntimeout 60s ./build_axi3/a.out baremetal/linux.bin\n```\n"},"lastSynced":"2026-03-08T02:13:40.471Z","agentAnalysis":{"suitability":{"en":"Ideal for Digital System Agents requiring comprehensive AXI-Interconnect Interface verification for 4-read masters and 2-write masters.","zh":"适用于需要对AXI-Interconnect Interface进行全面验证的数字系统代理，特别是对于4个读主设备和2个写主设备。","ja":"デジタルシステムエージェントがAXI-Interconnect Interfaceの包括的検証を必要とする場合に最適です。特に、4つのリードマスターと2つのライトマスターの場合。","ko":"디지털 시스템 에이전트가 AXI-Interconnect Interface의 완전한 검증을 필요로 하는 경우에 적합합니다. 특히 4개의 읽기 마스터와 2개의 쓰기 마스터의 경우에 적합합니다.","es":"Ideal para agentes de sistemas digitales que requieren una verificación integral de la interfaz AXI-Interconnect para 4 maestros de lectura y 2 maestros de escritura.","fr":"Idéal pour les agents de systèmes numériques nécessitant une vérification complète de l''interface AXI-Interconnect pour 4 maîtres de lecture et 2 maîtres d''écriture.","de":"Ideal für digitale Systemagenten, die eine umfassende Verifizierung der AXI-Interconnect-Schnittstelle für 4 Lese-Master und 2 Schreib-Master erfordern.","pt":"Ideal para Agentes de Sistema Digitais que exigem verificação abrangente da Interface de Interconexão AXI para 4 mestres de leitura e 2 mestres de escrita.","ru":"Идеально для цифровых системных агентов, требующих комплексной верификации интерфейса AXI-Interconnect для 4 мастеров чтения и 2 мастеров записи.","ar":"مثالية لعميل نظام رقمي يتطلب التحقق الشامل من واجهة AXI-Interconnect للقراءة 4 أسياد والكتابة 2 أسياد."},"recommendation":{"en":"Empowers agents to perform standalone tests and demos for AXI4 and AXI3 protocols, utilizing CMake and ctest for seamless verification, and enabling advanced digital system development with AXI-Interconnect Interface.","zh":"赋予代理执行独立测试和演示AXI4和AXI3协议的能力，利用CMake和ctest进行无缝验证，并启用高级数字系统开发与AXI-Interconnect Interface。","ja":"AXI4とAXI3プロトコルの独立テストとデモを実行するエージェントを可能にし、CMakeとctestを使用した無駄のない検証を実現し、AXI-Interconnect Interfaceでの高度なデジタルシステム開発を可能にします。","ko":"에이전트가 AXI4와 AXI3 프로토콜의 독립 테스트와 데모를 수행할 수 있도록 하며, CMake와 ctest를 사용하여 무결점 검증을 가능하게 하고, AXI-Interconnect Interface와의 고급 디지털 시스템 개발을 가능하게 합니다.","es":"Habilita a los agentes a realizar pruebas y demos autónomas para los protocolos AXI4 y AXI3, utilizando CMake y ctest para una verificación sin problemas y permitiendo un desarrollo avanzado de sistemas digitales con la interfaz AXI-Interconnect.","fr":"Permet aux agents de réaliser des tests et des démos autonomes pour les protocoles AXI4 et AXI3, en utilisant CMake et ctest pour une vérification sans problème et en permettant un développement avancé de systèmes numériques avec l''interface AXI-Interconnect.","de":"Ermöglicht es Agenten, eigenständige Tests und Demos für die Protokolle AXI4 und AXI3 durchzuführen, indem CMake und ctest für eine reibungslose Verifizierung verwendet werden und eine fortschrittliche Entwicklung digitaler Systeme mit der AXI-Interconnect-Schnittstelle ermöglicht.","pt":"Habilita os agentes a realizar testes autônomos e demonstrações para os protocolos AXI4 e AXI3, utilizando CMake e ctest para verificação sem interrupção, e permitindo o desenvolvimento avançado de sistemas digitais com a Interface de Interconexão AXI.","ru":"Наделяет агентов возможностью выполнять самостоятельные тесты и демонстрации для протоколов AXI4 и AXI3, используя CMake и ctest для бесперебойной верификации, и обеспечивая продвинутую разработку цифровых систем с интерфейсом AXI-Interconnect.","ar":"تمكين العملاء من أداء الاختبارات المنفصلة والتوضيحات لبروتوكولات AXI4 وAXI3، باستخدام CMake وctest للتحقق السلس، وتمكين التطوير المتقدم لأنظمة رقمية مع واجهة AXI-Interconnect."},"useCases":{"en":["Verifying AXI4 and AXI3 protocol compliance","Performing standalone tests for digital system validation","Demonstrating AXI-Interconnect Interface functionality with smoke demos"],"zh":["验证AXI4和AXI3协议的合规性","执行独立测试以验证数字系统","使用烟雾演示演示AXI-Interconnect Interface的功能性"],"ja":["AXI4とAXI3プロトコルのコンプライアンスを検証する","デジタルシステムの検証のための独立テストを実行する","AXI-Interconnect Interfaceの機能性をスモークデモで実証する"],"ko":["AXI4와 AXI3 프로토콜의 규정 준수를 검증하는 것","디지털 시스템 검증을 위한 독립 테스트를 수행하는 것","스모크 데모를 통해 AXI-Interconnect Interface의 기능을 示す 것"],"es":["Verificar el cumplimiento del protocolo AXI4 y AXI3","Realizar pruebas autónomas para la validación del sistema digital","Demostrar la funcionalidad de la interfaz AXI-Interconnect con demos de humo"],"fr":["Vérifier la conformité aux protocoles AXI4 et AXI3","Réalisser des tests autonomes pour la validation du système numérique","Démontrer la fonctionnalité de l''interface AXI-Interconnect avec des démos de fumée"],"de":["Überprüfen der Konformität mit den Protokollen AXI4 und AXI3","Durchführen von eigenständigen Tests für die Validierung des digitalen Systems","Demonstrieren der Funktionalität der AXI-Interconnect-Schnittstelle mit Rauchtests"],"pt":["Verificar a conformidade do protocolo AXI4 e AXI3","Realizar testes autônomos para validação do sistema digital","Demonstrar a funcionalidade da Interface de Interconexão AXI com demos de fumaça"],"ru":["Проверка соответствия протоколов AXI4 и AXI3","Выполнение самостоятельных тестов для валидации цифровой системы","Демонстрация функциональности интерфейса AXI-Interconnect с помощью дымовых демонстраций"],"ar":["التحقق من مطابقة بروتوكоли AXI4 وAXI3","إجراء اختبارات منفصلة للتحقق من نظام رقمي","إظهار وظيفة واجهة AXI-Interconnect مع عروض الدخان"]},"limitations":{"en":["Requires CMake for build and test automation","Limited to AXI4 and AXI3 protocol support","Needs specific build and test environment setup"],"zh":["需要CMake进行构建和测试自动化","仅限AXI4和AXI3协议支持","需要特定的构建和测试环境设置"],"ja":["ビルドとテストの自動化にCMakeが必要","AXI4とAXI3プロトコルのみをサポート","特定のビルドとテスト環境の設定が必要"],"ko":["빌드 및 테스트 자동화에 CMake가 필요","AXI4 및 AXI3 프로토콜만 지원","특정 빌드 및 테스트 환경 설정이 필요"],"es":["Requiere CMake para la automatización de la compilación y las pruebas","Limitado al soporte de protocolos AXI4 y AXI3","Necesita una configuración específica del entorno de compilación y prueba"],"fr":["Nécessite CMake pour l''automatisation de la construction et des tests","Limité au support des protocoles AXI4 et AXI3","Nécessite une configuration spécifique de l''environnement de construction et de test"],"de":["Benötigt CMake für die Automatisierung von Build und Test","Begrenzt auf die Unterstützung der Protokolle AXI4 und AXI3","Benötigt eine spezifische Einrichtung der Build- und Testumgebung"],"pt":["Exige CMake para automação de compilação e teste","Limitado ao suporte de protocolos AXI4 e AXI3","Necessita de configuração específica de ambiente de compilação e teste"],"ru":["Требует CMake для автоматизации сборки и тестирования","Ограничен поддержкой протоколов AXI4 и AXI3","Требует настройки специфической среды сборки и тестирования"],"ar":["يتطلب CMake للتحكم التلقائي في إنشاء وتجربة","محدود لدعم بروتوكولات AXI4 وAXI3","يحتاج إلى إعداد بيئة بناء وتجربة محددة"]},"version":4},"contentHash":"44a5e65cf330998137fbcdb7cbb7c14323846d0e8ed07aa26e57aacd8733ea10","qualityScore":33}');
