INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dyh1807/axi-interconnect-kit/axi-kit-verify', 'axi-kit-verify', 'dyh1807', 'axi-interconnect-kit', 'community', 'axi-kit-verify dyh1807 axi-interconnect-kit community The axi-kit-verify skill provides a comprehensive AXI-Interconnect Interface for 4-read masters and 2-write master, benefiting developers working with complex digital systems. It enables standalone tests and demos for AXI4 and AXI3 protocols. AXI-Kit-Verify 是一个用于验证 AXI-Interconnect 接口的工具，支持 4 个读取主控器和 2 个写入主控器。它提供了独立的测试和演示功能 AXI-Kit-Verify は、AXI-Interconnect インターフェイスを検証するためのツールです。4 つのリード マスターと 2 つのライト マスターをサポートします。スタンドアロン テストとデモ機能を提供します AXI-Kit-Verify는 AXI-Interconnect 인터페이스를 검증하는 도구입니다. 4개의 읽기 마스터와 2개의 쓰기 마스터를 지원합니다. 독립 테스트와 데모 기능을 제공합니다 axi-kit-verify es una herramienta para la verificación de interfaces de interconexión AXI con 4 maestros de lectura y 2 maestros de escritura. Proporciona pruebas y demos independientes para garantizar la compatibilidad y el rendimiento. axi-kit-verify est un outil de vérification pour les interfaces de interconnexion AXI avec 4 maîtres de lecture et 2 maîtres d''écriture. Il offre des tests et des démos autonomes pour assurer la compatibilité et les performances. axi-kit-verify ist ein Werkzeug zur Überprüfung von AXI-Interconnect-Schnittstellen mit 4 Lese- und 2 Schreibmastern. Es bietet eigenständige Tests und Demos, um die Kompatibilität und Leistung zu gewährleisten. O axi-kit-verify é uma ferramenta para verificar a interface AXI-Interconnect com 4 mestres de leitura e 2 mestres de escrita axi-kit-verify - это инструмент для проверки интерфейса AXI-Interconnect с 4 мастерами чтения и 2 мастерами записи axi-kit-verify هو أداة لتحقق واجهة AXI-Interconnect مع 4 أسياد قراءة و 2 أسياد كتابة how to use axi-kit-verify axi-kit-verify setup guide axi interconnect verification axi-kit-verify alternative axi-kit-verify vs other verification tools install axi-kit-verify axi-kit-verify for 4-read masters and 2-write master AXI-Kit-Verify AXI-Interconnect 4 个读取主控器 2 个写入主控器 AXI4 AXI3 CMake ctest AI工具 AXI 接口验证 Supports standalone tests via CMake and ctest commands Enables AXI4 and AXI3 protocol demos with smoke test executables Utilizes cmake -S and -B options for build configuration Leverages ctest --output-on-failure for detailed test results Compatible with USE_SIM_DDR and USE_SIM_DDR_AXI4 flags for simulator checks axi-kit-verify is an AXI-Interconnect Interface verification kit designed for 4-read masters and 2-write master configurations, facilitating testing and validation of digital systems.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('harrytran998/crossfire/Clean Architecture', 'community', 'harrytran998', 'crossfire', 'harrytran998/crossfire', 'Clean Architecture', 0, 0, 33, '2026-03-08T01:57:15.643Z', '2026-03-08T02:13:42.924Z', '06e1c308e5cee765f28f3efbe38c233c767c6dd181a64dc78cd5d3894c852117', '{"id":"harrytran998/crossfire/Clean Architecture","name":"Clean Architecture","description":{"en":"Clean Architecture helps AI agents separate concerns through concentric layers, containing business logic independent of external frameworks. It benefits developers by organizing code into entities, use cases, and interface adapters.","zh":"Clean Architecture 强调通过集中的层次结构实现关注点分离，包括实体、用例、接口适配器和框架等层次","ja":"Clean Architecture は、コンセントリックレイヤーを使用してソフトウェアシステムの設計を分離し、実体、ユースケース、インターフェースアダプターなどを含む","ko":"Clean Architecture 는 관심사를 분리하고 계층화하여 소프트웨어 시스템의 유지보수성을 향상시키는 설계 패턴으로, 엔티티、유즈케이스、인터페이스 어댑터 등을 포함","es":"La Arquitectura Limpia enfatiza la separación de concernientes a través de capas concéntricas, mejorando la independencia de la lógica de negocio","fr":"L''Architecture Propre met l''accent sur la séparation des préoccupations à travers des couches concéntriques, améliorant l''indépendance de la logique métier","de":"Die Clean Architecture betont die Trennung von Bedenken durch konzentrische Schichten, verbessert die Unabhängigkeit der Geschäftslogik","pt":"A Arquitetura Limpa é um padrão de design que separa as preocupações em camadas concêntricas, permitindo uma maior flexibilidade e manutenção","ru":"Чистая Архитектура - это шаблон проектирования, который разделяет проблемы на концентрические слои, обеспечивая большую гибкость и поддержку","ar":"هندسة البرمجيات النظيفة هي نمط تصميم يفصل الاهتمامات في طبقات متراكبة، مما يسمح بمرونة أكبر وضمان جودة"},"seo":{"title":{"en":"Clean Architecture: Setup Guide for AI Agents | AI Agent ...","zh":"Clean Architecture 设计指南 - 实现关注点分离","ja":"Clean Architecture 導入ガイド - コンセントリックレイヤーによる設計","ko":"Clean Architecture 구현 방법 - 관심사 분리 및 계층화","es":"Guía de Arquitectura Limpia: Implementación y Mejores Prá...","fr":"Guide de l''Architecture Propre: Mise en Œuvre et Bonnes P...","de":"Clean Architecture-Setup: Leitfaden und Best Practices","pt":"Guia de Configuração de Arquitetura Limpa para Desenvolve...","ru":"Настройка Чистой Архитектуры: ИИ Агенты для Разработчиков","ar":"دليل إعداد هندسة البرمجيات النظيفة للمطورين"},"description":{"en":"Discover how Clean Architecture''s concentric layers boost AI agent development. Learn to separate concerns and master entities, use cases, and interface adap...","zh":"了解 Clean Architecture 的核心概念和技术细节，实现软件系统的关注点分离和可维护性","ja":"Clean Architecture のコンセントリックレイヤーとインターフェースアダプターを使用して、ソフトウェアシステムの設計を改善する","ko":"Clean Architecture 를 사용하여 소프트웨어 시스템의 관심사를 분리하고 계층화하여 유지보수성을 향상시키는 방법","es":"Aprende a implementar la Arquitectura Limpia en tus proyectos web con nuestra guía detallada y mejora la separación de concernientes","fr":"Découvrez comment mettre en œuvre l''Architecture Propre dans vos projets web avec notre guide détaillé et améliorez la séparation des préoccupations","de":"Erfahren Sie, wie Sie die Clean Architecture in Ihren Webprojekten implementieren können, mit unserem detaillierten Leitfaden und verbessern Sie die Trennung...","pt":"Aprenda a aplicar a Arquitetura Limpa em seus projetos com nosso guia completo, incluindo camadas concêntricas e separação de preocupações","ru":"Изучите Чистую Архитектуру и ее применение в разработке с помощью нашего подробного руководства, включая концентрические слои и разделение проблем","ar":"تعلم كيفية تطبيق هندسة البرمجيات النظيفة في مشاريعك باستخدام دليلنا الشامل، بما في ذلك الطبقات المتراكزة وفصل الاهتمامات"},"definition":{"en":"Clean Architecture is a software design pattern emphasizing separation of concerns through concentric layers, including entities, use cases, interface adapters, and frameworks.","zh":"Clean Architecture 是一种软件设计模式，强调通过集中层次结构实现关注点分离","ja":"Clean Architecture は、ソフトウェアシステムの設計を分離するためのコンセントリックレイヤーを使用する設計パターン","ko":"Clean Architecture 는 소프트웨어 시스템의 설계를 분리하고 계층화하여 유지보수성을 향상시키는 설계 패턴","es":"La Arquitectura Limpia es un enfoque de diseño de software que separa la lógica de negocio de las preocupaciones externas","fr":"L''Architecture Propre est une approche de conception de logiciels qui sépare la logique métier des préoccupations externes","de":"Die Clean Architecture ist ein Ansatz für die Software-Entwicklung, der die Geschäftslogik von externen Bedenken trennt","pt":"Arquitetura Limpa é um padrão de design de software que separa as preocupações em camadas concêntricas","ru":"Чистая Архитектура - это шаблон проектирования программного обеспечения, который разделяет проблемы на концентрические слои","ar":"هندسة البرمجيات النظيفة هي نمط تصميم البرمجيات الذي يفصل الاهتمامات في طبقات متراكبة"},"features":{"en":["Separates business logic into innermost entities and use cases","Utilizes interface adapters to translate between use cases and external systems","Organizes code into concentric layers for better maintainability","Decouples application-specific business rules from external frameworks and tools","Enables developers to work with a framework-agnostic inner layer"],"zh":["实体（Entities）层：核心业务规则","用例（Use Cases）层：应用程序特定业务规则","接口适配器（Interface Adapters）层：翻译用例和外部系统之间的交互","框架（Frameworks）层：处理 UI、数据库和基础设施问题"],"ja":["エンティティ（Entities）層：コアビジネスルール","ユースケース（Use Cases）層：アプリケーション特定ビジネスルール","インターフェースアダプター（Interface Adapters）層：ユースケースと外部システムの間の相互作用を翻訳","フレームワーク（Frameworks）層：UI、データベース、インフラストラクチャ問題を処理"],"ko":["엔티티（Entities）층：코어 비즈니스 규칙","유즈케이스（Use Cases）층：어플리케이션 특정 비즈니스 규칙","인터페이스 어댑터（Interface Adapters）층：유즈케이스와 외부 시스템 사이의 상호작용을 번역","프레임워크（Frameworks）층：UI、데이터베이스、인프라스트ラク처 문제를 처리"],"es":["Capas concéntricas para separar la lógica de negocio","Entidades para reglas de negocio core","Casos de uso para reglas de negocio específicas de la aplicación","Adaptadores de interfaz para la traducción entre casos de uso y sistemas externos","Independencia de la lógica de negocio de frameworks y herramientas externas"],"fr":["Couches concéntriques pour séparer la logique métier","Entités pour les règles métier core","Cas d''utilisation pour les règles métier spécifiques à l''application","Adaptateurs d''interface pour la traduction entre les cas d''utilisation et les systèmes externes","Indépendance de la logique métier des frameworks et outils externes"],"de":["Konzentrische Schichten zur Trennung der Geschäftslogik","Entitäten für Kern-Geschäftsregeln","Anwendungsfälle für anwendungsspezifische Geschäftsregeln","Schnittstellen-Adapter für die Übersetzung zwischen Anwendungsfällen und externen Systemen","Unabhängigkeit der Geschäftslogik von externen Frameworks und Tools"],"pt":["Camadas concêntricas para separação de preocupações","Entidades como núcleo de regras de negócios","Casos de uso para regras de negócios específicas da aplicação","Adaptadores de interface para traduzir entre casos de uso e sistemas externos","Framewoks e infraestrutura como camadas externas"],"ru":["Концентрические слои для разделения проблем","Сущности как ядро бизнес-логики","Случаи использования для бизнес-логики, специфичной для приложения","Адаптеры интерфейса для перевода между случаями использования и внешними системами","Фреймворки и инфраструктура как внешние слои"],"ar":["الطبقات المتراكبة لفصل الاهتمامات","الكيانات كنواة لقواعد الأعمال","حالات الاستخدام لقواعد الأعمال المحددة للتطبيق","مُحوِّلات الواجهة لترجمة بين حالات الاستخدام والأنظمة الخارجية","الإطارات والبنية التحتية كطبقات خارجية"]},"keywords":{"en":["how to use Clean Architecture","Clean Architecture setup guide","what is Clean Architecture","Clean Architecture vs MVC","Clean Architecture install","Clean Architecture alternative","Clean Architecture for AI agents","Clean Architecture best practices","Clean Architecture tutorial"],"zh":["Clean Architecture 设计","软件系统设计模式","关注点分离","实体层","用例层","接口适配器层","框架层"],"ja":["Clean Architecture 設計","ソフトウェアシステム設計パターン","コンセントリックレイヤー","エンティティ層","ユースケース層","インターフェースアダプター層","フレームワーク層"],"ko":["Clean Architecture 설계","소프트웨어 시스템 설계 패턴","관심사 분리","엔티티층","유즈케이스층","인터페이스 어댑터층","프레임워크층"],"es":["arquitectura limpia","diseño de software","separación de concernientes","lógica de negocio","capas concéntricas","entidades","casos de uso","adaptadores de interfaz"],"fr":["architecture propre","conception de logiciels","séparation des préoccupations","logique métier","couches concéntriques","entités","cas d''utilisation","adaptateurs d''interface"],"de":["clean architecture","software-entwicklung","trennung von bedenken","geschäftslogik","konzentrische schichten","entitäten","anwendungsfälle","schnittstellen-adapter"],"pt":["arquitetura limpa","desenvolvimento de software","padrão de design","camadas concêntricas","entidades","casos de uso","adaptadores de interface","ferramentas de desenvolvimento"],"ru":["чистая архитектура","разработка программного обеспечения","шаблон проектирования","концентрические слои","сущности","случаи использования","адаптеры интерфейса","инструменты разработки","ИИ Агенты"],"ar":["هندسة البرمجيات النظيفة","تطوير البرمجيات","نمط تصميم","الطبقات المتراكبة","الكيانات","حالات الاستخدام","مُحوِّلات الواجهة","أدوات التطوير","أدوات الذكاء الاصطناعي"]}},"owner":"harrytran998","repo":"crossfire","repoPath":"harrytran998/crossfire","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.643Z","topics":[],"category":"community","skillMd":{"name":"Clean Architecture","description":"Clean Architecture module pattern for scalable, maintainable applications","bodyPreview":"## Overview\n\nClean Architecture emphasizes separation of concerns through concentric layers. The innermost layers (entities, use cases) contain business logic independent of external frameworks and tools. Outer layers handle UI, database, and infrastructure concerns.\n\n## Key Concepts\n\n### Concentric Layers\n\n1. **Entities**: Core business rules (innermost)\n2. **Use Cases**: Application-specific business rules\n3. **Interface Adapters**: Translates between use cases and external systems\n4. **Framew","body":"## Overview\n\nClean Architecture emphasizes separation of concerns through concentric layers. The innermost layers (entities, use cases) contain business logic independent of external frameworks and tools. Outer layers handle UI, database, and infrastructure concerns.\n\n## Key Concepts\n\n### Concentric Layers\n\n1. **Entities**: Core business rules (innermost)\n2. **Use Cases**: Application-specific business rules\n3. **Interface Adapters**: Translates between use cases and external systems\n4. **Frameworks & Drivers**: Web frameworks, databases, etc. (outermost)\n\n### Dependency Rule\n\nDependencies point inward only. Inner layers never depend on outer layers.\n\n### Independence\n\n- Independent of frameworks\n- Testable\n- Independent of UI\n- Independent of database\n- Independent of external agencies\n\n### Modularity\n\nOrganize code by business domain rather than technical layer.\n\n## Code Examples\n\n### Project Structure\n\n```\nsrc/\n├── domain/                  # Core business entities\n│   ├── User/\n│   │   └── User.ts\n│   ├── Post/\n│   │   └── Post.ts\n│   └── Comment/\n│       └── Comment.ts\n├── usecases/               # Application business rules\n│   ├── User/\n│   │   ├── CreateUserUseCase.ts\n│   │   └── GetUserUseCase.ts\n│   ├── Post/\n│   │   ├── CreatePostUseCase.ts\n│   │   └── ListPostsUseCase.ts\n│   └── Comment/\n│       └── CreateCommentUseCase.ts\n├── adapters/               # Interface adapters\n│   ├── http/\n│   │   ├── UserController.ts\n│   │   ├── PostController.ts\n│   │   └── routes.ts\n│   ├── persistence/\n│   │   ├── UserRepository.ts\n│   │   ├── PostRepository.ts\n│   │   └── CommentRepository.ts\n│   └── presenters/\n│       ├── UserPresenter.ts\n│       └── PostPresenter.ts\n├── frameworks/             # External frameworks\n│   ├── database/\n│   │   └── PostgresDatabase.ts\n│   ├── http/\n│   │   └── ExpressServer.ts\n│   └── cache/\n│       └── RedisCache.ts\n└── di/                     # Dependency Injection\n    └── Container.ts\n```\n\n### Domain Layer - Entities\n\n```typescript\n// src/domain/User/User.ts\nexport interface IUser {\n  id: string\n  email: string\n  username: string\n  passwordHash: string\n  createdAt: Date\n  updatedAt: Date\n}\n\nexport class User implements IUser {\n  id: string\n  email: string\n  username: string\n  passwordHash: string\n  createdAt: Date\n  updatedAt: Date\n\n  constructor(\n    id: string,\n    email: string,\n    username: string,\n    passwordHash: string,\n    createdAt: Date,\n    updatedAt: Date\n  ) {\n    this.id = id\n    this.email = email\n    this.username = username\n    this.passwordHash = passwordHash\n    this.createdAt = createdAt\n    this.updatedAt = updatedAt\n  }\n\n  // Business logic methods\n  updateEmail(newEmail: string): void {\n    if (!this.isValidEmail(newEmail)) {\n      throw new Error(''Invalid email format'')\n    }\n    this.email = newEmail\n    this.updatedAt = new Date()\n  }\n\n  private isValidEmail(email: string): boolean {\n    return /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email)\n  }\n}\n\n// src/domain/User/UserRepository.ts\nexport interface IUserRepository {\n  findById(id: string): Promise<User | null>\n  findByEmail(email: string): Promise<User | null>\n  save(user: User): Promise<void>\n  delete(id: string): Promise<void>\n  findAll(): Promise<User[]>\n}\n```\n\n### Use Case Layer\n\n```typescript\n// src/usecases/User/CreateUserUseCase.ts\nimport { User, IUserRepository } from ''../../domain/User''\n\nexport interface CreateUserRequest {\n  email: string\n  username: string\n  password: string\n}\n\nexport interface CreateUserResponse {\n  id: string\n  email: string\n  username: string\n}\n\nexport class CreateUserUseCase {\n  constructor(private userRepository: IUserRepository) {}\n\n  async execute(request: CreateUserRequest): Promise<CreateUserResponse> {\n    // Check if user already exists\n    const existingUser = await this.userRepository.findByEmail(request.email)\n    if (existingUser) {\n      throw new Error(''User with this email already exists'')\n    }\n\n    // Create user entity\n    const user = new User(\n      this.generateId(),\n      request.email,\n      request.username,\n      this.hashPassword(request.password),\n      new Date(),\n      new Date()\n    )\n\n    // Save to repository\n    await this.userRepository.save(user)\n\n    // Return response\n    return {\n      id: user.id,\n      email: user.email,\n      username: user.username,\n    }\n  }\n\n  private generateId(): string {\n    return Math.random().toString(36).substring(7)\n  }\n\n  private hashPassword(password: string): string {\n    // In production, use bcrypt or similar\n    return Buffer.from(password).toString(''base64'')\n  }\n}\n\n// src/usecases/User/GetUserUseCase.ts\nexport interface GetUserResponse {\n  id: string\n  email: string\n  username: string\n  createdAt: Date\n}\n\nexport class GetUserUseCase {\n  constructor(private userRepository: IUserRepository) {}\n\n  async execute(userId: string): Promise<GetUserResponse | null> {\n    const user = await this.userRepository.findById(userId)\n    if (!user) {\n      return null\n    }\n\n    return {\n      id: user.id,\n      email: user.email,\n      username: user.username,\n      createdAt: user.createdAt,\n    }\n  }\n}\n```\n\n### Adapter Layer - Controllers\n\n```typescript\n// src/adapters/http/UserController.ts\nimport { CreateUserUseCase, CreateUserRequest } from ''../../usecases/User''\nimport { GetUserUseCase } from ''../../usecases/User/GetUserUseCase''\nimport { IUserPresenter } from ''./presenters/UserPresenter''\n\nexport class UserController {\n  constructor(\n    private createUserUseCase: CreateUserUseCase,\n    private getUserUseCase: GetUserUseCase,\n    private userPresenter: IUserPresenter\n  ) {}\n\n  async createUser(req: any, res: any): Promise<void> {\n    try {\n      const request: CreateUserRequest = {\n        email: req.body.email,\n        username: req.body.username,\n        password: req.body.password,\n      }\n\n      const response = await this.createUserUseCase.execute(request)\n      res.status(201).json(this.userPresenter.present(response))\n    } catch (error: any) {\n      res.status(400).json({ error: error.message })\n    }\n  }\n\n  async getUser(req: any, res: any): Promise<void> {\n    try {\n      const userId = req.params.id\n      const response = await this.getUserUseCase.execute(userId)\n\n      if (!response) {\n        res.status(404).json({ error: ''User not found'' })\n        return\n      }\n\n      res.json(this.userPresenter.present(response))\n    } catch (error: any) {\n      res.status(500).json({ error: error.message })\n    }\n  }\n}\n\n// src/adapters/http/routes.ts\nimport { Router } from ''express''\nimport { UserController } from ''./UserController''\n\nexport function setupRoutes(router: Router, userController: UserController) {\n  router.post(''/users'', (req, res) => userController.createUser(req, res))\n  router.get(''/users/:id'', (req, res) => userController.getUser(req, res))\n}\n```\n\n### Adapter Layer - Repository Implementation\n\n```typescript\n// src/adapters/persistence/UserRepository.ts\nimport { User, IUserRepository } from ''../../domain/User''\nimport { Kysely } from ''kysely''\n\ninterface UserRow {\n  id: string\n  email: string\n  username: string\n  password_hash: string\n  created_at: Date\n  updated_at: Date\n}\n\nexport class UserRepository implements IUserRepository {\n  constructor(private db: Kysely<any>) {}\n\n  async findById(id: string): Promise<User | null> {\n    const row = await this.db\n      .selectFrom(''users'')\n      .selectAll()\n      .where(''id'', ''='', id)\n      .executeTakeFirst()\n\n    if (!row) return null\n    return this.mapRowToUser(row)\n  }\n\n  async findByEmail(email: string): Promise<User | null> {\n    const row = await this.db\n      .selectFrom(''users'')\n      .selectAll()\n      .where(''email'', ''='', email)\n      .executeTakeFirst()\n\n    if (!row) return null\n    return this.mapRowToUser(row)\n  }\n\n  async save(user: User): Promise<void> {\n    await this.db\n      .insertInto(''users'')\n      .values({\n        id: user.id,\n        email: user.email,\n        username: user.username,\n        password_hash: user.passwordHash,\n        created_at: user.createdAt,\n        updated_at: user.updatedAt,\n      })\n      .execute()\n  }\n\n  async delete(id: string): Promise<void> {\n    await this.db.deleteFrom(''users'').where(''id'', ''='', id).execute()\n  }\n\n  async findAll(): Promise<User[]> {\n    const rows = await this.db.selectFrom(''users'').selectAll().execute()\n\n    return rows.map((row) => this.mapRowToUser(row))\n  }\n\n  private mapRowToUser(row: UserRow): User {\n    return new User(\n      row.id,\n      row.email,\n      row.username,\n      row.password_hash,\n      row.created_at,\n      row.updated_at\n    )\n  }\n}\n```\n\n### Presenter\n\n```typescript\n// src/adapters/http/presenters/UserPresenter.ts\nexport interface IUserPresenter {\n  present(data: any): any\n}\n\nexport class UserPresenter implements IUserPresenter {\n  present(userData: any) {\n    return {\n      id: userData.id,\n      email: userData.email,\n      username: userData.username,\n      createdAt: userData.createdAt,\n    }\n  }\n}\n```\n\n### Dependency Injection Container\n\n```typescript\n// src/di/Container.ts\nimport { Kysely } from ''kysely''\nimport { CreateUserUseCase } from ''../usecases/User''\nimport { GetUserUseCase } from ''../usecases/User/GetUserUseCase''\nimport { UserRepository } from ''../adapters/persistence/UserRepository''\nimport { UserController } from ''../adapters/http/UserController''\nimport { UserPresenter } from ''../adapters/http/presenters/UserPresenter''\n\nexport class Container {\n  private static instance: Container\n  private services: Map<string, any> = new Map()\n\n  static getInstance(): Container {\n    if (!Container.instance) {\n      Container.instance = new Container()\n    }\n    return Container.instance\n  }\n\n  registerService(key: string, factory: () => any): void {\n    this.services.set(key, factory)\n  }\n\n  getService(key: string): any {\n    const factory = this.services.get(key)\n    if (!factory) {\n      throw new Error(`Service ${key} not found`)\n    }\n    return factory()\n  }\n\n  setupDefaultServices(db: Kysely<any>): void {\n    // Repositories\n    this.registerService(''userRepository'', () => new UserRepository(db))\n\n    // Use Cases\n    this.registerService(\n      ''createUserUseCase'',\n      () => new CreateUserUseCase(this.getService(''userRepository''))\n    )\n    this.registerService(\n      ''getUserUseCase'',\n      () => new GetUserUseCase(this.getService(''userRepository''))\n    )\n\n    // Presenters\n    this.registerService(''userPresenter'', () => new UserPresenter())\n\n    // Controllers\n    this.registerService(\n      ''userController'',\n      () =>\n        new UserController(\n          this.getService(''createUserUseCase''),\n          this.getService(''getUserUseCase''),\n          this.getService(''userPresenter'')\n        )\n    )\n  }\n}\n```\n\n## Best Practices\n\n### 1. Layer Separation\n\n- Keep business logic in domain and use cases\n- Controllers should be thin and delegate to use cases\n- Don''t leak framework details into inner layers\n\n### 2. Dependency Direction\n\n- Always point dependencies inward\n- Use dependency injection for external dependencies\n- Define interfaces at the layer that needs them\n\n### 3. Testing\n\n- Domain entities are easily testable (no dependencies)\n- Use case tests mock repositories\n- Integration tests verify adapter/framework layer\n\n### 4. Module Organization\n\n- Group by business domain, not technical layer\n- Keep related entities and use cases together\n- Each module should have clear responsibility\n\n### 5. Error Handling\n\n- Define domain-specific exceptions\n- Let use cases throw application exceptions\n- Controllers translate to HTTP responses\n\n## Common Patterns\n\n### Request/Response Objects\n\nUse DTOs to decouple between layers:\n\n```typescript\n// Request and Response are independent of HTTP framework\ninterface CreateUserRequest {\n  email: string\n  username: string\n  password: string\n}\n\ninterface CreateUserResponse {\n  id: string\n  email: string\n  username: string\n}\n```\n\n### Entity Validation\n\n```typescript\nexport class User {\n  static create(email: string, username: string, passwordHash: string): User | Error {\n    if (!this.isValidEmail(email)) {\n      return new Error(''Invalid email'')\n    }\n    return new User(generateId(), email, username, passwordHash, new Date(), new Date())\n  }\n}\n```\n\n### Use Case Composition\n\n```typescript\nexport class UpdateUserAndNotifyUseCase {\n  constructor(\n    private updateUserUseCase: UpdateUserUseCase,\n    private notifyUserUseCase: NotifyUserUseCase\n  ) {}\n\n  async execute(request: any) {\n    const updateResponse = await this.updateUserUseCase.execute(request)\n    await this.notifyUserUseCase.execute(updateResponse.id)\n    return updateResponse\n  }\n}\n```\n"},"lastSynced":"2026-03-08T02:13:42.924Z","agentAnalysis":{"suitability":{"en":"Perfect for Software Development Agents needing modular and scalable system design through concentric layers","zh":"非常适合需要通过同心层实现模块化和可扩展系统设计的软件开发代理","ja":"ソフトウェア開発エージェントが同心層を通じてモジュラーでスケーラブルなシステム設計を必要とする場合に最適","ko":"모듈화되고 확장 가능한 시스템 디자인을 위해 동심层을 통해 구현해야 하는 소프트웨어 개발 에이전트에게 적합","es":"Perfecto para agentes de desarrollo de software que necesitan un diseño de sistema modular y escalable a través de capas concéntricas","fr":"Parfait pour les agents de développement de logiciels nécessitant une conception de système modulaire et évolutives à travers des couches concéntriques","de":"Perfekt für Software-Entwicklungsagenten, die ein modulares und skalierbares Systemdesign durch konzentrische Schichten benötigen","pt":"Perfeito para Agentes de Desenvolvimento de Software que necessitam de design de sistema modular e escalável por meio de camadas concêntricas","ru":"Идеально подходит для агентов разработки программного обеспечения, которым необходим модульный и масштабируемый дизайн системы через концентрические слои","ar":"مثالي للوكلاء الذين يحتاجون إلى تصميم نظام قابل للتوسيع والتحديث من خلال طبقات متحدة المركز"},"recommendation":{"en":"Empowers agents to organize code into entities, use cases, and interface adapters, providing a clear separation of concerns and independence from external frameworks and tools like databases and UI components","zh":"赋予代理组织代码到实体、用例和接口适配器，提供明确的关注点分离和独立于外部框架和工具，如数据库和UI组件","ja":"エージェントがコードをエンティティ、ユースケース、インターフェイスアダプタに組織し、外部フレームワークやツール seperti データベースやUIコンポーネントからの明確な懸念の分離と独立性を提供する","ko":"에이전트가 코드를 엔티티, 유즈케이스, 인터페이스 어댑터로 구성하여 외부 프레임워크 및 툴(예: 데이터베이스 및 UI 컴포넌트)로부터의 명확한 관심사 분리 및 독립성을 제공","es":"Habilita a los agentes a organizar código en entidades, casos de uso e interface adapters, proporcionando una clara separación de preocupaciones e independencia de frameworks y herramientas externas como bases de datos y componentes de interfaz de usuario","fr":"Permet aux agents d''organiser le code en entités, cas d''utilisation et adaptateurs d''interface, fournissant une séparation claire des préoccupations et une indépendance vis-à-vis des frameworks et outils externes tels que les bases de données et les composants d''interface utilisateur","de":"Ermächtigt Agenten, Code in Entitäten, Use Cases und Schnittstellen-Adaptoren zu organisieren, wodurch eine klare Trennung von Belangen und Unabhängigkeit von externen Frameworks und Tools wie Datenbanken und Benutzeroberflächen-Komponenten gewährleistet wird","pt":"Habilita os agentes a organizar o código em entidades, casos de uso e adaptadores de interface, fornecendo uma clara separação de preocupações e independência de frameworks e ferramentas externas, como bancos de dados e componentes de UI","ru":"Наделяет агентов возможностью организовывать код в сущности, случаи использования и интерфейсные адаптеры, обеспечивая четкое разделение проблем и независимость от внешних фреймворков и инструментов, таких как базы данных и компоненты UI","ar":"يمنح الوكلاء القدرة على تنظيم الشفرة في كيانات وحدات استخدام وأدوات واجهة، مما يوفر فصلًا واضحًا للقلق واستقلالية من الإطارات والادوات الخارجية مثل قواعد البيانات ومكونات الواجهة"},"useCases":{"en":["Separating business logic from infrastructure concerns","Implementing interface adapters for seamless integration with external systems","Organizing code into modular entities and use cases"],"zh":["将业务逻辑与基础设施关注点分离","为与外部系统的无缝集成实现接口适配器","将代码组织到模块化实体和用例"],"ja":["ビジネスロジックをインフラストラクチャの懸念から分離する","外部システムとのシームレスな統合のためにインターフェイスアダプタを実装する","コードをモジュラーなエンティティとユースケースに組織する"],"ko":["비즈니스 로직을 인프라스트럭처 관심사로부터 분리","외부 시스템과無縫な 통합을 위한 인터페이스 어댑터 구현","코드를 모듈화된 엔티티 및 유즈케이스로 구성"],"es":["Separar la lógica empresarial de las preocupaciones de infraestructura","Implementar adaptadores de interfaz para una integración sin problemas con sistemas externos","Organizar código en entidades y casos de uso modulares"],"fr":["Séparer la logique métier des préoccupations d''infrastructure","Mettre en œuvre des adaptateurs d''interface pour une intégration transparente avec des systèmes externes","Organiser le code en entités et cas d''utilisation modulaires"],"de":["Trennen von Geschäftslogik von Infrastruktur-Bedenken","Implementieren von Schnittstellen-Adaptoren für eine nahtlose Integration mit externen Systemen","Organisieren von Code in modulare Entitäten und Use Cases"],"pt":["Separar a lógica de negócios das preocupações de infraestrutura","Implementar adaptadores de interface para integração transparente com sistemas externos","Organizar o código em entidades modulares e casos de uso"],"ru":["Разделить логику бизнеса от проблем инфраструктуры","Реализовать интерфейсные адаптеры для бесшовной интеграции с внешними системами","Организовать код в модульные сущности и случаи использования"],"ar":["فصل المنطق التجاري عن القلق البنيوي","تنفيذ أدوات واجهة لتكامل متوافق مع الأنظمة الخارجية","تنظيم الشفرة في كيانات قابلة للتحديث وأجزاء استخدام"]},"limitations":{"en":["Requires careful planning and design of concentric layers","May add complexity to small-scale projects"],"zh":["需要仔细规划和同心层的设计","可能会为小规模项目增加复杂性"],"ja":["同心層の慎重な計画と設計が必要","小規模プロジェクトに複雑性を追加する可能性がある"],"ko":["동심층의 신중한 계획 및 설계가 필요","소규모 프로젝트에 복잡성을 추가할 수 있음"],"es":["Requiere una planificación y diseño cuidadosos de las capas concéntricas","Puede agregar complejidad a proyectos de pequeña escala"],"fr":["Nécessite une planification et une conception soigneuses des couches concéntriques","Peut ajouter de la complexité aux projets à petite échelle"],"de":["Erfordert eine sorgfältige Planung und Gestaltung der konzentrischen Schichten","Kann Komplexität zu kleinen Projekten hinzufügen"],"pt":["Exige planejamento e design cuidadosos das camadas concêntricas","Pode adicionar complexidade a projetos de pequena escala"],"ru":["Требует тщательного планирования и проектирования концентрических слоев","Может добавить сложность в небольших проектах"],"ar":["يتطلب التخطيط والتصميم الدقيق للطبقات المتحدة المركز","يمكن أن يضيف تعقيدًا إلى المشاريع الصغيرة"]},"version":4},"contentHash":"06e1c308e5cee765f28f3efbe38c233c767c6dd181a64dc78cd5d3894c852117","qualityScore":33}');
