INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('harrytran998/crossfire/Clean Architecture', 'Clean Architecture', 'harrytran998', 'crossfire', 'community', 'Clean Architecture harrytran998 crossfire community Clean Architecture helps AI agents separate concerns through concentric layers, containing business logic independent of external frameworks. It benefits developers by organizing code into entities, use cases, and interface adapters. Clean Architecture 强调通过集中的层次结构实现关注点分离，包括实体、用例、接口适配器和框架等层次 Clean Architecture は、コンセントリックレイヤーを使用してソフトウェアシステムの設計を分離し、実体、ユースケース、インターフェースアダプターなどを含む Clean Architecture 는 관심사를 분리하고 계층화하여 소프트웨어 시스템의 유지보수성을 향상시키는 설계 패턴으로, 엔티티、유즈케이스、인터페이스 어댑터 등을 포함 La Arquitectura Limpia enfatiza la separación de concernientes a través de capas concéntricas, mejorando la independencia de la lógica de negocio L''Architecture Propre met l''accent sur la séparation des préoccupations à travers des couches concéntriques, améliorant l''indépendance de la logique métier Die Clean Architecture betont die Trennung von Bedenken durch konzentrische Schichten, verbessert die Unabhängigkeit der Geschäftslogik A Arquitetura Limpa é um padrão de design que separa as preocupações em camadas concêntricas, permitindo uma maior flexibilidade e manutenção Чистая Архитектура - это шаблон проектирования, который разделяет проблемы на концентрические слои, обеспечивая большую гибкость и поддержку هندسة البرمجيات النظيفة هي نمط تصميم يفصل الاهتمامات في طبقات متراكبة، مما يسمح بمرونة أكبر وضمان جودة how to use Clean Architecture Clean Architecture setup guide what is Clean Architecture Clean Architecture vs MVC Clean Architecture install Clean Architecture alternative Clean Architecture for AI agents Clean Architecture best practices Clean Architecture tutorial Clean Architecture 设计 软件系统设计模式 关注点分离 实体层 用例层 接口适配器层 框架层 Separates business logic into innermost entities and use cases Utilizes interface adapters to translate between use cases and external systems Organizes code into concentric layers for better maintainability Decouples application-specific business rules from external frameworks and tools Enables developers to work with a framework-agnostic inner layer Clean Architecture is a software design pattern emphasizing separation of concerns through concentric layers, including entities, use cases, interface adapters, and frameworks.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('alexander-kastil/skills-collection/azure-identity-ts', 'community', 'alexander-kastil', 'skills-collection', 'alexander-kastil/skills-collection', 'azure-identity-ts', 0, 0, 33, '2026-03-08T01:57:15.646Z', '2026-03-08T02:13:46.823Z', '4a792eac6e5d1901678db0c2fdfe51213a4ce0183c9cd1c02063b3b5e82163e4', '{"id":"alexander-kastil/skills-collection/azure-identity-ts","name":"azure-identity-ts","description":{"en":"The azure-identity-ts skill enables developers to authenticate to Azure services with various credential types, streamlining their workflow. It benefits developers working with Azure and TypeScript.","zh":"azure-identity-ts 是 Azure 服务身份验证的 TypeScript SDK，支持各种凭据类型","ja":"azure-identity-ts は Azure サービスの認証のための TypeScript SDK であり、様々な資格情報タイプをサポートしています","ko":"azure-identity-ts는 Azure 서비스 인증을 위한 TypeScript SDK이며 다양한 자격 증명 유형을 지원합니다","es":"Azure-identity-ts es una SDK para autenticar en Azure con credenciales de diferentes tipos. Instala y configura la SDK para empezar","fr":"Azure-identity-ts est une SDK d''authentification Azure qui prend en charge différents types de credentials. Installez et configurez la SDK pour commencer","de":"Azure-identity-ts ist eine SDK zur Authentifizierung in Azure mit verschiedenen Credential-Typen. Installieren und konfigurieren Sie die SDK, um loszulegen","pt":"O azure-identity-ts é uma SDK para autenticação em serviços Azure. Ele suporta diferentes tipos de credenciais, incluindo Service Principal e Certificate","ru":"azure-identity-ts — это SDK для аутентификации в Azure. Он поддерживает различные типы учетных данных, включая Service Principal и Certificate","ar":"azure-identity-ts هو SDK لتحقق الهوية في خدمات Azure. يدعم أنواعًا مختلفة من الاعتمادات، بما في ذلك Service Principal و Certificate"},"seo":{"title":{"en":"azure-identity-ts: Authentication Setup Guide for AI Agents","zh":"azure-identity-ts 设置指南：Azure 服务身份验证","ja":"azure-identity-ts セットアップガイド：Azure サービスの認証","ko":"azure-identity-ts 설정 가이드: Azure 서비스 인증","es":"Guía de configuración de azure-identity-ts para autentica...","fr":"Configurer azure-identity-ts pour l''authentification Azur...","de":"Einrichtungsanleitung für azure-identity-ts zur Azure-Aut...","pt":"Guia de Configuração do azure-identity-ts para Autenticaç...","ru":"Настройка ИИ Агентов: azure-identity-ts для аутентификаци...","ar":"دليل إعداد azure-identity-ts لتحقق الهوية في خدمات Azure"},"description":{"en":"Unlock seamless Azure service authentication with azure-identity-ts. Learn how to install and configure this SDK for TypeScript, and discover its key features.","zh":"使用 azure-identity-ts 身份验证 SDK 进行 Azure 服务身份验证，支持各种凭据类型","ja":"azure-identity-ts を使用して Azure サービスの認証を行う、様々な資格情報タイプをサポート","ko":"azure-identity-ts 身份验证 SDK를 사용하여 Azure 서비스 인증을 수행하고 다양한 자격 증명 유형을 지원합니다","es":"Aprende a autenticar en Azure con azure-identity-ts y diferentes tipos de credenciales. Descubre cómo instalar y configurar la SDK","fr":"Découvrez comment authentifier vos applications Azure avec azure-identity-ts et différents types de credentials. Installez et configurez la SDK","de":"Erfahren Sie, wie Sie mit azure-identity-ts und verschiedenen Credential-Typen in Azure authentifizieren. Installieren und konfigurieren Sie die SDK","pt":"Aprenda a usar o azure-identity-ts para autenticar em serviços Azure com diferentes tipos de credenciais","ru":"Узнайте, как использовать azure-identity-ts для аутентификации в Azure с различными типами учетных данных","ar":"تعرف على كيفية استخدام azure-identity-ts لتحقق الهوية في خدمات Azure باستخدام أنواع مختلفة من الاعتمادات"},"definition":{"en":"azure-identity-ts is a TypeScript SDK for authenticating to Azure services using different credential types, including service principals and certificates.","zh":"azure-identity-ts 是一个 TypeScript 库，用于 Azure 服务身份验证","ja":"azure-identity-ts は Azure サービスの認証のための TypeScript ライブラリです","ko":"azure-identity-ts는 Azure 서비스 인증을 위한 TypeScript 라이브러리입니다","es":"Azure-identity-ts es una biblioteca de autenticación para TypeScript que permite a los desarrolladores autenticar en Azure","fr":"Azure-identity-ts est une bibliothèque d''authentification pour TypeScript qui permet aux développeurs de s''authentifier sur Azure","de":"Azure-identity-ts ist eine Authentifizierungsbibliothek für TypeScript, die es Entwicklern ermöglicht, sich in Azure zu authentifizieren","pt":"O que é azure-identity-ts? É uma biblioteca TypeScript para autenticação em serviços Azure","ru":"Что такое azure-identity-ts? Это библиотека TypeScript для аутентификации в Azure","ar":"ما هو azure-identity-ts؟ إنه مكتبة TypeScript لتحقق الهوية في خدمات Azure"},"features":{"en":["Supports installation via npm using the @azure/identity package","Utilizes environment variables for service principal configuration, including AZURE_TENANT_ID and AZURE_CLIENT_ID","Allows for certificate-based authentication with AZURE_CLIENT_CERTIFICATE_PATH and AZURE_CLIENT_CERTIFICATE_PASS","Enables authentication to Azure services with various credential types","Provides a flexible and secure way to manage Azure service authentication"],"zh":["支持服务主体（秘密）身份验证","支持服务主体（证书）身份验证","使用环境变量配置身份验证","支持 Azure 服务身份验证","使用 npm 安装 @azure/identity 包"],"ja":["サービスプリンシパル（シークレット）認証をサポート","サービスプリンシパル（証明書）認証をサポート","環境変数を使用して認証を構成","Azure サービスの認証をサポート","npm を使用して @azure/identity パッケージをインストール"],"ko":["서비스 주체(비밀) 인증을 지원","서비스 주체(인증서) 인증을 지원","환경 변수를 사용하여 인증을 구성","Azure 서비스 인증을 지원","npm을 사용하여 @azure/identity 패키지를 설치"],"es":["Autenticación con credenciales de tipo secreto","Autenticación con credenciales de tipo certificado","Soporte para variables de entorno como AZURE_TENANT_ID y AZURE_CLIENT_ID","Instalación mediante npm con @azure/identity","Compatibilidad con TypeScript"],"fr":["Authentification avec des credentials de type secret","Authentification avec des credentials de type certificat","Prise en charge des variables d''environnement comme AZURE_TENANT_ID et AZURE_CLIENT_ID","Installation via npm avec @azure/identity","Compatibilité avec TypeScript"],"de":["Authentifizierung mit Credentials vom Typ Geheimnis","Authentifizierung mit Credentials vom Typ Zertifikat","Unterstützung für Umgebungsvariablen wie AZURE_TENANT_ID und AZURE_CLIENT_ID","Installation über npm mit @azure/identity","Kompatibilität mit TypeScript"],"pt":["Suporte a diferentes tipos de credenciais, incluindo Service Principal e Certificate","Autenticação em serviços Azure com o uso de variáveis de ambiente","Instalação simples com npm","Suporte a certificados X.509","Autenticação com client secret"],"ru":["Поддержка различных типов учетных данных, включая Service Principal и Certificate","Аутентификация в Azure с использованием переменных окружения","Простая установка с помощью npm","Поддержка сертификатов X.509","Аутентификация с client secret"],"ar":["دعم لأنواع مختلفة من الاعتمادات، بما في ذلك Service Principal و Certificate","تحقق الهوية في خدمات Azure باستخدام متغيرات البيئة","تركيب بسيط مع npm","دعم للشهادات X.509","تحقق الهوية مع client secret"]},"keywords":{"en":["azure-identity-ts install","azure-identity-ts setup guide","how to use azure-identity-ts","what is azure-identity-ts","azure-identity-ts alternative","azure-identity-ts vs azure-sdk","typescript azure authentication","azure service principal configuration","azure certificate authentication"],"zh":["azure-identity-ts","Azure 服务身份验证","TypeScript SDK","服务主体身份验证","环境变量配置","npm 安装","Azure 身份验证"],"ja":["azure-identity-ts","Azure サービスの認証","TypeScript SDK","サービスプリンシパル認証","環境変数の構成","npm インストール","Azure 認証"],"ko":["azure-identity-ts","Azure 서비스 인증","TypeScript SDK","서비스 주체 인증","환경 변수 구성","npm 설치","Azure 인증"],"es":["azure identity ts","autenticación en azure","credenciales de azure","typescript azure","azure identity sdk","instalación de azure identity","configuración de azure identity"],"fr":["azure identity ts","authentification azure","credentials azure","typescript azure","sdk azure identity","installation azure identity","configuration azure identity"],"de":["azure identity ts","authentifizierung in azure","azure-credentials","typescript azure","azure-identity-sdk","installation von azure-identity","konfiguration von azure-identity"],"pt":["azure-identity-ts","autenticação em serviços Azure","Service Principal","Certificate","variáveis de ambiente","npm","TypeScript","SDK para Azure"],"ru":["azure-identity-ts","аутентификация в Azure","Service Principal","Certificate","переменные окружения","npm","TypeScript","SDK для Azure","ИИ Агенты"],"ar":["azure-identity-ts","تحقق الهوية في خدمات Azure","Service Principal","Certificate","متغيرات البيئة","npm","TypeScript","SDK ل Azure","أدوات الذكاء الاصطناعي"]}},"owner":"alexander-kastil","repo":"skills-collection","repoPath":"alexander-kastil/skills-collection","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.646Z","topics":[],"category":"community","skillMd":{"name":"azure-identity-ts","description":"Authenticate to Azure services using Azure Identity SDK for JavaScript (@azure/identity). Use when configuring authentication with DefaultAzureCredential, managed identity, service principals, or interactive browser login.","bodyPreview":"# Azure Identity SDK for TypeScript\n\nAuthenticate to Azure services with various credential types.\n\n## Installation\n\n```bash\nnpm install @azure/identity\n```\n\n## Environment Variables\n\n### Service Principal (Secret)\n\n```bash\nAZURE_TENANT_ID=<tenant-id>\nAZURE_CLIENT_ID=<client-id>\nAZURE_CLIENT_SECRET=<client-secret>\n```\n\n### Service Principal (Certificate)\n\n```bash\nAZURE_TENANT_ID=<tenant-id>\nAZURE_CLIENT_ID=<client-id>\nAZURE_CLIENT_CERTIFICATE_PATH=/path/to/cert.pem\nAZURE_CLIENT_CERTIFICATE_PASSW","body":"# Azure Identity SDK for TypeScript\n\nAuthenticate to Azure services with various credential types.\n\n## Installation\n\n```bash\nnpm install @azure/identity\n```\n\n## Environment Variables\n\n### Service Principal (Secret)\n\n```bash\nAZURE_TENANT_ID=<tenant-id>\nAZURE_CLIENT_ID=<client-id>\nAZURE_CLIENT_SECRET=<client-secret>\n```\n\n### Service Principal (Certificate)\n\n```bash\nAZURE_TENANT_ID=<tenant-id>\nAZURE_CLIENT_ID=<client-id>\nAZURE_CLIENT_CERTIFICATE_PATH=/path/to/cert.pem\nAZURE_CLIENT_CERTIFICATE_PASSWORD=<optional-password>\n```\n\n### Workload Identity (Kubernetes)\n\n```bash\nAZURE_TENANT_ID=<tenant-id>\nAZURE_CLIENT_ID=<client-id>\nAZURE_FEDERATED_TOKEN_FILE=/var/run/secrets/tokens/azure-identity\n```\n\n## DefaultAzureCredential (Recommended)\n\n```typescript\nimport { DefaultAzureCredential } from \"@azure/identity\";\n\nconst credential = new DefaultAzureCredential();\n\n// Use with any Azure SDK client\nimport { BlobServiceClient } from \"@azure/storage-blob\";\nconst blobClient = new BlobServiceClient(\n  \"https://<account>.blob.core.windows.net\",\n  credential\n);\n```\n\n**Credential Chain Order:**\n1. EnvironmentCredential\n2. WorkloadIdentityCredential\n3. ManagedIdentityCredential\n4. VisualStudioCodeCredential\n5. AzureCliCredential\n6. AzurePowerShellCredential\n7. AzureDeveloperCliCredential\n\n## Managed Identity\n\n### System-Assigned\n\n```typescript\nimport { ManagedIdentityCredential } from \"@azure/identity\";\n\nconst credential = new ManagedIdentityCredential();\n```\n\n### User-Assigned (by Client ID)\n\n```typescript\nconst credential = new ManagedIdentityCredential({\n  clientId: \"<user-assigned-client-id>\"\n});\n```\n\n### User-Assigned (by Resource ID)\n\n```typescript\nconst credential = new ManagedIdentityCredential({\n  resourceId: \"/subscriptions/<sub>/resourceGroups/<rg>/providers/Microsoft.ManagedIdentity/userAssignedIdentities/<name>\"\n});\n```\n\n## Service Principal\n\n### Client Secret\n\n```typescript\nimport { ClientSecretCredential } from \"@azure/identity\";\n\nconst credential = new ClientSecretCredential(\n  \"<tenant-id>\",\n  \"<client-id>\",\n  \"<client-secret>\"\n);\n```\n\n### Client Certificate\n\n```typescript\nimport { ClientCertificateCredential } from \"@azure/identity\";\n\nconst credential = new ClientCertificateCredential(\n  \"<tenant-id>\",\n  \"<client-id>\",\n  { certificatePath: \"/path/to/cert.pem\" }\n);\n\n// With password\nconst credentialWithPwd = new ClientCertificateCredential(\n  \"<tenant-id>\",\n  \"<client-id>\",\n  { \n    certificatePath: \"/path/to/cert.pem\",\n    certificatePassword: \"<password>\"\n  }\n);\n```\n\n## Interactive Authentication\n\n### Browser-Based Login\n\n```typescript\nimport { InteractiveBrowserCredential } from \"@azure/identity\";\n\nconst credential = new InteractiveBrowserCredential({\n  clientId: \"<client-id>\",\n  tenantId: \"<tenant-id>\",\n  loginHint: \"user@example.com\"\n});\n```\n\n### Device Code Flow\n\n```typescript\nimport { DeviceCodeCredential } from \"@azure/identity\";\n\nconst credential = new DeviceCodeCredential({\n  clientId: \"<client-id>\",\n  tenantId: \"<tenant-id>\",\n  userPromptCallback: (info) => {\n    console.log(info.message);\n    // \"To sign in, use a web browser to open...\"\n  }\n});\n```\n\n## Custom Credential Chain\n\n```typescript\nimport { \n  ChainedTokenCredential,\n  ManagedIdentityCredential,\n  AzureCliCredential\n} from \"@azure/identity\";\n\n// Try managed identity first, fall back to CLI\nconst credential = new ChainedTokenCredential(\n  new ManagedIdentityCredential(),\n  new AzureCliCredential()\n);\n```\n\n## Developer Credentials\n\n### Azure CLI\n\n```typescript\nimport { AzureCliCredential } from \"@azure/identity\";\n\nconst credential = new AzureCliCredential();\n// Uses: az login\n```\n\n### Azure Developer CLI\n\n```typescript\nimport { AzureDeveloperCliCredential } from \"@azure/identity\";\n\nconst credential = new AzureDeveloperCliCredential();\n// Uses: azd auth login\n```\n\n### Azure PowerShell\n\n```typescript\nimport { AzurePowerShellCredential } from \"@azure/identity\";\n\nconst credential = new AzurePowerShellCredential();\n// Uses: Connect-AzAccount\n```\n\n## Sovereign Clouds\n\n```typescript\nimport { ClientSecretCredential, AzureAuthorityHosts } from \"@azure/identity\";\n\n// Azure Government\nconst credential = new ClientSecretCredential(\n  \"<tenant>\", \"<client>\", \"<secret>\",\n  { authorityHost: AzureAuthorityHosts.AzureGovernment }\n);\n\n// Azure China\nconst credentialChina = new ClientSecretCredential(\n  \"<tenant>\", \"<client>\", \"<secret>\",\n  { authorityHost: AzureAuthorityHosts.AzureChina }\n);\n```\n\n## Bearer Token Provider\n\n```typescript\nimport { DefaultAzureCredential, getBearerTokenProvider } from \"@azure/identity\";\n\nconst credential = new DefaultAzureCredential();\n\n// Create a function that returns tokens\nconst getAccessToken = getBearerTokenProvider(\n  credential,\n  \"https://cognitiveservices.azure.com/.default\"\n);\n\n// Use with APIs that need bearer tokens\nconst token = await getAccessToken();\n```\n\n## Key Types\n\n```typescript\nimport type { \n  TokenCredential, \n  AccessToken, \n  GetTokenOptions \n} from \"@azure/core-auth\";\n\nimport {\n  DefaultAzureCredential,\n  DefaultAzureCredentialOptions,\n  ManagedIdentityCredential,\n  ClientSecretCredential,\n  ClientCertificateCredential,\n  InteractiveBrowserCredential,\n  ChainedTokenCredential,\n  AzureCliCredential,\n  AzurePowerShellCredential,\n  AzureDeveloperCliCredential,\n  DeviceCodeCredential,\n  AzureAuthorityHosts\n} from \"@azure/identity\";\n```\n\n## Custom Credential Implementation\n\n```typescript\nimport type { TokenCredential, AccessToken, GetTokenOptions } from \"@azure/core-auth\";\n\nclass CustomCredential implements TokenCredential {\n  async getToken(\n    scopes: string | string[],\n    options?: GetTokenOptions\n  ): Promise<AccessToken | null> {\n    // Custom token acquisition logic\n    return {\n      token: \"<access-token>\",\n      expiresOnTimestamp: Date.now() + 3600000\n    };\n  }\n}\n```\n\n## Debugging\n\n```typescript\nimport { setLogLevel, AzureLogger } from \"@azure/logger\";\n\nsetLogLevel(\"verbose\");\n\n// Custom log handler\nAzureLogger.log = (...args) => {\n  console.log(\"[Azure]\", ...args);\n};\n```\n\n## Best Practices\n\n1. **Use DefaultAzureCredential** - Works in development (CLI) and production (managed identity)\n2. **Never hardcode credentials** - Use environment variables or managed identity\n3. **Prefer managed identity** - No secrets to manage in production\n4. **Scope credentials appropriately** - Use user-assigned identity for multi-tenant scenarios\n5. **Handle token refresh** - Azure SDK handles this automatically\n6. **Use ChainedTokenCredential** - For custom fallback scenarios\n"},"lastSynced":"2026-03-08T02:13:46.823Z","agentAnalysis":{"suitability":{"en":"Perfect for Cloud Agents needing streamlined Azure service authentication with TypeScript","zh":"非常适合需要简化Azure服务身份验证的TypeScript的Cloud Agents","ja":"TypeScriptを使用してAzureサービス認証を簡略化する必要があるCloud Agentsに最適","ko":"TypeScript를 사용하여 Azure 서비스 인증을 간소화하는 클라우드 에이전트에 적합합니다","es":"Perfecto para Agentes en la Nube que necesitan una autenticación de servicios de Azure simplificada con TypeScript","fr":"Parfait pour les agents Cloud nécessitant une authentification de services Azure simplifiée avec TypeScript","de":"Perfekt für Cloud-Agents, die eine vereinfachte Azure-Dienstauthentifizierung mit TypeScript benötigen","pt":"Perfeito para Agentes de Nuvem que precisam de autenticação de serviço do Azure simplificada com TypeScript","ru":"Идеально для облачных агентов, которым требуется упрощенная аутентификация служб Azure с помощью TypeScript","ar":"مثالي لعميل السحابة الذي يحتاج إلى تضمين خدمة Azure المبسطة مع TypeScript"},"recommendation":{"en":"Empowers agents to authenticate to Azure services with various credential types, including Service Principal secrets and certificates, using the @azure/identity library and environment variables like AZURE_TENANT_ID and AZURE_CLIENT_ID","zh":"使代理能够使用@azure/identity库和环境变量（如AZURE_TENANT_ID和AZURE_CLIENT_ID）进行Azure服务认证，支持服务主体密钥和证书等多种凭据类型","ja":"@azure/identityライブラリおよび環境変数（AZURE_TENANT_IDやAZURE_CLIENT_IDなど）を使用して、サービスプリンシパルのシークレットや証明書などの複数の資格情報タイプをサポートし、Azureサービスへの認証を可能にする","ko":"에이전트가 @azure/identity 라이브러리 및 환경 변수(AZURE_TENANT_ID 및 AZURE_CLIENT_ID 등)를 사용하여 Azure 서비스에 인증할 수 있도록 하며, 서비스 주체 비밀 및 인증서를 포함한 다양한 자격 증명 유형을 지원합니다","es":"Habilita a los agentes a autenticarse en los servicios de Azure con varios tipos de credenciales, incluidos secretos y certificados de Service Principal, utilizando la biblioteca @azure/identity y variables de entorno como AZURE_TENANT_ID y AZURE_CLIENT_ID","fr":"Permet aux agents de s''authentifier auprès des services Azure avec différents types de informations d''identification, notamment les secrets et les certificats de Service Principal, en utilisant la bibliothèque @azure/identity et des variables d''environnement comme AZURE_TENANT_ID et AZURE_CLIENT_ID","de":"Ermöglicht es den Agents, sich bei Azure-Diensten mit verschiedenen Anmeldeinformationstypen zu authentifizieren, einschließlich Service Principal-Geheimnissen und -Zertifikaten, unter Verwendung der Bibliothek @azure/identity und Umgebungsvariablen wie AZURE_TENANT_ID und AZURE_CLIENT_ID","pt":"Habilita os agentes a se autenticarem nos serviços do Azure com vários tipos de credenciais, incluindo segredos e certificados do Principal de Serviço, usando a biblioteca @azure/identity e variáveis de ambiente como AZURE_TENANT_ID e AZURE_CLIENT_ID","ru":"Позволяет агентам аутентифицироваться в службах Azure с помощью различных типов учетных данных, включая секреты и сертификаты основного сервиса, используя библиотеку @azure/identity и переменные среды, такие как AZURE_TENANT_ID и AZURE_CLIENT_ID","ar":"تمكين الوكيل من التحقق من صحة الهوية لخدمات Azure باستخدام أنواع مختلفة من بيانات الاعتماد ، بما في ذلك الأسرار وشهادات صاحب الخدمة ، باستخدام مكتبة @azure/identity ومتغيرات البيئة مثل AZURE_TENANT_ID و AZURE_CLIENT_ID"},"useCases":{"en":["Authenticating to Azure services with Service Principal credentials","Streamlining workflow with automated credential management using environment variables","Integrating Azure services with TypeScript applications using the Azure Identity SDK"],"zh":["使用服务主体凭据进行Azure服务身份验证","使用环境变量实现自动化凭据管理来简化工作流程","使用Azure Identity SDK将Azure服务集成到TypeScript应用程序中"],"ja":["サービスプリンシパルの資格情報を使用してAzureサービスに認証する","環境変数を使用して自動化された資格情報管理を実現し、ワークフローを簡略化する","Azure Identity SDKを使用してAzureサービスをTypeScriptアプリケーションに統合する"],"ko":["서비스 주체 자격 증명을 사용하여 Azure 서비스에 인증하는 것","환경 변수를 사용하여 자동화된 자격 증명 관리를 구현하여 워크플ロー를 간소화하는 것","Azure Identity SDK를 사용하여 Azure 서비스를 TypeScript 애플리케이션에 통합하는 것"],"es":["Autenticarse en los servicios de Azure con credenciales de Service Principal","Optimizar el flujo de trabajo con la administración automática de credenciales mediante variables de entorno","Integrar servicios de Azure con aplicaciones TypeScript utilizando el SDK de Azure Identity"],"fr":["S''authentifier auprès des services Azure avec des informations d''identification de Service Principal","Optimiser le flux de travail avec la gestion automatique des informations d''identification via des variables d''environnement","Intégrer les services Azure avec des applications TypeScript en utilisant le SDK d''identité Azure"],"de":["Sich bei Azure-Diensten mit Service Principal-Anmeldeinformationen zu authentifizieren","Den Workflow mit automatisierter Anmeldeinformationenverwaltung mithilfe von Umgebungsvariablen optimieren","Azure-Dienste in TypeScript-Anwendungen mithilfe des Azure Identity SDK integrieren"],"pt":["Autenticar nos serviços do Azure com credenciais do Principal de Serviço","Otimizar o fluxo de trabalho com gerenciamento de credenciais automatizado usando variáveis de ambiente","Integrar serviços do Azure com aplicativos TypeScript usando o SDK de Identidade do Azure"],"ru":["Аутентификация в службах Azure с помощью учетных данных основного сервиса","Оптимизация рабочего процесса с помощью автоматизированного управления учетными данными, используя переменные среды","Интеграция служб Azure с приложениями TypeScript с помощью SDK идентификатора Azure"],"ar":["التحقق من صحة الهوية لخدمات Azure باستخدام بيانات اعتماد صاحب الخدمة","تحسين سير العمل بإدارة بيانات الاعتماد الآلية باستخدام متغيرات البيئة","دمج خدمات Azure مع تطبيقات TypeScript باستخدام SDK الهوية Azure"]},"limitations":{"en":["Requires Azure tenant and client configuration","Dependent on @azure/identity library installation via npm","Limited to Azure services and TypeScript environments"],"zh":["需要Azure租户和客户端配置","依赖@azure/identity库通过npm安装","仅限Azure服务和TypeScript环境"],"ja":["Azureテナントおよびクライアントの構成が必要","npmを介した@azure/identityライブラリのインストールに依存","AzureサービスおよびTypeScript環境に限定"],"ko":["Azure 테넌트 및 클라이언트 구성이 필요합니다","npm을 통해 @azure/identity 라이브러리를 설치하는 것에 의존합니다","Azure 서비스 및 TypeScript 환경에만 محدود됩니다"],"es":["Requiere configuración de inquilino y cliente de Azure","Dependiente de la instalación de la biblioteca @azure/identity a través de npm","Limitado a servicios de Azure y entornos de TypeScript"],"fr":["Nécessite une configuration de locataire et de client Azure","Dépend de l''installation de la bibliothèque @azure/identity via npm","Limité aux services Azure et aux environnements TypeScript"],"de":["Benötigt Azure-Mandanten- und Client-Konfiguration","Hängt von der Installation der Bibliothek @azure/identity über npm ab","Begrenzt auf Azure-Dienste und TypeScript-Umgebungen"],"pt":["Exige configuração de locatário e cliente do Azure","Dependente da instalação da biblioteca @azure/identity via npm","Limitado a serviços do Azure e ambientes TypeScript"],"ru":["Требует настройки арендатора и клиента Azure","Зависит от установки библиотеки @azure/identity через npm","Ограничен службами Azure и средами TypeScript"],"ar":["يتطلب تكوين المستأجر والعميل Azure","يعتمد على تثبيت مكتبة @azure/identity عبر npm","محدود لخدمات Azure وبيئات TypeScript"]},"version":4},"contentHash":"4a792eac6e5d1901678db0c2fdfe51213a4ce0183c9cd1c02063b3b5e82163e4","qualityScore":33}');
