INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('alexander-kastil/skills-collection/azure-identity-ts', 'azure-identity-ts', 'alexander-kastil', 'skills-collection', 'community', 'azure-identity-ts alexander-kastil skills-collection community The azure-identity-ts skill enables developers to authenticate to Azure services with various credential types, streamlining their workflow. It benefits developers working with Azure and TypeScript. azure-identity-ts 是 Azure 服务身份验证的 TypeScript SDK，支持各种凭据类型 azure-identity-ts は Azure サービスの認証のための TypeScript SDK であり、様々な資格情報タイプをサポートしています azure-identity-ts는 Azure 서비스 인증을 위한 TypeScript SDK이며 다양한 자격 증명 유형을 지원합니다 Azure-identity-ts es una SDK para autenticar en Azure con credenciales de diferentes tipos. Instala y configura la SDK para empezar Azure-identity-ts est une SDK d''authentification Azure qui prend en charge différents types de credentials. Installez et configurez la SDK pour commencer Azure-identity-ts ist eine SDK zur Authentifizierung in Azure mit verschiedenen Credential-Typen. Installieren und konfigurieren Sie die SDK, um loszulegen O azure-identity-ts é uma SDK para autenticação em serviços Azure. Ele suporta diferentes tipos de credenciais, incluindo Service Principal e Certificate azure-identity-ts — это SDK для аутентификации в Azure. Он поддерживает различные типы учетных данных, включая Service Principal и Certificate azure-identity-ts هو SDK لتحقق الهوية في خدمات Azure. يدعم أنواعًا مختلفة من الاعتمادات، بما في ذلك Service Principal و Certificate azure-identity-ts install azure-identity-ts setup guide how to use azure-identity-ts what is azure-identity-ts azure-identity-ts alternative azure-identity-ts vs azure-sdk typescript azure authentication azure service principal configuration azure certificate authentication azure-identity-ts Azure 服务身份验证 TypeScript SDK 服务主体身份验证 环境变量配置 npm 安装 Azure 身份验证 Supports installation via npm using the @azure/identity package Utilizes environment variables for service principal configuration, including AZURE_TENANT_ID and AZURE_CLIENT_ID Allows for certificate-based authentication with AZURE_CLIENT_CERTIFICATE_PATH and AZURE_CLIENT_CERTIFICATE_PASS Enables authentication to Azure services with various credential types Provides a flexible and secure way to manage Azure service authentication azure-identity-ts is a TypeScript SDK for authenticating to Azure services using different credential types, including service principals and certificates.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vercel-labs/next-skills/next-cache-components', 'community', 'vercel-labs', 'next-skills', 'vercel-labs/next-skills', 'next-cache-components', 0, 0, 33, '2026-03-08T01:57:15.649Z', '2026-03-08T02:13:50.570Z', '92fc6ac94c5cabdcd13c7dc7aabd6a4d04921e6295dfc00dd9888e375fd1ff4c', '{"id":"vercel-labs/next-skills/next-cache-components","name":"next-cache-components","description":{"en":"next-cache-components enables Partial Prerendering (PPR) in Next.js 16+, allowing developers to mix static, cached, and dynamic content in a single route. This skill benefits developers working with Next.js.","zh":"Next.js 缓存组件允许您混合静态、缓存和动态内容，优化应用性能","ja":"Next.js キャッシュコンポーネントを使用して静的、キャッシュ、動的コンテンツをミックスし、应用のパフォーマンスを最適化する","ko":"Next.js 캐시 컴포넌트를 사용하여 정적, 캐시, 동적 콘텐츠를 혼합하여 애플리케이션 성능을 최적화합니다","es":"next-cache-components permite el prerenderizado parcial de contenido en Next.js, mejorando el rendimiento de las aplicaciones","fr":"next-cache-components permet le prerendering partiel de contenu dans Next.js, améliorant les performances des applications","de":"next-cache-components ermöglicht das teilweise Vorrendern von Inhalten in Next.js, wodurch die Leistung von Anwendungen verbessert wird","pt":"O next-cache-components é uma funcionalidade do Next.js que permite pré-renderização parcial de conteúdo estático, em cache e dinâmico","ru":"ИИ Агенты next-cache-components - это функция Next.js, которая позволяет частичную предварительную отрисовку статического, кэшированного и динамического контента","ar":"next-cache-components هو ميزة في Next.js تسمح بالتحديث المسبق الجزئي للمحتوى الثابت والمتحكم فيه والديناميكي"},"seo":{"title":{"en":"next-cache-components: Partial Prerendering Setup Guide |...","zh":"Next.js 缓存组件设置指南","ja":"Next.js キャッシュコンポーネントのベストプラクティス","ko":"Next.js 캐시 컴포넌트 설치 가이드","es":"Guía de configuración de next-cache-components para desar...","fr":"Mise en place de next-cache-components pour les développeurs","de":"Einrichtungsleitfaden für next-cache-components","pt":"Guia de Configuração do next-cache-components para Desenv...","ru":"Настройка ИИ Агентов: next-cache-components для Разработч...","ar":"دليل إعداد next-cache-components للبرمجة"},"description":{"en":"Unlock mixed static, cached, and dynamic content in Next.js 16+ with next-cache-components. Learn how to enable cache components and improve performance today!","zh":"了解 Next.js 缓存组件的功能和设置方法，优化您的应用性能","ja":"Next.js キャッシュコンポーネントの機能と設定方法を学び、应用のパフォーマンスを最適化する","ko":"Next.js 캐시 컴포넌트의 기능과 설정 방법을 알아보고 애플리케이션 성능을 최적화하세요","es":"Aprende a configurar next-cache-components para mejorar el rendimiento de tus aplicaciones Next.js con prerenderizado parcial","fr":"Découvrez comment configurer next-cache-components pour améliorer les performances de vos applications Next.js avec le prerendering partiel","de":"Erfahren Sie, wie Sie next-cache-components konfigurieren, um die Leistung Ihrer Next.js-Anwendungen mit teilweisem Vorrendern zu verbessern","pt":"Aprenda a configurar o next-cache-components para melhorar o desempenho da sua aplicação Next.js com pré-renderização parcial","ru":"Узнайте, как настроить next-cache-components для улучшения производительности вашего приложения Next.js с частичной предварительной отрисовкой","ar":"تعرف على كيفية إعداد next-cache-components لتحسين أداء تطبيق Next.js الخاص بك مع الإعداد المسبق الجزئي"},"definition":{"en":"next-cache-components is a Next.js feature that enables Partial Prerendering (PPR), allowing for mixed content types in a single route.","zh":"Next.js 缓存组件是一种功能，允许您混合静态、缓存和动态内容","ja":"Next.js キャッシュコンポーネントは、静的、キャッシュ、動的コンテンツをミックスできる機能です","ko":"Next.js 캐시 컴포넌트는 정적, 캐시, 동적 콘텐츠를 혼합할 수 있는 기능입니다","es":"next-cache-components es una característica de Next.js que permite combinar contenido estático, en caché y dinámico en una sola ruta","fr":"next-cache-components est une fonctionnalité de Next.js qui permet de combiner du contenu statique, en cache et dynamique dans une seule route","de":"next-cache-components ist eine Funktion von Next.js, die es ermöglicht, statischen, zwischengespeicherten und dynamischen Inhalt in einer einzigen Route zu kombinieren","pt":"O next-cache-components é uma funcionalidade do Next.js que permite misturar conteúdo estático, em cache e dinâmico em uma única rota","ru":"ИИ Агенты next-cache-components - это функция Next.js, которая позволяет смешивать статический, кэшированный и динамический контент в одном маршруте","ar":"next-cache-components هو ميزة في Next.js تتيح مزج المحتوى الثابت والمتحكم فيه والديناميكي في مسار واحد"},"features":{"en":["Enables Partial Prerendering (PPR) in Next.js 16+","Supports mixed static, cached, and dynamic content in a single route","Replaces the old `experimental.ppr` flag","Configurable via `next.config.ts` file","Allows for three content types: static, cached, and dynamic"],"zh":["启用 Partial Prerendering (PPR)","混合静态、缓存和动态内容","替换旧的 experimental.ppr 标志","使用 next.config.ts 配置","支持 Next.js 16+"],"ja":["Partial Prerendering (PPR) を有効にする","静的、キャッシュ、動的コンテンツをミックスする","旧の experimental.ppr フラグを置き換える","next.config.ts を使用して構成する","Next.js 16+ をサポートする"],"ko":["Partial Prerendering (PPR) 활성화","정적, 캐시, 동적 콘텐츠 混合","旧 experimental.ppr 플래그 대체","next.config.ts 사용하여 구성","Next.js 16+ 지원"],"es":["Habilitación de la prerenderización parcial (PPR) de contenido","Compatibilidad con contenido estático, en caché y dinámico","Reemplazo de la bandera experimental.ppr","Configuración a través de next.config.ts","Mejora del rendimiento de las aplicaciones Next.js"],"fr":["Activation du prerendering partiel (PPR) de contenu","Compatibilité avec du contenu statique, en cache et dynamique","Remplacement du drapeau experimental.ppr","Configuration via next.config.ts","Amélioration des performances des applications Next.js"],"de":["Aktivierung des teilweisen Vorrenderns (PPR) von Inhalten","Unterstützung von statischem, zwischengespeicherten und dynamischem Inhalt","Ersetzung der experimental.ppr-Flagge","Konfiguration über next.config.ts","Verbesserung der Leistung von Next.js-Anwendungen"],"pt":["Pré-renderização parcial de conteúdo estático, em cache e dinâmico","Suporte ao Next.js 16+","Substitui a bandeira experimental.ppr","Permite misturar conteúdo estático, em cache e dinâmico em uma única rota","Melhora o desempenho da aplicação com cache de componentes","Facilita a configuração com next.config.ts"],"ru":["Частичная предварительная отрисовка статического, кэшированного и динамического контента","Поддержка Next.js 16+","Заменяет флаг experimental.ppr","Позволяет смешивать статический, кэшированный и динамический контент в одном маршруте","Улучшает производительность приложения с помощью кэширования компонентов","Облегчает настройку с помощью next.config.ts"],"ar":["التحديث المسبق الجزئي للمحتوى الثابت والمتحكم فيه والديناميكي","دعم Next.js 16+","يستبدل علامة experimental.ppr","يمكّن مزج المحتوى الثابت والمتحكم فيه والديناميكي في مسار واحد","يحسن أداء التطبيق مع التحكم في المكونات","يُسهل الإعداد مع next.config.ts"]},"keywords":{"en":["how to use next-cache-components","what is next-cache-components","next-cache-components alternative","next-cache-components vs react","next-cache-components install","next-cache-components setup guide","next.js 16+ cache components","partial prerendering next.js"],"zh":["Next.js 缓存组件","Partial Prerendering","静态内容","缓存内容","动态内容","Next.js 性能优化","AIエージェント","Next.js 16+"],"ja":["Next.js キャッシュコンポーネント","Partial Prerendering","静的コンテンツ","キャッシュコンテンツ","動的コンテンツ","Next.js パフォーマンス最適化","AIエージェント","Next.js 16+"],"ko":["Next.js 캐시 컴포넌트","Partial Prerendering","정적 콘텐츠","캐시 콘텐츠","동적 콘텐츠","Next.js 성능 최적화","AI 에이전트","Next.js 16+"],"es":["next-cache-components","prerenderizado parcial","Next.js","rendimiento de aplicaciones","contenido estático","contenido en caché","contenido dinámico","configuración de next.config.ts"],"fr":["next-cache-components","prerendering partiel","Next.js","performances des applications","contenu statique","contenu en cache","contenu dynamique","configuration de next.config.ts"],"de":["next-cache-components","teilweises Vorrendern","Next.js","Leistung von Anwendungen","statischer Inhalt","zwischengespeicherter Inhalt","dynamischer Inhalt","Konfiguration von next.config.ts"],"pt":["next-cache-components","pré-renderização parcial","Next.js 16+","experimental.ppr","cache de componentes","desempenho da aplicação","configuração next.config.ts","desenvolvedores Next.js"],"ru":["ИИ Агенты next-cache-components","частичная предварительная отрисовка","Next.js 16+","experimental.ppr","кэширование компонентов","производительность приложения","настройка next.config.ts","разработчики Next.js"],"ar":["مكونات التخزين المؤقت التالية","التحديث المسبق الجزئي","Next.js 16+","experimental.ppr","التحكم في المكونات","أداء التطبيق","إعداد next.config.ts","مطورو Next.js"]}},"owner":"vercel-labs","repo":"next-skills","repoPath":"vercel-labs/next-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.649Z","topics":[],"category":"community","skillMd":{"name":"next-cache-components","description":"Next.js 16 Cache Components - PPR, use cache directive, cacheLife, cacheTag, updateTag","bodyPreview":"# Cache Components (Next.js 16+)\n\nCache Components enable Partial Prerendering (PPR) - mix static, cached, and dynamic content in a single route.\n\n## Enable Cache Components\n\n```ts\n// next.config.ts\nimport type { NextConfig } from ''next''\n\nconst nextConfig: NextConfig = {\n  cacheComponents: true,\n}\n\nexport default nextConfig\n```\n\nThis replaces the old `experimental.ppr` flag.\n\n---\n\n## Three Content Types\n\nWith Cache Components enabled, content falls into three categories:\n\n### 1. Static (Auto-Pre","body":"# Cache Components (Next.js 16+)\n\nCache Components enable Partial Prerendering (PPR) - mix static, cached, and dynamic content in a single route.\n\n## Enable Cache Components\n\n```ts\n// next.config.ts\nimport type { NextConfig } from ''next''\n\nconst nextConfig: NextConfig = {\n  cacheComponents: true,\n}\n\nexport default nextConfig\n```\n\nThis replaces the old `experimental.ppr` flag.\n\n---\n\n## Three Content Types\n\nWith Cache Components enabled, content falls into three categories:\n\n### 1. Static (Auto-Prerendered)\n\nSynchronous code, imports, pure computations - prerendered at build time:\n\n```tsx\nexport default function Page() {\n  return (\n    <header>\n      <h1>Our Blog</h1>  {/* Static - instant */}\n      <nav>...</nav>\n    </header>\n  )\n}\n```\n\n### 2. Cached (`use cache`)\n\nAsync data that doesn''t need fresh fetches every request:\n\n```tsx\nasync function BlogPosts() {\n  ''use cache''\n  cacheLife(''hours'')\n\n  const posts = await db.posts.findMany()\n  return <PostList posts={posts} />\n}\n```\n\n### 3. Dynamic (Suspense)\n\nRuntime data that must be fresh - wrap in Suspense:\n\n```tsx\nimport { Suspense } from ''react''\n\nexport default function Page() {\n  return (\n    <>\n      <BlogPosts />  {/* Cached */}\n\n      <Suspense fallback={<p>Loading...</p>}>\n        <UserPreferences />  {/* Dynamic - streams in */}\n      </Suspense>\n    </>\n  )\n}\n\nasync function UserPreferences() {\n  const theme = (await cookies()).get(''theme'')?.value\n  return <p>Theme: {theme}</p>\n}\n```\n\n---\n\n## `use cache` Directive\n\n### File Level\n\n```tsx\n''use cache''\n\nexport default async function Page() {\n  // Entire page is cached\n  const data = await fetchData()\n  return <div>{data}</div>\n}\n```\n\n### Component Level\n\n```tsx\nexport async function CachedComponent() {\n  ''use cache''\n  const data = await fetchData()\n  return <div>{data}</div>\n}\n```\n\n### Function Level\n\n```tsx\nexport async function getData() {\n  ''use cache''\n  return db.query(''SELECT * FROM posts'')\n}\n```\n\n---\n\n## Cache Profiles\n\n### Built-in Profiles\n\n```tsx\n''use cache''                    // Default: 5m stale, 15m revalidate\n```\n\n```tsx\n''use cache: remote''           // Platform-provided cache (Redis, KV)\n```\n\n```tsx\n''use cache: private''          // For compliance, allows runtime APIs\n```\n\n### `cacheLife()` - Custom Lifetime\n\n```tsx\nimport { cacheLife } from ''next/cache''\n\nasync function getData() {\n  ''use cache''\n  cacheLife(''hours'')  // Built-in profile\n  return fetch(''/api/data'')\n}\n```\n\nBuilt-in profiles: `''default''`, `''minutes''`, `''hours''`, `''days''`, `''weeks''`, `''max''`\n\n### Inline Configuration\n\n```tsx\nasync function getData() {\n  ''use cache''\n  cacheLife({\n    stale: 3600,      // 1 hour - serve stale while revalidating\n    revalidate: 7200, // 2 hours - background revalidation interval\n    expire: 86400,    // 1 day - hard expiration\n  })\n  return fetch(''/api/data'')\n}\n```\n\n---\n\n## Cache Invalidation\n\n### `cacheTag()` - Tag Cached Content\n\n```tsx\nimport { cacheTag } from ''next/cache''\n\nasync function getProducts() {\n  ''use cache''\n  cacheTag(''products'')\n  return db.products.findMany()\n}\n\nasync function getProduct(id: string) {\n  ''use cache''\n  cacheTag(''products'', `product-${id}`)\n  return db.products.findUnique({ where: { id } })\n}\n```\n\n### `updateTag()` - Immediate Invalidation\n\nUse when you need the cache refreshed within the same request:\n\n```tsx\n''use server''\n\nimport { updateTag } from ''next/cache''\n\nexport async function updateProduct(id: string, data: FormData) {\n  await db.products.update({ where: { id }, data })\n  updateTag(`product-${id}`)  // Immediate - same request sees fresh data\n}\n```\n\n### `revalidateTag()` - Background Revalidation\n\nUse for stale-while-revalidate behavior:\n\n```tsx\n''use server''\n\nimport { revalidateTag } from ''next/cache''\n\nexport async function createPost(data: FormData) {\n  await db.posts.create({ data })\n  revalidateTag(''posts'')  // Background - next request sees fresh data\n}\n```\n\n---\n\n## Runtime Data Constraint\n\n**Cannot** access `cookies()`, `headers()`, or `searchParams` inside `use cache`.\n\n### Solution: Pass as Arguments\n\n```tsx\n// Wrong - runtime API inside use cache\nasync function CachedProfile() {\n  ''use cache''\n  const session = (await cookies()).get(''session'')?.value  // Error!\n  return <div>{session}</div>\n}\n\n// Correct - extract outside, pass as argument\nasync function ProfilePage() {\n  const session = (await cookies()).get(''session'')?.value\n  return <CachedProfile sessionId={session} />\n}\n\nasync function CachedProfile({ sessionId }: { sessionId: string }) {\n  ''use cache''\n  // sessionId becomes part of cache key automatically\n  const data = await fetchUserData(sessionId)\n  return <div>{data.name}</div>\n}\n```\n\n### Exception: `use cache: private`\n\nFor compliance requirements when you can''t refactor:\n\n```tsx\nasync function getData() {\n  ''use cache: private''\n  const session = (await cookies()).get(''session'')?.value  // Allowed\n  return fetchData(session)\n}\n```\n\n---\n\n## Cache Key Generation\n\nCache keys are automatic based on:\n- **Build ID** - invalidates all caches on deploy\n- **Function ID** - hash of function location\n- **Serializable arguments** - props become part of key\n- **Closure variables** - outer scope values included\n\n```tsx\nasync function Component({ userId }: { userId: string }) {\n  const getData = async (filter: string) => {\n    ''use cache''\n    // Cache key = userId (closure) + filter (argument)\n    return fetch(`/api/users/${userId}?filter=${filter}`)\n  }\n  return getData(''active'')\n}\n```\n\n---\n\n## Complete Example\n\n```tsx\nimport { Suspense } from ''react''\nimport { cookies } from ''next/headers''\nimport { cacheLife, cacheTag } from ''next/cache''\n\nexport default function DashboardPage() {\n  return (\n    <>\n      {/* Static shell - instant from CDN */}\n      <header><h1>Dashboard</h1></header>\n      <nav>...</nav>\n\n      {/* Cached - fast, revalidates hourly */}\n      <Stats />\n\n      {/* Dynamic - streams in with fresh data */}\n      <Suspense fallback={<NotificationsSkeleton />}>\n        <Notifications />\n      </Suspense>\n    </>\n  )\n}\n\nasync function Stats() {\n  ''use cache''\n  cacheLife(''hours'')\n  cacheTag(''dashboard-stats'')\n\n  const stats = await db.stats.aggregate()\n  return <StatsDisplay stats={stats} />\n}\n\nasync function Notifications() {\n  const userId = (await cookies()).get(''userId'')?.value\n  const notifications = await db.notifications.findMany({\n    where: { userId, read: false }\n  })\n  return <NotificationList items={notifications} />\n}\n```\n\n---\n\n## Migration from Previous Versions\n\n| Old Config | Replacement |\n|-----------|-------------|\n| `experimental.ppr` | `cacheComponents: true` |\n| `dynamic = ''force-dynamic''` | Remove (default behavior) |\n| `dynamic = ''force-static''` | `''use cache''` + `cacheLife(''max'')` |\n| `revalidate = N` | `cacheLife({ revalidate: N })` |\n| `unstable_cache()` | `''use cache''` directive |\n\n### Migrating `unstable_cache` to `use cache`\n\n`unstable_cache` has been replaced by the `use cache` directive in Next.js 16. When `cacheComponents` is enabled, convert `unstable_cache` calls to `use cache` functions:\n\n**Before (`unstable_cache`):**\n\n```tsx\nimport { unstable_cache } from ''next/cache''\n\nconst getCachedUser = unstable_cache(\n  async (id) => getUser(id),\n  [''my-app-user''],\n  {\n    tags: [''users''],\n    revalidate: 60,\n  }\n)\n\nexport default async function Page({ params }: { params: Promise<{ id: string }> }) {\n  const { id } = await params\n  const user = await getCachedUser(id)\n  return <div>{user.name}</div>\n}\n```\n\n**After (`use cache`):**\n\n```tsx\nimport { cacheLife, cacheTag } from ''next/cache''\n\nasync function getCachedUser(id: string) {\n  ''use cache''\n  cacheTag(''users'')\n  cacheLife({ revalidate: 60 })\n  return getUser(id)\n}\n\nexport default async function Page({ params }: { params: Promise<{ id: string }> }) {\n  const { id } = await params\n  const user = await getCachedUser(id)\n  return <div>{user.name}</div>\n}\n```\n\nKey differences:\n- **No manual cache keys** - `use cache` generates keys automatically from function arguments and closures. The `keyParts` array from `unstable_cache` is no longer needed.\n- **Tags** - Replace `options.tags` with `cacheTag()` calls inside the function.\n- **Revalidation** - Replace `options.revalidate` with `cacheLife({ revalidate: N })` or a built-in profile like `cacheLife(''minutes'')`.\n- **Dynamic data** - `unstable_cache` did not support `cookies()` or `headers()` inside the callback. The same restriction applies to `use cache`, but you can use `''use cache: private''` if needed.\n\n---\n\n## Limitations\n\n- **Edge runtime not supported** - requires Node.js\n- **Static export not supported** - needs server\n- **Non-deterministic values** (`Math.random()`, `Date.now()`) execute once at build time inside `use cache`\n\nFor request-time randomness outside cache:\n\n```tsx\nimport { connection } from ''next/server''\n\nasync function DynamicContent() {\n  await connection()  // Defer to request time\n  const id = crypto.randomUUID()  // Different per request\n  return <div>{id}</div>\n}\n```\n\nSources:\n- [Cache Components Guide](https://nextjs.org/docs/app/getting-started/cache-components)\n- [use cache Directive](https://nextjs.org/docs/app/api-reference/directives/use-cache)\n- [unstable_cache (legacy)](https://nextjs.org/docs/app/api-reference/functions/unstable_cache)\n"},"lastSynced":"2026-03-08T02:13:50.570Z","agentAnalysis":{"suitability":{"en":"Perfect for Next.js Agents needing advanced caching and prerendering capabilities for mixed static, cached, and dynamic content.","zh":"适用于需要高级缓存和预渲染功能的 Next.js Agents，尤其是混合静态、缓存和动态内容的场景。","ja":"Next.js エージェントが高度なキャッシュと事前レンダリング機能を必要とする場合に適しています。静的、キャッシュ、動的コンテンツを混合する場合に最適です。","ko":"Next.js 에이전트가 고급 캐싱 및 事前 렌더링 기능을 필요로 하는 경우에 적합합니다. 정적, 캐시, 동적 콘텐츠가 혼합된 경우에 최적입니다.","es":"Perfecto para Agentes de Next.js que necesitan capacidades de caché avanzadas y prerenderizado para contenido estático, en caché y dinámico mixto.","fr":"Parfait pour les Agents Next.js nécessitant des fonctionnalités de mise en cache avancées et de prérendu pour un contenu statique, mis en cache et dynamique mixte.","de":"Perfekt für Next.js-Agents, die erweiterte Caching- und Prerendering-Funktionen für gemischte statische, zwischengespeicherte und dynamische Inhalte benötigen.","pt":"Perfeito para Agentes Next.js que precisam de capacidades avançadas de cache e prerenderização para conteúdo estático, em cache e dinâmico misturado.","ru":"Идеально подходит для агентов Next.js, которым требуются расширенные возможности кэширования и предварительной отрисовки для смешанного статического, кэшированного и динамического контента.","ar":"مثالي لعمليات وكيل Next.js التي تحتاج إلى قدرات متقدمة للتخزين المؤقت والترnder المسبق لمحتوى ثابت ومتحول وديناميكي مخلوط."},"recommendation":{"en":"Empowers agents to leverage Partial Prerendering (PPR) in Next.js 16+, seamlessly integrating static, cached, and dynamic content in a single route using cacheComponents in next.config.ts.","zh":"赋予代理能力，利用 Next.js 16+ 中的部分事前渲染（PPR），使用 next.config.ts 中的 cacheComponents 无缝集成静态、缓存和动态内容到单一路由中。","ja":"エージェントに力を与え、Next.js 16+ の部分事前レンダリング（PPR）を利用し、next.config.ts の cacheComponents を使用して静的、キャッシュ、動的コンテンツを 1 つのルートにシームレスに統合します。","ko":"에이전트에 힘을 부여하여 Next.js 16+의 부분 事前 렌더링（PPR）을 활용하고 next.config.ts의 cacheComponents를 사용하여 정적, 캐시, 동적 콘텐츠를 하나의 루트에 무결점으로 통합합니다.","es":"Habilita a los agentes a aprovechar el prerenderizado parcial (PPR) en Next.js 16+, integrando de forma transparente contenido estático, en caché y dinámico en una sola ruta utilizando cacheComponents en next.config.ts.","fr":"Permet aux agents d''exploiter le prérendu partiel (PPR) dans Next.js 16+, en intégrant de manière transparente le contenu statique, mis en cache et dynamique dans une seule route à l''aide de cacheComponents dans next.config.ts.","de":"Ermächtigt Agents, das partielle Prerendering (PPR) in Next.js 16+ zu nutzen, indem es statischen, zwischengespeicherten und dynamischen Inhalt in einer einzigen Route mithilfe von cacheComponents in next.config.ts nahtlos integriert.","pt":"Habilita os agentes a aproveitar a Prerenderização Parcial (PPR) no Next.js 16+, integrando de forma transparente o conteúdo estático, em cache e dinâmico em uma única rota usando cacheComponents em next.config.ts.","ru":"Позволяет агентам использовать частичную предварительную отрисовку (PPR) в Next.js 16+, бесшовно интегрируя статический, кэшированный и динамический контент в одном маршруте с помощью cacheComponents в next.config.ts.","ar":"تمكين الوكيل من الاستفادة من предварية التصيير الجزئي (PPR) في Next.js 16+ ، وتكامل المحتوى الثابت والمتحول والديناميكي في مسار واحد باستخدام cacheComponents في next.config.ts."},"useCases":{"en":["Enabling Partial Prerendering for improved performance","Mixing static and dynamic content in a single Next.js route","Optimizing Next.js applications with cacheComponents"],"zh":["启用部分事前渲染以提高性能","在单一 Next.js 路由中混合静态和动态内容","使用 cacheComponents 优化 Next.js 应用"],"ja":["パフォーマンスの向上のために部分事前レンダリングを有効にする","1 つの Next.js ルートで静的と動的コンテンツを混合する","cacheComponents を使用して Next.js アプリケーションを最適化する"],"ko":["성능 개선을 위한 부분 事前 렌더링 활성화","하나의 Next.js 루트에서 정적 및 동적 콘텐츠 混合","cacheComponents를 사용한 Next.js 애플리케이션 최적화"],"es":["Habilitar el prerenderizado parcial para una mejor rendimiento","Combinar contenido estático y dinámico en una sola ruta de Next.js","Optimizar aplicaciones de Next.js con cacheComponents"],"fr":["Activer le prérendu partiel pour améliorer les performances","Mélanger le contenu statique et dynamique dans une seule route Next.js","Optimiser les applications Next.js avec cacheComponents"],"de":["Partielles Prerendering für verbesserte Leistung aktivieren","Statischen und dynamischen Inhalt in einer einzigen Next.js-Route kombinieren","Next.js-Anwendungen mit cacheComponents optimieren"],"pt":["Habilitar a Prerenderização Parcial para melhorar o desempenho","Misturar conteúdo estático e dinâmico em uma única rota Next.js","Otimizar aplicações Next.js com cacheComponents"],"ru":["Включение частичной предварительной отрисовки для улучшения производительности","Смешивание статического и динамического контента в одном маршруте Next.js","Оптимизация приложений Next.js с помощью cacheComponents"],"ar":["تمكين предварية التصيير الجزئي لتحسين الأداء","خلط المحتوى الثابت والديناميكي في مسار واحد Next.js","تحسين تطبيقات Next.js باستخدام cacheComponents"]},"limitations":{"en":["Requires Next.js 16+","Needs cacheComponents flag enabled in next.config.ts"],"zh":["需要 Next.js 16+","需要在 next.config.ts 中启用 cacheComponents 标志"],"ja":["Next.js 16+ が必要","next.config.ts で cacheComponents フラグを有効にする必要がある"],"ko":["Next.js 16+ 필요","next.config.ts에서 cacheComponents 플래그 활성화 필요"],"es":["Requiere Next.js 16+","Necesita la marca cacheComponents habilitada en next.config.ts"],"fr":["Nécessite Next.js 16+","Nécessite le flag cacheComponents activé dans next.config.ts"],"de":["Benötigt Next.js 16+","Benötigt die cacheComponents-Flag in next.config.ts aktiviert"],"pt":["Requer Next.js 16+","Necessita da flag cacheComponents habilitada em next.config.ts"],"ru":["Требуется Next.js 16+","Требуется включить флаг cacheComponents в next.config.ts"],"ar":["يتطلب Next.js 16+","يحتاج إلى تمكين علم cacheComponents في next.config.ts"]},"version":4},"contentHash":"92fc6ac94c5cabdcd13c7dc7aabd6a4d04921e6295dfc00dd9888e375fd1ff4c","qualityScore":33}');
