INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('vercel-labs/next-skills/next-cache-components', 'next-cache-components', 'vercel-labs', 'next-skills', 'community', 'next-cache-components vercel-labs next-skills community next-cache-components enables Partial Prerendering (PPR) in Next.js 16+, allowing developers to mix static, cached, and dynamic content in a single route. This skill benefits developers working with Next.js. Next.js 缓存组件允许您混合静态、缓存和动态内容，优化应用性能 Next.js キャッシュコンポーネントを使用して静的、キャッシュ、動的コンテンツをミックスし、应用のパフォーマンスを最適化する Next.js 캐시 컴포넌트를 사용하여 정적, 캐시, 동적 콘텐츠를 혼합하여 애플리케이션 성능을 최적화합니다 next-cache-components permite el prerenderizado parcial de contenido en Next.js, mejorando el rendimiento de las aplicaciones next-cache-components permet le prerendering partiel de contenu dans Next.js, améliorant les performances des applications next-cache-components ermöglicht das teilweise Vorrendern von Inhalten in Next.js, wodurch die Leistung von Anwendungen verbessert wird O next-cache-components é uma funcionalidade do Next.js que permite pré-renderização parcial de conteúdo estático, em cache e dinâmico ИИ Агенты next-cache-components - это функция Next.js, которая позволяет частичную предварительную отрисовку статического, кэшированного и динамического контента next-cache-components هو ميزة في Next.js تسمح بالتحديث المسبق الجزئي للمحتوى الثابت والمتحكم فيه والديناميكي how to use next-cache-components what is next-cache-components next-cache-components alternative next-cache-components vs react next-cache-components install next-cache-components setup guide next.js 16+ cache components partial prerendering next.js Next.js 缓存组件 Partial Prerendering 静态内容 缓存内容 动态内容 Next.js 性能优化 AIエージェント Next.js 16+ Enables Partial Prerendering (PPR) in Next.js 16+ Supports mixed static, cached, and dynamic content in a single route Replaces the old `experimental.ppr` flag Configurable via `next.config.ts` file Allows for three content types: static, cached, and dynamic next-cache-components is a Next.js feature that enables Partial Prerendering (PPR), allowing for mixed content types in a single route.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Svenja-dev/claude-code-skills/ui-freeze', 'community', 'Svenja-dev', 'claude-code-skills', 'Svenja-dev/claude-code-skills', 'ui-freeze', 0, 0, 33, '2026-03-08T01:57:15.655Z', '2026-03-08T02:13:57.908Z', 'ebc0c8be172e63cb7f1c9a5cf90192dd2e9b1a13e149c218b2bda87223d73d65', '{"id":"Svenja-dev/claude-code-skills/ui-freeze","name":"ui-freeze","description":{"en":"The ui-freeze skill protects critical theme files and important UI components from unintended changes, benefiting B2B SaaS developers. It enforces quality gates and TypeScript, ensuring a stable and consistent design.","zh":"UI Freeze 是一个自定义的 Claude Code CLI 技能，用于保护设计和主题文件免受意外更改。它支持 Tailwind 配置、TypeScript 和多 LLM 顾问等功能","ja":"UI Freeze は、デザインとテーマファイルを意図しない変更から保護するためのカスタム Claude Code CLI スキルです。Tailwind 構成、TypeScript、多 LLM アドバイザーなどの機能をサポートしています","ko":"UI Freeze는 디자인 및 테마 파일을 의도하지 않은 변경으로부터 보호하기 위한 사용자 지정 Claude Code CLI 스킬입니다. Tailwind 구성, TypeScript 및 다중 LLM 어드바이저 등과 같은 기능을 지원합니다","es":"ui-freeze es una habilidad de Claude Code CLI que protege los archivos de diseño y temas de cambios no deseados en proyectos B2B SaaS","fr":"ui-freeze est une compétence de Claude Code CLI qui protège les fichiers de conception et de thèmes contre les modifications indésirables dans les projets B2B SaaS","de":"ui-freeze ist eine Fähigkeit von Claude Code CLI, die Design- und Theme-Dateien vor unerwünschten Änderungen in B2B-SaaS-Projekten schützt","pt":"ui-freeze é uma habilidade que protege arquivos de design e tema contra alterações não intencionais, com recursos como TypeScript e multi-LLM advisor","ru":"ui-freeze - это навык, который защищает файлы дизайна и темы от непреднамеренных изменений, с функциями seperti TypeScript и multi-LLM advisor","ar":"ui-freeze هو مهارة لحماية ملفات التصميم والموضوع من التغييرات غير المقصودة، مع ميزات مثل TypeScript وmulti-LLM advisor"},"seo":{"title":{"en":"ui-freeze: Protect Design Files with Automated Quality Ga...","zh":"UI Freeze 设置指南：保护设计和主题文件","ja":"UI Freeze のベストプラクティス：デザインとテーマファイルの保護","ko":"UI Freeze 설정 가이드: 디자인 및 테마 파일 보호","es":"Configuración de ui-freeze: Protección de Diseño y Temas","fr":"Guide d''installation de ui-freeze: Sauvegarde de la Conce...","de":"ui-freeze Einrichtung: Schutz von Design- und Theme-Dateien","pt":"Configurando ui-freeze: Proteja Arquivos de Design com Fe...","ru":"Настройка ui-freeze: Защита файлов дизайна с помощью ИИ А...","ar":"إعداد ui-freeze: حماية ملفات التصميم باستخدام أدوات الذكا..."},"description":{"en":"Discover how ui-freeze safeguards your design and theme files from unintended changes. Learn how to set up and utilize this skill for B2B SaaS development","zh":"使用 UI Freeze AI 에이전트保护您的设计和主题文件免受意外更改，确保 B2B SaaS 应用的质量和一致性","ja":"UI Freeze AIエージェントを使用して、デザインとテーマファイルを意図しない変更から保護し、B2B SaaS アプリケーションの品質と一貫性を確保する","ko":"UI Freeze AI 에이전트를 사용하여 디자인 및 테마 파일을 의도하지 않은 변경으로부터 보호하고 B2B SaaS 애플리케이션의 품질 및 일관성을 보장합니다","es":"Aprende a configurar ui-freeze para proteger tus archivos de diseño y temas de cambios no deseados en proyectos B2B SaaS","fr":"Découvrez comment installer ui-freeze pour protéger vos fichiers de conception et de thèmes contre les modifications indésirables dans les projets B2B SaaS","de":"Erfahren Sie, wie Sie ui-freeze einrichten, um Ihre Design- und Theme-Dateien vor unerwünschten Änderungen in B2B-SaaS-Projekten zu schützen","pt":"Aprenda a configurar ui-freeze para proteger arquivos de design e tema contra alterações não intencionais, com recursos como TypeScript e multi-LLM advisor","ru":"Узнайте, как настроить ui-freeze для защиты файлов дизайна и темы от непреднамеренных изменений, с функциями seperti TypeScript и multi-LLM advisor","ar":"تعرف على كيفية إعداد ui-freeze لحماية ملفات التصميم والموضوع من التغييرات غير المقصودة، مع ميزات مثل TypeScript وmulti-LLM advisor"},"definition":{"en":"ui-freeze is a skill that automatically protects design and theme files from unintended changes, locking critical files like tailwind.config and index.css","zh":"UI Freeze 是一种保护设计和主题文件免受意外更改的技术，用于确保 B2B SaaS 应用的质量和一致性","ja":"UI Freeze は、デザインとテーマファイルを意図しない変更から保護する技術であり、B2B SaaS アプリケーションの品質と一貫性を確保するために使用されます","ko":"UI Freeze는 의도하지 않은 변경으로부터 디자인 및 테마 파일을 보호하기 위한 기술로서 B2B SaaS 애플리케이션의 품질 및 일관성을 보장하기 위해 사용됩니다","es":"ui-freeze es una herramienta de protección de diseño y temas que evita cambios no deseados en archivos críticos","fr":"ui-freeze est un outil de protection de la conception et des thèmes qui empêche les modifications indésirables dans les fichiers critiques","de":"ui-freeze ist ein Tool zum Schutz von Design- und Theme-Dateien, das unerwünschte Änderungen in kritischen Dateien verhindert","pt":"ui-freeze é uma habilidade que protege arquivos de design e tema contra alterações não intencionais","ru":"ui-freeze - это навык, который защищает файлы дизайна и темы от непреднамеренных изменений","ar":"ui-freeze هو مهارة لحماية ملفات التصميم والموضوع من التغييرات غير المقصودة"},"features":{"en":["Automatically locks critical theme files like tailwind.config and index.css","Warns on changes to important UI components like Header and Footer","Enforces TypeScript for consistent and stable design","Provides multi-LLM advisor for informed design decisions","Protects global styles and CSS variables in files like globals.css and variables.css"],"zh":["保护关键主题文件（Tailwind 配置、全局样式等）","警告重要 UI 组件（导航、页脚等）","支持 TypeScript 和多 LLM 顾问","自动触发保护机制","防止意外更改和确保一致性"],"ja":["重要なテーマファイル（Tailwind 構成、グローバルスタイル等）を保護","重要な UI コンポーネント（ナビゲーション、フッター等）を警告","TypeScript と多 LLM アドバイザーをサポート","自動的に保護メカニズムをトリガー","意図しない変更を防止し、一貫性を確保"],"ko":["중요한 테마 파일（Tailwind 구성, 전역 스타일 등）을 보호","중요한 UI 컴포넌트（네비게이션, 푸터 등）을 경고","TypeScript 및 다중 LLM 어드바이저를 지원","자동으로 보호 메커니즘을 트리거","의도하지 않은 변경을 방지하고 일관성을 보장"],"es":["Protección de archivos de tema críticos como tailwind.config.* y **/index.css","Advertencia para componentes de interfaz de usuario importantes como **/Header.* y **/Footer.*","Compatibilidad con TypeScript y multi-LLM advisor","Integración con CLI para una configuración fácil","Protección de variables de tema y CSS personalizadas"],"fr":["Protection des fichiers de thème critiques tels que tailwind.config.* et **/index.css","Avertissement pour les composants d''interface utilisateur importants tels que **/Header.* et **/Footer.*","Compatibilité avec TypeScript et multi-LLM advisor","Intégration avec CLI pour une configuration facile","Protection des variables de thème et des propriétés CSS personnalisées"],"de":["Schutz von kritischen Theme-Dateien wie tailwind.config.* und **/index.css","Warnung für wichtige Benutzeroberflächenkomponenten wie **/Header.* und **/Footer.*","Unterstützung für TypeScript und multi-LLM-Advisor","Integration mit CLI für eine einfache Konfiguration","Schutz von Theme-Variablen und benutzerdefinierten CSS-Eigenschaften"],"pt":["Proteção de arquivos de design e tema","Recursos como TypeScript e multi-LLM advisor","Detecção de alterações em arquivos críticos como tailwind.config.*","Avisos para alterações em componentes de UI importantes como Header e Footer","Integração com CLI para automação de tarefas"],"ru":["Защита файлов дизайна и темы","Функции seperti TypeScript и multi-LLM advisor","Обнаружение изменений в критических файлах seperti tailwind.config.*","Предупреждения для изменений в важных компонентах UI zoals Header и Footer","Интеграция с CLI для автоматизации задач"],"ar":["حماية ملفات التصميم والموضوع","ميزات مثل TypeScript وmulti-LLM advisor","اكتشاف التغييرات في الملفات الحرجة مثل tailwind.config.*","تحذيرات للتغييرات في مكونات واجهة المستخدم المهمة مثل Header وFooter","التكامل مع CLI لتأتمة المهام"]},"keywords":{"en":["how to use ui-freeze","ui-freeze setup guide","what is ui-freeze","ui-freeze alternative","ui-freeze vs competitors","ui-freeze install","ui-freeze for B2B SaaS development","automated quality gates for design files","TypeScript enforcement in ui-freeze"],"zh":["UI Freeze","AI 에이전트","B2B SaaS","设计保护","主题文件保护","Tailwind 配置","TypeScript","多 LLM 顾问"],"ja":["UI Freeze","AIエージェント","B2B SaaS","デザイン保護","テーマファイル保護","Tailwind 構成","TypeScript","多 LLM アドバイザー"],"ko":["UI Freeze","AI 에이전트","B2B SaaS","디자인 보호","테마 파일 보호","Tailwind 구성","TypeScript","다중 LLM 어드바이저"],"es":["ui-freeze","protección de diseño","protección de temas","B2B SaaS","Claude Code CLI","TypeScript","multi-LLM advisor","configuración de ui-freeze","herramientas de desarrollo"],"fr":["ui-freeze","protection de la conception","protection des thèmes","B2B SaaS","Claude Code CLI","TypeScript","multi-LLM advisor","configuration de ui-freeze","outils de développement"],"de":["ui-freeze","Schutz von Design","Schutz von Theme-Dateien","B2B-SaaS","Claude Code CLI","TypeScript","multi-LLM-Advisor","Konfiguration von ui-freeze","Entwicklungstools"],"pt":["ui-freeze","proteção de arquivos de design","TypeScript","multi-LLM advisor","CLI","automação de tarefas","desenvolvimento de software","ferramentas de inteligência artificial"],"ru":["ui-freeze","защита файлов дизайна","TypeScript","multi-LLM advisor","CLI","автоматизация задач","разработка программного обеспечения","ИИ Агенты"],"ar":["ui-freeze","حماية ملفات التصميم","TypeScript","multi-LLM advisor","CLI","تأتمة المهام","تطوير البرمجيات","أدوات الذكاء الاصطناعي"]}},"owner":"Svenja-dev","repo":"claude-code-skills","repoPath":"Svenja-dev/claude-code-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.655Z","topics":[],"category":"community","skillMd":{"name":"ui-freeze","description":"Protects design and theme files from unintended changes. Locks tailwind.config, global CSS, and theme variables. Requires explicit confirmation before modifying UI components. Activate on changes to CSS, theme config, or layout components.","bodyPreview":"# UI Freeze\n\n> Skill to protect design and theme files from unintended changes\n\n## Trigger\n\nThis skill activates automatically on changes to:\n\n### Critical Theme Files (LOCKED)\n\n- `tailwind.config.*` - Tailwind configuration\n- `**/index.css` - Global styles\n- `**/globals.css` - Global CSS variables\n- `**/theme.css` - Theme variables\n- `**/variables.css` - CSS custom properties\n\n### Important UI Components (WARNING)\n\n- `**/Header.*` - Navigation & Branding\n- `**/Footer.*` - Footer & Legal Links\n-","body":"# UI Freeze\n\n> Skill to protect design and theme files from unintended changes\n\n## Trigger\n\nThis skill activates automatically on changes to:\n\n### Critical Theme Files (LOCKED)\n\n- `tailwind.config.*` - Tailwind configuration\n- `**/index.css` - Global styles\n- `**/globals.css` - Global CSS variables\n- `**/theme.css` - Theme variables\n- `**/variables.css` - CSS custom properties\n\n### Important UI Components (WARNING)\n\n- `**/Header.*` - Navigation & Branding\n- `**/Footer.*` - Footer & Legal Links\n- `**/App.*` - Root Layout & Theme Provider\n- `**/Layout.*` - Main Layout wrapper\n\n## Rules\n\n### On Changes to LOCKED Files:\n\n1. **STOP** - Don''t automatically make changes\n2. **SHOW** - Display exactly what would change\n3. **JUSTIFY** - Why is this change needed?\n4. **IMPACT** - Which components are affected?\n5. **PREVIEW** - If possible, show visual diff\n6. **CONFIRM** - Explicit \"Yes, change design\"\n\n### On Changes to WARNING Files:\n\n1. **NOTE** - \"This file affects the UI\"\n2. **JUSTIFY** - Brief explanation of change\n3. **PROCEED** - Can continue without explicit confirmation\n\n## Example Dialog\n\n**User:** \"Change the background color to gray\"\n\n**Claude (with this skill):**\n\n```\nUI FREEZE ACTIVE\n\nYou want to modify a theme file. This affects:\n- File: tailwind.config.ts\n- Change: backgroundColor from #0f172a to #374151\n- Affected pages: ALL (global style)\n\nLast stable version: v1.0-stable-ui\n\nPreview:\n- Before: Dark blue background (#0f172a)\n- After: Gray background (#374151)\n\nShould I proceed? (Answer with \"Yes, change design\")\nAlternative: \"Show me a before/after screenshot\"\n```\n\n## Golden Screenshots (Reference)\n\nDefine baseline screenshots for visual regression:\n\n| Page | File | Last Check |\n|------|------|------------|\n| Login | `tests/screenshots/login-baseline.png` | - |\n| Dashboard | `tests/screenshots/dashboard-baseline.png` | - |\n| Settings | `tests/screenshots/settings-baseline.png` | - |\n\n## CSS Variables (Single Source of Truth)\n\nAll colors must be defined via CSS Variables:\n\n```css\n/* CORRECT - in theme.css or tailwind.config */\n--color-primary: #3B82F6;\n--color-background: #0f172a;\n\n/* WRONG - hard values in components */\nbackground-color: #0f172a; /* Not allowed */\nclassName=\"bg-[#0f172a]\"   /* Not allowed */\n```\n\n## Integration with Visual Regression\n\nAfter every approved design change:\n\n1. Run `npx playwright test --update-snapshots`\n2. Commit new baseline screenshots\n3. Update release tag (e.g., `v1.1-ui-gray-theme`)\n\n## Emergency Rollback\n\nIf design was accidentally changed:\n\n```bash\n# Restore last stable state\ngit checkout <last-stable-tag> -- tailwind.config.ts src/index.css\n\n# Or: Reset all theme files\ngit checkout <last-stable-tag> -- $(git diff --name-only HEAD <last-stable-tag> | grep -E ''\\.(css|config)'')\n```\n\n## Configuration\n\nAdd to your CLAUDE.md:\n\n```markdown\n### UI Protection\n\nLocked Files:\n- tailwind.config.*\n- src/index.css\n- src/globals.css\n\nLast Stable UI Tag: v1.0-stable-ui\n\nDesign System:\n- Primary: #3B82F6\n- Background: #0f172a\n- Use CSS variables only\n```\n\n---\n\n## Origin\n\nOriginally developed for [fabrikIQ](https://fabrikiq.com) - AI-powered manufacturing data analysis.\n\n## License\n\nMIT - Free to use and modify\n"},"lastSynced":"2026-03-08T02:13:57.908Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents requiring strict control over UI component modifications and theme consistency.","zh":"适用于需要对 UI 组件修改和主题一致性进行严格控制的前端代理。","ja":"UI コンポーネントの変更とテーマの一貫性を厳格に制御する必要があるフロントエンド エージェントに最適です。","ko":"UI 컴포넌트 수정 및 테마 일관성을 엄격하게 제어해야 하는 프론트엔드 에이전트에 적합합니다.","es":"Ideal para Agentes Frontend que requieren un control estricto sobre las modificaciones de los componentes de la interfaz de usuario y la coherencia del tema.","fr":"Idéal pour les agents Frontend nécessitant un contrôle strict des modifications des composants d''interface utilisateur et de la cohérence du thème.","de":"Ideal für Frontend-Agents, die eine strenge Kontrolle über die Modifikationen von Benutzeroberflächenkomponenten und die Konsistenz des Designs benötigen.","pt":"Ideal para Agentes Frontend que requerem controle rigoroso sobre modificações de componentes de interface do usuário e consistência de tema.","ru":"Идеален для агентов Frontend, требующих строгого контроля над изменениями компонентов пользовательского интерфейса и согласованности темы.","ar":"مثالي لوكلاء الواجهة الأمامية الذين يتطلبون سيطرة صارمة على تعديلات مكونات واجهة المستخدم وثبات الموضوع."},"recommendation":{"en":"Empowers agents to enforce quality gates and TypeScript checks, ensuring a stable design by protecting critical theme files such as tailwind.config and global CSS variables, and warning on changes to important UI components like Header and Footer sections.","zh":"赋予代理人执行质量门槛和 TypeScript 检查的能力，通过保护关键主题文件（如 tailwind.config 和全局 CSS 变量）以及警告重要 UI 组件（如头部和底部部分）的更改，确保稳定的设计。","ja":"エージェントに品質ゲートとTypeScriptチェックを実行する能力を付与し、重要なUIコンポーネント（ヘッダーとフッター部分など）の変更に対して警告を発生させることで、tailwind.configやグローバルCSS変数などの重要なテーマファイルを保護し、安定した設計を保証します。","ko":"에이전트에게 품질 게이트 및 TypeScript 확인을 수행할 수 있는 능력을 부여하여, tailwind.config 및 전역 CSS 변수와 같은 중요한 테마 파일을 보호하고, 헤더 및 풋터 섹션과 같은 중요한 UI 컴포넌트의 변경에 대한 경고를 발생시켜 안정적인 디자인을 보장합니다.","es":"Permite a los agentes aplicar controles de calidad y comprobaciones de TypeScript, garantizando un diseño estable al proteger archivos de tema críticos como tailwind.config y variables CSS globales, y alertar sobre cambios en componentes de interfaz de usuario importantes como las secciones de Encabezado y Pie de página.","fr":"Permet aux agents d''appliquer des contrôles de qualité et des vérifications de TypeScript, garantissant une conception stable en protégeant les fichiers de thème critiques tels que tailwind.config et les variables CSS globales, et en avertissant des modifications apportées à des composants d''interface utilisateur importants comme les sections d''En-tête et de Pied de page.","de":"Ermächtigt die Agenten, Qualitätskontrollen und TypeScript-Überprüfungen durchzuführen, um ein stabiles Design zu gewährleisten, indem kritische Theme-Dateien wie tailwind.config und globale CSS-Variablen geschützt werden und Warnungen bei Änderungen an wichtigen Benutzeroberflächenkomponenten wie Kopf- und Fußzeilen ausgelöst werden.","pt":"Habilita os agentes a impor portais de qualidade e verificações de TypeScript, garantindo um design estável ao proteger arquivos de tema críticos, como tailwind.config e variáveis CSS globais, e alertando sobre alterações em componentes de UI importantes, como seções de Cabeçalho e Rodapé.","ru":"Наделяет агентов возможностью устанавливать ворота качества и проверки TypeScript, обеспечивая стабильный дизайн путем защиты критических файлов темы, таких как tailwind.config и глобальные переменные CSS, и предупреждая об изменениях важных компонентов пользовательского интерфейса, таких как секции Заголовка и Подвала.","ar":"يمنح الوكلاء القدرة على فرض بوابات جودة وفحوصات TypeScript، مما يضمن تصميمًا مستقرًا من خلال حماية ملفات الموضوع الحاسمة، مثل tailwind.config ومتغيرات CSS العالمیة، وتحذير التعديلات على مكونات واجهة المستخدم المهمة، مثل أقسام العنوان والتذييل."},"useCases":{"en":["Automating theme file protection","Validating TypeScript configurations","Preventing unintended changes to global styles and UI components"],"zh":["自动保护主题文件","验证TypeScript配置","防止全局样式和UI组件的意外更改"],"ja":["テーマファイルの保護を自動化する","TypeScriptの設定を検証する","グローバルスタイルとUIコンポーネントの意図しない変更を防止する"],"ko":["테마 파일 보호 자동화","TypeScript 구성 검증","전역 스타일 및 UI 컴포넌트의 의도하지 않은 변경 방지"],"es":["Automatizar la protección de archivos de tema","Validar configuraciones de TypeScript","Prevenir cambios no deseados en estilos globales y componentes de la interfaz de usuario"],"fr":["Automatiser la protection des fichiers de thème","Valider les configurations de TypeScript","Prévenir les modifications involontaires des styles globaux et des composants d''interface utilisateur"],"de":["Automatisieren des Schutzes von Theme-Dateien","Validieren von TypeScript-Konfigurationen","Verhindern unbeabsichtigter Änderungen an globalen Stilen und Benutzeroberflächenkomponenten"],"pt":["Automatizar a proteção de arquivos de tema","Validar configurações de TypeScript","Prevenir alterações involuntárias em estilos globais e componentes de UI"],"ru":["Автоматизировать защиту файлов темы","Проверять конфигурации TypeScript","Предотвращать непреднамеренные изменения глобальных стилей и компонентов пользовательского интерфейса"],"ar":["تأتمتة حماية ملفات الموضوع"," التحقق من إعدادات TypeScript","منع التغييرات غير المقصودة للأسلوب العالمي ومكوّنات واجهة المستخدم"]},"limitations":{"en":["Requires access to specific file types like tailwind.config and index.css","Limited to protecting predefined critical theme files and UI components"],"zh":["需要访问特定文件类型，如tailwind.config和index.css","仅限保护预定义的关键主题文件和UI组件"],"ja":["tailwind.configやindex.cssなどの特定のファイルタイプへのアクセスが必要","事前に定義された重要なテーマファイルとUIコンポーネントのみを保護する"],"ko":["tailwind.config 및 index.css와 같은 특정 파일 유형에 대한 액세스가 필요함","미리 정의된 중요한 테마 파일 및 UI 컴포넌트만 보호"],"es":["Requiere acceso a tipos de archivos específicos como tailwind.config e index.css","Limitado a la protección de archivos de tema críticos y componentes de la interfaz de usuario predefinidos"],"fr":["Nécessite l''accès à des types de fichiers spécifiques comme tailwind.config et index.css","Limité à la protection de fichiers de thème critiques et de composants d''interface utilisateur prédéfinis"],"de":["Erfordert den Zugriff auf bestimmte Dateitypen wie tailwind.config und index.css","Begrenzt auf den Schutz vordefinierter kritischer Theme-Dateien und Benutzeroberflächenkomponenten"],"pt":["Requer acesso a tipos de arquivos específicos, como tailwind.config e index.css","Limitado à proteção de arquivos de tema críticos e componentes de UI predefinidos"],"ru":["Требует доступа к определенным типам файлов, таким как tailwind.config и index.css","Ограничен защитой предопределенных критических файлов темы и компонентов пользовательского интерфейса"],"ar":["يتطلب الوصول إلى أنواع ملفات محددة، مثل tailwind.config وindex.css","محدود بحماية ملفات الموضوع الحاسمة ومكونات واجهة المستخدم المحددة مسبقًا"]},"version":4},"contentHash":"ebc0c8be172e63cb7f1c9a5cf90192dd2e9b1a13e149c218b2bda87223d73d65","qualityScore":33}');
