INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sorafujitani/claudedot/pr:cmt-plan', 'pr:cmt-plan', 'sorafujitani', 'claudedot', 'community', 'pr:cmt-plan sorafujitani claudedot community The pr:cmt-plan skill analyzes unresolved GitHub PR comments and develops improvement plans for developers. It retrieves related PR information using gh pr list and ctx:github agent. pr:cmt-plan AIエージェント用于分析GitHub PR评论并创建改进计划，支持git和gh命令 pr:cmt-plan AIエージェントはGitHub PRのレビューコメントを分析し、改善計画を策定します。gitおよびghコマンドに対応しています pr:cmt-plan AI 에이전트는 GitHub PR의 리뷰 댓글을 분석하여 개선 계획을 수립하며 git 및 gh 명령어를 지원합니다 pr:cmt-plan es una habilidad para analizar comentarios de GitHub y planificar mejoras en tus proyectos de desarrollo pr:cmt-plan est une compétence pour analyser les commentaires GitHub et planifier des améliorations dans vos projets de développement pr:cmt-plan ist eine Fähigkeit zur Analyse von GitHub-Kommentaren und zur Planung von Verbesserungen in Ihren Entwicklungsprojekten O pr:cmt-plan é uma ferramenta para análise de comentários de PR em GitHub, permitindo que os desenvolvedores melhorem seus fluxos de trabalho Пр:cmt-plan - это инструмент для анализа комментариев PR в GitHub, позволяющий разработчикам улучшить свои рабочие процессы بر:cmt-plan هو أداة لتحليل تعليقات طلب السحب في GitHub، مما يسمح للمطورين بتحسين سير عملهم pr:cmt-plan setup guide GitHub PR comment analysis how to use pr:cmt-plan pr:cmt-plan vs github pr tools pr:cmt-plan install git branch management gh pr list command ctx:github agent tutorial pr:cmt-plan alternative github pr improvement planning PR评论分析 改进计划 AIエージェント GitHub PR git命令 gh命令 ctx:githubエージェント JSON数据处理 jq数据处理 Retrieves current branch name using git branch --show-current Identifies related PR numbers with gh pr list --head [branch-name] --json number,url Analyzes PR comments using ctx:github agent Develops systematic improvement plans based on PR metadata and body Utilizes subagent_type: ctx:github for PR context retrieval Supports JSON output for structured PR information pr:cmt-plan is a GitHub PR comment analysis and improvement planning skill that helps developers manage and resolve PR comments efficiently.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anombyte93/atlas-session-lifecycle/sync', 'community', 'anombyte93', 'atlas-session-lifecycle', 'anombyte93/atlas-session-lifecycle', 'sync', 0, 0, 33, '2026-03-08T01:57:15.662Z', '2026-03-08T02:14:09.001Z', 'ffd069bfffe2e47ffad9ed6404fce787d790b0c5135fcbe5ba03a54d9ad71d4d', '{"id":"anombyte93/atlas-session-lifecycle/sync","name":"sync","description":{"en":"The sync skill manages session lifecycles for Claude Code, providing persistent memory and automated file editing. It benefits developers by simplifying session management.","zh":"Sync技能是Claude Code的会话生命周期管理，实现persistent memory、soul purpose、reconcile、harvest和archive。它可以直接读写文件，提高速度","ja":"SyncスキルはClaude Codeのセッションライフサイクル管理であり、persistent memory、soul purpose、reconcile、harvest、archiveを実現します。直接ファイル読み書きにより高速化します","ko":"Sync 스킬은 Claude Code의 세션 생명주기 관리입니다. persistent memory, soul purpose, reconcile, harvest, archive를 구현하며 직접 파일 읽기/쓰기를 통해 속도를 높입니다","es":"Sync es una habilidad para la gestión del ciclo de vida de sesiones con características como memoria persistente y propósito de alma","fr":"Sync est une compétence pour la gestion du cycle de vie des sessions avec des fonctionnalités telles que la mémoire persistante et le but de l''âme","de":"Sync ist eine Fähigkeit für die Lebenszyklusverwaltung von Sitzungen mit Funktionen wie persistenter Speicherung und Seelenzweck","pt":"O sync é uma habilidade que gerencia o ciclo de vida da sessão com persistência de memória e propósito, permitindo a reconciliação e arquivamento de dados.","ru":"Синхронизация - это способность, которая управляет жизненным циклом сессии с сохранением памяти и целью,允яя согласование и архивирование данных.","ar":"Sync هو مهارة لإدارة دورة حياة الجلسة مع ذاكرة متواصلة وغرض، مما يسمح بمواءمة وأرشفة البيانات."},"seo":{"title":{"en":"Sync: Session Lifecycle Management Setup Guide | AI Agent...","zh":"Sync_SETUP GUIDE: Claude Code会话生命周期管理","ja":"Sync_BEST PRACTICES: Claude Codeセッションライフサイクル管理","ko":"Sync_SETUP GUIDE: Claude Code 세션 생명주기 관리","es":"Guía de Configuración de Sync para Agentes de IA","fr":"Guide de Configuration de Sync pour Outils d''IA","de":"Sync-Setup-Anleitung für KI-Agents","pt":"Guia de Configuração do Sync para Ferramentas de IA","ru":"Настройка Синхронизации для ИИ Агентов","ar":"دليل إعداد Sync لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to implement sync for Claude Code, streamlining session management with direct file edits and timestamp entries. Learn more and get started today!","zh":"了解Sync技能如何管理Claude Code会话生命周期，实现persistent memory、soul purpose、reconcile、harvest和archive","ja":"SyncスキルがClaude Codeセッションライフサイクルをどのように管理するかを学び、persistent memory、soul purpose、reconcile、harvest、archiveを実現する","ko":"Sync 스킬이 Claude Code 세션 생명주기를 어떻게 관리하는지 알아보고 persistent memory, soul purpose, reconcile, harvest, archive를 구현하세요","es":"Aprende a configurar Sync para gestionar el ciclo de vida de sesiones con memoria persistente y propósito de alma","fr":"Découvrez comment configurer Sync pour gérer le cycle de vie des sessions avec mémoire persistante et but de l''âme","de":"Erfahren Sie, wie Sie Sync konfigurieren, um den Lebenszyklus von Sitzungen mit persistenter Speicherung und Seelenzweck zu verwalten","pt":"Aprenda a configurar o sync para gerenciar o ciclo de vida da sessão com persistência de memória e propósito","ru":"Узнайте, как настроить синхронизацию для управления жизненным циклом сессии с сохранением памяти и целью","ar":"تعلم كيفية إعداد Sync لإدارة دورة حياة الجلسة مع ذاكرة متواصلة وغرض"},"definition":{"en":"Sync is a session lifecycle management skill for Claude Code, enabling persistent memory and automated file edits with features like timestamp entries and direct file reads.","zh":"Sync是Claude Code会话生命周期管理的技能，用于管理persistent memory、soul purpose、reconcile、harvest和archive","ja":"SyncはClaude Codeセッションライフサイクル管理のスキルであり、persistent memory、soul purpose、reconcile、harvest、archiveを管理する","ko":"Sync는 Claude Code 세션 생명주기 관리 스킬로 persistent memory, soul purpose, reconcile, harvest, archive를 관리합니다","es":"Sync es una habilidad de gestión de sesiones que utiliza memoria persistente y propósito de alma para reconciliar y archivar","fr":"Sync est une compétence de gestion de sessions qui utilise la mémoire persistante et le but de l''âme pour réconcilier et archiver","de":"Sync ist eine Fähigkeit zur Sitzungsverwaltung, die persistente Speicherung und Seelenzweck zur Reconciliation und Archivierung nutzt","pt":"O sync é uma habilidade de gerenciamento de ciclo de vida da sessão que utiliza persistência de memória e propósito","ru":"Синхронизация - это способность управления жизненным циклом сессии с сохранением памяти и целью","ar":"Sync هو مهارة لإدارة دورة حياة الجلسة مع ذاكرة متواصلة وغرض"},"features":{"en":["Direct file reads and edits for faster performance","Automated timestamp entry addition to all files","No narration or announcements, just direct execution","Runs entirely in the main thread without subagents","Uses current time formatted as HH:MM DD/MM/Y for logging","Touches every file, even if only for timestamp updates"],"zh":["直接文件读写","persistent memory管理","soul purpose实现","reconcile和harvest功能","archive支持","速度优先"],"ja":["直接ファイル読み書き","persistent memory管理","soul purpose実現","reconcileとharvest機能","archiveサポート","速度優先"],"ko":["직접 파일 읽기/쓰기","persistent memory 관리","soul purpose 구현","reconcile와 harvest 기능","archive 지원","속도 우선"],"es":["Gestión del ciclo de vida de sesiones con memoria persistente","Propósito de alma para reconciliar y archivar","Edición de archivos sin subagentes","Lectura y edición directa de archivos sin herramientas MCP","Ejecución en el hilo principal sin narración","Priorización de la velocidad sobre la perfección"],"fr":["Gestion du cycle de vie des sessions avec mémoire persistante","But de l''âme pour réconcilier et archiver","Édition de fichiers sans sous-agents","Lecture et édition directe de fichiers sans outils MCP","Exécution dans le thread principal sans narration","Priorisation de la vitesse sur la perfection"],"de":["Lebenszyklusverwaltung von Sitzungen mit persistenter Speicherung","Seelenzweck zur Reconciliation und Archivierung","Dateibearbeitung ohne Subagenten","Direkte Dateilektüre und -bearbeitung ohne MCP-Tools","Ausführung im Hauptthread ohne Erzählung","Priorisierung von Geschwindigkeit gegenüber Perfektion"],"pt":["Gerenciamento de ciclo de vida da sessão com persistência de memória","Reconciliação e arquivamento de dados","Edição de arquivos sem subagentes","Execução direta sem ferramentas de MCP","Priorização da velocidade sobre a perfeição"],"ru":["Управление жизненным циклом сессии с сохранением памяти","Согласование и архивирование данных","Редактирование файлов без субагентов","Прямое выполнение без инструментов MCP","Приоритет скорости над совершенством"],"ar":["إدارة دورة حياة الجلسة مع ذاكرة متواصلة","موائمة وأرشفة البيانات","تحرير الملفات بدون وكلاء فرعيين","تنفيذ مباشر بدون أدوات MCP","أولوية السرعة على الكمال"]},"keywords":{"en":["how to use sync for Claude Code","sync setup guide for AI agents","what is sync in session management","sync vs other session management tools","sync install for developers","sync alternative for lifecycle management","sync best practices for AI agents","sync tutorial for beginners","sync implementation for Claude Code"],"zh":["Sync技能","Claude Code会话生命周期管理","persistent memory","soul purpose","reconcile","harvest","archive","AIエージェント","直接文件读写"],"ja":["Syncスキル","Claude Codeセッションライフサイクル管理","persistent memory","soul purpose","reconcile","harvest","archive","AIエージェント","直接ファイル読み書き"],"ko":["Sync 스킬","Claude Code 세션 생명주기 관리","persistent memory","soul purpose","reconcile","harvest","archive","AI 에이전트","직접 파일 읽기/쓰기"],"es":["agentes de ia","herramientas de ia","gestión de sesiones","memoria persistente","propósito de alma","reconciliación","archivado","edición de archivos","lectura directa de archivos"],"fr":["outils d''ia","agents d''ia","gestion de sessions","mémoire persistante","but de l''âme","réconciliation","archivage","édition de fichiers","lecture directe de fichiers"],"de":["ki-agents","ki-tools","sitzungsverwaltung","persistente speicherung","seelenzweck","reconciliation","archivierung","dateibearbeitung","direkte dateilektüre"],"pt":["sync para ferramentas de IA","gerenciamento de ciclo de vida da sessão","persistência de memória","reconciliação de dados","edição de arquivos","execução direta","velocidade sobre perfeição"],"ru":["синхронизация для ИИ агентов","управление жизненным циклом сессии","сохранение памяти","согласование данных","редактирование файлов","прямое выполнение","скорость над совершенством"],"ar":["sync لأدوات الذكاء الاصطناعي","إدارة دورة حياة الجلسة","ذاكرة متواصلة","موائمة البيانات","تحرير الملفات","تنفيذ مباشر","أولوية السرعة على الكمال"]}},"owner":"anombyte93","repo":"atlas-session-lifecycle","repoPath":"anombyte93/atlas-session-lifecycle","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.662Z","topics":[],"category":"community","skillMd":{"name":"sync","description":"Fast save-point: sync all session-context files and MEMORY.md with current progress. Zero questions, zero delay. Use when user says /sync, save progress, save state, sync context, or /sync --full for capability inventory.","bodyPreview":"# Sync\n\n> Zero questions. Edit files. Print summary. Done.\n\n## Rules\n\n1. **No questions** — never ask the user anything. Just save.\n2. **No subagents** — run entirely in the main thread.\n3. **No MCP tools** — direct file reads and edits only (faster).\n4. **No narration** — don''t announce steps. Just do them.\n5. **Touch every file** — even if only adding a timestamp entry.\n6. **Speed over perfection** — a rough sync beats no sync.\n\n---\n\n## Execute\n\nUse the current time formatted as `HH:MM DD/MM/Y","body":"# Sync\n\n> Zero questions. Edit files. Print summary. Done.\n\n## Rules\n\n1. **No questions** — never ask the user anything. Just save.\n2. **No subagents** — run entirely in the main thread.\n3. **No MCP tools** — direct file reads and edits only (faster).\n4. **No narration** — don''t announce steps. Just do them.\n5. **Touch every file** — even if only adding a timestamp entry.\n6. **Speed over perfection** — a rough sync beats no sync.\n\n---\n\n## Execute\n\nUse the current time formatted as `HH:MM DD/MM/YY` for the checkpoint header.\n\n### 1. Edit `session-context/CLAUDE-activeContext.md`\n\nAppend a new section at the end:\n\n```markdown\n## [SYNC] {time}\n\n**Accomplished:**\n- {bullet list of what was done this session}\n\n**In progress:**\n- {what''s currently being worked on}\n\n**Next steps:**\n- {what comes next}\n\n**Blockers:**\n- {any blockers, or \"None\"}\n```\n\n### 2. Edit `session-context/CLAUDE-decisions.md`\n\nAppend new decisions made this session. If none, append:\n\n```markdown\n## {time}\nNo new decisions this session.\n```\n\n### 3. Edit `session-context/CLAUDE-patterns.md`\n\nAppend new patterns discovered. If none, append:\n\n```markdown\n## {time}\nNo new patterns this session.\n```\n\n### 4. Edit `session-context/CLAUDE-troubleshooting.md`\n\nAppend new issues and solutions. If none, append:\n\n```markdown\n## {time}\nNo new issues this session.\n```\n\n### 5. Update MEMORY.md\n\nUpdate the auto-memory file at the project memory path with any new learnings from this session. If nothing new, skip this file (memory should stay concise).\n\n### 6. Print summary\n\nPrint exactly one block:\n\n```\nSynced. {N} files updated.\n- Active context: {1-line summary of what was captured}\n- Decisions: {count new or \"no new\"}\n- Patterns: {count new or \"no new\"}\n- Troubleshooting: {count new or \"no new\"}\n- Memory: {updated or \"no changes\"}\n```\n\n---\n\n## /sync --full (Capability Inventory)\n\n> Extended sync that includes capability inventory generation.\n\n### Execute\n\n1. Run standard sync flow (Steps 1-5 above).\n2. Call `session_capability_inventory(project_dir, force_refresh=True)` — bypasses cache and regenerates inventory even if git unchanged.\n3. If `needs_generation == True`: the MCP tool will generate the inventory.\n4. Read `CLAUDE-capability-inventory.md` if it exists.\n\n### Print summary\n\nPrint the standard sync block above, plus:\n\n```\nCapability Inventory: {status}\n- MCP Tools: {count}\n- Test Coverage: {percentage}\n- Critical Untested: {count}\n- Inventory: {path}\n```\n"},"lastSynced":"2026-03-08T02:14:09.001Z","agentAnalysis":{"suitability":{"en":"Ideal for agents like Claude Code requiring session lifecycle management with persistent memory and automated file editing","zh":"非常适合需要会话生命周期管理、持久内存和自动文件编辑的代理，如Claude Code","ja":"Claude Codeのようなセッションライフサイクル管理と永続的なメモリ、および自動ファイル編集を必要とするエージェントに最適","ko":"Claude Code와 같은 세션 라이프사이클 관리 및 지속적인 메모리, 자동 파일 편집이 필요한 에이전트에 적합","es":"Ideal para agentes como Claude Code que requieren gestión de ciclo de sesión con memoria persistente y edición de archivos automatizada","fr":"Idéal pour des agents comme Claude Code nécessitant une gestion de cycle de session avec une mémoire persistante et une édition de fichiers automatisée","de":"Ideal für Agenten wie Claude Code, die eine Sitzungslebenszyklusverwaltung mit persistenter Speicherung und automatisierter Dateibearbeitung erfordern","pt":"Ideal para agentes como Claude Code que exigem gerenciamento de ciclo de vida de sessão com memória persistente e edição de arquivos automatizada","ru":"Идеально для агентов, таких как Claude Code, требующих управления жизненным циклом сессии с постоянной памятью и автоматическим редактированием файлов","ar":"مثالي للوكلاء مثل Claude Code الذين يتطلبون إدارة دورة حياة الجلسة مع الذاكرة الثابتة وتحرير الملفات التلقائي"},"recommendation":{"en":"Empowers agents to manage sessions efficiently with direct file reads and edits, providing a faster and more reliable syncing process using timestamp entries, all while prioritizing speed over perfection","zh":"使代理能够高效地管理会话，直接读取和编辑文件，提供更快、更可靠的同步过程，使用时间戳项，同时优先考虑速度而非完美","ja":"エージェントがセッションを効率的に管理できるようにし、直接ファイルを読み取り編集して、タイムスタンプエントリを使用したより迅速で信頼性の高い同期プロセスを提供し、完璧さよりも速度を優先する","ko":"에이전트가 세션을 효율적으로 관리할 수 있도록 하며, 직접 파일을 읽고 편집하여 타임스탬프 항목을 사용한 더 빠르고 신뢰할 수 있는 동기화 프로세스를 제공하며, 완벽함보다 속도를 우선시함","es":"Permite a los agentes gestionar las sesiones de forma eficiente con lecturas y ediciones de archivos directas, proporcionando un proceso de sincronización más rápido y fiable utilizando entradas de marca de tiempo, priorizando la velocidad sobre la perfección","fr":"Permet aux agents de gérer les sessions de manière efficace avec des lectures et des éditions de fichiers directes, fournissant un processus de synchronisation plus rapide et plus fiable en utilisant des entrées de timestamp, en privilégiant la vitesse par rapport à la perfection","de":"Ermöglicht es Agenten, Sitzungen effizient zu verwalten, mit direkten Dateilektüren und -bearbeitungen, und bietet so einen schnelleren und zuverlässigeren Synchronisierungsprozess unter Verwendung von Zeitstempel-Einträgen, wobei die Geschwindigkeit Vorrang vor der Perfektion hat","pt":"Habilita os agentes a gerenciar sessões de forma eficiente com leitura e edição direta de arquivos, fornecendo um processo de sincronização mais rápido e confiável usando entradas de carimbo de data/hora, priorizando a velocidade sobre a perfeição","ru":"Наделяет агентов возможностью управлять сессиями эффективно с прямым чтением и редактированием файлов, обеспечивая более быстрый и надежный процесс синхронизации с использованием записей временных меток, отдающих приоритет скорости над совершенством","ar":"يمنح الوكلاء القدرة على إدارة الجلسات بفعالية مع قراءة وتحرير الملفات بشكل مباشر، ويتوفر عملية مزامنة أسرع وأكثر موثوقية باستخدام إدخالات علامات التاريخ، مع إعطاء الأفضلية للسرعة على الكمال"},"useCases":{"en":["Automating session lifecycle management","Editing files silently without user interaction","Printing summaries of sync operations"],"zh":["自动化会话生命周期管理","在不需要用户交互的情况下静默编辑文件","打印同步操作摘要"],"ja":["セッションライフサイクル管理の自動化","ユーザーとのやり取りなしにファイルを静かに編集する","同期操作のサマリーを印刷する"],"ko":["세션 라이프사이클 관리 자동화","사용자 상호작용 없이 파일을默示적으로 편집","동기화 작업 요약 인쇄"],"es":["Automatización de la gestión de ciclo de sesión","Edición de archivos de forma silenciosa sin interacción del usuario","Impresión de resúmenes de operaciones de sincronización"],"fr":["Automatisation de la gestion de cycle de session","Édition de fichiers de manière silencieuse sans interaction de l''utilisateur","Impression de résumés d''opérations de synchronisation"],"de":["Automatisierung der Sitzungslebenszyklusverwaltung","Dateibearbeitung stillschweigend ohne Benutzereingriff","Drucken von Zusammenfassungen von Synchronisierungsoperationen"],"pt":["Automatizar o gerenciamento de ciclo de vida de sessão","Editar arquivos silenciosamente sem interação do usuário","Imprimir resumos de operações de sincronização"],"ru":["Автоматизировать управление жизненным циклом сессии","Редактировать файлы без взаимодействия с пользователем","Печатать сводки операций синхронизации"],"ar":["توفير automatizar إدارة دورة حياة الجلسة","تحرير الملفات بدون تفاعل مع المستخدم","طباعة ملخصات عمليات المزامنة"]},"limitations":{"en":["No support for subagents","No compatibility with MCP tools","Requires running entirely in the main thread"],"zh":["不支持子代理","不兼容MCP工具","需要在主线程中完全运行"],"ja":["サブエージェントのサポートなし","MCPツールとの互換性なし","メインスレッドで完全に実行する必要あり"],"ko":["서브 에이전트 지원 안 함","MCP 툴과 호환되지 않음","메인 스레드에서 완전히 실행해야 함"],"es":["No admite subagentes","No es compatible con herramientas MCP","Requiere ejecución completa en el hilo principal"],"fr":["N''a pas de prise en charge des sous-agents","N''est pas compatible avec les outils MCP","Nécessite une exécution complète dans le thread principal"],"de":["Unterstützt keine Subagenten","Ist nicht kompatibel mit MCP-Tools","Erfordert eine vollständige Ausführung im Hauptthread"],"pt":["Sem suporte para subagentes","Sem compatibilidade com ferramentas MCP","Exige execução inteiramente na thread principal"],"ru":["Нет поддержки для субагентов","Нет совместимости с инструментами MCP","Требует выполнения целиком в основной поток"],"ar":["لا يدعم الوكلاء الفرعيين","لا يتوافق مع أدوات MCP","يتطلب التشغيل بالكامل في الخيط الرئيسي"]},"version":4},"contentHash":"ffd069bfffe2e47ffad9ed6404fce787d790b0c5135fcbe5ba03a54d9ad71d4d","qualityScore":33}');
