INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('anombyte93/atlas-session-lifecycle/sync', 'sync', 'anombyte93', 'atlas-session-lifecycle', 'community', 'sync anombyte93 atlas-session-lifecycle community The sync skill manages session lifecycles for Claude Code, providing persistent memory and automated file editing. It benefits developers by simplifying session management. Sync技能是Claude Code的会话生命周期管理，实现persistent memory、soul purpose、reconcile、harvest和archive。它可以直接读写文件，提高速度 SyncスキルはClaude Codeのセッションライフサイクル管理であり、persistent memory、soul purpose、reconcile、harvest、archiveを実現します。直接ファイル読み書きにより高速化します Sync 스킬은 Claude Code의 세션 생명주기 관리입니다. persistent memory, soul purpose, reconcile, harvest, archive를 구현하며 직접 파일 읽기/쓰기를 통해 속도를 높입니다 Sync es una habilidad para la gestión del ciclo de vida de sesiones con características como memoria persistente y propósito de alma Sync est une compétence pour la gestion du cycle de vie des sessions avec des fonctionnalités telles que la mémoire persistante et le but de l''âme Sync ist eine Fähigkeit für die Lebenszyklusverwaltung von Sitzungen mit Funktionen wie persistenter Speicherung und Seelenzweck O sync é uma habilidade que gerencia o ciclo de vida da sessão com persistência de memória e propósito, permitindo a reconciliação e arquivamento de dados. Синхронизация - это способность, которая управляет жизненным циклом сессии с сохранением памяти и целью,允яя согласование и архивирование данных. Sync هو مهارة لإدارة دورة حياة الجلسة مع ذاكرة متواصلة وغرض، مما يسمح بمواءمة وأرشفة البيانات. how to use sync for Claude Code sync setup guide for AI agents what is sync in session management sync vs other session management tools sync install for developers sync alternative for lifecycle management sync best practices for AI agents sync tutorial for beginners sync implementation for Claude Code Sync技能 Claude Code会话生命周期管理 persistent memory soul purpose reconcile harvest archive AIエージェント 直接文件读写 Direct file reads and edits for faster performance Automated timestamp entry addition to all files No narration or announcements, just direct execution Runs entirely in the main thread without subagents Uses current time formatted as HH:MM DD/MM/Y for logging Touches every file, even if only for timestamp updates Sync is a session lifecycle management skill for Claude Code, enabling persistent memory and automated file edits with features like timestamp entries and direct file reads.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('toplyr-narfur/urbit-skills/nock-interpreter-engineer-assistant', 'community', 'toplyr-narfur', 'urbit-skills', 'toplyr-narfur/urbit-skills', 'nock-interpreter-engineer-assistant', 0, 0, 33, '2026-03-08T01:57:15.662Z', '2026-03-08T02:14:09.065Z', 'a1d462af7980fa45c4f06b7e16c7825384ceaba2288988bd89187367a307d919', '{"id":"toplyr-narfur/urbit-skills/nock-interpreter-engineer-assistant","name":"nock-interpreter-engineer-assistant","description":{"en":"The nock-interpreter-engineer-assistant skill provides expert guidance for implementing Nock virtual machines, benefiting developers working with Urbit and its native languages like Hoon and Nock.","zh":"Nock 解释器工程师助手提供了跨语言的 Nock 虚拟机实现方法，解决 Urbit 运行时和终端命令的编码问题","ja":"Nock Interpreter Engineer アシスタントは、Urbit ランタイムとターミナルコマンドのコーディング問題を解決するための Nock 仮想マシンの実装方法を提供する","ko":"Nock 인터프리터 엔지니어 어시스트는 Urbit 런타임과 터미널 명령어의 코딩 문제를 해결하는 Nock 가상 머신의 구현 방법을 제공한다","es":"El asistente de ingeniero de intérprete nock proporciona orientación experta para implementar máquinas virtuales Nock en varios lenguajes de programación. Incluye evaluaciones de bucles, operaciones de árboles y optimización de tiempo de ejecución","fr":"L''assistant d''ingénieur d''interpréteur nock offre une guidance experte pour implémenter des machines virtuelles Nock dans plusieurs langages de programmation. Il comprend des évaluations de boucles, des opérations d''arbres et une optimisation du temps d''exécution","de":"Der nock-Interpreter-Engineer-Assistent bietet Expertenleitfäden zur Implementierung von Nock-Virtuellen Maschinen in verschiedenen Programmiersprachen. Er umfasst Bewertungsschleifen, Baumoperationen und Laufzeitoptimierung","pt":"O Nock Interpreter Engineer Assistant é uma ferramenta que ajuda a resolver problemas de codificação em Urbit, incluindo a implementação de máquinas virtuais Nock","ru":"Nock Interpreter Engineer Assistant - это инструмент, помогающий решать проблемы кодирования в Urbit, включая реализацию виртуальных машин Nock для ИИ Агентов","ar":"محرك الترجمة Nock Interpreter Engineer Assistant هو أداة تساعد في حل مشاكل البرمجة في Urbit، بما في ذلك تنفيذ الآلات الافتراضية Nock للوكلاء الذكاء الاصطناعي"},"seo":{"title":{"en":"nock-interpreter-engineer-assistant: Nock Virtual Machine...","zh":"Nock 解释器工程师助手设置指南","ja":"Nock Interpreter Engineer アシスタントのベストプラクティス","ko":"Nock 인터프리터 엔지니어 어시스트 구현 가이드","es":"Guía de configuración de nock-interpreter-engineer-assist...","fr":"Guide de mise en place de nock-interpreter-engineer-assis...","de":"Einrichtungsleitfaden für nock-interpreter-engineer-assis...","pt":"Guia de Configuração do Nock Interpreter Engineer Assistant","ru":"Руководство по настройке Nock Interpreter Engineer Assist...","ar":"دليل إعداد محرك الترجمة Nock Interpreter Engineer Assista..."},"description":{"en":"Unlock efficient Urbit runtime interactions with nock-interpreter-engineer-assistant. Explore expert guidance on Nock implementation and optimization techniq...","zh":"了解 Nock 解释器工程师助手如何解决 Urbit 运行时和终端命令的编码问题，实现跨语言的 Nock 虚拟机","ja":"Urbit ランタイムとターミナルコマンドのコーディング問題を解決する Nock Interpreter Engineer アシスタントの実装方法","ko":"Urbit 런타임과 터미널 명령어의 코딩 문제를 해결하는 Nock 인터프리터 엔지니어 어시스트의 구현 방법","es":"Mejora la comprensión de la máquina virtual Nock con el asistente de ingeniero de intérprete nock. Aprende a implementar evaluaciones de bucles y operaciones...","fr":"Améliorez la compréhension de la machine virtuelle Nock avec l''assistant d''ingénieur d''interpréteur nock. Découvrez comment implémenter des évaluations de bo...","de":"Verbessern Sie das Verständnis der Nock-Virtuellen Maschine mit dem nock-Interpreter-Engineer-Assistenten. Erfahren Sie, wie Sie Bewertungsschleifen und Baum...","pt":"Aprenda a implementar máquinas virtuais Nock em múltiplas linguagens de programação com o Nock Interpreter Engineer Assistant","ru":"Узнайте, как реализовать вирт