INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('endlessblink/flow-state/next', 'next', 'endlessblink', 'flow-state', 'community', 'next endlessblink flow-state community The next skill enables a chat-first task selection flow, allowing users to select tasks via chat and view full context with npm run commands. It benefits developers and teams seeking streamlined task management. Next AI技能使用chat-first任务选择流程，通过CLI命令实现任务选择和展示 Next AIエージェントはchat-firstタスク選択フローを使用し、CLIコマンドでタスクを選択して表示します Next AI 에이전트는 채팅 우선 작업 선택 흐름을 사용하여 CLI 명령어로 작업을 선택하고 표시합니다 El skill ''next'' permite una selección de tareas chat-first y ofrece una mejor experiencia de usuario. Utiliza npm y CLI para ejecutar comandos como ''pick:list'' y ''pick:show'' Le skill ''next'' permet une sélection de tâches chat-first et offre une meilleure expérience utilisateur. Il utilise npm et CLI pour exécuter des commandes comme ''pick:list'' et ''pick:show'' Der Skill ''next'' ermöglicht eine chat-erste Aufgabenverwaltung und bietet eine bessere Benutzererfahrung. Er verwendet npm und CLI, um Befehle wie ''pick:list'' und ''pick:show'' auszuführen O Next é uma habilidade que proporciona um fluxo de seleção de tarefas por chat, permitindo que os usuários selecionem tarefas com facilidade. Следующий - это навык, который обеспечивает поток seleção задач по чату, позволяя пользователям выбирать задачи легко. Next هو مهارة توفر تدفق اختيار المهام عبر الدردشة، مما يسمح للمستخدمين باختيار المهام بسهولة. how to use next next setup guide chat-first task selection flow npm run commands task management with next next alternative next vs TUI next install what is next Next AI技能 chat-first任务选择流程 CLI命令 任务选择 AI工具 AIエージェント Runs npm run --silent pick:list to display a numbered task list Returns task list in chat without launching TUI automatically Asks users to reply with a task ID or number for selection Shows full task context with npm run --silent pick:show Offers next actions, including starting work, showing another task, or opening the TUI picker next is a skill that implements a chat-first task selection flow, utilizing npm run commands to display task lists and context.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('LucasPier/cuentos-interactivos/code-auditor', 'community', 'LucasPier', 'cuentos-interactivos', 'LucasPier/cuentos-interactivos', 'code-auditor', 0, 0, 33, '2026-03-06T17:11:54Z', '2026-03-08T02:18:59.365Z', '2228fda22a76635156d0750c3558f2b781a22473363a55f1796a3049d2f8ebff', '{"id":"LucasPier/cuentos-interactivos/code-auditor","name":"code-auditor","description":{"en":"The code-auditor skill provides a hybrid approach to code analysis, combining a Python script for mechanical detection with deep semantic analysis for improved code quality, benefiting developers and project managers.","zh":"code-auditor是一种混合技能，结合Python脚本和语义分析，用于代码审计和分析","ja":"code-auditorは、Pythonスクリプトとセマンティック分析を組み合わせたハイブリッドスキルであり、コード監査と分析に使用されます","ko":"code-auditor는 파이썬 스크립트와 의미 분석을 결합한 하이브리드 스킬로 코드 감시 및 분석에 사용됩니다","es":"El code-auditor es una herramienta híbrida que combina un script Python para detección mecánica de hallazgos con instrucciones para análisis semántico profundo. Se utiliza para auditar proyectos y detectar errores","fr":"Le code-auditor est un outil hybride qui combine un script Python pour la détection mécanique des résultats avec des instructions pour l''analyse sémantique approfondie. Il est utilisé pour auditer les projets et détecter les erreurs","de":"Der code-auditor ist ein hybrides Tool, das ein Python-Skript für die mechanische Ergebnisdetektion mit Anweisungen für eine tiefe semantische Analyse kombiniert. Es wird verwendet, um Projekte zu auditen und Fehler zu erkennen","pt":"O code-auditor é uma ferramenta híbrida que combina script Python com análise semântica profunda para auditoria de código","ru":"ИИ Агент code-auditor - это гибридный инструмент, который сочетает скрипт Python с глубоким семантическим анализом для аудита кода","ar":"أداة فحص الرمز code-auditor هي أداة هجينة تجمع بين سكريبت Python و تحليل دقيق لمراجعة رمز البرامج"},"seo":{"title":{"en":"code-auditor: Hybrid Code Analysis Setup Guide | AI Agent...","zh":"代码审计工具code-auditor setup指南","ja":"AIエージェントcode-auditorのベストプラクティス","ko":"코드 감시 도구 code-auditor 설정 가이드","es":"Configuración del code-auditor: Guía de Auditoría de Código","fr":"Paramétrer le code-auditor: Guide d''Audit de Code","de":"Einrichtung des code-auditors: Leitfaden zur Code-Auditor","pt":"Guia de Configuração do code-auditor: Auditoria de Código...","ru":"ИИ Агент code-auditor: Руководство по Настройке и Аудите Код","ar":"دليل إعداد ومراجعة رمز code-auditor: أداة فحص متقدمة"},"description":{"en":"Discover how code-auditor''s Python script and semantic analysis capabilities improve your project''s code quality - learn more and get started today!","zh":"使用code-auditor进行代码审计和分析，提高代码质量和安全性，了解更多","ja":"code-auditorを使用してコードを分析し、品質とセキュリティを向上させる方法","ko":"코드 감시 도구 code-auditor를 사용하여 코드를 분석하고 개선하는 방법","es":"Aprende a configurar y utilizar el code-auditor para auditar tu código con precisión y eficiencia, incluyendo análisis semántico profundo y detección mecánic...","fr":"Découvrez comment paramétrer et utiliser le code-auditor pour auditer votre code avec précision et efficacité, y compris l''analyse sémantique approfondie et ...","de":"Erfahren Sie, wie Sie den code-auditor konfigurieren und verwenden, um Ihren Code mit Präzision und Effizienz zu auditen, einschließlich tiefer semantischer ...","pt":"Aprenda a configurar e utilizar o code-auditor para auditorias de código Python, JavaScript, CSS e JSON de forma eficiente","ru":"Узнайте, как настроить и использовать ИИ Агент code-auditor для аудита кода на Python, JavaScript, CSS и JSON","ar":"تعرف على كيفية إعداد أداة فحص الرمز code-auditor لمراجعة رمز Python و JavaScript و CSS و JSON بشكل فعال"},"definition":{"en":"code-auditor is a hybrid skill that combines mechanical and semantic analysis for comprehensive code auditing and improvement.","zh":"code-auditor是一种代码审计工具，用于检测和分析代码中的问题","ja":"code-auditorは、コード内の問題を検出して分析するためのコード監査ツールです","ko":"code-auditor는 코드 내의 문제를 감지하고 분석하기 위한 코드 감시 도구입니다","es":"El code-auditor es una herramienta de auditoría de código que combina detección mecánica y análisis semántico","fr":"Le code-auditor est un outil d''audit de code qui combine la détection mécanique et l''analyse sémantique","de":"Der code-auditor ist ein Code-Auditor-Tool, das die mechanische Ergebnisdetektion und die semantische Analyse kombiniert","pt":"O code-auditor é uma ferramenta de auditoria de código que utiliza Python e análise semântica","ru":"ИИ Агент code-auditor - это инструмент аудита кода, использующий Python и семантический анализ","ar":"أداة فحص الرمز code-auditor هي أداة لمراجعة رمز البرامج تستخدم لغة Python و التحليل الدقيق"},"features":{"en":["Executes Python script for mechanical detection of code issues","Performs deep semantic analysis for improved code understanding","Supports detailed checks for JavaScript, CSS, JSON, and PWA/Service Worker","Utilizes resources like checks-js.md, checks-css.md, and checks-pwa.md for criteria","Enables analysis of JSONs for scenes and challenges"],"zh":["支持JavaScript、CSS、JSON和PWA代码分析","使用Python脚本进行机械检测","支持深度语义分析","提供详细的代码检查标准","支持Service Worker和PWA代码审计"],"ja":["JavaScript、CSS、JSON、PWAコード分析をサポート","Pythonスクリプトを使用した機械検出","深いセマンティック分析をサポート","詳細なコードチェック基準を提供","Service WorkerとPWAコード監査をサポート"],"ko":["자바스크립트, CSS, JSON 및 PWA 코드 분석 지원","파이썬 스크립트를 사용한 기계 감지","깊은 의미 분석 지원","자세한 코드 감시 기준 제공","서비스 워커 및 PWA 코드 감시 지원"],"es":["Detección mecánica de hallazgos con script Python","Análisis semántico profundo para auditar proyectos","Criterios detallados para JavaScript, CSS y JSON","Compatibilidad con PWA y Service Worker","Recursos para auditoría de código y análisis de resultados"],"fr":["Détection mécanique des résultats avec script Python","Analyse sémantique approfondie pour auditer les projets","Critères détaillés pour JavaScript, CSS et JSON","Compatibilité avec PWA et Service Worker","Ressources pour l''audit de code et l''analyse des résultats"],"de":["Mechanische Ergebnisdetektion mit Python-Skript","Tiefe semantische Analyse zur Auditerung von Projekten","Detaillierte Kriterien für JavaScript, CSS und JSON","Kompatibilität mit PWA und Service Worker","Ressourcen für Code-Auditor und Ergebnisanalyse"],"pt":["Deteção mecânica de problemas com script Python","Análise semântica profunda de código","Criterios detallados para JavaScript, CSS e JSON","Suporte a PWA e Service Worker","Recursos para auditoria de código de forma eficiente"],"ru":["Механическое обнаружение проблем с помощью скрипта Python","Глубокий семантический анализ кода","Детальные критерии для JavaScript, CSS и JSON","Поддержка PWA и Service Worker","Ресурсы для эффективной аудиты кода"],"ar":["اكتشاف آلي للمشاكل باستخدام سكريبت Python","تحليل دقيق للرمز البرمجي","معايير مفصلة لJavaScript و CSS و JSON","دعم تطبيقات الويب التقدمية و Service Worker","مصادر لمراجعة رمز البرامج بشكل فعال"]},"keywords":{"en":["how to use code-auditor","code-auditor setup guide","code-auditor vs sonarqube","code-auditor install","what is code-auditor","code-auditor alternative","code-auditor tutorial","code-auditor for AI agents","code-auditor best practices"],"zh":["代码审计","代码分析","Python脚本","语义分析","代码检查","JavaScript代码分析","CSS代码分析","JSON代码分析","PWA代码分析"],"ja":["コード監査","コード分析","Pythonスクリプト","セマンティック分析","コードチェック","JavaScriptコード分析","CSSコード分析","JSONコード分析","PWAコード分析"],"ko":["코드 감시","코드 분석","파이썬 스크립트","의미 분석","코드 감시","자바스크립트 코드 분석","CSS 코드 분석","JSON 코드 분석","PWA 코드 분석"],"es":["code-auditor","auditoría de código","análisis semántico","detección mecánica","script Python","PWA y Service Worker","JavaScript, CSS y JSON","herramientas de auditoría","desarrollo de software"],"fr":["code-auditor","audit de code","analyse sémantique","détection mécanique","script Python","PWA et Service Worker","JavaScript, CSS et JSON","outils d''audit","développement de logiciels"],"de":["code-auditor","Code-Auditor","semantische Analyse","mechanische Ergebnisdetektion","Python-Skript","PWA und Service Worker","JavaScript, CSS und JSON","Audit-Tools","Software-Entwicklung"],"pt":["code-auditor","auditoria de código","Python","análise semântica","JavaScript","CSS","JSON","PWA","Service Worker","desenvolvimento de software"],"ru":["ИИ Агент code-auditor","аудит кода","Python","семантический анализ","JavaScript","CSS","JSON","PWA","Service Worker","разработка программного обеспечения"],"ar":["أداة فحص الرمز code-auditor","مراجعة رمز البرامج","Python","التحليل الدقيق","JavaScript","CSS","JSON","تطبيقات الويب التقدمية","Service Worker","تطوير البرمجيات"]}},"owner":"LucasPier","repo":"cuentos-interactivos","repoPath":"LucasPier/cuentos-interactivos","stars":0,"forks":0,"updatedAt":"2026-03-06T17:11:54Z","topics":[],"category":"community","skillMd":{"name":"code-auditor","description":"|","bodyPreview":"# code-auditor — Auditoría de Código del Proyecto\n\nSkill híbrida que combina un script Python para detección mecánica de hallazgos\ncon instrucciones para que el agente haga análisis semántico profundo.\n\n## Recursos\n\n- `resources/checks-js.md` — Criterios detallados para JavaScript\n- `resources/checks-css.md` — Criterios detallados para CSS\n- `resources/checks-json.md` — Criterios detallados para JSONs de escenas/desafíos\n- `resources/checks-pwa.md` — Criterios para PWA y Service Worker\n- `resour","body":"# code-auditor — Auditoría de Código del Proyecto\n\nSkill híbrida que combina un script Python para detección mecánica de hallazgos\ncon instrucciones para que el agente haga análisis semántico profundo.\n\n## Recursos\n\n- `resources/checks-js.md` — Criterios detallados para JavaScript\n- `resources/checks-css.md` — Criterios detallados para CSS\n- `resources/checks-json.md` — Criterios detallados para JSONs de escenas/desafíos\n- `resources/checks-pwa.md` — Criterios para PWA y Service Worker\n- `resources/checks-cross.md` — Checks transversales (cross-cutting)\n- `resources/informe-formato.md` — Template del informe de auditoría\n- `scripts/auditar.py` — Script de detección automática (solo lectura)\n\n---\n\n## Decision Tree\n\n```\n¿Qué necesitás auditar?\n  │\n  ├── Todo el proyecto                    →  MODO 1: AUDITORÍA COMPLETA\n  │\n  ├── Una categoría específica            →  MODO 2: AUDITORÍA POR ÁREA\n  │   (js, css, json, pwa, cross)\n  │\n  └── Un archivo en particular            →  MODO 3: AUDITORÍA DE ARCHIVO\n```\n\n---\n\n## Modo 1 — AUDITORÍA COMPLETA\n\n**Objetivo:** Escanear todo el proyecto en busca de defectos y mejoras.\n\n### Pasos\n\n1. Ejecutar el script automático:\n```bash\npython .agents/skills/code-auditor/scripts/auditar.py\n```\n\n2. Leer el JSON de salida del script (hallazgos mecánicos).\n\n3. Para cada categoría (js, css, json, pwa, cross), cargar el recurso\n   correspondiente (`resources/checks-{cat}.md`) y hacer análisis semántico:\n   - Leer los archivos relevantes del proyecto\n   - Aplicar los criterios de análisis semántico listados en el recurso\n   - Anotar hallazgos que el script no puede detectar\n\n4. Consolidar hallazgos (automáticos + semánticos) en informe\n   usando `resources/informe-formato.md`.\n\n5. Presentar informe al usuario y preguntar qué corregir.\n\n> **IMPORTANTE:** Cargá los archivos de a uno para no saturar el contexto.\n> Emití hallazgos parciales por categoría antes de pasar a la siguiente.\n\n---\n\n## Modo 2 — AUDITORÍA POR ÁREA\n\n**Objetivo:** Auditar en profundidad una categoría específica.\n\n### Categorías válidas\n\n| Categoría | Qué cubre | Recurso |\n|-----------|-----------|---------|\n| `js` | Módulos JS, handlers, patterns | `resources/checks-js.md` |\n| `css` | Estilos, variables, z-index, layout | `resources/checks-css.md` |\n| `json` | Escenas, desafíos, schema, voseo | `resources/checks-json.md` |\n| `pwa` | Service Worker, manifest, cachés | `resources/checks-pwa.md` |\n| `cross` | Consistencia inter-módulo | `resources/checks-cross.md` |\n\n### Pasos\n\n1. Ejecutar script filtrado:\n```bash\npython .agents/skills/code-auditor/scripts/auditar.py --categoria js\n```\n\n2. Cargar `resources/checks-{categoria}.md` completo.\n\n3. Leer los archivos del proyecto relevantes a esa categoría.\n\n4. Aplicar todos los criterios (mecánicos del script + semánticos del recurso).\n\n5. Emitir informe usando `resources/informe-formato.md`.\n\n---\n\n## Modo 3 — AUDITORÍA DE ARCHIVO\n\n**Objetivo:** Revisar un archivo específico a fondo.\n\n### Pasos\n\n1. Ejecutar script con archivo:\n```bash\npython .agents/skills/code-auditor/scripts/auditar.py --archivo js/GameEngine.js\n```\n\n2. Determinar la categoría del archivo por extensión/ubicación:\n   - `.js` → cargar `resources/checks-js.md`\n   - `.css` → cargar `resources/checks-css.md`\n   - `.json` (en `datos/`) → cargar `resources/checks-json.md`\n   - `service-worker.js` / `manifest.json` → cargar `resources/checks-pwa.md`\n\n3. Leer el archivo completo.\n\n4. Aplicar todos los criterios de su categoría + checks cross-cutting relevantes.\n\n5. Emitir informe usando `resources/informe-formato.md`.\n\n---\n\n## Ejemplo de Flujo\n\n```\nUsuario: \"Auditá el código JavaScript del proyecto\"\n\n1. python .agents/skills/code-auditor/scripts/auditar.py --categoria js\n2. Leer resources/checks-js.md\n3. Leer cada módulo en js/ → aplicar criterios semánticos\n4. Consolidar hallazgos automáticos + semánticos\n5. Presentar informe categorizado\n6. \"¿Querés que corrija alguno de estos hallazgos?\"\n```\n\n---\n\n## Reglas de Oro\n\n1. **Informe primero, correcciones después** — nunca corregir sin aprobación explícita\n2. **El script es de solo lectura** — no modifica ningún archivo del proyecto\n3. **Análisis semántico obligatorio** — el script cubre lo mecánico, el agente debe\n   complementar leyendo el código real y aplicando los criterios de `resources/`\n4. **Carga progresiva** — en auditoría completa, procesar una categoría a la vez\n5. **Contexto del proyecto** — respetar las convenciones de `AGENTS.md` como fuente de verdad\n6. **Voseo rioplatense** — el informe se escribe en español rioplatense\n7. **Usar `--help`** — ante dudas sobre el script, ejecutar `auditar.py --help`\n8. **Prohibido commitear automáticamente** — El agente NO debe realizar commits por su cuenta después de aplicar correcciones. El commit lo gestiona el usuario o debe pedirse como un paso EXPLÍCITO y separado. No asumas que \"terminar el laburo\" implica commitear.\n9. **Uso de artefactos para informes** — Si el entorno soporta la creación de \"artefactos\" (archivos de respuesta estructurada), entregá los informes usándolos. Si no, presentalos normalmente en la conversación.\n"},"lastSynced":"2026-03-08T02:18:59.365Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing advanced code analysis and auditing capabilities, particularly those utilizing Python and semantic analysis for improved code quality.","zh":"适用于需要高级代码分析和审计能力的AI代理，特别是那些利用Python和语义分析来改善代码质量的代理。","ja":"Pythonやセマンティック分析を使用してコード品質を向上させる必要があるAIエージェント、特に高度なコード分析および監査機能を必要とするエージェントに適しています。","ko":"Python 및 의미 분석을 사용하여 코드 품질을 개선해야 하는 AI 에이전트, 특히 고급 코드 분석 및 감사 기능이 필요한 에이전트에게 적합합니다.","es":"Perfecto para agentes de IA que necesitan capacidades de análisis y auditoría de código avanzadas, particularmente aquellos que utilizan Python y análisis semántico para mejorar la calidad del código.","fr":"Parfait pour les agents IA ayant besoin d''une analyse et d''une audit de code avancées, en particulier ceux utilisant Python et l''analyse sémantique pour améliorer la qualité du code.","de":"Perfekt für KI-Agents, die erweiterte Code-Analyse- und Audit-Funktionen benötigen, insbesondere solche, die Python und semantische Analyse für eine verbesserte Codequalität verwenden.","pt":"Perfeito para Agentes de IA que necessitam de capacidades avançadas de análise e auditoria de código, particularmente aqueles que utilizam Python e análise semântica para melhorar a qualidade do código.","ru":"Идеально подходит для агентов ИИ, которым требуются передовые возможности анализа и аудита кода, в частности, те, которые используют Python и семантический анализ для улучшения качества кода.","ar":"مثالي لعمليات وكيل الذكاء الاصطناعي التي تحتاج إلى قدرات متقدمة لتحليل ومراجعة الشفرة، خاصة تلك التي تستخدم بايثون والتحليل الدلالي لتحسين جودة الشفرة."},"recommendation":{"en":"Empowers agents to perform hybrid code analysis, combining mechanical detection with deep semantic analysis for JavaScript, CSS, JSON, and PWA files, utilizing Python scripts and detailed criteria from resources like checks-js.md and checks-css.md.","zh":"赋予代理执行混合代码分析的能力，结合机械检测和深度语义分析，用于JavaScript、CSS、JSON和PWA文件，利用Python脚本和来自资源如checks-js.md和checks-css.md的详细标准。","ja":"JavaScript、CSS、JSON、PWAファイルに対して、機械的な検出と深いセマンティック分析を組み合わせたハイブリッドコード分析を実行するエージェントの能力を提供します。Pythonスクリプトと、checks-js.mdやchecks-css.mdなどのリソースからの詳細基準を利用します。","ko":"JavaScript, CSS, JSON 및 PWA 파일을 위한 기계적 감지 및 심층 의미 분석의 결합인 하이브리드 코드 분석을 수행할 수 있는 에이전트의 능력을 부여합니다. Python 스크립트와 checks-js.md 및 checks-css.md와 같은 리소스에서 가져온 자세한 기준을 사용합니다.","es":"Habilita a los agentes a realizar un análisis de código híbrido, combinando la detección mecánica con un análisis semántico profundo para archivos JavaScript, CSS, JSON y PWA, utilizando scripts de Python y criterios detallados de recursos como checks-js.md y checks-css.md.","fr":"Permet aux agents d''effectuer une analyse de code hybride, combinant la détection mécanique avec une analyse sémantique approfondie pour les fichiers JavaScript, CSS, JSON et PWA, en utilisant des scripts Python et des critères détaillés de ressources comme checks-js.md et checks-css.md.","de":"Ermöglicht es den Agents, eine hybride Code-Analyse durchzuführen, indem mechanische Erkennung mit tiefer semantischer Analyse für JavaScript-, CSS-, JSON- und PWA-Dateien kombiniert wird, unter Verwendung von Python-Skripten und detaillierten Kriterien aus Ressourcen wie checks-js.md und checks-css.md.","pt":"Habilita os agentes a realizar análise de código híbrida, combinando detecção mecânica com análise semântica profunda para arquivos JavaScript, CSS, JSON e PWA, utilizando scripts Python e critérios detalhados de recursos como checks-js.md e checks-css.md.","ru":"Наделяет агентов возможностью проводить гибридный анализ кода, сочетая механическое обнаружение с глубоким семантическим анализом для файлов JavaScript, CSS, JSON и PWA, используя скрипты Python и подробные критерии из ресурсов, таких как checks-js.md и checks-css.md.","ar":"تمكين الوكيل من إجراء تحليل شفرة هجين، يجمع بين الكشف الميكانيكي مع التحليل الدلالي العميق لأماكن JavaScript و CSS و JSON و PWA، باستخدام نصوص بايثون ومعايير مفصلة من موارد مثل checks-js.md و checks-css.md."},"useCases":{"en":["Automating code audits for JavaScript projects","Debugging CSS stylesheets using detailed criteria","Validating JSON data formats for scene and challenge files","Optimizing Progressive Web Apps (PWAs) and Service Workers"],"zh":["自动化JavaScript项目的代码审计","使用详细标准调试CSS样式表","验证场景和挑战文件的JSON数据格式","优化渐进式Web应用（PWAs）和Service Workers"],"ja":["JavaScriptプロジェクトのコード監査を自動化する","詳細な基準を使用してCSSスタイルシートをデバッグする","シーンとチャレンジファイルのJSONデータ形式を検証する","プログレッシブWebアプリ（PWAs）とService Workersを最適化する"],"ko":["JavaScript 프로젝트의 코드 감사를 자동화하는 것","자세한 기준을 사용하여 CSS 스타일시트를 디버깅하는 것","장면 및 도전 파일의 JSON 데이터 형식을 검증하는 것","진행적 웹 애플리케이션(PWAs) 및 서비스 작업자를 최적화하는 것"],"es":["Automatizar auditorías de código para proyectos JavaScript","Depurar hojas de estilo CSS utilizando criterios detallados","Validar formatos de datos JSON para archivos de escena y desafío","Optimizar Progressive Web Apps (PWAs) y Service Workers"],"fr":["Automatiser les audits de code pour les projets JavaScript","Déboguer les feuilles de style CSS en utilisant des critères détaillés","Valider les formats de données JSON pour les fichiers de scène et de défi","Optimiser les Progressive Web Apps (PWAs) et les Service Workers"],"de":["Automatisieren von Code-Audits für JavaScript-Projekte","Debuggen von CSS-Stylesheets unter Verwendung detaillierter Kriterien","Validieren von JSON-Datiformaten für Szene- und Herausforderungsdateien","Optimieren von Progressive Web Apps (PWAs) und Service Workern"],"pt":["Automatizar auditorias de código para projetos JavaScript","Depurar folhas de estilo CSS usando critérios detalhados","Validar formatos de dados JSON para arquivos de cena e desafio","Otimizar Progressive Web Apps (PWAs) e Service Workers"],"ru":["Автоматизировать аудит кода для проектов JavaScript","Отлаживать таблицы стилей CSS с помощью подробных критериев","Проверять форматы данных JSON для файлов сцены и задач","Оптимизировать прогрессивные веб-приложения (PWA) и Service Workers"],"ar":["تأتمتة مراجعة الشفرة لمشاريع JavaScript","تصحيح أوراق الأنماط CSS باستخدام معايير مفصلة","التحقق من تنسيقات بيانات JSON للملفات المشهد والتحدي","تحسين تطبيقات الويب التقدمية (PWAs) وخدمات العملاء"]},"limitations":{"en":["Requires Python script execution capabilities","Limited to analysis of JavaScript, CSS, JSON, and PWA files","Dependent on resources like checks-js.md and checks-css.md for detailed criteria"],"zh":["需要Python脚本执行能力","仅限于JavaScript、CSS、JSON和PWA文件的分析","依赖于资源如checks-js.md和checks-css.md的详细标准"],"ja":["Pythonスクリプトの実行能力が必要","JavaScript、CSS、JSON、PWAファイルのみを分析","checks-js.mdやchecks-css.mdなどのリソースからの詳細基準に依存"],"ko":["Python 스크립트 실행 기능이 필요합니다","JavaScript, CSS, JSON 및 PWA 파일의 분석만 가능합니다","checks-js.md 및 checks-css.md와 같은 리소스에서 가져온 자세한 기준에 의존합니다"],"es":["Requiere capacidades de ejecución de scripts de Python","Limitado al análisis de archivos JavaScript, CSS, JSON y PWA","Dependiente de recursos como checks-js.md y checks-css.md para criterios detallados"],"fr":["Nécessite des capacités d''exécution de scripts Python","Limité à l''analyse des fichiers JavaScript, CSS, JSON et PWA","Dépendant de ressources comme checks-js.md et checks-css.md pour des critères détaillés"],"de":["Erfordert Python-Skript-Ausführungsfähigkeiten","Begrenzt auf die Analyse von JavaScript-, CSS-, JSON- und PWA-Dateien","Abhängig von Ressourcen wie checks-js.md und checks-css.md für detaillierte Kriterien"],"pt":["Requer capacidades de execução de scripts Python","Limitado à análise de arquivos JavaScript, CSS, JSON e PWA","Dependente de recursos como checks-js.md e checks-css.md para critérios detalhados"],"ru":["Требует возможности выполнения скриптов Python","Ограничен анализом файлов JavaScript, CSS, JSON и PWA","Зависит от ресурсов, таких как checks-js.md и checks-css.md, для подробных критериев"],"ar":["يتطلب القدرة على تشغيل نصوص بايثون","محدود بالتحليل لأماكن JavaScript و CSS و JSON و PWA","يعتمد على موارد مثل checks-js.md و checks-css.md لمعايير مفصلة"]},"version":4},"contentHash":"2228fda22a76635156d0750c3558f2b781a22473363a55f1796a3049d2f8ebff","qualityScore":33}');
