INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('LucasPier/cuentos-interactivos/code-auditor', 'code-auditor', 'LucasPier', 'cuentos-interactivos', 'community', 'code-auditor LucasPier cuentos-interactivos community The code-auditor skill provides a hybrid approach to code analysis, combining a Python script for mechanical detection with deep semantic analysis for improved code quality, benefiting developers and project managers. code-auditor是一种混合技能，结合Python脚本和语义分析，用于代码审计和分析 code-auditorは、Pythonスクリプトとセマンティック分析を組み合わせたハイブリッドスキルであり、コード監査と分析に使用されます code-auditor는 파이썬 스크립트와 의미 분석을 결합한 하이브리드 스킬로 코드 감시 및 분석에 사용됩니다 El code-auditor es una herramienta híbrida que combina un script Python para detección mecánica de hallazgos con instrucciones para análisis semántico profundo. Se utiliza para auditar proyectos y detectar errores Le code-auditor est un outil hybride qui combine un script Python pour la détection mécanique des résultats avec des instructions pour l''analyse sémantique approfondie. Il est utilisé pour auditer les projets et détecter les erreurs Der code-auditor ist ein hybrides Tool, das ein Python-Skript für die mechanische Ergebnisdetektion mit Anweisungen für eine tiefe semantische Analyse kombiniert. Es wird verwendet, um Projekte zu auditen und Fehler zu erkennen O code-auditor é uma ferramenta híbrida que combina script Python com análise semântica profunda para auditoria de código ИИ Агент code-auditor - это гибридный инструмент, который сочетает скрипт Python с глубоким семантическим анализом для аудита кода أداة فحص الرمز code-auditor هي أداة هجينة تجمع بين سكريبت Python و تحليل دقيق لمراجعة رمز البرامج how to use code-auditor code-auditor setup guide code-auditor vs sonarqube code-auditor install what is code-auditor code-auditor alternative code-auditor tutorial code-auditor for AI agents code-auditor best practices 代码审计 代码分析 Python脚本 语义分析 代码检查 JavaScript代码分析 CSS代码分析 JSON代码分析 PWA代码分析 Executes Python script for mechanical detection of code issues Performs deep semantic analysis for improved code understanding Supports detailed checks for JavaScript, CSS, JSON, and PWA/Service Worker Utilizes resources like checks-js.md, checks-css.md, and checks-pwa.md for criteria Enables analysis of JSONs for scenes and challenges code-auditor is a hybrid skill that combines mechanical and semantic analysis for comprehensive code auditing and improvement.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('HelixDevelopment/HelixAgent/ssh', 'community', 'HelixDevelopment', 'HelixAgent', 'HelixDevelopment/HelixAgent', 'ssh', 0, 0, 33, '2026-03-07T12:46:33.374Z', '2026-03-07T12:50:51.999Z', '02b94d8014244412cbac9ee93c1860ecd87ffdce8df95f4acb823c9075ca7366', '{"id":"HelixDevelopment/HelixAgent/ssh","name":"ssh","description":{"en":"The SSH skill enables AI agents to establish and manage secure connections to remote machines, benefiting developers and system administrators. It provides capabilities for authentication, command execution, and file transfer.","zh":"SSH","ja":"SSH","ko":"SSH","es":"El agente de LLM proporciona capacidades para establecer y gestionar conexiones SSH a máquinas remotas. Soporta autenticación por contraseña o clave y ejecución de comandos en máquinas remotas.","fr":"L''agent LLM fournit des capacités pour établir et gérer des connexions SSH à des machines distantes. Il prend en charge l''authentification par mot de passe ou clé et l''exécution de commandes sur des machines distantes.","de":"Der LLM-Agent bietet Funktionen zur Herstellung und Verwaltung von SSH-Verbindungen zu Remote-Maschinen. Er unterstützt Passwort- oder Schlüsselauthentifizierung und die Ausführung von Befehlen auf Remote-Maschinen.","pt":"O skill SSH fornece capacidades para estabelecer e gerenciar conexões SSH a máquinas remotas, incluindo autenticação e transferência de arquivos.","ru":"Навык SSH предоставляет возможности для установления и управления подключениями SSH к удаленным машинам, включая аутентификацию и передачу файлов с помощью ИИ Агентов.","ar":"مهارة SSH توفر إمكانيات لإنشاء وتحكم في الاتصالات SSH إلى أجهزة بعيدة، بما في ذلك التحقق ونقل الملفات مع وكلاء الذكاء الاصطناعي."},"seo":{"title":{"en":"SSH Skill: Secure Connection Setup Guide | AI Agent","zh":"SSH_SETUP_GUIDE","ja":"SSH_BEST_PRACTICES","ko":"SSH_SETUP_TUTORIAL","es":"Guía de configuración de SSH para agentes de LLM","fr":"Guide de configuration SSH pour les agents LLM","de":"SSH-Setup-Leitfaden für LLM-Agents","pt":"Guia de Configuração SSH: Autenticação e Gerenciamento","ru":"Настройка SSH: Руководство по аутентификации и управлению...","ar":"إعداد SSH: دليل للتحقق والتحكم في وكلاء الذكاء الاصطناعي"},"description":{"en":"Discover how to establish secure SSH connections with ease. Learn password and key-based authentication methods and manage SSH configurations effectively.","zh":"SSH","ja":"SSH","ko":"SSH","es":"Aprende a configurar y gestionar conexiones SSH con autenticación por contraseña o clave, y ejecuta comandos en máquinas remotas con nuestro agente de LLM","fr":"Découvrez comment configurer et gérer des connexions SSH avec authentification par mot de passe ou clé, et exécutez des commandes sur des machines distantes ...","de":"Erfahren Sie, wie Sie SSH-Verbindungen mit Passwort- oder Schlüsselauthentifizierung konfigurieren und verwalten, und führen Sie Befehle auf Remote-Maschinen...","pt":"Aprenda a configurar e gerenciar conexões SSH com autenticação por senha ou chave, transfira arquivos e execute comandos em máquinas remotas.","ru":"Узнайте, как настроить и управлять подключениями SSH с аутентификацией по паролю или ключу, передавать файлы и выполнять команды на удаленных машинах с помощ...","ar":"تعلم كيفية إعداد وتحكم في الاتصالات SSH باستخدام التحقق من كلمة المرور أو المفتاح، ونقل الملفات وتنفيذ الأوامر على أجهزة بعيدة مع وكلاء الذكاء الاصطناعي."},"definition":{"en":"ssh is a secure protocol for remote access, allowing users to establish encrypted connections to remote machines for command execution and file transfer.","zh":"SSH","ja":"SSH","ko":"SSH","es":"¿Qué es SSH? SSH es un protocolo de comunicación seguro para acceder y gestionar máquinas remotas.","fr":"Qu''est-ce que SSH ? SSH est un protocole de communication sécurisé pour accéder et gérer des machines distantes.","de":"Was ist SSH? SSH ist ein sicheres Kommunikationsprotokoll zum Zugriff und zur Verwaltung von Remote-Maschinen.","pt":"SSH é um protocolo de rede que permite acessar e gerenciar máquinas remotas de forma segura.","ru":"SSH — это сетевой протокол, который позволяет безопасно доступ и управлять удаленными машинами с помощью ИИ Агентов.","ar":"SSH هو بروتوكول شبكة يسمح بالوصول إلى أجهزة بعيدة وتحكمها بأمان مع وكلاء الذكاء الاصطناعي."},"features":{"en":["Establish SSH connections using password or key-based authentication","Generate and manage SSH key pairs","Execute commands on remote machines","Transfer files between local and remote machines","Configure SSH for easier connections"],"zh":["SSH","SSH","SSH","SSH","SSH","SSH"],"ja":["SSH","SSH","SSH","SSH","SSH","SSH"],"ko":["SSH","SSH","SSH","SSH","SSH","SSH"],"es":["Establecer conexiones SSH con autenticación por contraseña o clave","Generar y gestionar pares de claves SSH","Configurar SSH para conexiones más fáciles","Ejecutar comandos en máquinas remotas","Transferir archivos entre máquinas locales y remotas","Gestionar configuraciones SSH y hosts conocidos"],"fr":["Établir des connexions SSH avec authentification par mot de passe ou clé","Générer et gérer des paires de clés SSH","Configurer SSH pour des connexions plus faciles","Exécuter des commandes sur des machines distantes","Transférer des fichiers entre machines locales et distantes","Gérer des configurations SSH et des hôtes connus"],"de":["Herstellen von SSH-Verbindungen mit Passwort- oder Schlüsselauthentifizierung","Generieren und Verwalten von SSH-Schlüsselpaaren","Konfigurieren von SSH für einfachere Verbindungen","Ausführen von Befehlen auf Remote-Maschinen","Übertragen von Dateien zwischen lokalen und Remote-Maschinen","Verwalten von SSH-Konfigurationen und bekannten Hosts"],"pt":["Estabelecer conexões SSH com autenticação por senha ou chave","Gerar e gerenciar pares de chaves SSH","Configurar SSH para conexões mais fáceis","Executar comandos em máquinas remotas","Transferir arquivos entre máquinas locais e remotas","Gerenciar configurações SSH e hosts conhecidos"],"ru":["Установить подключения SSH с аутентификацией по паролю или ключу","Генерировать и управлять парами ключей SSH","Настроить SSH для более легких подключений","Выполнять команды на удаленных машинах","Передавать файлы между локальными и удаленными машинами","Управлять конфигурациями SSH и известными хостами с помощью ИИ Агентов"],"ar":["إنشاء اتصالات SSH باستخدام التحقق من كلمة المرور أو المفتاح","إنشاء وتحكم في أزواج المفاتيح SSH","إعداد SSH للاتصالات الأسهل","تنفيذ الأوامر على أجهزة بعيدة","نقل الملفات بين الأجهزة المحلية والبعيدة","تحكم في إعدادات SSH والمضيفين المعروفين مع وكلاء الذكاء الاصطناعي"]},"keywords":{"en":["how to use ssh","ssh setup guide","ssh vs telnet","ssh alternative","ssh install","ssh key pair generation"],"zh":["SSH","SSH","SSH","SSH","SSH","SSH","SSH"],"ja":["SSH","SSH","SSH","SSH","SSH","SSH","SSH"],"ko":["SSH","SSH","SSH","SSH","SSH","SSH","SSH"],"es":["agentes de LLM","configuración de SSH","autenticación por contraseña","autenticación por clave","ejecución de comandos en máquinas remotas","transferencia de archivos","gestión de configuraciones SSH","herramientas de SSH","protocolo SSH"],"fr":["agents LLM","configuration SSH","authentification par mot de passe","authentification par clé","exécution de commandes sur des machines distantes","transfert de fichiers","gestion de configurations SSH","outils SSH","protocole SSH"],"de":["LLM-Agents","SSH-Konfiguration","Passwortauthentifizierung","Schlüsselauthentifizierung","Befehlsausführung auf Remote-Maschinen","Dateiübertragung","SSH-Konfigurationsverwaltung","SSH-Tools","SSH-Protokoll"],"pt":["ssh","autenticação ssh","gerenciamento ssh","transferência de arquivos ssh","execução de comandos ssh","configuração ssh","segurança ssh","conexões ssh","máquinas remotas"],"ru":["ssh","аутентификация ssh","управление ssh","передача файлов ssh","выполнение команд ssh","настройка ssh","безопасность ssh","подключения ssh","удаленные машины","ИИ Агенты"],"ar":["ssh","التحقق ssh","التحكم ssh","نقل الملفات ssh","تنفيذ الأوامر ssh","إعداد ssh","أمان ssh","اتصالات ssh","أجهزة بعيدة","وكلاء الذكاء الاصطناعي"]}},"owner":"HelixDevelopment","repo":"HelixAgent","repoPath":"HelixDevelopment/HelixAgent","stars":0,"forks":0,"updatedAt":"2026-03-07T12:46:33.374Z","topics":[],"category":"community","skillMd":{"name":"ssh","description":"Establish and manage SSH connections to remote machines, including key generation, configuration, and file transfers. Use when connecting to remote servers, executing remote commands, or transferring files via SCP.","bodyPreview":"# SSH Skill\n\nThis skill provides capabilities for establishing and managing SSH connections to remote machines.\n\n## Capabilities\n\n- Establish SSH connections using password or key-based authentication\n- Generate and manage SSH key pairs\n- Configure SSH for easier connections\n- Execute commands on remote machines\n- Transfer files between local and remote machines\n- Manage SSH configurations and known hosts\n\n## Authentication Methods\n\n### Password Authentication\n\n```bash\nssh username@hostname\n```","body":"# SSH Skill\n\nThis skill provides capabilities for establishing and managing SSH connections to remote machines.\n\n## Capabilities\n\n- Establish SSH connections using password or key-based authentication\n- Generate and manage SSH key pairs\n- Configure SSH for easier connections\n- Execute commands on remote machines\n- Transfer files between local and remote machines\n- Manage SSH configurations and known hosts\n\n## Authentication Methods\n\n### Password Authentication\n\n```bash\nssh username@hostname\n```\n\nWhen prompted, you should ask the user for their password or a private key.\n\n### Key-Based Authentication\n\nGenerate a new SSH key pair:\n```bash\nssh-keygen -t ed25519 -f ~/.ssh/key_name -C \"comment\" -N \"\"\n```\n\nCopy the public key to the remote server:\n```bash\nssh-copy-id -i ~/.ssh/key_name.pub username@hostname\n```\n\nConnect using the private key:\n```bash\nssh -i ~/.ssh/key_name username@hostname\n```\n\n## SSH Configuration\n\nCreate or edit the SSH config file for easier connections:\n```bash\nmkdir -p ~/.ssh\ncat > ~/.ssh/config << ''EOF''\nHost alias\n    HostName hostname_or_ip\n    User username\n    IdentityFile ~/.ssh/key_name\n    Port 22\n    ServerAliveInterval 60\nEOF\nchmod 600 ~/.ssh/config\n```\n\nThen connect using the alias:\n```bash\nssh alias\n```\n\n## Common SSH Options\n\n- `-p PORT`: Connect to a specific port\n- `-X`: Enable X11 forwarding\n- `-L local_port:remote_host:remote_port`: Set up local port forwarding\n- `-R remote_port:local_host:local_port`: Set up remote port forwarding\n- `-N`: Do not execute a remote command (useful for port forwarding)\n- `-f`: Run in background\n- `-v`: Verbose mode (add more v''s for increased verbosity)\n\n## File Transfer with SCP\n\nCopy a file to the remote server:\n```bash\nscp /path/to/local/file username@hostname:/path/to/remote/directory/\n```\n\nCopy a file from the remote server:\n```bash\nscp username@hostname:/path/to/remote/file /path/to/local/directory/\n```\n\nCopy a directory recursively:\n```bash\nscp -r /path/to/local/directory username@hostname:/path/to/remote/directory/\n```\n\n## SSH Agent\n\nStart the SSH agent:\n```bash\neval \"$(ssh-agent -s)\"\n```\n\nAdd a key to the agent:\n```bash\nssh-add ~/.ssh/key_name\n```\n\n## Troubleshooting\n\n- Check SSH service status on remote: `systemctl status sshd`\n- Verify SSH port is open: `nc -zv hostname 22`\n- Debug connection issues: `ssh -vvv username@hostname`\n- Check permissions: SSH private keys should have 600 permissions (`chmod 600 ~/.ssh/key_name`)\n- Verify known_hosts: If host key changed, remove the old entry with `ssh-keygen -R hostname`\n\n## Secure SSH Key Management\n\n### Local Storage with Proper Permissions\n\nThe most basic approach is to ensure proper file permissions:\n\n```bash\n# Set correct permissions for private keys\nchmod 600 ~/.ssh/id_ed25519\n# Set correct permissions for public keys\nchmod 644 ~/.ssh/id_ed25519.pub\n# Set correct permissions for SSH directory\nchmod 700 ~/.ssh\n```"},"lastSynced":"2026-03-07T12:50:51.999Z","agentAnalysis":{"suitability":{"en":"Ideal for System Administration Agents requiring secure remote access and file transfer capabilities.","zh":"适合需要安全远程访问和文件传输能力的系统管理代理。","ja":"安全なリモートアクセスとファイル転送機能を必要とするシステム管理エージェントに最適です。","ko":"보안 원격 액세스 및 파일 전송 기능이 필요한 시스템 관리 에이전트에 적합합니다.","es":"Ideal para Agentes de Administración de Sistemas que requieren acceso remoto seguro y capacidades de transferencia de archivos.","fr":"Idéal pour les agents d''administration de système nécessitant un accès à distance sécurisé et des capacités de transfert de fichiers.","de":"Ideal für SystemadministrationssAgenten, die sicheren Fernzugriff und Dateitransferfunktionen erfordern.","pt":"Ideal para Agentes de Administração de Sistema que requerem acesso remoto seguro e capacidades de transferência de arquivos.","ru":"Идеально подходит для агентов системного администрирования, требующих безопасного удаленного доступа и возможностей передачи файлов.","ar":"مثالي لوكلاء إدارة النظام الذين يتطلبون الوصول البعدي الآمن وقدرات نقل الملفات."},"recommendation":{"en":"Empowers agents to establish and manage secure SSH connections using password or key-based authentication, execute commands on remote machines, and transfer files between local and remote machines using protocols like SSH.","zh":"使代理能够建立和管理安全的SSH连接，使用基于密码或密钥的身份验证，在远程机器上执行命令，并使用SSH等协议在本地和远程机器之间传输文件。","ja":"エージェントが安全なSSH接続を確立して管理し、パスワードまたはキーベースの認証を使用してリモートマシンでコマンドを実行し、SSHなどのプロトコルを使用してローカルマシンとリモートマシンの間でファイルを転送することができます。","ko":"에이전트가 보안 SSH 연결을 설정 및 관리하고, 비밀번호 또는 키 기반 인증을 사용하여 원격 머신에서 명령을 실행하며, SSH와 같은 프로토콜을 사용하여 로컬 및 원격 머신 사이에서 파일을 전송할 수 있습니다.","es":"Habilita a los agentes a establecer y gestionar conexiones SSH seguras usando autenticación por contraseña o basada en claves, ejecutar comandos en máquinas remotas y transferir archivos entre máquinas locales y remotas usando protocolos como SSH.","fr":"Permet aux agents d''établir et de gérer des connexions SSH sécurisées à l''aide d''une authentification par mot de passe ou basée sur des clés, d''exécuter des commandes sur des machines distantes et de transférer des fichiers entre des machines locales et distantes à l''aide de protocoles tels que SSH.","de":"Ermöglicht es den Agenten, sichere SSH-Verbindungen mithilfe von Passwort- oder schlüsselbasierter Authentifizierung herzustellen und zu verwalten, Befehle auf Remote-Maschinen auszuführen und Dateien zwischen lokalen und Remote-Maschinen mithilfe von Protokollen wie SSH zu übertragen.","pt":"Permite que os agentes estabeleçam e gerenciem conexões SSH seguras usando autenticação baseada em senha ou chave, executem comandos em máquinas remotas e transfiram arquivos entre máquinas locais e remotas usando protocolos como SSH.","ru":"Позволяет агентам устанавливать и управлять безопасными соединениями SSH с использованием аутентификации по паролю или ключу, выполнять команды на удаленных машинах и передавать файлы между локальными и удаленными машинами с использованием протоколов типа SSH.","ar":"تمكن الوكلاء من إنشاء وتشغيل اتصالات SSH آمنة باستخدام مصادقة كلمة المرور أو المفتاح، وتنفيذ أوامر على أجهزة بعيدة، ونقل الملفات بين الأجهزة المحلية والبعيدة باستخدام بروتوكولات مثل SSH."},"useCases":{"en":["Automating remote server management","Executing commands on remote machines","Transferring files securely between local and remote machines"],"zh":["自动化远程服务器管理","在远程机器上执行命令","使用SSH等协议在本地和远程机器之间安全地传输文件"],"ja":["リモートサーバー管理の自動化","リモートマシンでコマンドを実行","SSHなどのプロトコルを使用してローカルマシンとリモートマシンの間でファイルを安全に転送"],"ko":["원격 서버 관리 자동화","원격 머신에서 명령 실행","SSH와 같은 프로토콜을 사용하여 로컬 및 원격 머신 사이에서 파일을 안전하게 전송"],"es":["Automatización de la administración de servidores remotos","Ejecución de comandos en máquinas remotas","Transferencia segura de archivos entre máquinas locales y remotas"],"fr":["Automatisation de la gestion de serveurs distants","Exécution de commandes sur des machines distantes","Transfert sécurisé de fichiers entre des machines locales et distantes"],"de":["Automatisierung der Remote-Server-Verwaltung","Ausführen von Befehlen auf Remote-Maschinen","Sichere Übertragung von Dateien zwischen lokalen und Remote-Maschinen"],"pt":["Automizar a gestão de servidores remotos","Executar comandos em máquinas remotas","Transferir arquivos de forma segura entre máquinas locais e remotas"],"ru":["Автоматизация удаленного управления серверами","Выполнение команд на удаленных машинах","Безопасная передача файлов между локальными и удаленными машинами"],"ar":["أتمتة إدارة الخواديم عن بعد","تنفيذ أوامر على أجهزة بعيدة","نقل الملفات بشكل آمن بين الأجهزة المحلية والبعيدة"]},"limitations":{"en":["Requires SSH server setup","Depends on network connectivity","Key-based authentication requires key pair management"],"zh":["需要SSH服务器设置","依赖于网络连接","密钥 기반身份验证需要密钥对管理"],"ja":["SSHサーバーの設定が必要","ネットワーク接続に依存","キーベースの認証にはキーペアの管理が必要"],"ko":["SSH 서버 설정이 필요합니다.","네트워크 연결에 의존합니다.","키 기반 인증에는 키 페어 관리가 필요합니다."],"es":["Requiere configuración del servidor SSH","Depende de la conectividad de red","La autenticación basada en claves requiere gestión de pares de claves"],"fr":["Nécessite une configuration du serveur SSH","Dépend de la connectivité réseau","L''authentification basée sur des clés nécessite une gestion de paires de clés"],"de":["Benötigt SSH-Server-Einrichtung","Hängt von der Netzwerkverbindung ab","Schlüsselbasierte Authentifizierung erfordert Schlüsselpaarverwaltung"],"pt":["Requer configuração do servidor SSH","Depende da conectividade de rede","A autenticação baseada em chave requer gerenciamento de pares de chaves"],"ru":["Требуется настройка сервера SSH","Зависит от сетевой связности","Аутентификация на основе ключа требует управления парами ключей"],"ar":["يتطلب إعداد خادم SSH","يعتمد على الاتصال الشبكي","المصادقة القائمة على المفتاح تتطلب إدارة أزواج المفاتيح"]},"version":4},"contentHash":"02b94d8014244412cbac9ee93c1860ecd87ffdce8df95f4acb823c9075ca7366","qualityScore":33}');
