INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('WSU-Carbon-Lab/xray-atlas/architecture-designer', 'architecture-designer', 'WSU-Carbon-Lab', 'xray-atlas', 'community', 'architecture-designer WSU-Carbon-Lab xray-atlas community AI智能代理架构设计师是一款用于科学X射线社区的NEXAFS数据库网页应用，用于设计和开发高效的数据管理系统 AIエージェントアーキテクチャデザイナーは、科学X線コミュニティのためのNEXAFSデータベースWebアプリで、高効率のデータ管理システムを設計・開発するためのツールです AI 에이전트 아키텍처 디자이너는 科学 X선 커뮤니티를 위한 NEXAFS 데이터베이스 웹 애플리케이션으로, 효율적인 데이터 관리 시스템을 설계 및 개발하는 데 사용됩니다 La herramienta de diseño de arquitectura de AI es una aplicación web para bases de datos NEXAFS que sirve a la comunidad científica de rayos X L''outil de conception d''architecture d''IA est une application web pour les bases de données NEXAFS qui sert la communauté scientifique des rayons X Das AI-Architektur-Designer-Tool ist eine Webanwendung für NEXAFS-Datenbanken, die der wissenschaftlichen X-Ray-Community dient O arquiteto de design de AI é uma ferramenta de design de web applications para a comunidade científica de X-ray. ИИ архитектор - это инструмент для проектирования веб-приложений для научного сообщества X-ray. مصمم تصميم AI - هو أداة تصميم تطبيقات الوب لجماعة العلمية X-ray Web application for a NEXAFS database for use by the scientific X-ray community AI智能代理 NEXAFS数据库 科学X射线社区 数据管理系统 AI技术 研究效率 如何使用AI智能代理 AI智能代理的优点 NEXAFS数据库的设计 Web application for a NEXAFS database for use by the scientific X-ray community');
