INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('CleanExpo/Unite-Hub/decision-moment-skill', 'decision-moment-skill', 'CleanExpo', 'Unite-Hub', 'community', 'decision-moment-skill CleanExpo Unite-Hub community decision-moment-skill是Unite Group CRM中的AI智能决策工具，帮助开发者做出更好的决策 decision-moment-skillはUnite Group CRMのAIエージェント機能で、開発者の意思決定を支援します decision-moment-skill은 Unite Group CRM의 AI 에이전트 기능으로 개발자의 의사결정을 지원합니다 Unite Group CRM es una plataforma que se integra con decision-moment-skill para mejorar la toma de decisiones con herramientas de IA Unite Group CRM est une plateforme qui s''intègre à decision-moment-skill pour améliorer la prise de décision avec des outils d''IA Unite Group CRM ist eine Plattform, die sich mit decision-moment-skill integriert, um die Entscheidungsfindung mit KI-Tools zu verbessern O decision-moment-skill é uma habilidade de IA que otimiza o Unite Group CRM para desenvolvedores, melhorando a tomada de decisões Decision-moment-skill - это навык ИИ, который оптимизирует Unite Group CRM для разработчиков, улучшая процесс принятия решений decision-moment-skill هو مهارة ذكاء اصطناعي تحسن من Unite Group CRM للمطورين، وتحسين عملية اتخاذ القرارات Unite Group CRM 如何使用AI智能决策工具 什么是AI智能决策 Unite Group CRM替代品 decision-moment-skill安装 AI智能决策工具设置指南 Unite Group CRM vs Competitor Unite Group CRM');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('heyAyushh/gloves/deslop', 'community', 'heyAyushh', 'gloves', 'heyAyushh/gloves', 'deslop', 0, 0, 33, '2026-02-27T13:08:04.220Z', '2026-02-27T14:10:46.930Z', '931d9baf60c69db6a51a1d32775ab80eb67ff8a7038428ad1bfc94f87acfa515', '{"id":"heyAyushh/gloves/deslop","name":"deslop","description":{"zh":"Deslop AI智能代理是一款使用OpenCLAW的凭证和密码管理工具，提供安全审计功能","ja":"Deslop AIエージェントはOpenCLAWを使用した資格情報とパスワードマネージャーです","ko":"Deslop AI 에이전트는 OpenCLAW를 사용하여 자격 증명 및 암호를 관리하고 보안 감사를 제공하는 도구입니다","es":"Deslop es un gestor de credenciales y contraseñas con auditorías para humanos y agentes de IA. Proporciona una forma segura de gestionar tus datos","fr":"Deslop est un gestionnaire de credentials et de mots de passe avec audits pour humains et agents d''IA. Il offre une façon sécurisée de gérer vos données","de":"Deslop ist ein Credential- und Passwort-Manager mit Audits für Menschen und KI-Agents. Es bietet eine sichere Möglichkeit, Ihre Daten zu verwalten","pt":"O Deslop é um gerenciador de credenciais e senhas com auditorias para humanos e agentes, projetado para melhorar a segurança e a eficiência","ru":"Deslop - менеджер учетных данных и паролей с аудитом для людей и ИИ Агентов, предназначенный для улучшения безопасности и эффективности","ar":"Deslop هو مدير بيانات الاعتماد وكلمات المرور مع تدقيق للبشر وآلات الإي الأجنت، مصمم لتحسين الأمان والكفاءة","en":"openclaw credentials and passwords manager with audits for humans and agents."},"seo":{"title":{"zh":"Deslop AI智能代理：OpenCLAW凭证和密码管理","ja":"Deslop AIエージェント：OpenCLAW資格情報とパスワードマネージャー","ko":"Deslop AI 에이전트: OpenCLAW 자격 증명 및 암호 관리자","es":"Deslop: Gestor de credenciales y contraseñas con auditorí...","fr":"Deslop: Gestionnaire de credentials et de mots de passe a...","de":"Deslop: Credential- und Passwort-Manager mit Audits für M...","pt":"Deslop: Gerenciador de Credenciais e Senhas com A