INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('heyAyushh/gloves/deslop', 'deslop', 'heyAyushh', 'gloves', 'community', 'deslop heyAyushh gloves community Deslop AI智能代理是一款使用OpenCLAW的凭证和密码管理工具，提供安全审计功能 Deslop AIエージェントはOpenCLAWを使用した資格情報とパスワードマネージャーです Deslop AI 에이전트는 OpenCLAW를 사용하여 자격 증명 및 암호를 관리하고 보안 감사를 제공하는 도구입니다 Deslop es un gestor de credenciales y contraseñas con auditorías para humanos y agentes de IA. Proporciona una forma segura de gestionar tus datos Deslop est un gestionnaire de credentials et de mots de passe avec audits pour humains et agents d''IA. Il offre une façon sécurisée de gérer vos données Deslop ist ein Credential- und Passwort-Manager mit Audits für Menschen und KI-Agents. Es bietet eine sichere Möglichkeit, Ihre Daten zu verwalten O Deslop é um gerenciador de credenciais e senhas com auditorias para humanos e agentes, projetado para melhorar a segurança e a eficiência Deslop - менеджер учетных данных и паролей с аудитом для людей и ИИ Агентов, предназначенный для улучшения безопасности и эффективности Deslop هو مدير بيانات الاعتماد وكلمات المرور مع تدقيق للبشر وآلات الإي الأجنت، مصمم لتحسين الأمان والكفاءة openclaw credentials and passwords manager with audits for humans and agents. Deslop AI智能代理 OpenCLAW凭证管理 密码管理工具 安全审计软件 如何使用Deslop Deslop与其他工具比较 openclaw credentials and passwords manager with audits for humans and agents.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('udecode/plate/ankane-readme-writer', 'community', 'udecode', 'plate', 'udecode/plate', 'ankane-readme-writer', 15972, 955, 33, '2026-03-02T01:54:45Z', '2026-03-06T02:33:51.562Z', '43005a802f8a1659c03fc8a1227d12ee538b062a37bdd8b4261588433c656f1d', '{"id":"udecode/plate/ankane-readme-writer","name":"ankane-readme-writer","description":{"en":"ankane-readme-writer is a rich-text editor skill that leverages AI, MCP (Model Context Protocol), and shadcn/ui to generate structured documentation. It helps developers, particularly in the Ruby ecosystem, create Ankane-style READMEs for projects like the ''turbo-search'' gem."},"seo":{"title":{"en":"ankane-readme-writer: AI-Powered Documentation Setup Guid..."},"description":{"en":"Generate polished READMEs for Ruby gems & projects using the ankane-readme-writer AI agent. This MCP-compliant tool integrates shadcn/ui, Slate, and React. I..."},"definition":{"en":"ankane-readme-writer is an AI agent skill that functions as a rich-text editor for generating technical documentation. It uses MCP, React, shadcn/ui, Slate, and TypeScript to produce README files that adhere to the Ankane template structure for Ruby gems and other software projects."},"features":{"en":["Integrates MCP (Model Context Protocol) for standardized AI agent communication","Built with shadcn/ui components for a modern, accessible user interface","Utilizes Slate.js framework for rich-text WYSIWYG editing capabilities","Implemented in TypeScript for type-safe development and scalability","Follows the Ankane template structure for Ruby gem documentation","Generates README files for projects like the ''turbo-search'' gem"]},"keywords":{"en":["how to use ankane-readme-writer","ankane-readme-writer MCP integration","ankane-readme-writer vs generic README generators","ankane-readme-writer install guide","shadcn/ui README editor","Slate.js AI documentation tool","ankane-readme-writer for Ruby gems","TypeScript README generator AI agent"]}},"owner":"udecode","repo":"plate","repoPath":"udecode/plate","stars":15972,"forks":955,"updatedAt":"2026-03-02T01:54:45Z","topics":["ai","mcp","react","shadcn-ui","slate","typescript","wysiwyg"],"category":"community","skillMd":{"name":"ankane-readme-writer","description":"Creates or updates README files following Ankane-style template for Ruby gems. Use when writing gem documentation with imperative voice, concise prose, and standard section ordering.","bodyPreview":"<examples>\n<example>\nContext: User is creating documentation for a new Ruby gem.\nuser: \"I need to write a README for my new search gem called ''turbo-search''\"\nassistant: \"I''ll use the ankane-readme-writer agent to create a properly formatted README following the Ankane style guide\"\n<commentary>Since the user needs a README for a Ruby gem and wants to follow best practices, use the ankane-readme-writer agent to ensure it follows the Ankane template structure.</commentary>\n</example>\n<example>\nCont","body":"<examples>\n<example>\nContext: User is creating documentation for a new Ruby gem.\nuser: \"I need to write a README for my new search gem called ''turbo-search''\"\nassistant: \"I''ll use the ankane-readme-writer agent to create a properly formatted README following the Ankane style guide\"\n<commentary>Since the user needs a README for a Ruby gem and wants to follow best practices, use the ankane-readme-writer agent to ensure it follows the Ankane template structure.</commentary>\n</example>\n<example>\nContext: User has an existing README that needs to be reformatted.\nuser: \"Can you update my gem''s README to follow the Ankane style?\"\nassistant: \"Let me use the ankane-readme-writer agent to reformat your README according to the Ankane template\"\n<commentary>The user explicitly wants to follow Ankane style, so use the specialized agent for this formatting standard.</commentary>\n</example>\n</examples>\n\nYou are an expert Ruby gem documentation writer specializing in the Ankane-style README format. You have deep knowledge of Ruby ecosystem conventions and excel at creating clear, concise documentation that follows Andrew Kane''s proven template structure.\n\nYour core responsibilities:\n1. Write README files that strictly adhere to the Ankane template structure\n2. Use imperative voice throughout (\"Add\", \"Run\", \"Create\" - never \"Adds\", \"Running\", \"Creates\")\n3. Keep every sentence to 15 words or less - brevity is essential\n4. Organize sections in the exact order: Header (with badges), Installation, Quick Start, Usage, Options (if needed), Upgrading (if applicable), Contributing, License\n5. Remove ALL HTML comments before finalizing\n\nKey formatting rules you must follow:\n- One code fence per logical example - never combine multiple concepts\n- Minimal prose between code blocks - let the code speak\n- Use exact wording for standard sections (e.g., \"Add this line to your application''s **Gemfile**:\")\n- Two-space indentation in all code examples\n- Inline comments in code should be lowercase and under 60 characters\n- Options tables should have 10 rows or fewer with one-line descriptions\n\nWhen creating the header:\n- Include the gem name as the main title\n- Add a one-sentence tagline describing what the gem does\n- Include up to 4 badges maximum (Gem Version, Build, Ruby version, License)\n- Use proper badge URLs with placeholders that need replacement\n\nFor the Quick Start section:\n- Provide the absolute fastest path to getting started\n- Usually a generator command or simple initialization\n- Avoid any explanatory text between code fences\n\nFor Usage examples:\n- Always include at least one basic and one advanced example\n- Basic examples should show the simplest possible usage\n- Advanced examples demonstrate key configuration options\n- Add brief inline comments only when necessary\n\nQuality checks before completion:\n- Verify all sentences are 15 words or less\n- Ensure all verbs are in imperative form\n- Confirm sections appear in the correct order\n- Check that all placeholder values (like <gemname>, <user>) are clearly marked\n- Validate that no HTML comments remain\n- Ensure code fences are single-purpose\n\nRemember: The goal is maximum clarity with minimum words. Every word should earn its place. When in doubt, cut it out.\n"},"lastSynced":"2026-03-06T02:33:51.562Z","agentAnalysis":{"suitability":{"en":"Perfect for Ruby Documentation Agents needing structured README generation following Ankane''s best practices.","zh":"非常适合需要遵循 Ankane 最佳实践来生成结构化 README 的 Ruby Documentation Agents。","ja":"Ankane のベストプラクティスに従った構造化 README 生成を必要とする Ruby Documentation Agents に最適です。","ko":"Ankane의 모범 사례를 따르는 구조화된 README 생성이 필요한 Ruby Documentation Agents에 완벽합니다.","es":"Perfecto para agentes de documentación de Ruby que necesitan generar READMEs estructurados siguiendo las mejores prácticas de Ankane.","fr":"Parfait pour les agents de documentation Ruby nécessitant une génération de README structurée suivant les meilleures pratiques d''Ankane.","de":"Perfekt für Ruby-Dokumentations-Agents, die strukturierte README-Generierung nach den Best Practices von Ankane benötigen.","pt":"Perfeito para Agentes de Documentação Ruby que necessitam de geração estruturada de README seguindo as melhores práticas de Ankane.","ru":"Идеально подходит для Агентов документации Ruby, которым требуется структурированное создание README в соответствии с лучшими практиками Ankane.","ar":"مثالي لوكلاء توثيق Ruby الذين يحتاجون إلى إنشاء ملفات README منظمة تتبع أفضل ممارسات Ankane."},"recommendation":{"en":"Empowers agents to generate comprehensive, structured documentation using rich-text editing capabilities, AI integration, and the Model Context Protocol with shadcn/ui components specifically tailored for Ruby gem documentation.","zh":"赋能代理使用富文本编辑功能、AI 集成以及 Model Context Protocol，利用专为 Ruby gem 文档定制的 shadcn/ui 组件来生成全面、结构化的文档。","ja":"リッチテキスト編集機能、AI 統合、および Ruby gem ドキュメント専用に調整された shadcn/ui コンポーネントを備えた Model Context Protocol を使用して、エージェントが包括的で構造化されたドキュメントを生成できるようにします。","ko":"풍부한 텍스트 편집 기능, AI 통합 및 Ruby gem 문서에 특별히 맞춤화된 shadcn/ui 컴포넌트를 갖춘 Model Context Protocol을 사용하여 포괄적이고 구조화된 문서를 생성하도록 에이전트에 권한을 부여합니다.","es":"Empodera a los agentes para generar documentación integral y estructurada utilizando capacidades de edición de texto enriquecido, integración de IA y el Model Context Protocol con componentes shadcn/ui específicamente diseñados para la documentación de gems de Ruby.","fr":"Permet aux agents de générer une documentation complète et structurée en utilisant des capacités d''édition de texte enrichi, l''intégration d''IA et le Model Context Protocol avec des composants shadcn/ui spécialement adaptés pour la documentation de gems Ruby.","de":"Ermöglicht Agents die Generierung umfassender, strukturierter Dokumentation durch Nutzung von Rich-Text-Bearbeitungsfunktionen, KI-Integration und dem Model Context Protocol mit shadcn/ui-Komponenten, die speziell für Ruby gem-Dokumentation zugeschnitten sind.","pt":"Capacita os agentes a gerar documentação abrangente e estruturada usando capacidades de edição de rich-text, integração de AI e o Model Context Protocol com componentes shadcn/ui especificamente adaptados para documentação de gems Ruby.","ru":"Позволяет агентам создавать комплексную структурированную документацию с использованием возможностей редактирования форматированного текста, интеграции AI и Model Context Protocol с компонентами shadcn/ui, специально предназначенными для документации Ruby gem.","ar":"يمكّن الوكلاء من إنشاء توثيق شامل ومنظم باستخدام قدرات تحرير النص المنسق، والتكامل مع AI، وبروتوكول Model Context Protocol مع مكونات shadcn/ui المصممة خصيصًا لتوثيق حزم Ruby."},"useCases":{"en":["Generating Ankane-style READMEs for Ruby gems","Creating structured documentation for turbo-search components","Automating project documentation following Ruby ecosystem standards"],"zh":["为 Ruby gems 生成 Ankane 风格的 README","为 turbo-search 组件创建结构化文档","遵循 Ruby 生态系统标准自动化项目文档"],"ja":["Ruby gems のための Ankane スタイルの README 生成","turbo-search コンポーネントのための構造化ドキュメント作成","Ruby エコシステム標準に従ったプロジェクトドキュメントの自動化"],"ko":["Ruby gems용 Ankane 스타일 README 생성","turbo-search 컴포넌트용 구조화된 문서 작성","Ruby 생태계 표준을 따르는 프로젝트 문서 자동화"],"es":["Generación de READMEs al estilo Ankane para gems de Ruby","Creación de documentación estructurada para componentes turbo-search","Automatización de la documentación de proyectos siguiendo los estándares del ecosistema Ruby"],"fr":["Génération de READMEs de style Ankane pour les gems Ruby","Création d''une documentation structurée pour les composants turbo-search","Automatisation de la documentation de projet suivant les standards de l''écosystème Ruby"],"de":["Generierung von Ankane-style READMEs für Ruby gems","Erstellung strukturierter Dokumentation für turbo-search-Komponenten","Automatisierung der Projektdokumentation nach Standards des Ruby-Ökosystems"],"pt":["Geração de READMEs no estilo Ankane para gems Ruby","Criação de documentação estruturada para componentes turbo-search","Automatização da documentação de projetos seguindo os padrões do ecossistema Ruby"],"ru":["Создание README в стиле Ankane для Ruby gems","Создание структурированной документации для компонентов turbo-search","Автоматизация документации проекта в соответствии со стандартами экосистемы Ruby"],"ar":["إنشاء ملفات README على غرار Ankane لحزم Ruby","إنشاء توثيق منظم لمكونات turbo-search","أتمتة توثيق المشاريع باتباع معايير ecosystem Ruby"]},"limitations":{"en":["Primarily optimized for Ruby gem documentation","Requires MCP integration","Follows specific Ankane template structure"],"zh":["主要针对 Ruby gem 文档进行了优化","需要 MCP 集成","遵循特定的 Ankane 模板结构"],"ja":["主に Ruby gem ドキュメント用に最適化されている","MCP 統合が必要","特定の Ankane テンプレート構造に従う"],"ko":["주로 Ruby gem 문서에 최적화됨","MCP 통합이 필요함","특정 Ankane 템플릿 구조를 따름"],"es":["Principalmente optimizado para la documentación de gems de Ruby","Requiere integración MCP","Sigue una estructura de plantilla específica de Ankane"],"fr":["Principalement optimisé pour la documentation de gems Ruby","Nécessite une intégration MCP","Suit une structure de modèle spécifique à Ankane"],"de":["Hauptsächlich für die Dokumentation von Ruby gems optimiert","Erfordert MCP-Integration","Folgt einer spezifischen Ankane-Vorlagenstruktur"],"pt":["Otimizado principalmente para documentação de gems Ruby","Requer integração com MCP","Segue uma estrutura de template específica do Ankane"],"ru":["В первую очередь оптимизирован для документации Ruby gem","Требует интеграции MCP","Следует определенной структуре шаблона Ankane"],"ar":["مُحسّن بشكل أساسي لتوثيق حزم Ruby","يتطلب تكامل MCP","يتبع هيكل قالب Ankane محدد"]},"version":4},"contentHash":"43005a802f8a1659c03fc8a1227d12ee538b062a37bdd8b4261588433c656f1d","qualityScore":33}');
