INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('udecode/plate/ankane-readme-writer', 'ankane-readme-writer', 'udecode', 'plate', 'community', 'ankane-readme-writer udecode plate community ai mcp react shadcn-ui slate typescript wysiwyg ankane-readme-writer is a rich-text editor skill that leverages AI, MCP (Model Context Protocol), and shadcn/ui to generate structured documentation. It helps developers, particularly in the Ruby ecosystem, create Ankane-style READMEs for projects like the ''turbo-search'' gem. how to use ankane-readme-writer ankane-readme-writer MCP integration ankane-readme-writer vs generic README generators ankane-readme-writer install guide shadcn/ui README editor Slate.js AI documentation tool ankane-readme-writer for Ruby gems TypeScript README generator AI agent Integrates MCP (Model Context Protocol) for standardized AI agent communication Built with shadcn/ui components for a modern, accessible user interface Utilizes Slate.js framework for rich-text WYSIWYG editing capabilities Implemented in TypeScript for type-safe development and scalability Follows the Ankane template structure for Ruby gem documentation Generates README files for projects like the ''turbo-search'' gem ankane-readme-writer is an AI agent skill that functions as a rich-text editor for generating technical documentation. It uses MCP, React, shadcn/ui, Slate, and TypeScript to produce README files that adhere to the Ankane template structure for Ruby gems and other software projects.');
