INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nesihaver-IL/MyFirstRepo/github-trending', 'github-trending', 'nesihaver-IL', 'MyFirstRepo', 'community', 'github-trending nesihaver-IL MyFirstRepo community The github-trending skill fetches trending repositories and developers from GitHub using web scraping or GitHub Search API, benefiting developers and repository owners. GitHub Trending Skill 提供了获取热门仓库和开发者数据的能力，使用 Web Scraping 和 GitHub Search API GitHub Trending Skill は、Web Scraping と GitHub Search API を使用して、人気のリポジトリと開発者データを取得します GitHub Trending Skill은 Web Scraping과 GitHub Search API를 사용하여 인기 있는 저장소와 개발자 데이터를 가져옵니다 github-trending permite a los desarrolladores fetch de repositorios y desarrolladores de GitHub utilizando web scraping o GitHub Search API github-trending permet aux développeurs de récupérer des repositories et des développeurs de GitHub en utilisant le web scraping ou l''API de recherche GitHub github-trending ermöglicht es Entwicklern, Repositories und Entwickler von GitHub mithilfe von Web Scraping oder der GitHub Search API abzurufen O github-trending é uma habilidade que permite fetchar repositórios e desenvolvedores em tendência no GitHub usando web scraping ou GitHub Search API github-trending - это навык, который позволяет получать данные о трендах репозиториев и разработчиков на GitHub с помощью web scraping или GitHub Search API github-trending هو مهارة يُمكنها جلب البيانات حول المستودعات والمنشئين الشائعين على GitHub باستخدام تقنيات الويب سكرابينج أو GitHub Search API github-trending setup guide how to use github-trending github-trending alternative github-trending vs github api github-trending install what is github-trending github-trending web scraping github-trending search api github trending repositories github trending developers GitHub Trending Web Scraping GitHub Search API TypeScript Cheerio TrendingRepo AIエージェント 数据抓取 仓库数据 Uses web scraping as a recommended method for fetching trending data Utilizes GitHub Search API as an alternative for fetching trending repositories Supports TypeScript for defining trending repository interfaces Extracts repository information including owner, name, URL, description, language, stars, forks, and today''s stars Employs Cheerio for HTML parsing and data extraction Provides an async function for fetching trending data github-trending is a skill that uses web scraping or GitHub Search API to fetch trending repositories and developers from GitHub.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-arsenal/github-trending', 'community', 'majiayu000', 'claude-arsenal', 'majiayu000/claude-arsenal', 'github-trending', 0, 0, 33, '2026-03-06T12:59:22.125Z', '2026-03-06T13:11:48.482Z', '424da9e9581db78cba40a378281a35405dbe2697e6f4ddba5e9a61519784a9ed', '{"id":"majiayu000/claude-arsenal/github-trending","name":"github-trending","description":{"en":"The github-trending skill provides real-time GitHub Trending repository and developer analysis, benefiting professional software developers. It offers trend discovery, technical insights, and community pulse understanding.","zh":"GitHub Trending 技术探索指南，实时获取 GitHub Trending 仓库和开发者，分析热门项目背后的技术栈和架构","ja":"GitHub Trending AIエージェントのセットアップガイド。人気プロジェクトの技術スタックとアーキテクチャを分析","ko":"GitHub Trending 개발자 가이드. 인기 프로젝트의 기술 스택과 아키텍처를 분석","es":"GitHub Trending es una habilidad que te permite analizar proyectos en tendencia y tecnologías emergentes en GitHub, ayudándote a mejorar tus habilidades de desarrollo","fr":"GitHub Trending est une compétence qui vous permet d''analyser les projets tendance et les technologies émergentes sur GitHub, vous aidant à améliorer vos compétences de développement","de":"GitHub Trending ist eine Fähigkeit, die es Ihnen ermöglicht, Trend-Projekte und aufstrebende Technologien auf GitHub zu analysieren, um Ihre Entwicklerfähigkeiten zu verbessern","pt":"O github-trending é uma habilidade que fornece tendências de tecnologia em tempo real, permitindo que os desenvolvedores descubram projetos em alta e entendam as tecnologias por trás deles","ru":"github-trending - это навык, который предоставляет информацию о трендах технологий в режиме реального времени, позволяя разработчикам обнаружить популярные проекты и проанализировать технологический стек","ar":"github-trending هو مهارة توفر معلومات حول التوجهات التكنولوجية في الوقت الفعلي، مما يسمح للمطورين باكتشاف المشاريع الشائعة وفهم التقنيات المستخدمة"},"seo":{"title":{"en":"github-trending: Trending Repository Analysis for AI Agen...","zh":"GitHub Trending 技术探索指南","ja":"GitHub Trending AIエージェントのセットアップガイド","ko":"GitHub Trending 개발자 가이드","es":"Guía de configuración para GitHub Trending: Análisis de p...","fr":"Guide de mise en route pour GitHub Trending: Analyse des ...","de":"Einrichtungsleitfaden für GitHub Trending: Analyse von Tr...","pt":"Guia de Configuração do github-trending: Descubra Projeto...","ru":"ИИ Агенты: Руководство по Настройке github-trending для О...","ar":"دليل إعداد github-trending: استكشاف المشاريع الشائعة"},"description":{"en":"Unlock GitHub''s hidden gems with github-trending! Discover trending repos, analyze tech stacks, and identify opportunities. Get started now!","zh":"实时获取 GitHub Trending 仓库和开发者，分析热门项目背后的技术栈和架构","ja":"GitHub Trending のリアルタイム情報を取得し、人気プロジェクトの技術スタックとアーキテクチャを分析","ko":"GitHub Trending 저장소와 개발자를 실시간으로 가져와서 인기 프로젝트의 기술 스택과 아키텍처를 분석","es":"Descubre cómo utilizar GitHub Trending para analizar proyectos en tendencia y tecnologías emergentes, y mejora tus habilidades de desarrollo con nuestra guía","fr":"Découvrez comment utiliser GitHub Trending pour analyser les projets tendance et les technologies émergentes, et améliorez vos compétences de développement a...","de":"Erfahren Sie, wie Sie GitHub Trending nutzen können, um Trend-Projekte und aufstrebende Technologien zu analysieren, und verbessern Sie Ihre Entwicklerfähigk...","pt":"Aprenda a configurar o github-trending para descobrir projetos em alta e entender as tendências de tecnologia em tempo real","ru":"Узнайте, как настроить github-trending для определения трендов и анализа技术栈 популярных проектов","ar":"تعرف على كيفية إعداد github-trending لاستكشاف المشاريع الشائعة وتحليل التكنولوجيا المستخدمة"},"definition":{"en":"github-trending is a comprehensive skill library for analyzing GitHub trends, providing insights into popular projects, technologies, and devel