INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-arsenal/github-trending', 'github-trending', 'majiayu000', 'claude-arsenal', 'community', 'github-trending majiayu000 claude-arsenal community The github-trending skill provides real-time GitHub Trending repository and developer analysis, benefiting professional software developers. It offers trend discovery, technical insights, and community pulse understanding. GitHub Trending 技术探索指南，实时获取 GitHub Trending 仓库和开发者，分析热门项目背后的技术栈和架构 GitHub Trending AIエージェントのセットアップガイド。人気プロジェクトの技術スタックとアーキテクチャを分析 GitHub Trending 개발자 가이드. 인기 프로젝트의 기술 스택과 아키텍처를 분석 GitHub Trending es una habilidad que te permite analizar proyectos en tendencia y tecnologías emergentes en GitHub, ayudándote a mejorar tus habilidades de desarrollo GitHub Trending est une compétence qui vous permet d''analyser les projets tendance et les technologies émergentes sur GitHub, vous aidant à améliorer vos compétences de développement GitHub Trending ist eine Fähigkeit, die es Ihnen ermöglicht, Trend-Projekte und aufstrebende Technologien auf GitHub zu analysieren, um Ihre Entwicklerfähigkeiten zu verbessern O github-trending é uma habilidade que fornece tendências de tecnologia em tempo real, permitindo que os desenvolvedores descubram projetos em alta e entendam as tecnologias por trás deles github-trending - это навык, который предоставляет информацию о трендах технологий в режиме реального времени, позволяя разработчикам обнаружить популярные проекты и проанализировать технологический стек github-trending هو مهارة توفر معلومات حول التوجهات التكنولوجية في الوقت الفعلي، مما يسمح للمطورين باكتشاف المشاريع الشائعة وفهم التقنيات المستخدمة github-trending setup guide how to use github-trending for trend analysis github-trending vs git-trend github-trending alternative for repository analysis what is github-trending and its benefits github-trending install for AI agents github-trending for professional software development github-trending tutorial for beginners github-trending for open-source contribution opportunities GitHub Trending AI技术 实时趋势 技术栈分析 开发者社区 开源贡献 Rust React Real-time trend discovery of GitHub repositories and developers Technical insights into popular project tech stacks and architectures Community pulse analysis for understanding developer interests and needs Opportunity identification for potential open-source contributions and learning directions Support for exploring trending projects by language, domain, or technology github-trending is a comprehensive skill library for analyzing GitHub trends, providing insights into popular projects, technologies, and developer communities.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tolitius/salvador/game', 'community', 'tolitius', 'salvador', 'tolitius/salvador', 'game', 12, 2, 32, '2026-02-11T22:13:52Z', '2026-03-06T06:45:08.172Z', 'd7d16b7d353691e1fb655d58ee0d5fe79eb0cf08ac63022200a08d92634541c5', '{"id":"tolitius/salvador/game","name":"game","description":{"en":"The game skill enables developers to create browser-based games using KAPLAY.js and Three.js, focusing on playable mechanics and polished feel. It benefits developers looking to build engaging 2D and 3D games.","zh":"使用游戏代理创建浏览器游戏，包括2D和3D游戏开发，使用KAPLAY.js和Three.js技术","ja":"ゲームエージェントを使用してブラウザゲームを作成する，2Dと3Dゲーム開発，KAPLAY.jsとThree.js技術を使用","ko":"게임 에이전트를 사용하여 브라우저 게임을 생성하는 방법, 2D와 3D 게임 개발, KAPLAY.js와 Three.js 기술 사용","es":"El agente de juego permite crear juegos en el navegador con KAPLAY.js y Three.js, enfocándose en playable mechanics y polished feel.","fr":"L''agent de jeu permet de créer des jeux dans le navigateur avec KAPLAY.js et Three.js, en mettant l''accent sur les mécaniques de jeu et le sentiment poli.","de":"Der Game-Agent ermöglicht die Erstellung von Browser-Spielen mit KAPLAY.js und Three.js, mit Fokus auf playable Mechanics und einem polierten Gefühl.","pt":"Crie jogos baseados em navegador com KAPLAY.js e Three.js, com foco em mecânicas jogáveis e feedback claro","ru":"Создавайте браузерные игры с KAPLAY.js и Three.js, уделяя внимание играбельности и четкой обратной связи","ar":"انشئ ألعاب متوافقة مع المتصفحات باستخدام KAPLAY.js و Three.js مع التركيز على الميكانيكا القابلة للعب وتجاوب واضح"},"seo":{"title":{"en":"Game: Browser-Based Game Development Setup Guide | AI Age...","zh":"游戏开发指南：使用KAPLAY.js和Three.js创建浏览器游戏","ja":"ゲーム開発ガイド：KAPLAY.jsとThree.jsを使用したブラウザゲームの作成","ko":"게임 개발 가이드: KAPLAY.js와 Three.js를 사용한 브라우저 게임 생성","es":"Guía de configuración de juegos con KAPLAY.js y Three.js","fr":"Guide de démarrage des jeux avec KAPLAY.js et Three.js","de":"Einrichtungsleitfaden für Spiele mit KAPLAY.js und Three.js","pt":"Guia de Configuração de Jogos com KAPLAY.js e Three.js","ru":"ИИ Агенты: Настройка Игр с KAPLAY.js и Three.js","ar":"دليل إعداد الألعاب مع KAPLAY.js و Three.js"},"description":{"en":"Discover how to create immersive browser-based games with KAPLAY.js and Three.js. Get started with our game development setup guide and unlock playable mecha...","zh":"使用AI游戏代理创建浏览器游戏，包括2D和3D游戏开发，使用KAPLAY.js和Three.js","ja":"AIエージェントを使用してブラウザゲームを作成する方法，2Dと3Dゲーム開発，KAPLAY.jsとThree.jsを使用","ko":"AI 에이전트를 사용하여 브라우저 게임을 생성하는 방법, 2D와 3D 게임 개발, KAPLAY.js와 Three.js 사용","es":"Crea juegos en el navegador con KAPLAY.js y Three.js. Aprende a configurar y desarrollar juegos con playable mechanics y polished feel.","fr":"Créez des jeux dans le navigateur avec KAPLAY.js et Three.js. Découvrez comment configurer et développer des jeux avec des mécaniques de jeu et un sentiment ...","de":"Erstellen Sie Browser-Spiele mit KAPLAY.js und Three.js. Erfahren Sie, wie Sie Spiele mit playable Mechanics und einem polierten Gefühl konfigurieren und ent...","pt":"Aprenda a criar jogos baseados em navegador com KAPLAY.js e Three.js, focando em mecânicas jogáveis e feedback claro","ru":"ИИ Агенты: Создавайте браузерные игры с KAPLAY.js и Three.js, уделяя внимание играбельности и четкой обратной связи","ar":"تعلم كيفية إنشاء ألعاب متوافقة مع المتصفحات باستخدام KAPLAY.js و Three.js مع التركيز على الميكانيكا القابلة للعب وتجاوب واضح"},"definition":{"en":"Game is a skill that allows developers to create browser-based games using JavaScript libraries like KAPLAY.js and Three.js, with a focus on playable mechanics and clear feedback.","zh":"游戏代理是使用KAPLAY.js和Three.js技术创建浏览器游戏的AI工具","ja":"ゲームエージェントは，KAPLAY.jsとThree.js技術を使用してブラウザゲームを作成するAIエージェントです","ko":"게임 에이전트는 KAPLAY.js와 Three.js 기술을 사용하여 브라우저 게임을 생성하는 AI 도구입니다","es":"Un agente de juego es una herramienta de IA que utiliza KAPLAY.js y Three.js para crear juegos en el navegador","fr":"Un agent de jeu est un outil d''IA qui utilise KAPLAY.js et Three.js pour créer des jeux dans le navigateur","de":"Ein Game-Agent ist ein AI-Tool, das KAPLAY.js und Three.js verwendet, um Browser-Spiele zu erstellen","pt":"O agente de jogo é uma ferramenta que permite criar jogos baseados em navegador com tecnologias como KAPLAY.js e Three.js","ru":"ИИ Агент игры - это инструмент, позволяющий создавать браузерные игры с использованием технологий KAPLAY.js и Three.js","ar":"وكلاء الألعاب هي أداة تمكن من إنشاء ألعاب متوافقة مع المتصفحات باستخدام تقنيات مثل KAPLAY.js و Three.js"},"features":{"en":["Creates browser-based games using KAPLAY.js (2D) or Three.js (3D)","Follows a strict loop for game development, including bootstrap and scaffolding phases","Utilizes package.json and bash scripts for setup and configuration","Supports inline JavaScript code in index.html or separate src/game.js files","Reads API references for 2D games using KAPLAY.js"],"zh":["使用KAPLAY.js创建2D游戏","使用Three.js创建3D游戏","支持可玩的游戏机制","提供清晰的反馈和精致的感觉","支持浏览器游戏开发","提供游戏开发工作流程"],"ja":["KAPLAY.jsを使用して2Dゲームを作成","Three.jsを使用して3Dゲームを作成","プレイ可能なゲームメカニズムをサポート","クリアなフィードバックとポリッシュされた感覚を提供","ブラウザゲーム開発をサポート","ゲーム開発ワークフローを提供"],"ko":["KAPLAY.js를 사용하여 2D 게임을 생성","Three.js를 사용하여 3D 게임을 생성","Playable 게임 메커니즘을 지원","클리어한 피드백과 폴리시된 감각을 제공","브라우저 게임 개발을 지원","게임 개발 워크플로우를 제공"],"es":["Uso de KAPLAY.js para juegos 2D","Uso de Three.js para juegos 3D","Enfocarse en playable mechanics","Proporcionar un polished feel","Compatibilidad con index.html y src/game.js","Soporte para la creación de juegos en el navegador"],"fr":["Utilisation de KAPLAY.js pour les jeux 2D","Utilisation de Three.js pour les jeux 3D","Mise en avant des mécaniques de jeu","Fournir un sentiment poli","Compatibilité avec index.html et src/game.js","Prise en charge de la création de jeux dans le navigateur"],"de":["Verwendung von KAPLAY.js für 2D-Spiele","Verwendung von Three.js für 3D-Spiele","Fokus auf playable Mechanics","Bereitstellung eines polierten Gefühls","Kompatibilität mit index.html und src/game.js","Unterstützung für die Erstellung von Browser-Spielen"],"pt":["Criação de jogos baseados em navegador com KAPLAY.js","Desenvolvimento de jogos 3D com Three.js","Foco em mecânicas jogáveis e feedback claro","Integração com package.json e scripts de setup","Suporte a index.html e src/game.js","Uso de bash para execução de scripts"],"ru":["Создание браузерных игр с KAPLAY.js","Разработка 3D-игр с Three.js","Фокус на играбельности и четкой обратной связи","Интеграция с package.json и скриптами настройки","Поддержка index.html и src/game.js","Использование bash для выполнения скриптов"],"ar":["إنشاء ألعاب متوافقة مع المتصفحات مع KAPLAY.js","تطوير ألعاب ثلاثية الأبعاد مع Three.js","التركيز على الميكانيكا القابلة للعب وتجاوب واضح","التكامل مع package.json و스크ربتات الإعداد","دعم index.html و src/game.js","استخدام bash لتشغيل السكربتات"]},"keywords":{"en":["how to use game skill","game development with KAPLAY.js","Three.js game engine","browser-based game setup guide","game alternative to Unity","game vs Phaser","game install and setup","game development best practices","game skill for AI agents"],"zh":["游戏开发","浏览器游戏","KAPLAY.js","Three.js","2D游戏","3D游戏","游戏代理","AI工具","游戏开发工作流程"],"ja":["ゲーム開発","ブラウザゲーム","KAPLAY.js","Three.js","2Dゲーム","3Dゲーム","ゲームエージェント","AIエージェント","ゲーム開発ワークフロー"],"ko":["게임 개발","브라우저 게임","KAPLAY.js","Three.js","2D 게임","3D 게임","게임 에이전트","AI 에이전트","게임 개발 워크플로우"],"es":["agente de juego","KAPLAY.js","Three.js","juegos en el navegador","desarrollo de juegos","herramientas de IA para juegos","creación de juegos 2D","creación de juegos 3D","mejores prácticas para juegos"],"fr":["agent de jeu","KAPLAY.js","Three.js","jeux dans le navigateur","développement de jeux","outils d''IA pour jeux","création de jeux 2D","création de jeux 3D","meilleures pratiques pour jeux"],"de":["Game-Agent","KAPLAY.js","Three.js","Browser-Spiele","Spiele-Entwicklung","AI-Tools für Spiele","Erstellung von 2D-Spielen","Erstellung von 3D-Spielen","Best Practices für Spiele"],"pt":["jogos baseados em navegador","KAPLAY.js","Three.js","mecânicas jogáveis","feedback claro","package.json","bash","index.html","src/game.js"],"ru":["браузерные игры","KAPLAY.js","Three.js","играбельность","четкая обратная связь","package.json","bash","index.html","src/game.js","ИИ Агенты"],"ar":["ألعاب متوافقة مع المتصفحات","KAPLAY.js","Three.js","الميكانيكا القابلة للعب","تجاوب واضح","package.json","bash","index.html","src/game.js","وكلاء الذكاء الاصطناعي"]}},"owner":"tolitius","repo":"salvador","repoPath":"tolitius/salvador","stars":12,"forks":2,"updatedAt":"2026-02-11T22:13:52Z","topics":[],"category":"community","skillMd":{"name":"game","description":"Autonomous browser game agent. Analyzes game concept, implements with KAPLAY.js (2D) or Three.js (3D), playtests in headless browser, critiques gameplay/mechanics, fixes, and launches the result.","bodyPreview":"# Game Agent\nUse this skill to create browser-based games using KAPLAY.js (2D) or Three.js (3D) with a focus on **playable mechanics, clear feedback, and polished feel**.\n\n## Workflow\nFollow this **strict loop** when asked to create a game:\n\n### Phase 1: Bootstrap\n1. **Check Context**: If `package.json` is missing, run `bash .claude/skills/game/scripts/setup.sh`.\n2. **Scaffold**: Ensure `index.html` and `src/game.js` exist (or inline in index.html).\n3. **Read API Reference**:\n   - For 2D games:","body":"# Game Agent\nUse this skill to create browser-based games using KAPLAY.js (2D) or Three.js (3D) with a focus on **playable mechanics, clear feedback, and polished feel**.\n\n## Workflow\nFollow this **strict loop** when asked to create a game:\n\n### Phase 1: Bootstrap\n1. **Check Context**: If `package.json` is missing, run `bash .claude/skills/game/scripts/setup.sh`.\n2. **Scaffold**: Ensure `index.html` and `src/game.js` exist (or inline in index.html).\n3. **Read API Reference**:\n   - For 2D games: Read `references/kaplay-ref.md` for KAPLAY API.\n   - For 3D games: Read `references/threejs-ref.md` for Three.js API.\n   - For FPS games: Read `references/fps-patterns.md` for pointer lock, hit detection, enemy AI.\n4. **Read Game Patterns**: Read `references/game-patterns.md` for architecture patterns.\n5. **Read Game Systems**: Read `references/game-systems.md` for difficulty scaling, scoring, persistence, and UI patterns.\n6. **Read Visual Assets**: Read `references/visual-assets.md` for procedural sprites, palettes, and visual effects.\n\n### Phase 1.5: Game Design Analysis (Before Coding!)\n\nThis game needs to be **playable and fun** from the first iteration.\nTherefore, define the core loop before writing any code.\n\nBefore writing any code, decompose the game:\n\n1. **Identify the Core Mechanic**: What is the ONE thing the player does repeatedly?\n   - Strip away everything else first\n   - This mechanic must be satisfying on its own\n   - Examples: jump, shoot, match, dodge, collect, solve\n\n2. **Define the Challenge**: What makes it difficult?\n   - Timing? Precision? Resource management? Puzzle solving?\n   - How does difficulty progress?\n   - What''s the failure state?\n\n3. **Establish the Feedback Loop**:\n   - **Input**: What does the player press/click/drag?\n   - **Response**: What happens immediately? (must feel < 100ms)\n   - **Outcome**: Success or failure indication\n   - **Reward/Penalty**: Score change, sound, visual effect\n\n4. **Scope to Minimum Viable Game (MVG)**:\n   - ONE level or endless mode\n   - ONE enemy type or obstacle  \n   - ONE player ability\n   - Win AND lose conditions\n   - Can be expanded later, but MVG must work first\n\n5. **Research the Domain** (for educational/simulation games):\n   - Look up actual facts (angles, counts, formulas, rules)\n   - Don''t guess scientific/mathematical details\n   - See `references/physics-constants.md` for common values\n\n### Phase 1.6: Game Feel Principles\n\n6. **Juice**: The game must feel alive and responsive.\n   - **Input Response**: Every input produces immediate visual/audio feedback\n   - **Screen Shake**: On impacts, collisions, explosions - use `shake(intensity)`\n   - **Flash**: Brief color flash on damage or success - use `flash(color, duration)`\n   - **Particles**: On deaths, pickups, actions (spawn small objects with `lifespan`)\n   - **Squash & Stretch**: Scale objects on jumps, bounces, movements\n\n7. **Clarity**: The player must always understand:\n   - Where they are (player position obvious, distinct color/shape)\n   - What they can do (affordances clear)\n   - What hurts them (dangers visually distinct - red, spiky, animated)\n   - What helps them (pickups/goals highlighted - gold, glowing, animated)\n   - Current state (score, lives, progress visible in HUD)\n\n8. **Pacing**: Control the rhythm\n   - Moments of tension followed by release\n   - Difficulty curves, not walls\n   - Rest points between challenges\n   - Even endless games need rhythm variation (spawn rate waves)\n\n9. **Polish Details**:\n   - Title/start screen with game name and controls\n   - Pause functionality (P key or Escape)\n   - Restart on game over (R key)\n   - Score or progress display (top-left, `fixed()` for HUD)\n   - Control hints visible (\"Arrow keys: Move | Space: Jump\")\n\n### Phase 1.7: Physics & Reachability Validation\n\n**CRITICAL**: Validate that game physics allow the player to accomplish required actions.\n\n16. **Test Core Movement**: Before finalizing level/game design:\n    - Can the player reach all required locations?\n    - Can the player avoid all avoidable hazards?\n    - Does movement feel responsive (not sluggish or twitchy)?\n    - Are speeds balanced (player vs enemies vs projectiles)?\n\n17. **Validate With Math**: For physics-based games, calculate limits:\n    - Movement range per second = speed × time\n    - Jump/launch height = (force)² / (2 × gravity)\n    - Projectile range = speed × lifetime\n    - **If design requires X, verify physics allow X**\n\n18. **Common Physics Pitfalls**:\n    - Targets placed beyond movement range\n    - Gaps larger than jump/dash distance\n    - Enemies faster than player can react\n    - Timers shorter than required actions\n    - **Always prototype movement before building levels**\n\n### Phase 1.8: Visual Polish (Before Coding!)\n\n**CRITICAL**: Games must look polished from the first iteration. No \"sticks and boxes.\"\n\n**Quality Bar**: Ask yourself - \"Would someone pay $5 for this?\" If not, it''s not ready.\n\n10. **Choose a Color Palette**: Select from `visual-assets.md` palettes:\n    - `PASTEL` - friendly, casual games\n    - `PICO8` - retro pixel art feel\n    - `ENDESGA` - modern indie aesthetic\n    - `NEON` - cyberpunk, arcade style\n\n11. **Generate PREMIUM Procedural Sprites**: Every sprite needs MULTIPLE layers of polish:\n    - **Player/Hero**: outer glow + multi-stop gradient + shadow + character details (eyes, expression) + highlights\n    - **Collectibles**: glow aura + metallic/shiny gradient + inner detail + shine streak + sparkle accents\n    - **Enemies/Hazards**: danger glow + gradient body + expressive features + shadow + distinguishing details\n    - **Environment** (platforms, walls, tiles): surface texture + body gradient + edge highlights + shadow + structural details\n    - **Projectiles/Effects**: core glow + color gradient + trail suggestion + bright center\n    - **NEVER use bare `rect()`, `circle()`, `polygon()` for visible game objects**\n    - **\"Has a gradient\" is NOT enough** - premium sprites have 5+ visual layers\n    - See `visual-assets.md` for the universal sprite layer checklist\n\n12. **Create Gradient Background**: Flat backgrounds look cheap.\n    - Use `makeGradientBg()` with palette colors\n    - Add subtle stars/dots for depth\n    - Consider parallax layers for side-scrollers\n\n13. **Add Idle Animations**: Static objects feel dead.\n    - Coins: `addFloat()` - gentle bobbing\n    - Player: `addBreathing()` - subtle scale pulse\n    - Enemies: combine breathing + slight movement\n    - Pickups: `addSpin()` or glow pulse\n\n14. **Plan Particle Effects**: Every interaction needs MULTIPLE feedback layers:\n    - **Positive events** (collect, score, win): particle burst + floating text (+1, +100) + screen flash + UI reaction + small shake\n    - **Negative events** (damage, death, lose): explosion particles + screen shake + color flash + UI feedback\n    - **Movement events** (jump, dash, land, turn): directional particles + object deformation (squash/stretch/spin)\n    - **Ambient atmosphere**: floating particles + twinkling/pulsing background elements\n    - **Projectiles/Actions**: spawn flash + trail particles + impact burst\n    - **One effect is NOT enough** - premium feedback stacks 3+ effects per action\n\n15. **Establish Z-Index Hierarchy**: Proper layering adds depth.\n    - Background: z(-100)\n    - Platforms: z(0)\n    - Pickups: z(10)\n    - Enemies: z(20)\n    - Player: z(30)\n    - Particles: z(50)\n    - HUD: z(100) + fixed()\n\n### Phase 2: Autonomous Loop (The \"Work\")\nRepeat this cycle until the game is **Playable and Polished**:\n\n1. **Implement/Refine**: Write game code.\n   * *Constraint*: Use KAPLAY.js for 2D (default), Three.js only if 3D is explicitly needed.\n   * *Constraint*: Single HTML file with CDN imports (no build step for player).\n   * *Constraint*: **Color Palette**: Use a predefined palette from `visual-assets.md` (PASTEL, PICO8, ENDESGA, NEON).\n   * *Constraint*: **No Bare Primitives**: NEVER use `rect()`, `circle()`, `polygon()` for game objects. Use procedural sprites from `visual-assets.md`.\n   * *Constraint*: **Gradient Background**: Always use `makeGradientBg()` instead of flat `background` color.\n   * *Constraint*: **Idle Animations**: All game objects must have subtle animations (float, breathe, pulse, spin).\n   * *Constraint*: **Particle Effects**: Every collision/pickup must spawn particles using `burstParticles()` or `deathExplosion()`.\n   * *Constraint*: **Z-Index Layering**: Use proper z-index hierarchy (BG:-100, platforms:0, pickups:10, enemies:20, player:30, particles:50, HUD:100).\n   * *Constraint*: **Game Loop**: Use KAPLAY''s `onUpdate()` for continuous logic. Never use `noLoop()`.\n   * *Constraint*: **Input Handling**: Use KAPLAY''s `onKeyPress`, `onKeyDown`, `isKeyDown`.\n   * *Constraint*: **Collision**: Use `area()` component and `onCollide()` for interactions.\n   * *Constraint*: **Canvas sizing**: 800x600 or 16:9 aspect ratio.\n   * *Constraint*: **State Management**: Use KAPLAY scenes for menu/play/gameover states.\n   * *Constraint*: **HUD**: Use `fixed()` and `z(100)` for UI that ignores camera.\n   * *Constraint*: **Controls Display**: Show control hints on screen at all times.\n   * *Constraint*: **Keyboard Handling**: Use `onKeyPress(\"space\", ...)` not raw DOM events for game input.\n\n2. **Playtest**: Run `node playtest.js`\n   - Captures screenshots at t=0, t=2s, t=5s\n   - Simulates basic inputs (arrow keys, space, click)\n   - Checks console for errors\n   - Extracts game state variables if exposed\n\n3. **Critique**:\n   * **Logs**: Are there JavaScript errors?\n   * **Visual Audit**: Open *all* generated screenshots (`playtest-screenshots/`) and evaluate:\n     * **Does it run?**: Is there movement/change between frames?\n     * **Input Response**: Did simulated input cause visible change?\n     * **Readability**: Is text/HUD legible? Good contrast?\n     * **Composition**: Is game area centered? Nothing cut off?\n     * **State Changes**: Can you see game progressing (score changing, objects moving)?\n   * **Visual Quality Audit** (CRITICAL - no sticks and boxes!):\n     * **No bare primitives?**: Are all objects using procedural sprites with gradients/details?\n     * **Gradient background?**: Is the background a gradient (not flat color)?\n     * **Objects alive?**: Do coins bob, player breathe, objects animate?\n     * **Particles present?**: Are there particle effects on interactions?\n     * **Color harmony?**: Is a consistent palette used throughout?\n     * **Visual depth?**: Are z-indexes creating proper layering?\n     * **Glow/highlights?**: Do important objects (coins, player) have visual emphasis?\n   * **Gameplay Audit** (mental simulation):\n     * Is the core mechanic present and functional?\n     * Is there a clear goal?\n     * Is there a failure state?\n     * Would a player understand what to do without external instructions?\n\n4. **Decide**:\n   * *Errors?* → Fix code → **Repeat**.\n   * *Static/Frozen?* → Fix game loop, ensure `onUpdate` runs → **Repeat**.\n   * *No Input Response?* → Fix input handlers, check key names → **Repeat**.\n   * *Missing Feedback?* → Add juice (shake, flash, particles) → **Repeat**.\n   * *Unclear Goal?* → Add visual indicators, HUD elements → **Repeat**.\n   * *No Win/Lose?* → Implement end conditions → **Repeat**.\n   * *Unreadable Text?* → Increase font size, add contrast → **Repeat**.\n   * *Bare rectangles/circles?* → Replace with procedural sprites → **Repeat**.\n   * *Flat background?* → Add gradient background → **Repeat**.\n   * *Static objects?* → Add idle animations (float, breathe) → **Repeat**.\n   * *No particles?* → Add burst/explosion effects → **Repeat**.\n   * *Playable, Clear, Responsive & Visually Polished?* → **Proceed to Phase 3**.\n\n### Phase 3: Presentation (The \"Launch\")\nOnce the loop is complete and the game is polished:\n1. **Launch**: Run `npx vite --open`.\n2. **Notify**: Tell the user:\n   - \"Game is ready!\"\n   - \"Controls: [List all controls]\"\n   - \"Goal: [One sentence on how to win/play]\"\n\n---\n\n## Technology Selection\n\n| Request Type | Framework | Template |\n|-------------|-----------|----------|\n| 2D game (default) | KAPLAY.js | `templates/kaplay-2d.html` |\n| 3D game (explicit) | Three.js | `templates/threejs-3d.html` |\n| FPS / first-person shooter | Three.js | `templates/threejs-fps.html` |\n| Ultra-simple (quiz, flashcard) | Vanilla Canvas | `templates/canvas-minimal.html` |\n\n**Decision rule**:\n- Use KAPLAY for most 2D games (platformer, top-down, puzzle, etc.)\n- Use `threejs-fps.html` for first-person shooters, DOOM-likes, or any game requiring pointer lock + mouse look\n- Use `threejs-3d.html` for third-person 3D games, 3D puzzles, or non-shooter 3D experiences\n- FPS indicators: \"first-person\", \"FPS\", \"shooter\", \"DOOM\", \"Wolfenstein\", \"gun\", \"pointer lock\"\n\n---\n\n## File References\n- **KAPLAY API**: See `references/kaplay-ref.md` for component list and patterns\n- **Visual Assets**: See `references/visual-assets.md` for procedural sprites, color palettes, animations, and particle effects\n- **Three.js API**: See `references/threejs-ref.md` for 3D setup\n- **FPS Patterns**: See `references/fps-patterns.md` for pointer lock, hit detection, enemy AI, weapon rendering\n- **Game Systems**: See `references/game-systems.md` for difficulty scaling, scoring, persistence, UI patterns\n- **Game Patterns**: See `references/game-patterns.md` for architecture (state machines, ECS, proc-gen)\n- **Physics Constants**: See `references/physics-constants.md` for educational accuracy\n\n---\n\n## Common Pitfalls (Avoid These)\n\n### Gameplay Pitfalls\n1. **No game loop**: Forgetting `onUpdate()` results in static screen\n2. **Wrong key names**: Use `\"space\"` not `\"Space\"`, `\"left\"` not `\"ArrowLeft\"` in KAPLAY\n3. **Missing `area()`**: Objects won''t collide without the `area()` component\n4. **Missing `body()`**: Objects won''t fall or respond to physics without `body()`\n5. **HUD moves with camera**: Use `fixed()` component for UI elements\n6. **No scenes**: Putting everything in global scope - use `scene()` for states\n7. **Forgetting `go()`**: Must call `go(\"sceneName\")` to start the first scene\n8. **Text too small**: Default text size is often too small - use 20+ for HUD\n9. **No restart**: Player stuck at game over - always add R to restart\n10. **Missing `opacity()` for `lifespan()`**: The `lifespan` component requires `opacity()` to be present on the object\n11. **Unreachable goals**: ALWAYS verify physics allow completing required actions. If player must reach X, calculate whether movement/jump/projectile range allows it.\n12. **Variable name `rgb` conflicts with KAPLAY**: Never use `const rgb = ...` as it shadows KAPLAY''s `rgb()` function. Use `const c = hexToRgb(...)` instead.\n\n### Visual Pitfalls (CRITICAL)\n13. **Bare primitives**: Using `rect()`, `circle()`, `polygon()` for game objects looks terrible - use procedural sprites\n14. **Flat backgrounds**: `background: [r,g,b]` looks cheap - use `makeGradientBg()` with texture/particles\n15. **Static objects**: Game objects sitting motionless feel dead - add idle animations (`addFloat()`, `addBreathing()`, `addSpin()`)\n16. **No particles**: Interactions without visual feedback are unsatisfying - add particle bursts on all events\n17. **Random colors**: Picking colors without a palette creates visual chaos - use PASTEL, PICO8, ENDESGA, or NEON\n18. **No z-index**: Everything at same layer looks flat - use proper z-index hierarchy (-100 to 100)\n19. **No glow/outline**: Important objects don''t stand out - add glow/aura to key game objects\n20. **Bean for everything**: `loadBean()` is a placeholder, not a finished sprite - create proper procedural sprites\n21. **\"Good enough\" sprites**: A sprite with ONE gradient is functional, not premium. Premium = 5+ layers (glow + gradient + highlight + shadow + detail)\n22. **Single-effect feedback**: One particle burst is weak. Premium = stacked effects (particles + text + flash + shake + UI reaction)\n23. **No movement deformation**: Objects moving without squash/stretch/rotation feel stiff - add deformation on velocity changes\n24. **No impact particles**: Collisions and surface contacts without particles lack weight - add particles on all physical interactions\n25. **No floating text**: Score changes without visible \"+N\" text miss dopamine feedback - show value changes visually\n\n### FPS-Specific Pitfalls\n26. **Pointer lock not recovering**: After alt-tab or focus loss, pointer lock is lost. ALWAYS re-request on focus/click events.\n27. **Enemies shoot through walls**: Must check line of sight (step along ray) before allowing enemy attacks.\n28. **Enemies spawn in walls**: Validate spawn positions against collision map; use fallback positions if invalid.\n29. **3D hit detection for 2D gameplay**: Classic FPS uses 2D XZ-plane distance with cone-of-fire, ignoring Y axis.\n30. **Weapon drawn sideways**: FPS weapons should point forward (barrel vertical), not left-to-right like a side view.\n31. **No weapon feedback**: Always add recoil animation (move down/up) and muzzle flash on fire.\n32. **Static enemy sprites**: Animate walk (leg movement) and shoot (arms raised) states with canvas texture updates.\n33. **AI too aggressive**: Balance detection range, attack rate, and damage. First-time playability > difficulty.\n34. **Score counts down during play**: Live score should ONLY increase. Time bonuses calculated at end, only if mission succeeded.\n35. **Time bonus on failure**: Speed bonus should only be awarded when the player wins, not on death.\n36. **Floating point stat display**: Always use `Math.floor()` for health, armor, score display to avoid \"99.7\" health.\n37. **Modal UI not interactive**: Game over screen must have proper `pointer-events: auto` and exit pointer lock.\n\n---\n\n## Known Warnings (Safe to Ignore)\n\n- **Puppeteer ARM64 warning**: On Apple Silicon Macs, you may see a \"Degraded performance warning\" about Chrome/Rosetta. This is expected and does not affect playtest functionality.\n"},"lastSynced":"2026-03-06T06:45:08.172Z","agentAnalysis":{"suitability":{"en":"Ideal for Interactive Agents looking to create immersive browser-based games with KAPLAY.js and Three.js","zh":"适合于希望使用 KAPLAY.js 和 Three.js 创建基于浏览器的沉浸式游戏的交互式代理","ja":"KAPLAY.js と Three.js を使用してブラウザベースのインタラクティブゲームを作成したいインタラクティブエージェントに適しています","ko":"KAPLAY.js와 Three.js를 사용하여 브라우저 기반의 인터랙티브 게임을 생성하려는 상호작용 에이전트에게 적합합니다","es":"Ideal para agentes interactivos que buscan crear juegos basados en navegador inmersivos con KAPLAY.js y Three.js","fr":"Idéal pour les agents interactifs qui cherchent à créer des jeux basés sur navigateur immersifs avec KAPLAY.js et Three.js","de":"Ideal für interaktive Agenten, die immersive browserbasierte Spiele mit KAPLAY.js und Three.js erstellen möchten","pt":"Ideal para Agentes Interativos que desejam criar jogos baseados em navegador imersivos com KAPLAY.js e Three.js","ru":"Идеально для Интерактивных Агентов, желающих создавать иммерсивные браузерные игры с помощью KAPLAY.js и Three.js","ar":"مثالي لعميل التفاعل الذين يرغبون في إنشاء ألعاب متجاوبة على المتصفح مع KAPLAY.js و Three.js"},"recommendation":{"en":"Empowers agents to build engaging 2D and 3D games with a focus on playable mechanics, clear feedback, and polished feel, utilizing libraries like KAPLAY.js and Three.js, and file formats such as HTML and JavaScript","zh":"赋予代理创建引人入胜的 2D 和 3D 游戏的能力，重点是可玩的机制、清晰的反馈和精致的感觉，利用诸如 KAPLAY.js 和 Three.js 的库，以及 HTML 和 JavaScript 等文件格式","ja":"エージェントが KAPLAY.js や Three.js などのライブラリ、HTML や JavaScript などのファイル形式を使用して、遊びやすいメカニズム、明確なフィードバック、磨き上げられた感覚に焦点を当てた魅力的な 2D および 3D ゲームを作成する能力を提供します","ko":"KAPLAY.js 및 Three.js와 같은 라이브러리와 HTML 및 JavaScript와 같은 파일 형식을 사용하여 재미있는 2D 및 3D 게임을 구축할 수 있는 능력을 제공하며, 플레이 가능한 메커니즘, 명확한 피드백 및 다듬어진 감각에 중점을 둡니다","es":"Permite a los agentes crear juegos atractivos en 2D y 3D con un enfoque en mecánicas jugables, retroalimentación clara y sensación pulida, utilizando bibliotecas como KAPLAY.js y Three.js, y formatos de archivo como HTML y JavaScript","fr":"Permet aux agents de créer des jeux engageants en 2D et 3D avec un focus sur les mécaniques de jeu, les rétroactions claires et la sensation polie, en utilisant des bibliothèques comme KAPLAY.js et Three.js, et des formats de fichiers tels que HTML et JavaScript","de":"Ermächtigt Agenten, ansprechende 2D- und 3D-Spiele mit einem Fokus auf spielbare Mechaniken, klares Feedback und polierte Oberfläche zu erstellen, indem sie Bibliotheken wie KAPLAY.js und Three.js sowie Dateiformate wie HTML und JavaScript nutzen","pt":"Habilita agentes a construir jogos 2D e 3D envolventes com foco em mecânicas jogáveis, feedback claro e sensação polida, utilizando bibliotecas como KAPLAY.js e Three.js, e formatos de arquivo como HTML e JavaScript","ru":"Наделяет агентов возможностью создавать увлекательные 2D- и 3D-игры с упором на игровую механику, четкую обратную связь и отполированное ощущение, используя библиотеки như KAPLAY.js и Three.js, и форматы файлов, такие как HTML и JavaScript","ar":"يمنح الوكلاء khảية بناء ألعاب 2D و 3D ممتعة تركز على الميكانيكا القابلة للتشغيل و تغذية راجعة واضحة و شعور منعش، باستخدام مكتبات مثل KAPLAY.js و Three.js، و صيغ الملفات مثل HTML و JavaScript"},"useCases":{"en":["Creating interactive 2D games with KAPLAY.js","Developing immersive 3D experiences with Three.js","Designing game mechanics with clear feedback and polished feel"],"zh":["使用 KAPLAY.js 创建交互式 2D 游戏","使用 Three.js 开发沉浸式 3D 体验","设计具有清晰反馈和精致感受的游戏机制"],"ja":["KAPLAY.js を使用してインタラクティブな 2D ゲームを作成する","Three.js を使用して没入感のある 3D 体験を開発する","明確なフィードバックと磨き上げられた感覚を持つゲームメカニズムを設計する"],"ko":["KAPLAY.js를 사용하여 상호작용형 2D 게임을 생성하는 것","Three.js를 사용하여 몰입형 3D 경험을 개발하는 것","명확한 피드백 및 다듬어진 감각을 갖춘 게임 메커니즘을 설계하는 것"],"es":["Creación de juegos interactivos 2D con KAPLAY.js","Desarrollo de experiencias inmersivas 3D con Three.js","Diseño de mecánicas de juego con retroalimentación clara y sensación pulida"],"fr":["Création de jeux interactifs 2D avec KAPLAY.js","Développement d''expériences immersives 3D avec Three.js","Conception de mécaniques de jeu avec des rétroactions claires et une sensation polie"],"de":["Erstellung interaktiver 2D-Spiele mit KAPLAY.js","Entwicklung immersiver 3D-Erfahrungen mit Three.js","Entwurf von Spielmechaniken mit klarer Rückmeldung und polierter Oberfläche"],"pt":["Criação de jogos 2D interativos com KAPLAY.js","Desenvolvimento de experiências 3D imersivas com Three.js","Projeto de mecânicas de jogo com feedback claro e sensação polida"],"ru":["Создание интерактивных 2D-игр с помощью KAPLAY.js","Разработка иммерсивных 3D-опытов с помощью Three.js","Проектирование игровой механики с четкой обратной связью и отполированным ощущением"],"ar":["إنشاء ألعاب 2D متجاوبة مع KAPLAY.js","تطوير تجارب 3D متجاوبة مع Three.js","تصميم ميكانيكا اللعبة مع تغذية راجعة واضحة و شعور منعش"]},"limitations":{"en":["Requires presence of package.json or running setup script","Limited to browser-based games"],"zh":["需要 package.json 的存在或运行设置脚本","仅限于基于浏览器的游戏"],"ja":["package.json の存在または設定スクリプトの実行が必要","ブラウザベースのゲームのみに限定される"],"ko":["package.json의 존재 또는 설정 스크립트의 실행이 필요","브라우저 기반 게임만 해당"],"es":["Requiere la presencia de package.json o la ejecución de un script de configuración","Limitado a juegos basados en navegador"],"fr":["Nécessite la présence de package.json ou l''exécution d''un script de configuration","Limité aux jeux basés sur navigateur"],"de":["Benötigt die Anwesenheit von package.json oder die Ausführung eines Konfigurationsskripts","Begrenzt auf browserbasierte Spiele"],"pt":["Exige a presença do arquivo package.json ou a execução do script de configuração","Limitado a jogos baseados em navegador"],"ru":["Требует наличия файла package.json или запуска скрипта настройки","Ограничен браузерными играми"],"ar":["يتطلب وجود ملف package.json أو تشغيل سكريبت الإعداد","محدود بالألعاب المبنية على المتصفح"]},"version":4},"contentHash":"d7d16b7d353691e1fb655d58ee0d5fe79eb0cf08ac63022200a08d92634541c5","qualityScore":32}');
