INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tolitius/salvador/game', 'game', 'tolitius', 'salvador', 'community', 'game tolitius salvador community The game skill enables developers to create browser-based games using KAPLAY.js and Three.js, focusing on playable mechanics and polished feel. It benefits developers looking to build engaging 2D and 3D games. 使用游戏代理创建浏览器游戏，包括2D和3D游戏开发，使用KAPLAY.js和Three.js技术 ゲームエージェントを使用してブラウザゲームを作成する，2Dと3Dゲーム開発，KAPLAY.jsとThree.js技術を使用 게임 에이전트를 사용하여 브라우저 게임을 생성하는 방법, 2D와 3D 게임 개발, KAPLAY.js와 Three.js 기술 사용 El agente de juego permite crear juegos en el navegador con KAPLAY.js y Three.js, enfocándose en playable mechanics y polished feel. L''agent de jeu permet de créer des jeux dans le navigateur avec KAPLAY.js et Three.js, en mettant l''accent sur les mécaniques de jeu et le sentiment poli. Der Game-Agent ermöglicht die Erstellung von Browser-Spielen mit KAPLAY.js und Three.js, mit Fokus auf playable Mechanics und einem polierten Gefühl. Crie jogos baseados em navegador com KAPLAY.js e Three.js, com foco em mecânicas jogáveis e feedback claro Создавайте браузерные игры с KAPLAY.js и Three.js, уделяя внимание играбельности и четкой обратной связи انشئ ألعاب متوافقة مع المتصفحات باستخدام KAPLAY.js و Three.js مع التركيز على الميكانيكا القابلة للعب وتجاوب واضح how to use game skill game development with KAPLAY.js Three.js game engine browser-based game setup guide game alternative to Unity game vs Phaser game install and setup game development best practices game skill for AI agents 游戏开发 浏览器游戏 KAPLAY.js Three.js 2D游戏 3D游戏 游戏代理 AI工具 游戏开发工作流程 Creates browser-based games using KAPLAY.js (2D) or Three.js (3D) Follows a strict loop for game development, including bootstrap and scaffolding phases Utilizes package.json and bash scripts for setup and configuration Supports inline JavaScript code in index.html or separate src/game.js files Reads API references for 2D games using KAPLAY.js Game is a skill that allows developers to create browser-based games using JavaScript libraries like KAPLAY.js and Three.js, with a focus on playable mechanics and clear feedback.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Daisuke134/anicca-products/google-calendar-automation', 'community', 'Daisuke134', 'anicca-products', 'Daisuke134/anicca-products', 'google-calendar-automation', 4, 0, 32, '2026-02-28T14:30:47Z', '2026-03-06T06:58:19.308Z', '9d9cca2dfeb40c59100fb1f856667178da3da4e31eab6e371c8db53776d5b553', '{"id":"Daisuke134/anicca-products/google-calendar-automation","name":"google-calendar-automation","description":{"en":"The google-calendar-automation skill automates Google Calendar workflows for developers, including event creation and scheduling. It integrates with Rube MCP for seamless management.","zh":"Google 日历自动化允许您自动化事件创建、安排和日历浏览等工作流","ja":"Google カレンダー自動化は、イベントの作成、スケジューリング、カレンダーの閲覧などを自動化します","ko":"Google 캘린더 자동화는 이벤트 생성, 스케줄링, 캘린더 브라우징 등을 자동화합니다","es":"La automatización de Google Calendar permite la creación de eventos, programación, verificación de disponibilidad y gestión de asistentes. Se requiere Rube MCP y conexión de Google Calendar.","fr":"L''automatisation de Google Calendar permet la création d''événements, la planification, la vérification de disponibilité et la gestion des participants. Rube MCP et la connexion de Google Calendar sont nécessaires.","de":"Die Automatisierung von Google Calendar ermöglicht die Erstellung von Ereignissen, die Planung, die Verfügbarkeitsprüfung und die Teilnehmerverwaltung. Rube MCP und die Google Calendar-Verbindung sind erforderlich.","pt":"A automação de Google Calendar via Rube MCP permite criar eventos, verificar disponibilidade e gerenciar participantes. Conheça as ferramentas necessárias para começar.","ru":"Автоматизация Google Calendar через Rube MCP позволяет создавать события, проверять доступность и управлять участниками. Узнайте, какие инструменты необходимы для начала.","ar":"تتيح أتمتة جوجل كالندر عبر Rube MCP إنشاء أحداث، وتحقق من التوفر، وإدارة المشاركين. تعرف على الأدوات الضرورية للبدء."},"seo":{"title":{"en":"google-calendar-automation: Setup Guide for AI Agents","zh":"Google 日历自动化 Setup 指南","ja":"Google カレンダー自動化ベストプラクティス","ko":"Google 캘린더 자동화 설정 가이드","es":"Guía de configuración de automatización de Google Calendar","fr":"Guide de configuration de l''automatisation de Google Cale...","de":"Einrichtungsleitfaden für Google Calendar-Automatisierung","pt":"Guia de Configuração de Automação de Google Calendar via ...","ru":"Настройка Автоматизации Google Calendar через Rube MCP: И...","ar":"دليل إعداد تطبيق أتمتة جوجل كالندر عبر Rube MCP"},"description":{"en":"Discover how to automate Google Calendar workflows with Composio''s toolkit. Learn to integrate Rube MCP and manage events, attendees, and availability","zh":"了解如何使用 Rube MCP 自动化 Google 日历工作流，包括事件创建、安排和日历浏览","ja":"Rube MCP を使用して Google カレンダーのワークフローを自動化する方法を学びます","ko":"Rube MCP를 사용하여 Google 캘린더 워크플로를 자동화하는 방법을 알아보세요","es":"Automatice flujos de trabajo de Google Calendar con Rube MCP. Obtenga información sobre cómo configurar y utilizar la herramienta de automatización de Google...","fr":"Automatisez les flux de travail de Google Calendar avec Rube MCP. Découvrez comment configurer et utiliser l''outil d''automatisation de Google Calendar.","de":"Automatisieren Sie Google Calendar-Workflows mit Rube MCP. Erfahren Sie, wie Sie die Google Calendar-Automatisierungstool konfigurieren und verwenden.","pt":"Aprenda a automatizar fluxos de trabalho do Google Calendar com o Rube MCP e a ferramenta Composio. Crie eventos, verifique disponibilidade e gerencie partic...","ru":"Автоматизируйте рабочие процессы Google Calendar с помощью Rube MCP и инструмента Composio. Создавайте события, проверяйте доступность и управляйте участниками.","ar":"تعلم كيفية أتمتة سير عمل جوجل كالندر باستخدام Rube MCP وأداة Composio. أنشئ أحداثًا، وتحقق من التوفر، وإدارة المشاركين."},"definition":{"en":"google-calendar-automation is a skill that enables automation of Google Calendar workflows via Composio''s Google Calendar toolkit and Rube MCP integration","zh":"Google 日历自动化是通过 Rube MCP 实现的自动化工具","ja":"Google カレンダー自動化は Rube MCP を使用した自動化ツールです","ko":"Google 캘린더 자동화는 Rube MCP를 사용한 자동화 도구입니다","es":"La automatización de Google Calendar es una herramienta que permite automatizar flujos de trabajo de calendario mediante Rube MCP.","fr":"L''automatisation de Google Calendar est un outil qui permet d''automatiser les flux de travail de calendrier via Rube MCP.","de":"Die Automatisierung von Google Calendar ist ein Tool, das die Automatisierung von Kalender-Workflows über Rube MCP ermöglicht.","pt":"Automação de Google Calendar é uma ferramenta que permite automatizar fluxos de trabalho de calendário","ru":"Автоматизация Google Calendar - это инструмент, который позволяет автоматизировать рабочие процессы календаря","ar":"أتمتة جوجل كالندر هي أداة تتيح أتمتة سير عمل التقويم"},"features":{"en":["Automates event creation, scheduling, and availability checks","Manages attendees and calendar browsing through Composio''s Google Calendar toolkit","Requires Rube MCP connection with RUBE_SEARCH_TOOLS available","Needs active Google Calendar connection via RUBE_MANAGE_CONNECTIONS with googlecalendar toolkit","Utilizes RUBE_SEARCH_TOOLS for current tool schemas"],"zh":["事件创建自动化","日历浏览和安排","Rube MCP 连接","Google Calendar 连接","自动化工作流"],"ja":["イベント作成の自動化","カレンダーの閲覧とスケジューリング","Rube MCP 接続","Google カレンダー接続","ワークフローの自動化"],"ko":["이벤트 생성 자동화","캘린더 브라우징과 스케줄링","Rube MCP 연결","Google 캘린더 연결","워크플로 자동화"],"es":["Creación de eventos","Programación y verificación de disponibilidad","Gestión de asistentes","Navegación por calendario","Integración con Rube MCP"],"fr":["Création d''événements","Planification et vérification de disponibilité","Gestion des participants","Navigation dans le calendrier","Intégration avec Rube MCP"],"de":["Erstellung von Ereignissen","Planung und Verfügbarkeitsprüfung","Teilnehmerverwaltung","Kalender-Navigation","Integration mit Rube MCP"],"pt":["Criação de eventos","Verificação de disponibilidade","Gerenciamento de participantes","Navegação de calendário","Integração com Rube MCP"],"ru":["Создание событий","Проверка доступности","Управление участниками","Навигация по календарю","Интеграция с Rube MCP"],"ar":["إنشاء أحداث","التحقق من التوفر","إدارة المشاركين","تنقل التقويم","التكامل مع Rube MCP"]},"keywords":{"en":["how to use google-calendar-automation","google-calendar-automation setup guide","google-calendar-automation vs zapier","google-calendar-automation install","what is google-calendar-automation","google-calendar-automation alternative","Rube MCP integration with google-calendar-automation","Composio''s Google Calendar toolkit tutorial","automating google calendar workflows with AI agents"],"zh":["Google 日历自动化","Rube MCP","Google Calendar API","自动化工作流","事件创建自动化","日历浏览","AIエージェント","自动化工具"],"ja":["Google カレンダー自動化","Rube MCP","Google カレンダー API","ワークフローの自動化","イベント作成の自動化","カレンダーの閲覧","AIエージェント","自動化ツール"],"ko":["Google 캘린더 자동화","Rube MCP","Google 캘린더 API","워크플로 자동화","이벤트 생성 자동화","캘린더 브라우징","AI 에이전트","자동화 도구"],"es":["automatización de Google Calendar","Rube MCP","creación de eventos","programación de eventos","gestión de asistentes","navegación por calendario","herramientas de automatización de calendario"],"fr":["automatisation de Google Calendar","Rube MCP","création d''événements","planification d''événements","gestion des participants","navigation dans le calendrier","outils d''automatisation de calendrier"],"de":["Automatisierung von Google Calendar","Rube MCP","Erstellung von Ereignissen","Planung von Ereignissen","Teilnehmerverwaltung","Kalender-Navigation","Tools für die Automatisierung von Kalendern"],"pt":["automação de google calendar","rube mcp","composio","criação de eventos","verificação de disponibilidade","gerenciamento de participantes","navegação de calendário","integração com rube mcp"],"ru":["автоматизация google calendar","rube mcp","composio","создание событий","проверка доступности","управление участниками","навигация по календарю","интеграция с rube mcp"],"ar":["أتمتة جوجل كالندر","rube mcp","composio","إنشاء أحداث","التحقق من التوفر","إدارة المشاركين","تنقل التقويم","التكامل مع rube mcp"]}},"owner":"Daisuke134","repo":"anicca-products","repoPath":"Daisuke134/anicca-products","stars":4,"forks":0,"updatedAt":"2026-02-28T14:30:47Z","topics":[],"category":"community","skillMd":{"name":"google-calendar-automation","description":"Automate Google Calendar events, scheduling, availability checks, and attendee management via Rube MCP (Composio). Create events, find free slots, manage attendees, and list calendars programmatically.","bodyPreview":"# Google Calendar Automation via Rube MCP\n\nAutomate Google Calendar workflows including event creation, scheduling, availability checks, attendee management, and calendar browsing through Composio''s Google Calendar toolkit.\n\n## Prerequisites\n\n- Rube MCP must be connected (RUBE_SEARCH_TOOLS available)\n- Active Google Calendar connection via `RUBE_MANAGE_CONNECTIONS` with toolkit `googlecalendar`\n- Always call `RUBE_SEARCH_TOOLS` first to get current tool schemas\n\n## Setup\n\n**Get Rube MCP**: Add `","body":"# Google Calendar Automation via Rube MCP\n\nAutomate Google Calendar workflows including event creation, scheduling, availability checks, attendee management, and calendar browsing through Composio''s Google Calendar toolkit.\n\n## Prerequisites\n\n- Rube MCP must be connected (RUBE_SEARCH_TOOLS available)\n- Active Google Calendar connection via `RUBE_MANAGE_CONNECTIONS` with toolkit `googlecalendar`\n- Always call `RUBE_SEARCH_TOOLS` first to get current tool schemas\n\n## Setup\n\n**Get Rube MCP**: Add `https://rube.app/mcp` as an MCP server in your client configuration. No API keys needed — just add the endpoint and it works.\n\n\n1. Verify Rube MCP is available by confirming `RUBE_SEARCH_TOOLS` responds\n2. Call `RUBE_MANAGE_CONNECTIONS` with toolkit `googlecalendar`\n3. If connection is not ACTIVE, follow the returned auth link to complete Google OAuth\n4. Confirm connection status shows ACTIVE before running any workflows\n\n## Core Workflows\n\n### 1. Create and Manage Events\n\n**When to use**: User wants to create, update, or delete calendar events\n\n**Tool sequence**:\n1. `GOOGLECALENDAR_LIST_CALENDARS` - Identify target calendar ID [Prerequisite]\n2. `GOOGLECALENDAR_GET_CURRENT_DATE_TIME` - Get current time with proper timezone [Optional]\n3. `GOOGLECALENDAR_FIND_FREE_SLOTS` - Check availability before booking [Optional]\n4. `GOOGLECALENDAR_CREATE_EVENT` - Create the event [Required]\n5. `GOOGLECALENDAR_PATCH_EVENT` - Update specific fields of an existing event [Alternative]\n6. `GOOGLECALENDAR_UPDATE_EVENT` - Full replacement update of an event [Alternative]\n7. `GOOGLECALENDAR_DELETE_EVENT` - Delete an event [Optional]\n\n**Key parameters**:\n- `calendar_id`: Use ''primary'' for main calendar, or specific calendar ID\n- `start_datetime`: ISO 8601 format ''YYYY-MM-DDTHH:MM:SS'' (NOT natural language)\n- `timezone`: IANA timezone name (e.g., ''America/New_York'', NOT ''EST'' or ''PST'')\n- `event_duration_hour`: Hours (0+)\n- `event_duration_minutes`: Minutes (0-59 only; NEVER use 60+)\n- `summary`: Event title\n- `attendees`: Array of email addresses (NOT names)\n- `location`: Free-form text for event location\n\n**Pitfalls**:\n- `start_datetime` must be ISO 8601; natural language like ''tomorrow'' is rejected\n- `event_duration_minutes` max is 59; use `event_duration_hour=1` instead of `event_duration_minutes=60`\n- `timezone` must be IANA identifier; abbreviations like ''EST'', ''PST'' are NOT valid\n- `attendees` only accepts email addresses, not names; resolve names first\n- Google Meet link creation defaults to true; may fail on personal Gmail accounts (graceful fallback)\n- Organizer is auto-added as attendee unless `exclude_organizer=true`\n\n### 2. List and Search Events\n\n**When to use**: User wants to find or browse events on their calendar\n\n**Tool sequence**:\n1. `GOOGLECALENDAR_LIST_CALENDARS` - Get available calendars [Prerequisite]\n2. `GOOGLECALENDAR_FIND_EVENT` - Search by title/keyword with time bounds [Required]\n3. `GOOGLECALENDAR_EVENTS_LIST` - List events in a time range [Alternative]\n4. `GOOGLECALENDAR_EVENTS_INSTANCES` - List instances of a recurring event [Optional]\n\n**Key parameters**:\n- `query` / `q`: Free-text search (matches summary, description, location, attendees)\n- `timeMin`: Lower bound (RFC3339 with timezone offset, e.g., ''2024-01-01T00:00:00-08:00'')\n- `timeMax`: Upper bound (RFC3339 with timezone offset)\n- `singleEvents`: true to expand recurring events into instances\n- `orderBy`: ''startTime'' (requires singleEvents=true) or ''updated''\n- `maxResults`: Results per page (max 2500)\n\n**Pitfalls**:\n- **Timezone warning**: UTC timestamps (ending in ''Z'') don''t align with local dates; use local timezone offsets instead\n- Example: ''2026-01-19T00:00:00Z'' covers 2026-01-18 4pm to 2026-01-19 4pm in PST\n- Omitting `timeMin`/`timeMax` scans the full calendar and can be slow\n- `pageToken` in response means more results; paginate until absent\n- `orderBy=''startTime''` requires `singleEvents=true`\n\n### 3. Manage Attendees and Invitations\n\n**When to use**: User wants to add, remove, or update event attendees\n\n**Tool sequence**:\n1. `GOOGLECALENDAR_FIND_EVENT` or `GOOGLECALENDAR_EVENTS_LIST` - Find the event [Prerequisite]\n2. `GOOGLECALENDAR_PATCH_EVENT` - Add attendees (replaces entire attendees list) [Required]\n3. `GOOGLECALENDAR_REMOVE_ATTENDEE` - Remove a specific attendee by email [Required]\n\n**Key parameters**:\n- `event_id`: Unique event identifier (opaque string, NOT the event title)\n- `attendees`: Full list of attendee emails (PATCH replaces entire list)\n- `attendee_email`: Email to remove\n- `send_updates`: ''all'', ''externalOnly'', or ''none''\n\n**Pitfalls**:\n- `event_id` is a technical identifier, NOT the event title; always search first to get the ID\n- `PATCH_EVENT` attendees field replaces the entire list; include existing attendees to avoid removing them\n- Attendee names cannot be resolved; always use email addresses\n- Use `GMAIL_SEARCH_PEOPLE` to resolve names to emails before managing attendees\n\n### 4. Check Availability and Free/Busy Status\n\n**When to use**: User wants to find available time slots or check busy periods\n\n**Tool sequence**:\n1. `GOOGLECALENDAR_LIST_CALENDARS` - Identify calendars to check [Prerequisite]\n2. `GOOGLECALENDAR_GET_CURRENT_DATE_TIME` - Get current time with timezone [Optional]\n3. `GOOGLECALENDAR_FIND_FREE_SLOTS` - Find free intervals across calendars [Required]\n4. `GOOGLECALENDAR_FREE_BUSY_QUERY` - Get raw busy periods for computing gaps [Fallback]\n5. `GOOGLECALENDAR_CREATE_EVENT` - Book a confirmed slot [Required]\n\n**Key parameters**:\n- `items`: List of calendar IDs to check (e.g., [''primary''])\n- `time_min`/`time_max`: Query interval (defaults to current day if omitted)\n- `timezone`: IANA timezone for interpreting naive timestamps\n- `calendarExpansionMax`: Max calendars (1-50)\n- `groupExpansionMax`: Max members per group (1-100)\n\n**Pitfalls**:\n- Maximum span ~90 days per Google Calendar freeBusy API limit\n- Very long ranges or inaccessible calendars yield empty/invalid results\n- Only calendars with at least freeBusyReader access are visible\n- Free slots responses may normalize to UTC (''Z''); check offsets\n- `GOOGLECALENDAR_FREE_BUSY_QUERY` requires RFC3339 timestamps with timezone\n\n## Common Patterns\n\n### ID Resolution\n- **Calendar name -> calendar_id**: `GOOGLECALENDAR_LIST_CALENDARS` to enumerate all calendars\n- **Event title -> event_id**: `GOOGLECALENDAR_FIND_EVENT` or `GOOGLECALENDAR_EVENTS_LIST`\n- **Attendee name -> email**: `GMAIL_SEARCH_PEOPLE`\n\n### Timezone Handling\n- Always use IANA timezone identifiers (e.g., ''America/Los_Angeles'')\n- Use `GOOGLECALENDAR_GET_CURRENT_DATE_TIME` to get current time in user''s timezone\n- When querying events for a local date, use timestamps with local offset, NOT UTC\n- Example: ''2026-01-19T00:00:00-08:00'' for PST, NOT ''2026-01-19T00:00:00Z''\n\n### Pagination\n- `GOOGLECALENDAR_EVENTS_LIST` returns `nextPageToken`; iterate until absent\n- `GOOGLECALENDAR_LIST_CALENDARS` also paginates; use `page_token`\n\n## Known Pitfalls\n\n- **Natural language dates**: NOT supported; all dates must be ISO 8601 or RFC3339\n- **Timezone mismatch**: UTC timestamps don''t align with local dates for filtering\n- **Duration limits**: `event_duration_minutes` max 59; use hours for longer durations\n- **IANA timezones only**: ''EST'', ''PST'', etc. are NOT valid; use ''America/New_York''\n- **Event IDs are opaque**: Always search to get event_id; never guess or construct\n- **Attendees as emails**: Names cannot be used; resolve with GMAIL_SEARCH_PEOPLE\n- **PATCH replaces attendees**: Include all desired attendees in the array, not just new ones\n- **Conference limitations**: Google Meet may fail on personal accounts (graceful fallback)\n- **Rate limits**: High-volume searches can trigger 403/429; throttle between calls\n\n## Quick Reference\n\n| Task | Tool Slug | Key Params |\n|------|-----------|------------|\n| List calendars | `GOOGLECALENDAR_LIST_CALENDARS` | `max_results` |\n| Create event | `GOOGLECALENDAR_CREATE_EVENT` | `start_datetime`, `timezone`, `summary` |\n| Update event | `GOOGLECALENDAR_PATCH_EVENT` | `calendar_id`, `event_id`, fields to update |\n| Delete event | `GOOGLECALENDAR_DELETE_EVENT` | `calendar_id`, `event_id` |\n| Search events | `GOOGLECALENDAR_FIND_EVENT` | `query`, `timeMin`, `timeMax` |\n| List events | `GOOGLECALENDAR_EVENTS_LIST` | `calendarId`, `timeMin`, `timeMax` |\n| Recurring instances | `GOOGLECALENDAR_EVENTS_INSTANCES` | `calendarId`, `eventId` |\n| Find free slots | `GOOGLECALENDAR_FIND_FREE_SLOTS` | `items`, `time_min`, `time_max`, `timezone` |\n| Free/busy query | `GOOGLECALENDAR_FREE_BUSY_QUERY` | `timeMin`, `timeMax`, `items` |\n| Remove attendee | `GOOGLECALENDAR_REMOVE_ATTENDEE` | `event_id`, `attendee_email` |\n| Get current time | `GOOGLECALENDAR_GET_CURRENT_DATE_TIME` | `timezone` |\n| Get calendar | `GOOGLECALENDAR_GET_CALENDAR` | `calendar_id` |\n"},"lastSynced":"2026-03-06T06:58:19.308Z","agentAnalysis":{"suitability":{"en":"Ideal for Schedule Management Agents requiring seamless Google Calendar integration and automation capabilities.","zh":"适用于需要与Google Calendar无缝集成和自动化能力的日程管理代理。","ja":"Google Calendarとのシームレスな統合と自動化機能を必要とするスケジュール管理エージェントに適しています。","ko":"Google Calendar와의无缝한 통합 및 자동화 기능을 필요로 하는 스케줄 관리 에이전트에 적합합니다.","es":"Ideal para agentes de gestión de horarios que requieren una integración perfecta con Google Calendar y capacidades de automatización.","fr":"Idéal pour les agents de gestion de planning nécessitant une intégration transparente avec Google Calendar et des capacités d''automatisation.","de":"Ideal für Terminplanungsagenten, die eine nahtlose Google Calendar-Integration und Automatisierungsfähigkeiten erfordern.","pt":"Ideal para Agentes de Gerenciamento de Agenda que exigem integração sem problemas com o Google Calendar e capacidades de automação.","ru":"Идеально для агентов управления расписанием, требующих бесшовной интеграции с Google Calendar и возможностей автоматизации.","ar":"مثالي للوكلاء لإدارة الجدول الزمني الذين يتطلبون تكاملًا بدون مشاكل مع تقويم جوجل و khảیات الية"},"recommendation":{"en":"Empowers agents to automate Google Calendar workflows, including event creation, scheduling, availability checks, and attendee management, using Composio''s Google Calendar toolkit and integrating with Rube MCP for efficient management via protocols like RUBE_SEARCH_TOOLS and RUBE_MANAGE_CONNECTIONS.","zh":"赋予代理自动化Google Calendar工作流的能力，包括使用Composio的Google Calendar工具包和集成Rube MCP以高效管理的事件创建、调度、可用性检查和出席者管理，通过协议如RUBE_SEARCH_TOOLS和RUBE_MANAGE_CONNECTIONS。","ja":"ComposioのGoogle CalendarツールキットとRube MCPを統合し、RUBE_SEARCH_TOOLSやRUBE_MANAGE_CONNECTIONSなどのプロトコルを使用して効率的に管理することで、イベントの作成、スケジューリング、可用性の確認、出席者の管理などのGoogle Calendarワークフローを自動化するエージェントの能力を提供します。","ko":"Composio의 Google Calendar 툴킷과 Rube MCP를 통합하여 RUBE_SEARCH_TOOLS 및 RUBE_MANAGE_CONNECTIONS와 같은 프로토콜을 사용하여 효율적으로 관리함으로써 이벤트 생성, 스케줄링, 가용성 확인 및 참석자 관리 등을 포함한 Google Calendar 워크플로를 자동화하는 에이전트의 능력을 제공합니다.","es":"Permite a los agentes automatizar flujos de trabajo de Google Calendar, incluyendo la creación de eventos, programación, verificación de disponibilidad y gestión de asistentes, utilizando la herramienta de Google Calendar de Composio e integrándose con Rube MCP para una gestión eficiente a través de protocolos como RUBE_SEARCH_TOOLS y RUBE_MANAGE_CONNECTIONS.","fr":"Permet aux agents d''automatiser les flux de travail de Google Calendar, y compris la création d''événements, la planification, les vérifications de disponibilité et la gestion des participants, en utilisant l''outil de Google Calendar de Composio et en s''intégrant avec Rube MCP pour une gestion efficace via des protocoles tels que RUBE_SEARCH_TOOLS et RUBE_MANAGE_CONNECTIONS.","de":"Ermächtigt Agenten, Google Calendar-Workflows zu automatisieren, einschließlich Ereigniserstellung, Terminplanung, Verfügbarkeitsprüfung und Teilnehmermanagement, unter Verwendung von Composios Google Calendar-Toolkit und Integration mit Rube MCP für eine effiziente Verwaltung über Protokolle wie RUBE_SEARCH_TOOLS und RUBE_MANAGE_CONNECTIONS.","pt":"Habilita os agentes a automatizar fluxos de trabalho do Google Calendar, incluindo criação de eventos, agendamento, verificações de disponibilidade e gerenciamento de participantes, usando a ferramenta de toolkit do Google Calendar da Composio e integrando com Rube MCP para gerenciamento eficiente via protocolos como RUBE_SEARCH_TOOLS e RUBE_MANAGE_CONNECTIONS.","ru":"Наделяет агентов возможностью автоматизировать рабочие процессы Google Calendar, включая создание событий, планирование, проверки доступности и управление участниками, используя набор инструментов Google Calendar от Composio и интегрируя с Rube MCP для эффективного управления через протоколы seperti RUBE_SEARCH_TOOLS и RUBE_MANAGE_CONNECTIONS.","ar":"يمنح الوكلاء القدرة على Automating سير عمل جوجل كالندار، بما في ذلك إنشاء الفعاليات، وتحديد المواعيد، وفحص التوافر، وإدارة الحضور، باستخدام أداةToolkit لجوجل كالندار من Composio ودمجها مع Rube MCP من أجل الإدارة الفعالة عبر بروتوكولات مثل RUBE_SEARCH_TOOLS و RUBE_MANAGE_CONNECTIONS."},"useCases":{"en":["Automating event creation and scheduling","Checking availability and managing attendees","Browsing calendars for efficient scheduling"],"zh":["自动化事件创建和调度","检查可用性和管理出席者","浏览日历以实现高效调度"],"ja":["イベントの作成とスケジューリングの自動化","可用性の確認と出席者の管理","カレンダーの閲覧による効率的なスケジューリング"],"ko":["이벤트 생성 및 스케줄링 자동화","가용성 확인 및 참석자 관리","일정표閲覧을 통한 효율적인 스케줄링"],"es":["Automatización de la creación y programación de eventos","Verificación de disponibilidad y gestión de asistentes","Navegación por calendarios para una programación eficiente"],"fr":["Automatisation de la création et de la planification d''événements","Vérification de la disponibilité et gestion des participants","Navigation dans les calendriers pour une planification efficace"],"de":["Automatisierung der Erstellung und Terminplanung von Ereignissen","Verfügbarkeitsprüfung und Teilnehmermanagement","Navigieren in Kalendern für eine effiziente Terminplanung"],"pt":["Automatizar a criação e agendamento de eventos","Verificar a disponibilidade e gerenciar participantes","Navegar pelos calendários para agendamento eficiente"],"ru":["Автоматизировать создание и планирование событий","Проверять доступность и управлять участниками","Просматривать календари для эффективного планирования"],"ar":["توفير آلي لإنشاء الفعاليات وتحديد المواعيد","فحص التوافر وإدارة الحضور","استعراض التقاويم من أجل التخطيط الفعال"]},"limitations":{"en":["Requires Rube MCP connection with RUBE_SEARCH_TOOLS available","Active Google Calendar connection via RUBE_MANAGE_CONNECTIONS with toolkit googlecalendar necessary"],"zh":["需要Rube MCP连接且RUBE_SEARCH_TOOLS可用","需要通过RUBE_MANAGE_CONNECTIONS和工具包googlecalendar的活跃Google Calendar连接"],"ja":["RUBE_SEARCH_TOOLSが利用可能なRube MCP接続が必要","RUBE_MANAGE_CONNECTIONSとツールキットgooglecalendarを使用したGoogle Calendarのアクティブ接続が必要"],"ko":["RUBE_SEARCH_TOOLS가 사용 가능한 Rube MCP 연결이 필요함","RUBE_MANAGE_CONNECTIONS 및 툴킷 googlecalendar를 사용한 활성 Google Calendar 연결이 필요"],"es":["Requiere conexión con Rube MCP con RUBE_SEARCH_TOOLS disponible","Conexión activa de Google Calendar a través de RUBE_MANAGE_CONNECTIONS con la herramienta googlecalendar necesaria"],"fr":["Nécessite une connexion à Rube MCP avec RUBE_SEARCH_TOOLS disponible","Connexion active de Google Calendar via RUBE_MANAGE_CONNECTIONS avec l''outil googlecalendar nécessaire"],"de":["Erfordert Verbindung mit Rube MCP mit verfügbarer RUBE_SEARCH_TOOLS","Aktive Google Calendar-Verbindung über RUBE_MANAGE_CONNECTIONS mit dem Toolkit googlecalendar erforderlich"],"pt":["Exige conexão com Rube MCP com RUBE_SEARCH_TOOLS disponível","Conexão ativa com Google Calendar via RUBE_MANAGE_CONNECTIONS com toolkit googlecalendar necessário"],"ru":["Требует соединения с Rube MCP с доступным RUBE_SEARCH_TOOLS","Активное соединение с Google Calendar через RUBE_MANAGE_CONNECTIONS с необходимым toolkit googlecalendar"],"ar":["يتطلب الاتصال ب Rube MCP مع RUBE_SEARCH_TOOLS المتاح","اتصال نشط ب جوجل كالندار عبر RUBE_MANAGE_CONNECTIONS مع أداةToolkit جوجل كالندار الضرورية"]},"version":4},"contentHash":"9d9cca2dfeb40c59100fb1f856667178da3da4e31eab6e371c8db53776d5b553","qualityScore":32}');
